window.__Q=window.__Q||{};window.__Q["tcm/7/A1"]=[{"q":"大肠内细菌可合成","o":["维生素D","维生素B复合物和维生素K","维生素B12","维生素E","维生素C"],"a":1,"e":"大肠内细菌能利用肠内较简单的物质合成维生素B复合物和维生素K，供人体吸收，补充食物摄入的不足。维生素D主要由皮肤经紫外线照射合成，维生素C必须从食物获取，二者均非肠道菌群产物；维生素B12需与内因子结合后在回肠吸收，也不是大肠细菌合成的主要维生素"},{"q":"在实验中用单个电脉冲刺激心肌，逐渐增大刺激强度，心肌的反应是","o":["完全强直收缩","不完全强直收缩","收缩强度也随之增大","收缩强度先增大后减小","全或无反应"],"a":4,"e":"心肌细胞间以闰盘缝隙连接相连，兴奋可迅速扩布至全部心肌，单一阈上刺激即引起全部细胞同步收缩，故呈全或无反应。骨骼肌才表现为分级收缩，刺激增强可因参与收缩的肌纤维数目增多而张力增大；单个电脉冲不产生频率叠加，故不出现完全或不完全强直收缩"},{"q":"引起缩胆囊素释放作用最强的物质是","o":["盐酸","脂酸钠","蛋白质分解产物","葡萄糖","高渗溶液"],"a":2,"e":"缩胆囊素释放的刺激强弱依次为蛋白质分解产物、脂酸钠、盐酸、脂肪，故最强者为蛋白质分解产物。盐酸是刺激促胰液素释放的最强因素，两激素常被互换设错；葡萄糖与高渗溶液对缩胆囊素释放基本无刺激作用"},{"q":"单根神经纤维动作电位中，正后电位出现在","o":["阈电位之后","超射之后","锋电位之后","负后电位之后","恢复到静息电位之后"],"a":3,"e":"神经纤维动作电位依次为锋电位、负后电位（后去极化）、正后电位（后超极化），故正后电位出现在负后电位之后。超射指去极化超过零电位的部分，位于锋电位之中；阈电位是引发动作电位的临界膜电位，属刺激与兴奋的关系，不参与后电位的排序"},{"q":"下列物质进入肾小管后，既不被分泌又不被重吸收的是","o":["酚红","氨基酸","菊粉","葡萄糖","氯化钠"],"a":2,"e":"菊粉可被肾小球自由滤过，肾小管和集合管既不重吸收也不分泌，其清除率等于肾小球滤过率，是测定GFR的理想标志物。酚红主要经近端小管主动分泌，氨基酸和葡萄糖在近端小管被重吸收，氯化钠大部分被重吸收，均不符合条件"},{"q":"糖皮质激素对各系统功能的影响，下列哪一项描述是正确的","o":["使淋巴细胞数量增加","减少淋巴细胞与嗜酸性粒细胞的破坏","使嗜酸性粒细胞数量增加","降低中枢神经系统兴奋性","促进消化液的分泌"],"a":4,"e":"糖皮质激素可促进胃酸和胃蛋白酶原分泌，使消化液分泌增多。它使淋巴细胞和嗜酸性粒细胞减少，机制为促进其破坏并抑制生成；同时提高中枢神经系统兴奋性，过量时可致失眠、欣快。故淋巴细胞增多、嗜酸性粒细胞增多、中枢抑制三项均与之相反"},{"q":"肺气肿患者的肺弹性回缩力降低，主要导致哪项指标增加","o":["时间肺活量","肺活量","功能残气量和潮气量","潮气量","功能残气量"],"a":4,"e":"肺气肿时肺弹性成分大量破坏、回缩力下降，平静呼气末残留在肺内的气体增多，功能残气量增大。肺活量多正常或略减，时间肺活量因呼气动力不足而降低，潮气量一般不增加；功能残气量与潮气量并列的选项错误在于潮气量并不随之增大"},{"q":"下列关于呕吐的叙述，正确的是","o":["呕吐中枢位于下丘脑","感受器仅位于消化道内","主要为小肠逆蠕动动所致","仅有胃肌收缩","对机体有利有害"],"a":4,"e":"呕吐是机体的一种防御性反射，可排出胃内有害物质，但剧烈呕吐可引起脱水、低钾血症和代谢性碱中毒，故对机体有利也有害。呕吐中枢位于延髓，并非下丘脑；感受器除消化道外还有前庭器官和化学感受器触发区；其发生依赖胃、膈肌与腹肌协同，不只是小肠逆蠕动或胃肌收缩"},{"q":"交感神经系统不具有下列哪一特点","o":["节前纤维短，节后纤维长","支配几乎所有脏器","紧张性活动","刺激节前纤维时反应比较局限","在应急反应中活动明显加强"],"a":3,"e":"交感神经节前纤维短、节后纤维长，分布广泛几乎支配所有内脏，具有紧张性活动，应急反应时活动明显加强。其节前与节后神经元换元时辐散程度高，一个节前神经元可联系多个节后神经元，故刺激节前纤维时反应弥散而非局限；副交感神经的反应才相对局限"},{"q":"红细胞的变形能力取决于红细胞的","o":["体积","表面积","数量","比重","表面积与体积之比"],"a":4,"e":"正常双凹圆碟形使红细胞具有较大的表面积与体积之比，受外力时易于变形，该比值降低则变形能力减弱。体积、表面积单独一项均不能决定变形能力；数量反映红细胞总量，比重反映沉降特性，与变形无关。遗传性球形红细胞增多症即因该比值下降而变形能力减低"},{"q":"下列凝血因子中，稳定性最低的是","o":["因子Ⅴ","因子Ⅶ","因子Ⅹ","因子Ⅺ","因子Ⅻ"],"a":0,"e":"因子Ⅴ又称前加速素、易变因子，是凝血因子中最不稳定者，血液储存过程中易失活。因子Ⅶ、Ⅹ、Ⅺ、Ⅻ相对稳定；其中因子Ⅶ需维生素K参与合成，因子Ⅻ是内源性凝血途径的启动因子，稳定性均明显高于因子Ⅴ"},{"q":"机体对刺激发生反应的能力或特性称为","o":["稳态","兴奋性","兴奋","反应","收缩性"],"a":1,"e":"兴奋性指活组织细胞接受刺激产生反应的能力或特性，是生命活动的基本特征之一。兴奋指动作电位的产生过程本身；反应是刺激引起的功能变化总称；稳态指内环境理化性质的动态平衡；收缩性仅指肌细胞缩短的能力，均不能替代兴奋性的定义"},{"q":"刺激支配唾液腺的副交感神经，引起唾液分泌的特点是","o":["量多、固体成分少的唾液","量少、固体成分少的唾液","量少、固体成分多的唾液","量多、固体成分多的唾液","唾液量基本不变"],"a":0,"e":"副交感神经兴奋时唾液腺分泌量多而固体成分少的稀薄唾液，经M受体介导，阿托品可阻断该效应。交感神经兴奋则经β受体引起量少而固体成分多的黏稠唾液；量少固体成分少与量多固体成分多均不对应任何生理状态"},{"q":"心迷走节后纤维末梢释放的递质是","o":["脑啡肽","一氧化氮","乙酰胆碱","肾上腺素","去甲肾上腺素"],"a":2,"e":"心迷走节后纤维属胆碱能纤维，末梢释放乙酰胆碱，作用于心肌M受体产生负性变力、负性变时和负性变传导作用。去甲肾上腺素是心交感节后纤维的递质；肾上腺素主要由肾上腺髓质分泌；脑啡肽与一氧化氮仅为自主神经系统中少量存在的其他递质"},{"q":"排尿反射的初级中枢位于","o":["大脑皮层","脊髓","延髓","下丘脑","脑桥"],"a":1,"e":"排尿反射在脊髓水平即可完成，初级中枢位于骶髓，平时受脑桥、下丘脑和大脑皮层高位中枢控制。大脑皮层是最高级控制部位，损伤后虽不能随意控制排尿但仍保留反射；延髓为心血管、呼吸等基本中枢；脑桥含排尿易化区，均非初级中枢"},{"q":"关于三大营养物质在体内代谢的叙述，下列哪一项不正确","o":["机体所需能量的50%～70%由糖提供","只有将能量转移至ATP，才能被组织活动所利用","人体在不做外功的情况下，所消耗的能量全部转化为热能","能源物质在体内氧化释放的能量50%以上转化为热能","蛋白质在体内氧化和体外燃烧时所产生的能量相等"],"a":4,"e":"蛋白质在体内氧化不彻底，终产物为尿素等含氮废物，释放能量小于体外燃烧，故二者热价不相等。糖提供机体所需能量的50%～70%，能量须转移至ATP方可被组织利用，不做外功时消耗的能量最终全部转为热能，体内氧化释放能量50%以上转为热能，均正确"},{"q":"与骨骼肌细胞比较，心室肌细胞的动作电位具有的特征是","o":["去极化速度快","动作电位较大的幅度","复极化时间短暂","动作电位时间持续较长","去极化速度慢"],"a":3,"e":"心室肌细胞动作电位有明显平台期，时程可达300毫秒，复极缓慢使其持续时间远长于骨骼肌。其0期去极化由Na+内流介导，速度并不慢，幅度与骨骼肌相近；复极化时间短暂恰与心室肌相反，故去极化快、幅度大、复极短暂均不能选"},{"q":"下述关于EPSP产生过程的叙述，错误的是","o":["突触前膜超极化","Ca2+经突触前膜进入突触小体","突触小泡释放兴奋性递质并与后膜受体结合","突触后膜对Na+、K+特别是Na+通透性增强","Na+内流突触后膜去极化产生EPSP"],"a":0,"e":"EPSP产生时突触前膜去极化，使电压门控钙通道开放、Ca2+内流触发递质释放，而非超极化。递质作用于后膜使Na+、K+通透性增强，以Na+内流为主，产生去极化型EPSP；超极化是IPSP的表现，由Cl-内流或K+外流引起，故超极化项错误"},{"q":"脑电图对于以下哪种疾病的诊断有重要辅助作用","o":["癫痫","精神分裂症","高血压","糖尿病","智力低下"],"a":0,"e":"癫痫发作时脑电图可出现棘波、尖波、棘慢综合波，结合临床可判断病灶部位，故脑电图对癫痫诊断有重要辅助价值。精神分裂症与智力低下属高级认知功能异常，无特异性脑电改变；高血压、糖尿病为心血管与代谢疾病，诊断依靠血压和血糖，不靠脑电图"},{"q":"关于某成年女性患者的呼吸功能检查结果，下列哪一项不正常","o":["呼吸频率16次/分","潮气量500ml","肺活量2500ml","时间肺活量第1秒为70%，第2秒为85%，第3秒为94%","每分通气量为8L"],"a":3,"e":"正常成人时间肺活量第1秒约83%、第2秒约96%、第3秒约99%，该患者第1秒仅70%，提示阻塞性通气障碍。呼吸频率16次/分、潮气量500ml、每分通气量8L均在正常范围；女性肺活量2500ml亦属正常，故异常项为时间肺活量"},{"q":"人工呼吸的原理是人为地造成","o":["肺内压与胸内压的压力差","肺内压与大气压的压力差","腹内压与大气压的压力差","胸内压与大气压的压力差","肺内压与腹内压的压力差"],"a":1,"e":"肺通气依靠肺内压与大气压之间的压力差驱动，人工呼吸即人为建立该压差，如口对口吹气或使用呼吸机。胸膜腔内压为负压，是维持肺扩张状态的条件而非通气动力；腹内压仅在用力呼吸时辅助，不能直接推动气体进出肺"},{"q":"心肌组织中，兴奋传导速度最慢的是","o":["房室束","房室交界","心室肌","结间束","希氏束"],"a":1,"e":"房室交界结区细胞体积小、缝隙连接少，传导速度最慢，形成房室延搁，保证心房收缩完毕后心室才收缩。房室束、希氏束与结间束传导较快，心室肌借闰盘传导的速度也明显高于房室交界，故最慢者为房室交界"},{"q":"肾素是由下列哪种细胞分泌的","o":["球旁细胞","肾小管近端小管上皮细胞","肾血管内皮细胞","集合管上皮细胞","致密斑上皮细胞"],"a":0,"e":"肾素由球旁器的球旁细胞合成、储存和释放，属蛋白水解酶，可催化血浆血管紧张素原转变为血管紧张素Ⅰ。致密斑是感受小管液NaCl含量的化学感受器，不分泌肾素；近端小管上皮细胞、集合管上皮细胞和血管内皮细胞均无分泌肾素的功能"},{"q":"下列关于大肠内细菌作用的叙述，正确的是","o":["使糖和脂肪腐败","使蛋白质发酵","分解纤维素","合成维生素B和K","使氨基酸转化为二氧化碳"],"a":3,"e":"大肠内细菌对蛋白质的分解称腐败，对糖和脂肪的分解称发酵，两项表述恰好颠倒。细菌能利用肠内简单物质合成维生素B复合物和维生素K供人体吸收；氨基酸分解产物包括氨、硫化氢、组胺、吲哚等，并非只转化为二氧化碳；纤维素可被部分细菌分解，但不是该题所指的主要作用"},{"q":"形成中枢延搁现象的原因主要是突触传递过程中","o":["神经递质在胞体的合成","神经递质沿轴浆的运输","神经递质的释放、扩散和对突触后膜的作用","神经递质的失活","突触后电位的总和"],"a":2,"e":"中枢延搁指兴奋经突触传递时耗时较长，时间主要耗费在递质释放、经突触间隙扩散以及与突触后膜受体结合并引起后电位的过程。递质合成与轴浆运输属慢速过程，不参与每次传递的即时延搁；递质失活和后电位总和也不是延搁的主要环节"},{"q":"关于胎盘产生的激素的描述，下列哪一项是错误的","o":["人绒毛膜促性腺激素与人绒毛膜生长素都是糖蛋白激素","人绒毛膜促性腺激素的生理功能与黄体生成素相似","人绒毛膜生长素有促生长作用，促进胎儿摄取营养","雌三醇的主要前身物质来自母体的胆固醇","孕激素的生理作用是维持子宫内膜，抑制T细胞，防止母体排斥胎儿"],"a":3,"e":"雌三醇的生成以胎儿肾上腺分泌的脱氢异雄酮硫酸盐为前身，经胎儿肝羟化后在胎盘转化，故其前身并非母体胆固醇。hCG与hCS均为糖蛋白激素，hCG作用与黄体生成素相似，hCS促进胎儿摄取营养；孕激素维持子宫内膜并抑制T细胞、防止母体排斥胎儿，均正确"},{"q":"窦房结的兴奋由心房到达心室，表现在心电图上的相应部分是","o":["P-P间期","P-R间期","Q-T间期","S-T段","R-R间期"],"a":1,"e":"P-R间期代表窦房结兴奋经心房、房室交界和房室束到达心室并引起心室兴奋所需的时间，即房室传导时间。P-P间期反映窦性心律的频率，R-R间期反映心室节律，Q-T间期代表心室去极与复极全过程，S-T段反映心室缓慢复极，均不表示房室传导"},{"q":"肺泡表面活性物质缺乏，将使","o":["肺顺应性增高","肺弹性阻力增高","肺非弹性阻力增高","大肺泡内压大于小肺泡内压","肺水肿减轻"],"a":1,"e":"肺泡表面活性物质可降低肺泡表面张力，缺乏时表面张力增大，肺弹性阻力升高、顺应性降低，易发生肺不张。非弹性阻力主要来自气道阻力，与表面活性物质无关；缺乏时小肺泡因表面张力相对更大而更易萎陷，并非大肺泡内压大于小肺泡内压；肺水肿会加重而非减轻"},{"q":"下列关于体温调节过程的叙述，不正确的是","o":["温度信息多途径输入","整合中枢在下丘脑","以PO/AH为中心","传出信息多途径输出","与调定点无关"],"a":4,"e":"体温调节按调定点学说进行，调定点决定产热与散热的平衡水平，故与调定点无关的表述错误。温度信息经多途径传入，整合中枢在下丘脑并以视前区-下丘脑前部为中心，传出信息经多途径输出引起产热与散热反应，其余各项均正确"},{"q":"心室肌细胞动作电位4期恢复细胞内外钠钾离子正常浓度梯度依靠","o":["载体易化扩散","单纯扩散","通道易化扩散","离子泵主动转运","继发性主动转运"],"a":3,"e":"4期依靠钠泵即Na+-K+-ATP酶逆浓度梯度将细胞内Na+泵出、细胞外K+泵入，属原发性主动转运，直接耗ATP。载体与通道的易化扩散、单纯扩散均顺梯度进行，不能恢复离子浓度差；继发性主动转运利用钠泵建立的Na+梯度，为间接耗能，不是恢复梯度的直接机制"},{"q":"安静状态下，动-静脉血氧含量差最大的器官是","o":["皮肤","骨骼肌","心脏","肾脏","肝脏"],"a":2,"e":"心脏持续节律性做功，安静时耗氧量大，动脉血氧含量高而冠状静脉血氧含量低，动-静脉血氧含量差最大。皮肤与骨骼肌安静时血流量小、代谢率低，差值小；肾脏血流量大但摄氧比例低；肝脏代谢虽活跃，差值仍小于心脏"},{"q":"抑制胰岛素分泌的激素是","o":["胰高血糖素","生长抑素","生长激素","皮质醇","甲状腺激素"],"a":1,"e":"生长抑素由胰岛D细胞分泌，可抑制胰岛素及胰高血糖素的释放。胰高血糖素直接促进糖原分解和糖异生使血糖升高；生长激素、皮质醇、甲状腺激素均通过拮抗胰岛素作用升高血糖，均不抑制胰岛素分泌"},{"q":"脑组织消耗的能量，主要来自下列哪种物质","o":["氨基酸","胆固醇","蛋白质","甘油","葡萄糖"],"a":4,"e":"脑组织代谢率高且几乎无糖原储备，主要依靠血糖持续供能，低血糖时首先出现中枢功能障碍。氨基酸与蛋白质供能比例极低，胆固醇不能被脑氧化供能，甘油仅在长期饥饿时少量参与，故均非主要能源"},{"q":"实验测得某物质血浆清除率是150ml/min，表明","o":["该物质可被肾小管分泌","该物质可不被肾小管分泌","该物质分泌量等于重吸收量","该物质分泌量等于肾小球滤过量","该物质血浆清除率等于肾小球滤过率"],"a":0,"e":"血浆清除率150ml/min高于肾小球滤过率约125ml/min，说明该物质除被肾小球滤过外还有肾小管分泌。若仅靠滤过，清除率应等于肾小球滤过率；清除率低于滤过率才提示重吸收；分泌量等于重吸收量或等于滤过量均不能解释清除率升高"},{"q":"防御反应区主要位于","o":["延髓","脊髓","脑桥","下丘脑","低位脑干"],"a":3,"e":"防御反应区主要位于下丘脑，尤以近中线两旁的腹内侧区为主，刺激该区可引起血压升高、心率加快、骨骼肌血管舒张等防御反应。延髓、脑桥和脊髓仅为心血管反射的低位中枢与通路，低位脑干含心血管基本中枢，均不承担防御反应的整合"},{"q":"下列关于体温的正常生理变动的描述，哪项是正确的","o":["新生儿体温最稳定","午后1～6时体温最低","通常成年女性体温低于成年男性","肌肉活动可导致体温升高","老年人体温偏高"],"a":3,"e":"肌肉活动时代谢产热明显增加，可使体温暂时升高，属正常生理变动。新生儿体温调节功能不完善，体温最不稳定；体温昼夜波动以清晨2～6时最低、午后最高；成年女性基础体温略高于男性；老年人代谢率低，体温偏低"},{"q":"对细胞膜跨膜物质转运机制的研究属于","o":["器官、系统水平","局部水平","整体水平","细胞、分子水平","组织水平"],"a":3,"e":"跨膜物质转运涉及细胞膜上的通道、载体和离子泵，属细胞与分子水平的研究。器官、系统水平研究完整器官及器官之间的协同，整体水平研究机体整体功能，组织水平介于细胞与器官之间，均不针对膜蛋白的转运机制"},{"q":"下丘脑是较高级的","o":["交感神经中枢","副交感神经中枢","内脏活动调节中枢","躯体运动中枢","交感和副交感神经中枢"],"a":2,"e":"下丘脑是较高级的内脏活动调节中枢，可整合体温、摄食、水平衡和情绪等内脏功能，并通过交感与副交感神经下传。脊髓、延髓、脑桥属低级内脏反射中枢；下丘脑并非交感或副交感神经的唯一中枢，躯体运动主要由皮层运动区和锥体外系调控"},{"q":"体温调定点的部位在","o":["下丘脑","下丘脑后部","视前区-下丘脑前部","脑干网状结构","大脑皮层"],"a":2,"e":"体温调定点位于视前区-下丘脑前部，该区含热敏神经元与冷敏神经元，两类神经元随温度变化改变放电频率的特性决定调定点水平。下丘脑后部主要整合产热与散热的传出；脑干网状结构参与觉醒与肌张力；大脑皮层参与行为性体温调节，均非调定点所在"},{"q":"Rh血型系统的抗体是","o":["IgA","IgD","IgE","IgG","IgM"],"a":3,"e":"Rh血型系统的抗体为IgG，属不完全抗体，能通过胎盘，故Rh阴性母亲孕育Rh阳性胎儿可引起新生儿溶血。IgM是ABO血型的天然抗体，分子量大不能通过胎盘；IgA、IgD、IgE均不参与Rh血型系统的免疫应答"},{"q":"血管肌源性调节属于心血管活动的","o":["神经调节","体液调节","自身调节","负反馈调节","正反馈调节"],"a":2,"e":"血管平滑肌在灌注压升高时自身收缩、灌注压降低时自身舒张，使血流量保持相对稳定，属肌源性自身调节。神经调节通过缩血管纤维实现，体液调节通过儿茶酚胺等实现，二者均需外来信号；负反馈与正反馈描述的是控制方式，不是调节类型"},{"q":"小剂量使用肾上腺素可致","o":["心动周期缩短","心肌收缩力减弱","心输出量降低","外周阻力明显降低","外周阻力明显增加"],"a":0,"e":"小剂量肾上腺素以兴奋β受体为主，使心率加快、心肌收缩力增强、心输出量增加，心动周期相应缩短。其对α受体作用弱，外周阻力变化不明显，故外周阻力明显降低或明显增加均不准确；心肌收缩力减弱、心输出量降低与β1受体激动效应相反"},{"q":"呼吸气体交换的动力是","o":["温度","气体分压差","气体溶解度","气体的分子量","扩散面积"],"a":1,"e":"气体交换以扩散方式进行，动力是呼吸膜两侧的气体分压差。温度、溶解度、分子量和扩散面积影响扩散速率，属交换条件而非动力；分压差决定扩散的方向和量，故为肺换气与组织换气的直接动力。分压差越大，气体扩散速率越快"},{"q":"Rh阳性是指红细胞膜上含有","o":["A抗原","B抗原","C抗原","D抗原","E抗原"],"a":3,"e":"Rh阳性指红细胞膜上含D抗原，含D者为阳性，缺乏D者为阴性。A抗原、B抗原属ABO血型系统，决定ABO血型；C抗原、E抗原虽同属Rh系统，但其有无不用于判定阴性与阳性。Rh抗体为IgG，可经胎盘引起新生儿溶血"},{"q":"正常生理情况下，骨骼肌的收缩形式一般为","o":["全程的等长收缩","全程的等张收缩","单收缩","不完全强直收缩","完全强直收缩"],"a":4,"e":"正常生理情况下运动神经冲动频率较高，后一冲动落在前一次收缩的收缩期内，收缩发生叠加，形成完全强直收缩，便于产生持久有力的张力。单收缩仅在动作电位频率很低时出现；等长与等张收缩描述的是长度和张力的变化形式；不完全强直收缩见于冲动频率较低、后一冲动落在舒张期时"},{"q":"以下关于生物电现象的叙述，正确的是","o":["在静息状态下，Na＋、K＋通道处于关闭状态","细胞接受刺激开始去极化时，就有Na＋通道大量开放","膜电位在去极化达阈电位时，Na＋通道大量开放","Na＋通道关闭，出现动作电位的复极相","刺激可引起动作电位的爆发"],"a":2,"e":"膜电位去极化达阈电位时，电压门控Na+通道大量开放，Na+迅速内流形成动作电位陡峭的0期。静息时K+通道部分开放而非全部关闭；刺激未达阈电位时只有少量Na+通道开放，不足以引发动作电位；复极相是Na+通道失活、K+外流所致"},{"q":"传入侧支性抑制又称交互抑制，有关其活动过程和意义的正确叙述是","o":["可以不需要中间神经元的参与","主要的结构是轴-轴式突触","抑制性中间神经元兴奋性降低","有助于协调相互拮抗中枢的活动","有利于及时终止中枢内神经元的活动"],"a":3,"e":"传入侧支性抑制中，传入纤维的侧支兴奋抑制性中间神经元，进而抑制拮抗中枢，使伸肌与屈肌活动协调，故其意义是协调相互拮抗中枢的活动。该过程必须有抑制性中间神经元参与，突触为轴-体式，抑制性中间神经元兴奋性升高；及时终止中枢活动是回返性抑制的作用"},{"q":"cAMP作为第二信使，它的主要作用是激活","o":["G蛋白","腺苷酸环化酶","蛋白激酶A","蛋白激酶C","磷酸二酯酶"],"a":2,"e":"cAMP作为第二信使主要激活蛋白激酶A，使多种底物蛋白磷酸化而产生效应。G蛋白位于受体与腺苷酸环化酶之间，是cAMP生成的上游环节；腺苷酸环化酶催化ATP生成cAMP；蛋白激酶C由二酰甘油和Ca2+激活；磷酸二酯酶则降解cAMP"},{"q":"肠期胃液的分泌主要是通过十二指肠释放哪种胃肠激素实现的","o":["缩胆囊素","促胰液素","促胃液素","生长抑素","肠抑胃肽"],"a":2,"e":"肠期胃液分泌主要由食糜刺激十二指肠黏膜释放促胃液素实现，促胃液素经血液循环作用于胃腺。缩胆囊素与促胰液素主要调节胰液和胆汁分泌、胆囊收缩，对胃酸多呈抑制；生长抑素与肠抑胃肽均抑制胃酸分泌，不是肠期胃液分泌的兴奋因素"},{"q":"治疗“水中毒”应补充下列哪种物质","o":["皮质醇","醛固酮","血管升压素","褪黑素","胰岛素"],"a":0,"e":"水中毒时细胞外液低渗、水向细胞内转移，糖皮质激素可抑制抗利尿激素分泌、提高肾小球滤过率，促进水排出，故补充皮质醇有效。醛固酮保钠排钾，加重水钠潴留；血管升压素促进水重吸收，使病情恶化；褪黑素与胰岛素无促进水排出的作用"},{"q":"去睾丸后，血中促卵泡激素浓度增加的原因是以下哪一项","o":["睾酮对腺垂体分泌促卵泡激素有负反馈作用","甲基睾酮对促卵泡激素分泌有负反馈作用","孕烯醇酮对促卵泡激素分泌有负反馈作用","抑制素对促卵泡激素分泌有负反馈作用","雄激素结合球蛋白的负反馈作用"],"a":3,"e":"睾丸支持细胞分泌的抑制素对腺垂体促卵泡激素分泌有负反馈作用，去睾丸后抑制素减少，促卵泡激素分泌因而增加。睾酮主要负反馈抑制黄体生成素，对促卵泡激素作用弱；甲基睾酮、孕烯醇酮及雄激素结合球蛋白均非该反馈的主要因素"},{"q":"在动物实验中，电刺激家兔膈下迷走神经时，不会出现下列哪种情况","o":["小肠平滑肌收缩","胃平滑肌收缩","肛门外括约肌舒张","促胰液素分泌增多","胆汁分泌增多"],"a":2,"e":"膈下迷走神经含副交感纤维，兴奋时使胃肠平滑肌收缩、促进胆汁和胰液分泌，并可通过胃酸增多间接促进促胰液素释放。肛门外括约肌受阴部神经这一躯体神经支配，迷走神经不支配该肌，故电刺激膈下迷走神经不会出现肛门外括约肌舒张"},{"q":"代谢水平对心脏血流量的调节属于","o":["神经调节","体液调节","自身调节","正反馈调节","负反馈调节"],"a":2,"e":"心肌代谢水平改变可引起冠脉小血管舒缩，代谢产物如腺苷增多使血管舒张、血流量增加，属代谢性自身调节。神经调节与体液调节需神经递质或激素参与；正反馈与负反馈描述的是控制方式，不是调节类型"},{"q":"消化道平滑肌的自动节律性主要依赖于下列哪一项作用","o":["交感神经的支配","平滑肌本身的特性","迷走神经的支配","食物的刺激作用","壁内神经丛的作用"],"a":1,"e":"消化道平滑肌细胞膜电位可自发周期性去极化形成慢波，源于细胞本身膜电导的变化，故自动节律性依赖平滑肌自身特性。交感神经、迷走神经、壁内神经丛和食物刺激只能改变慢波的频率与幅度，属调节因素而非节律的起源"},{"q":"临床上，当胆瘘患者胆汁大量流失至体外时，其胆汁分泌与正常人相比较会显著减少，主要原因是","o":["合成胆盐的原料减少","胆盐的肠肝循环减少","促胃液素分泌减少","促胰液素分泌减少","缩胆囊素分泌减少"],"a":1,"e":"胆盐随胆汁排入小肠后大部分在回肠末端被重吸收，经门静脉回肝再利用，构成胆盐的肠肝循环。胆瘘时胆汁大量外流，胆盐丢失使肠肝循环减少，肝细胞合成胆汁的原料不足，胆汁分泌显著减少。促胃液素、促胰液素、缩胆囊素减少并非主因"},{"q":"心动周期中，心脏瓣膜的活动，下述哪项是错误的","o":["房室瓣关，动脉瓣开","房室瓣开，动脉瓣关","房室瓣、动脉瓣都开","房室瓣、动脉瓣都关","压力差控制瓣膜开关"],"a":2,"e":"房室瓣与动脉瓣不能同时开放，否则心房、心室与动脉之间形成无效通道。快速射血期房室瓣关、动脉瓣开；快速充盈期房室瓣开、动脉瓣关；等容收缩期与等容舒张期两瓣均关；瓣膜启闭由两侧压力差控制，故两瓣都开的表述错误"},{"q":"某患者在胃大部分切除后出现巨幼红细胞性贫血的原因是对哪项物质吸收障碍","o":["蛋白质","叶酸","维生素B12","脂肪","铁"],"a":2,"e":"维生素B12需与胃壁细胞分泌的内因子结合才能在回肠被吸收，胃大部切除后内因子缺乏，导致巨幼红细胞性贫血。叶酸缺乏也可引起巨幼贫，但与内因子无关；铁缺乏引起小细胞低色素性贫血；蛋白质和脂肪吸收障碍不导致巨幼红细胞性贫血"},{"q":"妊娠期内不排卵是由于下列哪些激素的作用","o":["雌激素","缩宫素","雌激素与孕激素","催乳素","促性腺激素释放激素"],"a":2,"e":"妊娠期胎盘分泌大量雌激素与孕激素，负反馈抑制下丘脑GnRH及腺垂体促卵泡激素、黄体生成素的分泌，使卵泡不发育、不排卵。缩宫素主要引起子宫收缩，催乳素促进泌乳，GnRH为兴奋性激素，均不造成妊娠期不排卵"},{"q":"O2在血液中的运输形式以氧合血红蛋白为主，1g血红蛋白大约可结合1、34ml的O2。某人的血红蛋白浓度为140g/L，该人血中的血红蛋白氧容量(ml/L)大约接近于下列哪一数值","o":["100","140","180","220","260"],"a":2,"e":"血红蛋白氧容量指每升血液中血红蛋白能结合的最大氧量，按1g血红蛋白结合1.34ml氧计算，140g/L×1.34约等于188ml/L，最接近180。100与140明显偏低，220与260超过按140g/L计算的上限，故取最接近值"},{"q":"临床上对严重肺气肿患者不宜以吸入纯氧来改善缺氧的原因是","o":["避免高氧对呼吸中枢的直接抑制作用","高氧对中枢化学感受器无刺激作用","反而引起CO2对中枢化学感受器的刺激减弱","维持低氧对外周化学感受器的刺激作用","维持高CO2对中枢的兴奋作用"],"a":3,"e":"严重肺气肿患者长期二氧化碳潴留，中枢化学感受器敏感性降低，呼吸主要靠低氧刺激外周化学感受器维持，吸入纯氧会解除该刺激而引起呼吸抑制。高氧对中枢的直接抑制不是主要顾虑；二氧化碳刺激减弱与中枢敏感性下降有关，但并非不宜吸纯氧的核心机制"},{"q":"与反馈相比，前馈控制的特点是","o":["反应滞后","产生波动","无预见性","适应性差","快速生效"],"a":4,"e":"前馈控制依据预先信号提前启动调节，不必等偏差出现，故快速生效且具有预见性。反馈控制需偏差出现后才纠正，因而反应滞后、易产生波动；前馈控制的适应性好，能提前抵消干扰。故滞后、波动、无预见性、适应性差均为反馈的特点"},{"q":"下列生理过程需要细胞本身耗能的是","o":["O2通过呼吸膜","动作电位复极化过程中K+外流","小肠黏膜上皮细胞吸收葡萄糖","集合管对水的重吸收","心室肌细胞动作电位2期的Ca2+内流"],"a":2,"e":"小肠黏膜上皮细胞吸收葡萄糖属继发性主动转运，借助钠泵建立的Na+浓度梯度逆梯度转运，间接消耗ATP，需细胞本身供能。氧通过呼吸膜、复极时K+外流、2期Ca2+内流均为顺梯度被动过程；集合管水重吸收经水通道，也不直接耗能"},{"q":"关于肺泡表面活性物质的描述，错误的是","o":["维持肺泡的扩张状态","由肺泡I型细胞所分泌","降低肺泡表面张力","稳定肺泡容积","使肺的顺应性增加"],"a":1,"e":"肺泡表面活性物质由肺泡Ⅱ型细胞分泌，故由Ⅰ型细胞分泌的表述错误。它降低肺泡表面张力、增加肺顺应性、维持肺泡扩张状态并稳定大小肺泡的容积，防止肺不张和肺水肿，其余各项描述均正确。早产儿因缺乏该物质易发生新生儿呼吸窘迫综合征"},{"q":"血浆胶体渗透压降低时可引起","o":["组织液减少","组织液增加","红细胞萎缩","红细胞膨胀和破裂","尿量减少"],"a":1,"e":"血浆胶体渗透压主要由白蛋白形成，其降低时有效滤过压升高，组织液生成增多。组织液减少与组织液增加相反；红细胞萎缩、膨胀破裂取决于血浆晶体渗透压；尿量减少主要与抗利尿激素和肾小球滤过有关，不是胶体渗透压降低的直接结果"},{"q":"交感缩血管神经节后纤维末梢释放的递质主要与下列哪一种受体结合","o":["M受体","N受体","α受体","β1受体","β2受体"],"a":2,"e":"交感缩血管神经节后纤维释放去甲肾上腺素，主要与血管平滑肌α受体结合引起血管收缩。β1受体主要分布于心脏，β2受体分布于骨骼肌血管和支气管平滑肌，激动后舒张；M受体为副交感节后纤维的效应受体，N受体位于神经节和骨骼肌终板"},{"q":"单纯扩散和易化扩散的共同点是","o":["需要ATP供能","借助于通道蛋白的帮助","借助于载体蛋白的帮助","顺浓度差转运","转运脂溶性物质"],"a":3,"e":"单纯扩散与易化扩散均为顺浓度梯度、不耗能的被动转运。单纯扩散不需膜蛋白，主要转运脂溶性物质；易化扩散需通道蛋白或载体蛋白帮助。需要ATP供能是主动转运的特点，借助通道或载体也只是易化扩散单方面的特征"},{"q":"呋塞米产生利尿作用的部位是","o":["近端小管","髓袢升支细段","髓袢升支粗段","远曲小管","集合管"],"a":2,"e":"呋塞米抑制髓袢升支粗段Na+-K+-2Cl-同向转运体，减少NaCl重吸收，破坏髓质高渗梯度，产生强大利尿作用。近端小管是碳酸酐酶抑制剂的作用部位，远曲小管是噻嗪类的作用部位，集合管是醛固酮拮抗剂的作用部位，髓袢升支细段无此转运体"},{"q":"在对血氧饱和度与血液PO2关系的描述中，P50是指","o":["使Hb氧饱和度达到50%的PO2","PO2为50mmHg时的氧饱和度","PCO2为50mmHg时的氧饱和度","PO2为正常值的50%时的氧饱和度","使Hb的氧容量达到正常值50%时的PO2"],"a":0,"e":"P50指血红蛋白氧饱和度达到50%时的氧分压，正常约26.5mmHg，反映血红蛋白对氧的亲和力。氧分压为50mmHg时氧饱和度约85%，不能称为P50；P50与二氧化碳分压无关，也不是正常氧容量或正常氧分压的50%"},{"q":"有关K+的分泌，下列说法不正确的是","o":["多吃多排","少吃少排","不吃也排","不能进食的患者，应防止发生低血钾","不吃不排"],"a":4,"e":"肾对钾的排泄特点是多吃多排、少吃少排、不吃也排，故不吃不排错误。不能进食的患者仍有钾从尿中排出，易发生低钾血症，临床需注意补钾。该特点由远曲小管和集合管主细胞的钾分泌功能决定。故对禁食患者需常规补钾，以防低钾血症"},{"q":"可作为心室舒张期开始的标志的心音是","o":["第一心音","第二心音","第三心音","第四心音","二尖瓣关闭音"],"a":1,"e":"第二心音由主动脉瓣和肺动脉瓣关闭引起，标志心室舒张期开始。第一心音由房室瓣关闭引起，标志心室收缩开始；第三心音出现在快速充盈期，第四心音出现在心房收缩期；二尖瓣关闭音属第一心音的组成部分"},{"q":"当长期不能进食或能量消耗过大时，维持生理活动必要的能源物质是","o":["葡萄糖","脂肪酸","甘油三酯","蛋白质","乳酸"],"a":3,"e":"长期不能进食或能量消耗过大时，糖原与脂肪储备逐渐耗竭，机体靠分解组织蛋白质供能来维持生命活动，故蛋白质是必要的能源物质。葡萄糖在长期饥饿时主要靠糖异生生成，脂肪酸与甘油三酯供能有限，乳酸仅为糖酵解的中间产物"},{"q":"临床上，气管插管或全身麻醉时可辅助使用肌肉松弛剂，如N型胆碱受体的阻断剂筒箭毒等，此类药物作用机制主要是抑制骨骼肌细胞哪一生理过程","o":["G蛋白偶联受体介导的信号转导","酪氨酸激酶受体介导的信号转导","酪氨酸激酶结合型受体介导的信号转导","离子通道型受体介导的信号转导","鸟苷酸环化酶受体介导的信号转导"],"a":3,"e":"筒箭毒碱阻断骨骼肌终板膜的N2型乙酰胆碱受体，该受体属离子通道型受体，故其机制是抑制离子通道型受体介导的信号转导。G蛋白偶联受体介导递质与激素的慢反应；酪氨酸激酶受体及酪氨酸激酶结合型受体介导生长因子、细胞因子作用；鸟苷酸环化酶受体介导心房钠尿肽作用"},{"q":"下列哪一项是糖皮质激素对代谢的作用","o":["促进葡萄糖的利用，促进蛋白质分解","促进葡萄糖的利用，抑制蛋白质分解","抑制葡萄糖的利用，促进蛋白质分解","促进葡萄糖的利用，促进蛋白质合成","抑制葡萄糖的利用，抑制蛋白质分解"],"a":2,"e":"糖皮质激素抑制外周组织摄取和利用葡萄糖，促进糖异生使血糖升高，同时促进肝外蛋白质分解。它既不促进葡萄糖利用，也不促进蛋白质合成，故促进利用、抑制分解以及促进合成等组合均不符合其代谢作用"},{"q":"下列物质中，通过离子通道型受体进行信号转导的是","o":["谷氨酸","心房钠尿肽","生长激素","表皮生长因子","甲状腺激素"],"a":0,"e":"谷氨酸作用于离子通道型受体，如NMDA受体和AMPA受体，引起配体门控通道开放。心房钠尿肽经鸟苷酸环化酶受体，生长激素经酪氨酸激酶结合型受体，表皮生长因子经酪氨酸激酶受体，甲状腺激素经核受体，均非离子通道型受体"},{"q":"所有平滑肌都具有的是","o":["自律性","传导性","交感神经和副交感神经支配","三联管结构","紧张性收缩"],"a":4,"e":"各类平滑肌均具有紧张性收缩，即持续保持一定张力，是维持器官形态和腔内压力的基础。自律性仅见于消化道、子宫等部分平滑肌；传导性并非所有平滑肌都具备；三联管是骨骼肌的结构；皮肤血管、竖毛肌等并无副交感神经支配"},{"q":"安静时心室肌细胞膜对K+通透性较高主要是由于","o":["IK通道开放","IK1通道开放","Ito通道开放","If通道开放","INa通道开放"],"a":1,"e":"安静时心室肌细胞膜上IK1通道开放，K+通透性高，K+外流形成静息电位。IK通道参与复极，Ito通道介导1期快速复极，If通道存在于自律细胞参与4期自动去极化，INa通道在兴奋时开放，均非安静时K+通透性高的原因"},{"q":"每分通气量和肺泡通气量之差为","o":["无效腔气量×呼吸频率","潮气量×呼吸频率","余气量×呼吸频率","功能余气量×呼吸频率","补吸气量×呼吸频率"],"a":0,"e":"每分通气量为潮气量与呼吸频率的乘积，肺泡通气量为（潮气量减无效腔气量）乘呼吸频率，二者之差即无效腔气量乘呼吸频率。潮气量乘呼吸频率为每分通气量本身；余气量、功能余气量和补吸气量均不参与该差值的计算"},{"q":"成人在清醒、安静并闭目时出现","o":["α波","β波","δ波","θ波","α波阻断"],"a":0,"e":"清醒、安静并闭目时枕叶皮层出现8～13Hz的α波，是正常成人该状态的特征性脑电波。睁眼或思考时α波消失称α波阻断；β波见于睁眼及精神活动时；θ波见于困倦或儿童；δ波见于深睡和婴幼儿"},{"q":"长期服用广谱抗生素，导致出血倾向可选用","o":["肝素","叶酸","维生素B1","维生素K","尿激酶"],"a":3,"e":"长期服用广谱抗生素抑制肠道菌群，使细菌合成的维生素K减少，凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的活化障碍而引起出血，故应补充维生素K。肝素与尿激酶为抗凝、溶栓药物，会加重出血；叶酸与维生素B1分别与巨幼贫和神经炎有关，不参与凝血因子活化"},{"q":"刺激引起兴奋的基本条件是使跨膜电位达到","o":["局部电位","阈电位","锋电位","后电位","动作电位"],"a":1,"e":"刺激引起兴奋的基本条件是使膜去极化达到阈电位，从而触发电压门控Na+通道大量开放。局部电位是阈下刺激引起的局部反应；锋电位是动作电位的组成部分；后电位出现在复极之后；动作电位是兴奋的标志而非产生条件"},{"q":"血浆中的碳酸氢盐主要在红细胞内生成，其主要原因是","o":["红细胞含丰富Hb","红细胞内含有丰富的碳酸酐酶","血浆蛋白可以抑制CO2与水的反应","CO2易于通过红细胞膜","红细胞膜上有HCO3--Cl-载体"],"a":1,"e":"红细胞内碳酸酐酶含量丰富，可高效催化二氧化碳与水生成碳酸并解离为碳酸氢根，故血浆中的碳酸氢盐主要在红细胞内生成后转移至血浆。血红蛋白主要运输氧和二氧化碳；二氧化碳易通过红细胞膜是条件而非主要原因；碳酸氢根-氯离子载体负责将其排出，也不是生成部位的原因"},{"q":"胆盐对下列哪种物质的消化具有重要意义","o":["淀粉","蛋白质","脂肪","多肽","胆固醇"],"a":2,"e":"胆盐是脂肪消化吸收的关键，可乳化脂肪、形成混合微胶粒，促进脂肪及脂溶性维生素的吸收。淀粉由淀粉酶消化，蛋白质与多肽由蛋白酶消化；胆固醇需溶于胆盐微胶粒而被吸收，并非被胆盐消化，故胆盐作用的对象是脂肪"},{"q":"外科手术中常用温热盐水纱布压迫止血，关于其生理机制的叙述错误的是","o":["纱布是异物，可激活因子Ⅻ","可促进红细胞凝集","凝血过程是酶促反应，适当加温可使凝血反应加速","纱布是异物，可激活血小板","压迫可使局部小血管收缩，促进凝血"],"a":1,"e":"温热盐水纱布压迫止血依靠异物激活因子Ⅻ和血小板、局部小血管受压收缩，以及加温加速酶促凝血反应。红细胞凝集属抗原抗体反应，与止血机制无关；纱布作为异物激活血小板与因子Ⅻ均属促进凝血的合理机制，压迫使血管收缩亦正确"},{"q":"关于胰岛素降低血糖的作用，下列哪一项是错误的","o":["促进组织细胞摄取葡萄糖","增强糖原的合成","抑制糖原的分解","增加糖异生","促进葡萄糖转变为脂肪酸"],"a":3,"e":"胰岛素促进组织细胞摄取葡萄糖、增强糖原合成、抑制糖原分解，并促进葡萄糖转变为脂肪酸储存，从而降低血糖。它抑制糖异生而非增加糖异生，故增加糖异生为错误表述；其余各项均属胰岛素的降糖机制"},{"q":"交感神经节后纤维释放的递质是","o":["ACh和NE","NE","5-HT","ACh","NE和5-HT"],"a":0,"e":"交感神经节后纤维大部分释放去甲肾上腺素，小部分如支配汗腺和骨骼肌舒血管纤维释放乙酰胆碱，故为乙酰胆碱和去甲肾上腺素。仅去甲肾上腺素或仅乙酰胆碱均不全面；5-羟色胺不是交感节后纤维的主要递质"},{"q":"在肾小球滤过中阻碍带电荷的蛋白通过滤过膜最主要的结构是","o":["肾小球毛细血管内皮","毛细血管内皮下基膜","肾小囊脏层足细胞","足细胞足突间裂隙膜","肾小球毛细血管口径"],"a":1,"e":"滤过膜各层均带负电荷，其中毛细血管内皮下基膜是阻碍带电荷蛋白通过的最主要结构屏障。内皮细胞窗孔较大，足细胞裂隙膜主要起机械屏障作用，毛细血管口径影响血流量而非电荷屏障，故关键结构为基膜"},{"q":"收缩压是下列哪个时期的大动脉血压","o":["等容收缩期","快速射血期","等容舒张期","房缩期","减慢射血期"],"a":1,"e":"收缩压是心室快速射血期大动脉内压力的最高值，此期射血速度快、射入血量多，动脉被动扩张。等容收缩期动脉压最低；减慢射血期动脉压已开始下降；等容舒张期与心房收缩期动脉压处于舒张压水平"},{"q":"细胞内外液渗透压的平衡主要依赖于下列哪一物质的移动来维持","o":["Na+","K+","CI-","葡萄糖","水"],"a":4,"e":"细胞内外液渗透压相等，水可自由通过细胞膜，故渗透压平衡主要依靠水的移动维持。钠、钾、氯等离子受膜通透性和离子泵的限制不能自由通过；葡萄糖参与渗透压形成但不能自由跨膜移动，故不是维持平衡的主要移动物质"},{"q":"下列关于气体在血液中运输的叙述，错误的是","o":["血中O2和CO2都有物理溶解和化学结合两种形式","O2的结合形式是氧合血红蛋白","O2与血红蛋白结合快、可逆，需要酶催化","CO2主要以HCO3-形式运输","CO2与血红蛋白的氨基结合不需酶的催化"],"a":2,"e":"氧与血红蛋白结合快、可逆，且不需酶催化，属氧合而非氧化，故需酶催化的表述错误。氧与二氧化碳均有物理溶解和化学结合两种运输形式，二氧化碳主要以碳酸氢根形式运输，二氧化碳与血红蛋白氨基结合形成氨基甲酰血红蛋白也不需酶"},{"q":"感受器就如实验中用到的换能器那样，最终可以将不同形式的刺激能量转变为电信号，其换能过程是","o":["刺激→静息电位减小→动作电位","刺激→超极化电位→动作电位","刺激→静息电位减小→局部去极化","刺激→感受器电位或发生器电位→动作电位","刺激→去极化电位→局部兴奋"],"a":3,"e":"感受器将不同形式的刺激能量转换为感受器电位或发生器电位，后者达阈电位后触发传入神经产生动作电位。刺激可直接引起静息电位减小或去极化，但只有形成发生器电位并引发动作电位才是完整的换能过程；超极化不是感受器换能的普遍形式"},{"q":"下列哪一项可使肾小球滤过率增加","o":["肾小球毛细血管血压增高","血浆胶体渗透压增高","肾小囊内压升高","肾小球毛细血管血压降低","血浆晶体渗透压升高"],"a":0,"e":"肾小球毛细血管血压是有效滤过压的推动力，其升高使有效滤过压增大、滤过率增加。血浆胶体渗透压升高和肾小囊内压升高均对抗滤过，使滤过率降低；血浆晶体渗透压对滤过影响很小，故不能使滤过率增加"},{"q":"家兔麻醉后行膀胱插管，观察影响尿生成的因素。这种实验方法属于","o":["慢性在体实验","慢性离体实验","混合性实验","急性在体实验","急性离体实验"],"a":3,"e":"家兔麻醉后行膀胱插管并观察影响尿生成的因素，动物处于麻醉状态、实验在短时间内完成，属急性在体实验。慢性实验需动物长期存活并待其恢复；离体实验将器官移出体外；混合性实验指急慢性结合，均不符合该实验设计"},{"q":"下列属于胰液成分的是","o":["肠激酶","内因子","糜蛋白酶原","胆固醇","胆色素"],"a":2,"e":"胰液由腺泡细胞分泌的消化酶和导管细胞分泌的碳酸氢盐组成，糜蛋白酶原即胰液中的蛋白水解酶前体。肠激酶由小肠黏膜分泌，内因子由胃壁细胞分泌，胆固醇与胆色素属胆汁成分，均不是胰液成分。胰液中还含胰淀粉酶、胰脂肪酶及碳酸氢盐"},{"q":"下列哪种情况，是呼吸商降低的主要因素","o":["酸中毒","碱中毒","肺过度通气","糖转变为脂肪","剧烈运动"],"a":1,"e":"碱中毒时呼吸受抑制、二氧化碳排出减少，而机体耗氧量不变，故呼吸商降低。酸中毒时呼吸加深加快、二氧化碳排出增多，呼吸商升高；肺过度通气同样使二氧化碳排出增多；糖转变为脂肪时释放二氧化碳较多，剧烈运动时乳酸与二氧化碳增加，均使呼吸商升高"},{"q":"幼儿排便反射常发生在进餐后，这种情况下引起结肠收缩的原因是","o":["胃-回肠反射","胃-结肠反射","迷走-迷走反射","内在神经丛局部反射","肠-胃反射"],"a":1,"e":"进食后食物扩张胃壁，通过壁内神经丛反射性引起结肠蠕动增强，称胃-结肠反射，故幼儿常在餐后排便。胃-回肠反射促进回肠排空；迷走-迷走反射参与胃容受性舒张；内在神经丛局部反射局限于肠段；肠-胃反射抑制胃排空"},{"q":"某肾盂结石患者出现尿量明显减少，其原因是","o":["肾小球毛细血管血压增高","肾小囊胶体渗透压增高","血浆胶体渗透压增高","血浆晶体渗透压升高","肾小囊内压升高"],"a":4,"e":"肾盂结石阻塞尿路，肾小囊内压升高，有效滤过压降低，肾小球滤过率下降而尿量减少。肾小球毛细血管血压增高使滤过增加；血浆胶体渗透压增高虽降低滤过，但非结石梗阻的直接机制；血浆晶体渗透压主要影响抗利尿激素释放"},{"q":"一天中血液生长激素分泌的最高水平出现在","o":["清晨","中午","傍晚","进食后","夜间"],"a":4,"e":"生长激素呈脉冲式分泌，深睡眠期出现分泌高峰，故一天中最高水平出现在夜间。清晨、中午、傍晚分泌水平较低；进食后主要引起胰岛素分泌，生长激素无明显高峰。该节律与慢波睡眠时相密切相关，有利于儿童生长发育"},{"q":"测定清除率的意义不包括","o":["反映肾对不同物质的清除能力","反映肾对各种物质的重吸收","反映肾对各种物质的分泌","清除率是检测肾功能的重要方法之一","反映肾对各种物质滤过率"],"a":4,"e":"清除率可反映肾对不同物质的清除能力、重吸收与分泌情况，是检测肾功能的重要方法，但不能直接反映肾对各种物质的滤过率。滤过率需用菊粉清除率等特定物质的清除率测定，故该表述不属于测定清除率的意义"},{"q":"牵张刺激可以引起以下哪种肌肉收缩","o":["子宫","虹膜肌","主动脉","输精管","竖毛肌"],"a":0,"e":"子宫平滑肌对牵张刺激敏感，妊娠末期子宫被胎儿牵张可引发收缩，属牵张反射。虹膜肌受神经调节，主动脉为弹性组织，输精管与竖毛肌受自主神经支配，均不因牵张刺激而收缩。子宫平滑肌对牵张、温度和化学刺激均敏感，其中牵张最易引发收缩"},{"q":"有髓神经纤维的传导特点是","o":["单向传导","传导速度慢","衰减性传导","跳跃式传导","离子跨膜运动总数多、耗能多"],"a":3,"e":"有髓神经纤维的髓鞘有绝缘作用，兴奋在有髓鞘的朗飞结之间呈跳跃式传导，速度快、耗能少。传导具有双向性而非单向；无髓纤维才表现为传导慢和衰减性传导；跳跃式传导使跨膜离子运动总数少，故耗能少而非多"},{"q":"肺有效通气量是指","o":["潮气量","肺活量","时间肺活量","肺泡通气量","肺总容量"],"a":3,"e":"肺有效通气量指肺泡通气量，即每分钟进入肺泡并与血液进行气体交换的量，等于（潮气量减无效腔气量）乘呼吸频率。潮气量、肺活量、肺总容量为静态肺容量，时间肺活量为动态肺容量指标，均不反映有效通气量"},{"q":"脊髓前角γ-运动神经元的功能主要是","o":["抑制α-运动神经元的活动","直接兴奋α-运动神经元","提高肌梭的敏感性","发动肌牵张反射","抑制肌牵张反射"],"a":2,"e":"γ-运动神经元支配肌梭内的梭内肌纤维，兴奋时使梭内肌收缩、提高肌梭的敏感性，从而增强牵张反射。它不直接兴奋α-运动神经元，也不发动牵张反射，牵张反射由α-运动神经元发动；其对牵张反射是增强而非抑制"},{"q":"优势半球指的是下列哪项特征占优势的一侧半球","o":["重量","运动功能","感觉功能","语言活动功能","皮层沟回数"],"a":3,"e":"优势半球指语言活动功能占优势的一侧半球，多为左半球，其额下回后部、颞上回后部受损后分别出现运动性失语和感觉性失语。两侧半球在重量、运动功能和感觉功能上基本对称，皮层沟回数目也无明显差别，故不以这些特征判定优势半球"},{"q":"胃酸的生理作用不包括下列哪一项","o":["杀死进入胃内的细菌","进入小肠后促进胰液和胆汁的分泌","促进维生素B12的吸收","促进钙和铁的吸收","激活胃蛋白酶原，并为胃蛋白酶提供适宜环境"],"a":2,"e":"胃酸可杀灭进入胃内的细菌、激活胃蛋白酶原并提供适宜的酸性环境，进入小肠后促进促胰液素和缩胆囊素释放而促进胰液与胆汁分泌，还促进钙和铁的吸收。维生素B12的吸收依赖胃壁细胞分泌的内因子，与胃酸无直接关系"},{"q":"肺泡与肺毛细血管血液之间的气体交换所通过的组织结构是","o":["呼吸膜","肺泡膜","肺泡上皮和毛细血管内皮","肺泡上皮，毛细血管内皮，内皮基膜","肺泡上皮，上皮基膜，毛细血管内皮基膜，毛细血管内皮"],"a":0,"e":"肺泡与肺毛细血管血液之间的气体交换通过呼吸膜，包括表面活性物质液体层、肺泡上皮、上皮基膜、间质、毛细血管基膜和内皮。肺泡膜、肺泡上皮加内皮等表述均不完整；仅列四层的选项缺少液体层和间质，故不准确"},{"q":"下列哪种因素会导致血中儿茶酚胺类激素浓度升高","o":["血糖升高","恐惧、焦虑和剧痛","慢波睡眠期","血压升高","机体清醒安静"],"a":1,"e":"恐惧、焦虑和剧痛等应激刺激通过交感神经兴奋，使肾上腺髓质释放肾上腺素和去甲肾上腺素增多。血糖升高主要引起胰岛素分泌；慢波睡眠期与清醒安静时交感活动低；血压升高经压力感受性反射抑制交感活动，使儿茶酚胺减少"},{"q":"衡量人眼调节能力大小的指标是","o":["瞳孔大小","角膜厚度","房水压力","远点","近点"],"a":4,"e":"眼通过晶状体变凸增加折光力，能看清物体的最近距离称近点，近点越近表明眼的调节能力越强。瞳孔大小、角膜厚度、房水压力不反映调节能力；远点为无需调节即可看清的最远距离，与调节能力大小无关"},{"q":"左心室和右心室相同的是","o":["心室内压","心肌收缩力","心输出量","心脏做功量","心室肌厚度"],"a":2,"e":"左、右心室串联，每分钟泵出的血量相等，故心输出量相同。左心室压力约为右心室的数倍，心肌收缩力和做功量均较大，室壁也更厚，故心室内压、收缩力、做功量与室壁厚度均不相同。右心室射血量必须与左心室相等，否则将出现肺循环或体循环淤血"},{"q":"下列选项中，能使血液中的促红细胞生成素含量增加的生理性刺激因素是","o":["缺氧","CO2潴留","雌激素","肾脏疾患","酸中毒"],"a":0,"e":"缺氧是刺激肾脏球旁细胞产生促红细胞生成素的主要生理性因素，可促进红细胞生成。二氧化碳潴留与酸中毒不是主要刺激因素；雌激素可抑制红细胞生成；肾脏疾患使促红细胞生成素生成减少，而非刺激其增加"},{"q":"舞蹈病的病变部位在","o":["黑质","纹状体","脑干网状结构","中脑上、下丘之间","小脑后叶"],"a":1,"e":"舞蹈病的病变部位在纹状体，表现为不自主的舞蹈样动作。黑质病变引起帕金森病；脑干网状结构损伤影响觉醒与肌张力；在中脑上、下丘之间切断引起去大脑僵直；小脑后叶病变引起共济失调。纹状体属锥体外系，参与运动协调"},{"q":"在心动周期中，心室内压最高的时期是","o":["等容收缩期末","快速射血期末","减慢射血期末","快速充盈期末","减慢充盈期末"],"a":1,"e":"快速射血期心室肌强烈收缩，心室内压急剧升高，并在期末达到最高，随后射血减慢、压力下降。等容收缩期末压力尚在上升途中；减慢射血期与快速充盈期、减慢充盈期的心室内压均明显低于快速射血期"},{"q":"下列哪一种因素促进胃的排空","o":["扩张十二指肠","十二指肠内渗透压升高","十二指肠内的脂肪浓度升高","十二指肠内的酸刺激","胃内食物的机械和化学刺激"],"a":4,"e":"胃内食物的机械扩张和化学刺激可增强胃蠕动、促进胃排空。十二指肠扩张、十二指肠内渗透压升高、脂肪浓度升高及酸刺激均通过肠-胃反射抑制胃运动，延缓胃排空。胃排空速度还与食物性状有关，液体快于固体，糖类快于蛋白质，脂肪最慢"},{"q":"与非自律细胞相比，自律细胞生物电活动主要特征是","o":["0期去极速度快","4期膜电位不稳定，自动去极","1期复极速度慢","3期复极速度慢","2期复极速度慢"],"a":1,"e":"自律细胞4期膜电位不稳定，可自动去极化达阈电位，是自动节律性的基础。0期去极速度及1期、2期、3期复极速度的差异不是自律细胞与非自律细胞的主要区别，工作心肌细胞同样具有完整的去极与复极过程"},{"q":"可作为有机磷中毒解救的药物是","o":["阿托品","鱼精蛋白","普萘洛尔","筒箭毒碱","酚妥拉明"],"a":0,"e":"有机磷中毒抑制胆碱酯酶，使乙酰胆碱蓄积，阿托品阻断M受体可缓解腺体分泌增多、支气管痉挛等毒蕈碱样症状。鱼精蛋白拮抗肝素，普萘洛尔阻断β受体，筒箭毒碱阻断N2受体，酚妥拉明阻断α受体，均不针对胆碱酯酶抑制"},{"q":"临床上，外科医生不轻易切除小肠，特别是十二指肠和空肠上段，即使切除也不能超过50%，其主要原因是","o":["小肠回盲括约肌的功能","小肠具有分节运动","小肠是食物消化和吸收的重要部位","小肠内胰液的化学性消化","十二指肠腺和肠腺是重要的消化腺"],"a":2,"e":"小肠是食物消化和吸收的最重要部位，切除过多将导致严重的营养吸收障碍，故外科尽量保留，尤其十二指肠和空肠上段。回盲括约肌功能、分节运动、胰液的化学性消化及十二指肠腺均非不能大量切除的根本原因"},{"q":"在动物实验中，对动物进行假饲后，引起胃液分泌的特点是","o":["量大、酸度高、消化力弱","量大、酸度低、消化力强","量大，酸度高、消化力强","量少、酸度低、消化力弱","量少、酸度高、消化力强"],"a":2,"e":"假饲通过食物刺激口咽部引起迷走神经兴奋，胃液分泌量大、酸度高、消化力强，属头期胃液分泌。量少或酸度低均不符合头期特点；消化力弱见于胃期部分情况，头期胃液中胃蛋白酶原含量高，消化力强"},{"q":"慢性肾病时出现组织水肿的主要原因是","o":["毛细血管血压增高","血浆胶体渗透压降低","组织液静水压降低","组织液胶体渗透压增高","血浆晶体渗透压降低"],"a":1,"e":"慢性肾病时白蛋白随尿丢失，血浆胶体渗透压降低，有效滤过压升高，组织液生成增多而形成水肿。毛细血管血压增高多见于右心衰竭；组织液静水压降低不是主因；血浆晶体渗透压降低引起细胞水肿，而非组织水肿"},{"q":"与肾近端小管重吸收葡萄糖关系密切的转运过程是","o":["Na+的主动重吸收","K+的主动重吸收","H+的分泌","Cl-的被动重吸收","氨基酸的重吸收"],"a":0,"e":"近端小管重吸收葡萄糖依赖钠泵建立的Na+浓度梯度，经Na+-葡萄糖同向转运体进行继发性主动转运，故与Na+的主动重吸收密切相关。钾重吸收、氢离子分泌、氯离子被动重吸收及氨基酸重吸收均不直接驱动葡萄糖转运"},{"q":"一个肌钙蛋白亚单位TnC亚单位可结合的钙离子数是","o":["2","3","4","5","6"],"a":2,"e":"每个肌钙蛋白TnC亚单位可结合4个Ca2+，Ca2+结合后使TnC构象改变、原肌球蛋白移位，暴露肌动蛋白上的结合位点，触发横桥摆动。2个、3个、5个、6个均与TnC的实际结合位点数不符；TnI为抑制亚单位，TnT负责与肌钙蛋白结合"},{"q":"非弹性阻力主要成分是","o":["气道阻力","肺泡表面张力","黏滞阻力","肺回缩力","惯性阻力"],"a":0,"e":"非弹性阻力包括气道阻力、黏滞阻力和惯性阻力，其中气道阻力约占80%～90%，为主要成分。肺泡表面张力与肺回缩力属弹性阻力；黏滞阻力与惯性阻力所占比例很小，故非弹性阻力的主要成分是气道阻力"},{"q":"通常所说的血型是指","o":["红细胞膜上特异性受体类型","血浆中特异性凝集素类型","血浆中特异性凝集原类型","红细胞膜上特异性凝集原类型","红细胞膜上特异性凝集素类型"],"a":3,"e":"血型通常指红细胞膜上特异性凝集原即抗原的类型，如A抗原、B抗原和D抗原，据此将血液分为不同型别。凝集素是血浆中的抗体，其类型由凝集原决定；受体类型与血型无关；凝集原位于红细胞膜上而非血浆中。临床输血须同时核查红细胞凝集原与血浆凝集素"},{"q":"膜内外Na+和K+浓度梯度的维持是由于","o":["膜在安静时对K+通透性大","膜在兴奋时对Na+通透性大","Na+和K+易化扩散的结果","膜上Na+-K+泵的作用","细胞膜上载体的作用"],"a":3,"e":"膜上Na+-K+泵逆浓度梯度将Na+泵出细胞、K+泵入细胞，维持膜内外的钠钾浓度梯度。安静时K+通透性大与兴奋时Na+通透性大是梯度存在的结果和表现；易化扩散顺梯度进行，不能建立梯度；载体转运也不逆梯度耗能"},{"q":"心室肌的后负荷为","o":["心房压力","快速射血期心室内压","减慢射血期心室内压","等容收缩期初心室内压","大动脉血压"],"a":4,"e":"心室肌的后负荷指心室射血时遇到的阻力，即大动脉血压。心房压力影响心室充盈，属前负荷；快速射血期与减慢射血期的心室内压是心肌收缩产生的结果；等容收缩期初心室内压为舒张末期压力。后负荷增大时每搏输出量减少"},{"q":"心交感神经节前纤维起源于","o":["星状神经节","脊髓中间外侧柱","延髓疑核","延髓背核","延髓孤束核"],"a":1,"e":"心交感神经节前纤维起自脊髓胸段中间外侧柱，在星状神经节等交感神经节换元后，节后纤维支配心脏。星状神经节为节后神经元所在部位；延髓疑核和背核发出迷走副交感节前纤维；孤束核为内脏感觉传入的核团"},{"q":"胸膜腔内压等于","o":["大气压+跨肺压","大气压+肺回缩力","大气压-肺回缩力","胸内压+跨胸壁压","大气压-肺内压"],"a":2,"e":"胸膜腔内压等于大气压减去肺回缩力，以大气压为零时即为负的肺回缩力。跨肺压为肺内压与胸膜腔内压之差；胸内压加跨胸壁压无此关系；大气压减肺内压为肺内外的压差，不是胸膜腔内压。胸膜腔负压有利于静脉血和淋巴液回流"},{"q":"传导速度最慢的神经纤维是","o":["C类纤维","B类纤维","Aα纤维","Aγ纤维","Aβ纤维"],"a":0,"e":"神经纤维的传导速度与直径和髓鞘有关。C类纤维无髓鞘、直径最细，传导速度最慢，仅约0.6～2m/s。B类纤维为自主神经节前纤维，有髓鞘；Aα、Aβ、Aγ均为有髓纤维，传导速度快，其中Aα纤维最粗、传导最快，故最慢者为C类纤维"},{"q":"下列关于机体运动时血压升高，心输出量增加的原因描述，哪一项是错误的","o":["交感神经兴奋","心肌收缩力增强","前负荷增加","后负荷增加","回心血量增加"],"a":3,"e":"运动时交感神经兴奋、心肌收缩力增强、回心血量增加使前负荷增大，心输出量增加、血压升高。后负荷增加会阻碍射血、降低每搏输出量，不是血压升高和心输出量增加的原因，故为错误项。前负荷增大则使每搏输出量增加"},{"q":"当血浆蛋白含量显著减少时，可引起","o":["血浆胶体渗透压明显升高","组织液生成减少","组织水肿","淋巴液回流减少","血浆晶体渗透压降低"],"a":2,"e":"血浆蛋白含量显著减少时胶体渗透压降低，有效滤过压升高，组织液生成增多而出现组织水肿。胶体渗透压不会升高；组织液生成减少与实际情况相反；淋巴回流随组织液增多而增加；晶体渗透压主要由电解质决定，不受血浆蛋白明显影响"},{"q":"在心动周期中，心室充盈主要依靠","o":["地心引力的作用","骨骼肌挤压和静脉瓣的共同作用","心房收缩的作用","心室舒张的负压抽吸作用","胸膜腔内负压的作用"],"a":3,"e":"心室舒张时室内压迅速下降形成负压，对心房和静脉血产生抽吸作用，是心室充盈的主要动力。地心引力、骨骼肌挤压与静脉瓣主要促进静脉回流；心房收缩仅提供约25%的充盈量；胸膜腔负压辅助静脉回流而非直接充盈心室"},{"q":"血液凝固的发生是由于","o":["纤维蛋白溶解","凝血酶的激活","纤维蛋白原变为纤维蛋白","凝血因子Ⅷ的激活","血小板聚集与红细胞叠连"],"a":2,"e":"血液凝固的本质是纤维蛋白原在凝血酶作用下转变为纤维蛋白，形成血凝块。纤维蛋白溶解是纤溶过程；凝血酶激活是凝血的中心环节但非最终结果；因子Ⅷ激活参与内源性途径；血小板聚集与红细胞叠连不形成纤维蛋白"},{"q":"下列因素中，不能引起心输出量增加的是","o":["焦虑","运动","贫血","妊娠","代谢性酸中毒"],"a":4,"e":"代谢性酸中毒时氢离子抑制心肌收缩力、降低心肌对儿茶酚胺的反应性，并使外周血管扩张，心输出量不增加甚至降低。焦虑、运动、贫血、妊娠分别通过交感兴奋、代谢需求增加或血容量增多使心输出量增加"},{"q":"人体功能活动的整合调控机制是","o":["神经调节","体液调节","自身调节","免疫调节","以上均正确"],"a":4,"e":"人体功能活动受神经调节、体液调节和自身调节共同整合，免疫系统也参与其中，故以上均正确。神经调节快速准确，体液调节缓慢持久，自身调节局限于局部，三者协同完成整体功能的调控。三者相互配合，使机体功能活动保持协调"},{"q":"机体发生酸中毒时，有关血钾变化描述正确的是","o":["降低","升高","不变","先降低后升高","先升高后降低"],"a":1,"e":"酸中毒时细胞外氢离子进入细胞，细胞内钾离子移出，同时肾小管泌氢增多、排钾减少，故血钾升高。碱中毒时相反，血钾降低；血钾不变或先降后升、先升后降均不符合酸中毒时的典型变化。故酸中毒时常伴高钾血症"},{"q":"小肠蠕动的特点是","o":["速度较快，约5cm/s","回肠蠕动的速度大于十二指肠","通常只进行一段短距离","空腹时无蠕动波","有赖于外来神经支配"],"a":2,"e":"小肠蠕动速度慢，约0.5～2cm/s，每个蠕动波只将食糜推进一段短距离。十二指肠蠕动速度快于回肠；空腹时仍有周期性移行性复合运动；蠕动的发生主要依赖壁内神经丛，切断外来神经后仍可进行"},{"q":"食物或食物残渣在消化道内停留时间最长的部位是","o":["胃","十二指肠","空肠和回肠","结肠","直肠"],"a":3,"e":"食物或食物残渣在结肠停留时间最长，可达十余小时，主要完成水分和电解质的吸收并形成粪便。胃停留数小时，小肠停留时间较短，直肠仅在排便前短暂储存粪便。结肠内细菌还能合成维生素B复合物和维生素K，故停留时间最长者为结肠"},{"q":"正常人动脉血液中血红蛋白的氧饱和度约为","o":["100%","97%","87%","77%","67%"],"a":1,"e":"正常人动脉血氧分压约100mmHg，血红蛋白氧饱和度约97%～98%。100%为理论最大值，实际因少量溶解氧和生理性分流而达不到；87%、77%、67%分别提示不同程度的低氧血症"},{"q":"浦肯野细胞不具有的生理特性是","o":["兴奋性","自律性","传导性","收缩性","有效不应期长"],"a":3,"e":"浦肯野细胞属特殊传导系统，具有兴奋性、传导性和自律性，但无收缩性，因其胞质内肌原纤维稀少。其有效不应期长是心肌细胞的共同特点；收缩性由心房肌、心室肌等工作心肌细胞具有。浦肯野细胞的功能是快速传导兴奋，保证心室肌同步收缩"},{"q":"安静时膜电位处于内负外正的状态，称为","o":["极化","去极化","复极化","超极化","反极化"],"a":0,"e":"安静时膜内为负、膜外为正的状态称极化，是静息电位的基础。去极化指膜内负值减小，复极化为恢复极化状态，超极化为膜内负值增大，反极化为膜内变正、膜外变负。极化状态由膜两侧离子分布不均及安静时膜对钾的通透性较高所决定"},{"q":"调节远曲小管和集合管对水重吸收的激素是","o":["抗利尿激素","醛固酮","肾上腺素","心房钠尿肽","缓激肽"],"a":0,"e":"抗利尿激素由下丘脑视上核和室旁核合成，作用于远曲小管和集合管的水通道，促进水重吸收。醛固酮调节钠重吸收和钾分泌；肾上腺素主要作用于心血管；心房钠尿肽促进钠水排出；缓激肽舒张血管。该激素又称血管升压素，大剂量时还可收缩血管"},{"q":"颈动脉窦和主动脉弓压力感受性反射的生理意义是","o":["降低动脉血压","升高动脉血压","减弱心血管活动","加强心血管活动","维持动脉血压相对恒定"],"a":4,"e":"压力感受性反射在血压升高时抑制心血管活动、使血压回降，血压降低时则相反，故其意义是维持动脉血压相对恒定，属负反馈调节。单向降低或升高血压、单纯减弱或加强心血管活动均不能概括其缓冲意义"},{"q":"健康成年男性在安静状态下的心输出量约为","o":["2～3L/min","4、5～6L/min","10～15L/min","20～25L/min","30～35L/min"],"a":1,"e":"健康成年男性安静时每搏输出量约70ml，心率约75次/分，心输出量约5L/min，即4.5～6L/min。2～3L/min偏低，10～15L/min为剧烈运动时水平，20L/min以上为运动极限或病理状态"},{"q":"窦房结细胞动作电位0期去极化是由于","o":["Na+电导增加","Na+电导降低","Ca2+电导增加","Ca2+电导降低","K+电导增加"],"a":2,"e":"窦房结细胞0期去极化由L型钙通道开放、Ca2+内流引起，故为Ca2+电导增加。其0期不被河豚毒素阻断，Na+电导变化不是主因；K+电导增加引起复极和4期自动去极化中的K+外流衰减，与0期去极化无关"},{"q":"在体内，主要用于供能的营养物质是","o":["糖与脂肪","糖与蛋白质","脂肪与蛋白质","脂肪与核酸","糖、脂肪与蛋白质"],"a":0,"e":"糖与脂肪是体内主要供能物质，糖供能约占50%～70%，脂肪是主要储能形式，氧化1g脂肪释放的能量约为糖的两倍。蛋白质主要在糖和脂肪耗竭时供能，核酸不供能，故仅含蛋白质或含核酸的组合均不准确，供能以糖和脂肪为主"},{"q":"健康成年男性静息状态下，心输出量约为","o":["2～3L/min","4、5～6L/min","6、5～8L/min","7、5～9L/min","9～10L/min"],"a":1,"e":"健康成年男性静息时每搏输出量约70ml，心率约75次/分，心输出量约5L/min，位于4.5～6L/min区间。2～3L/min偏低，6.5L/min以上偏高，7.5～10L/min多见于运动或病理状态"},{"q":"胃的容受性舒张是通过下列哪种途径实现的","o":["交感神经释放的去甲肾上腺素","迷走神经释放的乙酰胆碱","迷走神经释放的肽类物质或一氧化氮","壁内神经释放的生长抑素","肠-胃反射"],"a":2,"e":"胃容受性舒张由食物刺激咽和胃壁感受器，经迷走神经传入和传出，末梢释放血管活性肠肽或一氧化氮，使胃底、胃体平滑肌舒张。乙酰胆碱引起收缩；去甲肾上腺素为交感递质；生长抑素抑制分泌；肠-胃反射抑制胃运动"},{"q":"决定肺换气和组织换气方向的主要因素是","o":["气体分压差","气体分子量大小","呼吸膜的通透性","气体溶解度","扩散系数"],"a":0,"e":"肺换气和组织换气均以扩散方式进行，扩散方向由气体分压差决定。分子量、溶解度、扩散系数影响扩散速率，呼吸膜通透性影响交换效率，但均不决定扩散方向，故决定方向的主要因素是分压差。分压差越大，气体扩散速率越快"},{"q":"损伤动物下丘脑外侧区可引致","o":["动物拒食","动物多食","动物饮水增多","动物饮水减少","动物拒食和饮水减少"],"a":4,"e":"下丘脑外侧区为摄食中枢和饮水中枢所在，损伤后动物拒食、饮水减少。腹内侧核为饱中枢，损伤后动物多食；单纯饮水增多或减少不能概括该损伤的表现；拒食伴饮水增多与损伤部位不符。摄食中枢与饱中枢相互制约，共同调节摄食行为"},{"q":"迷走神经兴奋引起胰液分泌的特点是","o":["碳酸氢盐和酶的含量丰富","水分和碳酸氢盐的含量少，酶的含量丰富","水分多，碳酸氢盐和酶的含量也丰富","碳酸氢盐多，水分和酶的含量少","水分和碳酸氢盐的含量多，酶的含量少"],"a":1,"e":"迷走神经兴奋直接促进胰液分泌，其特点是水分和碳酸氢盐含量少、酶含量丰富。促胰液素引起水和碳酸氢盐多、酶少；缩胆囊素引起酶丰富而水盐少，但迷走神经作用与之不完全相同；水盐与酶均丰富不符合迷走神经的效应"},{"q":"临床上作胆囊造影时，为检查胆囊的收缩功能，让受试者进食油煎荷包蛋是为了促进","o":["胆盐的合成","胆固醇的合成","迷走神经的兴奋","缩胆囊素的分泌","促胃液素的分泌"],"a":3,"e":"油煎荷包蛋含大量脂肪，进入十二指肠后刺激Ⅰ细胞释放缩胆囊素，使胆囊收缩、Oddi括约肌舒张，故用于检查胆囊的收缩功能。胆盐与胆固醇合成反映肝脏功能，迷走神经兴奋和促胃液素分泌不是引起胆囊收缩的主要机制"},{"q":"下列关于蒸发散热的叙述，不正确的是","o":["以蒸发水分的形式散热","与发汗有关","与不感蒸发有关","蒸发1g水可带走2、43kJ的热量","与气温、湿度无关"],"a":4,"e":"蒸发散热受气温和湿度影响，气温高、湿度大时汗液不易蒸发，散热效率下降，故与气温湿度无关的表述错误。蒸发分不感蒸发和发汗两种形式，均以水分为载体，1g水蒸发可带走约2.43kJ的热量"},{"q":"关于睾酮的作用描述，下列哪一项是不正确的","o":["刺激男性生殖器官的生长发育和性征的出现","维持生精","维持和提高性欲","促进红细胞生成","促进水钠排出"],"a":4,"e":"睾酮由睾丸间质细胞分泌，促进男性生殖器官发育与第二性征出现，维持生精和性欲，并刺激促红细胞生成素生成而使红细胞增多。促进水钠排出是心房利尿钠肽的作用，醛固酮与雌激素则引起水钠潴留"},{"q":"下列关于甲状腺的描述，哪一项是错误的","o":["是人体最大的内分泌腺体","主要分泌甲状腺激素","激素贮存在甲状腺腺上皮内","甲状腺激素包括T3和T4","甲状腺激素能显著影响基础代谢率"],"a":2,"e":"甲状腺是人体最大的内分泌腺，主要分泌T4和T3，激素以甲状腺球蛋白形式贮存于腺泡腔的胶质中，并能显著提高基础代谢率。激素贮存部位是腺泡腔内胶质，而非腺上皮细胞内；甲状腺激素也不以胞内颗粒形式储存"},{"q":"血小板磷脂酶A2激活后可产生的物质是","o":["血小板活化因子","ADP","TXA2","cAMP","组胺"],"a":2,"e":"血小板磷脂酶A2水解膜磷脂生成花生四烯酸，后者经环加氧酶和血栓烷合酶作用生成TXA2，TXA2是强烈的血小板聚集剂和缩血管物质。ADP由血小板致密颗粒释放，cAMP为腺苷酸环化酶产物且抑制聚集，组胺主要来自肥大细胞"},{"q":"下列哪种原因会引起便意","o":["横结肠粪便积聚","降结肠粪便积聚","乙状结肠粪便积聚","粪便进入直肠","粪便刺激肛门"],"a":3,"e":"粪便进入直肠刺激壁内感受器，经盆神经传入引起便意和排便反射。横结肠、降结肠和乙状结肠充盈只引起结肠蠕动增强，不产生便意；肛门受刺激引起的是局部不适，并非便意。直肠壁内感受器对粪便充盈敏感，是触发便意的关键部位"},{"q":"脊髓灰质炎患者发生肢体肌肉萎缩的主要原因是","o":["病毒的直接侵害","患肢肌肉血供减少","失去神经的营养性作用","患肢长期废用","脊髓失去高位中枢的控制"],"a":2,"e":"支配骨骼肌的运动神经末梢持续释放神经营养因子，维持肌纤维结构和代谢；脊髓前角细胞受损后肌肉失去神经营养作用，出现明显萎缩。长期废用引起的是废用性萎缩，程度较轻；病毒侵害的是前角运动神经元而非肌纤维，血供减少不是主因"},{"q":"心室肌细胞动作电位各时期跨膜电位变化不包括","o":["1期复极化","2期平台期","0期去极化","3期复极化","4期自动去极化"],"a":4,"e":"心室肌动作电位分0、1、2、3、4期，4期为稳定的静息电位，无自动去极化。4期自动去极化是窦房结、浦肯野等自律细胞的特征；1期由Ito钾外流介导，2期平台由钙内流与钾外流共同形成"},{"q":"关于唾液的生理作用，下列哪项是错误的","o":["可湿润与溶解食物，使食物便于吞咽，并引起味觉。","可清除口腔中的食物残渣","可对蛋白质初步分解","可冲淡、中和、清除进入口腔的有害物质","可把淀粉分解为麦芽糖"],"a":2,"e":"唾液含唾液淀粉酶，可把淀粉分解为麦芽糖，但不含蛋白酶，不能分解蛋白质。蛋白质的初步分解由胃蛋白酶在胃内完成；湿润溶解食物、清除残渣、冲淡中和有害物质均属唾液的正常作用。唾液呈中性偏酸，含溶菌酶和免疫球蛋白，兼具抗菌作用"},{"q":"阿司匹林具有抗血小板聚集作用，是因为阿司匹林可抑制血小板的","o":["磷脂酶A2","环加氧酶","血栓烷合酶","前列环素合酶","过氧化物酶"],"a":1,"e":"阿司匹林不可逆抑制血小板环加氧酶，阻断花生四烯酸生成TXA2，从而抑制血小板聚集。磷脂酶A2位于环加氧酶上游，不是阿司匹林的靶点；血栓烷合酶只催化PGH2转变为TXA2，前列环素合酶存在于血管内皮"},{"q":"心房肌的电生理特性是","o":["有自律性，无传导性","有传导性，无自律性，传导速度较慢","有传导性，有自律性，自律性较高","有传导性，有自律性，自律性较低","有传导性，无自律性，传导速度较快"],"a":1,"e":"心房肌具有传导性但无自律性，其传导速度约0.4m/s，慢于心室肌和浦肯野纤维。自律性见于窦房结、房室交界和浦肯野细胞；心房肌传导又快于房室交界，故也不是传导最慢的部位。心房肌无自律性，故不会成为异位起搏点"},{"q":"内脏痛与皮肤痛比较，主要特点是","o":["刺痛，定位明确","钝痛，定位不精确","对切割刺激敏感","对牵拉不敏感","常伴轻微的情绪反应"],"a":1,"e":"内脏痛多为钝痛、烧灼痛，定位不精确，对牵拉、缺血和痉挛敏感，对切割烧灼不敏感，常伴明显情绪反应。刺痛且定位明确是皮肤痛的特点，皮肤痛对切割刺激敏感，而内脏痛对牵拉敏感。内脏痛的传入纤维多为C类，主要经交感神经传入"},{"q":"在自动控制系统中，从受控部分发出到达控制部分的信息称为","o":["偏差信息","干扰信息","控制信息","反馈信息","自控信息"],"a":3,"e":"反馈信息由受控部分发出并返回控制部分，用以纠正偏差。控制信息由控制部分发向受控部分，如迷走神经传出冲动；偏差信息是参考信息与反馈信息之差，干扰信息来自内外环境的扰乱因素。反馈分负反馈与正反馈，前者维持稳态，后者加速过程"},{"q":"兴奋在中枢的传播比在外周神经纤维上复杂，可表现为","o":["传播速度慢","在单位时间内传播距离远","在每个神经元之间的传播方式都不同","在传播过程中都会经过几十个突触","传播机制是电-机械-化学-电模式"],"a":0,"e":"中枢内兴奋经突触传递，存在突触延搁，故传播速度明显慢于外周神经纤维。外周神经纤维传导快、单位时间传播距离远；中枢传播并非每个神经元之间方式都不同，也非必经几十个突触。突触延搁使反射弧中枢部分耗时最长"},{"q":"迷走神经传出纤维上的神经冲动可看作","o":["反馈信息","控制信息","受控系统","控制系统","干扰信息"],"a":1,"e":"迷走神经传出纤维把中枢的指令送到心脏，属控制部分发出的控制信息。反馈信息由受控的心血管系统返回；受控系统指心脏和血管本身；干扰信息指扰乱调节过程的内外因素。传出神经冲动既可为兴奋性指令，也可为抑制性指令"},{"q":"细胞的胞质内不含致密体的组织是","o":["心室肌","子宫平滑肌","睫状肌","输精管平滑肌","主动脉平滑肌"],"a":0,"e":"心室肌属横纹肌，胞质内无致密体；致密体是平滑肌细胞内细肌丝的附着结构。子宫平滑肌、睫状肌、输精管平滑肌和主动脉平滑肌均有致密体，心肌则以Z线固定细肌丝。致密体相当于平滑肌的Z线，与细肌丝和中间丝相连"},{"q":"临床上常用t-PA应用于心肌梗死、脑梗死等血栓性疾病，该类药物治疗的生理机制是","o":["激活血液中的抗凝血酶Ⅲ，发挥抗凝作用","激活血液中纤溶酶原激活物","刺激肥大细胞产生肝素，发挥抗凝作用","刺激肝脏合成蛋白质C，灭活凝血因子，发挥抗凝作用","激活纤溶酶原，使纤维蛋白发生降解"],"a":4,"e":"t-PA激活纤溶酶原转变为纤溶酶，纤溶酶降解纤维蛋白，使血栓溶解。抗凝血酶Ⅲ是肝素发挥抗凝作用的辅因子；肝素由肥大细胞产生；蛋白质C的激活依赖凝血酶-血栓调节蛋白复合物。尿激酶与链激酶同属纤溶酶原激活物，作用机制相同"},{"q":"下列哪一项不是生长激素的作用","o":["抑制组织细胞利用葡萄糖","促进蛋白质的合成","促进脑的发育","促进软骨生长","促进脂肪分解"],"a":2,"e":"生长激素促进软骨生长、蛋白质合成和脂肪分解，抑制组织利用葡萄糖而使血糖升高；脑的发育主要依赖甲状腺激素。甲状腺激素才是一生中促进脑发育的关键激素，生长激素经胰岛素样生长因子介导促生长，并不促进脑发育"},{"q":"以下关于钠泵生理作用的叙述，错误的是","o":["逆浓度差将进入细胞内的Na+移出膜外","顺浓度差使细胞膜外的K+转入膜内","使细胞超极化","建立离子势能储备","是神经、肌肉等组织具有兴奋性的基础"],"a":1,"e":"钠泵每分解1分子ATP，逆浓度差将3个Na+移出、2个K+移入，形成离子势能储备，并因生电性使膜超极化，是神经肌肉兴奋性的基础。顺浓度差使K+入胞的描述与泵的逆梯度特性矛盾，超极化与势能储备则是钠泵的正确作用"},{"q":"下列关于小肠运动调节的叙述，正确的是","o":["交感神经兴奋，肠运动加强","副交感神经兴奋，肠运动减弱","肌间神经丛起主要作用","对扩张刺激不敏感","对化学刺激不敏感"],"a":2,"e":"小肠运动主要受肌间神经丛调控，其兴奋使纵行肌与环行肌协调收缩。交感兴奋抑制肠运动，副交感兴奋增强肠运动；小肠对扩张和化学刺激均敏感，牵张可引发蠕动反射。黏膜下神经丛主要调节分泌和血流，对运动影响小"},{"q":"红细胞比容是指红细胞","o":["与血清容积之比","与血浆容积之比","在血液中所占容积百分比","在血液中所占重量百分比","与血浆所占重量之比"],"a":2,"e":"红细胞比容指红细胞在血液中所占的容积百分比，正常男性40%～50%，女性37%～48%。与血浆容积之比、与血清容积之比都混淆了分母；重量百分比不是血细胞比容的定义。比容增大见于红细胞增多症，减小见于贫血"},{"q":"后负荷突然增加会引起","o":["心室肌缩短程度增加","心室肌缩短速度加快","搏功减少","射血速度加快","心室内剩余血量增加"],"a":4,"e":"后负荷突然增加时射血阻力增大，心室肌缩短速度减慢、缩短程度减小，搏出量减少而收缩末室内剩余血量增多。后负荷持续升高时搏功反而增大，故搏功减少不是主要表现；射血速度是减慢而非加快。剩余血量增多使初长度增加，经异长自身调节增强收缩"},{"q":"心交感神经节后纤维末梢释放的递质主要与下列哪一种受体结合","o":["M受体","N受体","α受体","β1受体","β2受体"],"a":3,"e":"心交感神经节后纤维释放去甲肾上腺素，主要作用于心肌β1受体，产生正性变力、变时和变传导效应。M受体是迷走神经释放ACh的靶点；α受体主要介导血管收缩，β2受体介导支气管和骨骼肌血管舒张"},{"q":"下列关于舒血管神经的叙述，正确的是","o":["体内血管主要接受舒血管神经的支配","副交感舒血管神经主要支配骨骼肌血管","对循环系统的总外周阻力影响较大","主要调节所支配器官的血流量","始终存在紧张性活动"],"a":3,"e":"舒血管神经纤维只支配特定器官，兴奋时使该器官血流量增加，对总外周阻力影响很小。体内多数血管只接受缩血管神经支配；副交感舒血管纤维主要分布在唾液腺、胃肠和外生殖器，并非骨骼肌，且平时无紧张性活动"},{"q":"关于肺通气阻力的描述，错误的是","o":["肺通气阻力来自弹性和非弹性阻力","弹性阻力来自肺组织和胸廓","非弹性阻力主要来自呼吸道气流的摩擦","同样压力下，弹性阻力大则表示顺应性亦大","肺的顺应性过分减小或过分增大，对呼吸均不利"],"a":3,"e":"弹性阻力与顺应性成反比，同样压力下弹性阻力越大则顺应性越小，说弹性阻力大顺应性也大是颠倒了两者关系。肺的弹性阻力来自肺组织与胸廓，非弹性阻力以气道摩擦为主，二者共同构成通气阻力。顺应性以单位压力变化所引起的容积变化表示"},{"q":"深呼气末较平静呼气末","o":["肺内压绝对值不变","肺内压绝对值增加","胸内压绝对值不变","胸内压绝对值增加","肺内压绝对值减小"],"a":0,"e":"无论平静呼气末还是深呼气末，气流停止时肺内压均与大气压相等，以大气压为零则两者绝对值都是零。深呼气末肺容积更小、肺弹性回缩力更弱，胸膜腔内压负值减小而非绝对值增大。吸气时肺内压低于大气压，呼气时高于大气压"},{"q":"中枢内兴奋传递时必须通过的结构是","o":["轴突","树突","神经纤维","突触","胞体"],"a":3,"e":"中枢内神经元之间的信息传递依赖突触，突触是兴奋传递的必需结构。轴突、树突和胞体是神经元的组成部分，单独不构成传递环节；神经纤维传导的是同一细胞内的冲动。突触前膜释放递质，突触后膜产生突触后电位"},{"q":"血液进出心腔按方向流动取决于","o":["重力作用","心室肌收缩","心房心室依次收缩","压力差与瓣膜开启","心房收缩"],"a":3,"e":"血液进出心腔由压力差推动，瓣膜随压力差被动开启或关闭，从而保证单向血流。心室肌收缩是产生压力差的动力，不是直接决定流向的因素；心房收缩只提供心室充盈的末段动力，重力仅在特定体位下起作用"},{"q":"下列选项中，不属于血浆蛋白组成成分的是","o":["白蛋白","α1球蛋白","β球蛋白","γ球蛋白","纤维蛋白"],"a":4,"e":"血浆蛋白包括白蛋白、球蛋白和纤维蛋白原，纤维蛋白是凝血酶作用下纤维蛋白原转变而成的多聚体，不属血浆蛋白成分。γ球蛋白属球蛋白组分，α1、β球蛋白同样在列；纤维蛋白原才是血浆中的正常蛋白"},{"q":"以下关于抑制素的描述，哪一项是错误的","o":["由睾丸支持细胞分泌","是含氮类激素","对促卵泡激素分泌有很强的抑制作用","对黄体生成素分泌有很强的抑制作用","由两个亚单位组成"],"a":3,"e":"抑制素由睾丸支持细胞分泌，属含氮类激素，由α、β两个亚单位组成，对腺垂体FSH分泌有很强的负反馈抑制作用。它对LH分泌的抑制很弱，LH主要受睾酮负反馈调节。抑制素减少FSH释放，从而抑制生精上皮的活动"},{"q":"下列凝血因子不属于蛋白质的是","o":["因子Ⅰ","因子Ⅱ","因子Ⅲ","因子Ⅳ","因子Ⅴ"],"a":3,"e":"凝血因子Ⅳ是钙离子，属无机离子；因子Ⅰ、Ⅱ、Ⅲ、Ⅴ等均为蛋白质。因子Ⅲ即组织因子，是跨膜糖蛋白；因子Ⅴ是辅因子蛋白；因子Ⅰ为纤维蛋白原。因子Ⅳ即Ca2+，参与内源性和外源性凝血的多个环节，也是凝血酶原酶复合物的组分"},{"q":"下列关于消化道平滑肌基本电节律的叙述，哪一项是错误的","o":["在消化道平滑肌不收缩的情况下，也可记录到基本电节律","其波幅和频率与平滑肌组织在消化道中所处的位置无关","起源于纵行肌和环形肌层之间的Cajal间质细胞","其产生可能是肌源性的","是动作电位产生的基础"],"a":1,"e":"基本电节律的波幅和频率随消化道部位而异，胃约3次/分，十二指肠约11～12次/分，故与部位无关的说法错误。基本电节律由Cajal间质细胞产生，属肌源性，不依赖平滑肌收缩而存在，是动作电位产生的基础"},{"q":"在急慢性肾小球肾炎时，出现蛋白尿是由于","o":["肾小球滤过率增加","滤过膜通透性降低","滤过膜的唾液（涎）蛋白减少","小管液溶质浓度增高","肾小球血浆流量增多"],"a":2,"e":"肾炎时滤过膜电荷屏障受损，带负电的涎蛋白减少，白蛋白易滤出而形成蛋白尿。滤过膜通透性降低会减少蛋白滤出；肾小球滤过率增加和血浆流量增多不改变屏障选择性；小管液溶质浓度增高影响的是水的重吸收"},{"q":"有些人饮用牛奶后出现腹胀、腹痛、腹泻、排气增加，原因是由于缺乏","o":["蛋白酶","纤维素酶","乳糖酶","淀粉酶","脂肪酶"],"a":2,"e":"牛奶含乳糖，乳糖酶缺乏者乳糖不能被水解吸收，进入结肠被细菌发酵产气，引起腹胀、腹痛和腹泻。蛋白酶、淀粉酶和脂肪酶分别水解蛋白质、淀粉和脂肪；人体不分泌纤维素酶，纤维素本就不被消化"},{"q":"浦肯野细胞动作电位2期内向电流电化学驱动力是","o":["Na+浓度差势能","K+浓度差势能","Ca2+浓度差势能","K+平衡电位势能","Ca2+平衡电位势能"],"a":2,"e":"浦肯野细胞2期平台的内向电流由L型钙通道介导，其电化学驱动力取决于膜电位与钙平衡电位之差，即钙的浓度差势能。钠电流主要在0期，钾电流是2期的外向成分；钙平衡电位是驱动力为零的电位值，本身不是驱动力"},{"q":"下列生理活动中，属于负反馈调节的是","o":["减压反射","排尿反射","血液凝固","分娩","射乳反射"],"a":0,"e":"减压反射在血压升高时经压力感受器加强心迷走、抑制心交感，使血压回降，是典型的负反馈。排尿反射、分娩和射乳反射均为正反馈；血液凝固一旦启动也以正反馈方式加速。正反馈使原效应不断加强，直至该生理过程完成"},{"q":"迷走神经兴奋时，下列说法错误的是","o":["胃平滑肌收缩","肠道平滑肌收缩","胰液分泌增加","胃液分泌增加","胃肠道括约肌收缩"],"a":4,"e":"迷走神经兴奋使胃、肠平滑肌收缩增强，胃液和胰液分泌增加，同时使胃肠道括约肌舒张，故括约肌收缩的说法错误。胃液分泌增加由迷走促胃液素释放介导，胰液分泌增加亦为其作用；括约肌在交感兴奋时收缩"},{"q":"在动物实验中，将脂肪注入动物的十二指肠会引起","o":["肠胃反射，导致胃排空加速","胰液分泌增加","胆汁分泌减少","胃液分泌增加","小肠液分泌减少"],"a":1,"e":"脂肪进入十二指肠刺激Ⅰ细胞释放缩胆囊素，促使胰酶分泌增多，同时引起胆囊收缩。脂肪使胆汁排放增加而非减少；脂肪抑制胃排空而非加速；小肠液分泌以局部刺激为主，不因脂肪而减少。缩胆囊素同时增强小肠和结肠的运动"},{"q":"肺通气的原动力来自","o":["肺的舒缩运动","肺的弹性回缩","呼吸肌的舒缩","胸内负压的周期性变化","肺内压与胸内压之差"],"a":2,"e":"呼吸肌的舒缩引起胸廓扩大与缩小，造成肺内压与大气压之间的压力差，是肺通气的原动力。肺内压与大气压之差是直接动力；肺弹性回缩力是呼气时的被动动力；胸内负压变化是结果而非原动力。呼吸运动由膈肌和肋间外肌的节律性收缩完成"},{"q":"关于使静脉回心血量增加的因素，叙述错误的是","o":["深吸气","体力活动加强","心肌收缩力增强","体位从卧位变成立位","循环系统平均充盈压升高"],"a":3,"e":"由卧位转为立位时血液受重力作用滞留于下肢，静脉回心血量减少，故不属于增加回心血量的因素。深吸气使胸内负压增大、体力活动增强肌肉泵作用、心肌收缩力增强均使回心血量增加；循环系统平均充盈压升高同样使其增多"},{"q":"肾小管中对水易通透而对Na+不易通透的部位是","o":["髓袢升支细段","髓袢升支粗段","髓袢降支细段","髓袢降支粗段","远曲小管"],"a":2,"e":"髓袢降支细段对水通透而对Na+、尿素等溶质通透性很低，水被重吸收而溶质留在管内，小管液被浓缩。升支细段对水不通透而对NaCl通透；升支粗段主动重吸收NaCl且对水不通透；远曲小管受醛固酮和ADH调节"},{"q":"皮肤触压觉的传入神经纤维属于","o":["Aα纤维","Aβ纤维","Aγ纤维","B类纤维","C类纤维"],"a":1,"e":"皮肤触压觉由Aβ纤维传入，该纤维直径粗、有髓鞘、传导速度快。Aα纤维支配骨骼肌牵张感受器；Aγ纤维为梭内肌传出纤维；C类纤维传导慢，主要传递痛温觉。Aβ纤维传导速度约30～90m/s，故触压觉定位精细"},{"q":"下列关于快波睡眠时相的描述中，哪一项是错误的","o":["快波睡眠又称为异相睡眠","骨骼肌反射运动和肌紧张进一步减弱","各种感觉功能进一步减退","可观察到血压升高和心率加快，呼吸加快","快波睡眠每晚只出现一次"],"a":4,"e":"快波睡眠在整个睡眠中反复出现，成人每晚约4～6次，并非只出现一次。异相睡眠期肌紧张进一步降低、感觉功能减退、血压升高且心率呼吸加快，均属其特点；生长激素分泌增多见于慢波睡眠。快波睡眠与慢波睡眠每夜交替约4～5个周期"},{"q":"平滑肌收缩过程中胞内钙离子的主要来源是","o":["细胞外钙离子内流","肌质网内钙离子释放","肌质网膜上钙泵的转运","肌钙蛋白与大量钙离子解离","与钙调蛋白结合的钙离子解离释放"],"a":0,"e":"内脏平滑肌肌质网不发达，收缩时胞质Ca2+主要来自细胞外经L型钙通道内流。肌质网释放的Ca2+在心肌和骨骼肌中占主导；钙泵是把Ca2+泵回肌质网或排出胞外的转运体，不构成钙的来源"},{"q":"作为感受器官，人的耳属于","o":["听觉、位置觉和平衡觉器官","听觉和平衡觉器官","听觉器官","位置觉器官","平衡觉器官"],"a":0,"e":"耳包括外耳、中耳和内耳，耳蜗感受声音，前庭器官感受位置与平衡，故耳是听觉、位置觉和平衡觉器官。仅称听觉器官忽略了前庭功能；位置觉与平衡觉由同一前庭器官承担，并非两个独立器官。外耳和中耳负责传音，内耳兼具传音与感音功能"},{"q":"在折光异常情况中，视远物和视近物都需要眼进行调节的是","o":["老视","近视","远视","散光","近视和散光"],"a":2,"e":"远视眼因眼球前后径过短或折光力过弱，平行光线聚焦于视网膜后，视远物时也需调节，视近物时调节更为加强。近视视远不需调节而视近需调节；老视是晶状体弹性下降；散光由角膜或晶状体曲率不均所致"},{"q":"从器官和系统水平研究的生命活动是","o":["食物在胃肠内消化与吸收","神经细胞的生物电活动","航天环境对机体功能的影响","心肌细胞的收缩机制","神经骨骼肌接头的兴奋传递"],"a":0,"e":"器官和系统水平研究完整器官的活动，食物在胃肠内的消化与吸收属消化道这一系统的功能。心肌细胞收缩机制和神经-骨骼肌接头传递属细胞分子水平，神经细胞生物电活动属细胞水平，航天环境对机体的影响属整体水平"},{"q":"分娩前没有乳汁分泌，其原因是","o":["缺乏缩宫素","催乳素浓度过低","催乳素受体不足","血中雌孕激素浓度过高","血中雌孕激素浓度过低"],"a":3,"e":"妊娠期血中雌激素、孕激素水平很高，抑制催乳素的泌乳作用，故乳腺虽已发育成熟却不泌乳。妊娠期催乳素水平并不低，分娩时达高峰；催乳素受体在分娩后增加约20倍，此前并非受体不足；缩宫素主要参与射乳"},{"q":"体液调节的特点包括","o":["迅速","精确","持久","短暂","起作用快"],"a":2,"e":"体液调节通过激素经血液运输，作用出现较慢但持续时间较长。迅速、精确、作用短暂是神经调节的特点；体液调节定位性差，起效也不快。激素经组织液扩散或经血液运输作用于靶细胞，反应速度慢于神经冲动"},{"q":"当细胞外Ca2+浓度降低时，心肌收缩的变化为","o":["收缩降低","舒张减慢","收缩增强","舒张增快","传导增快"],"a":0,"e":"细胞外Ca2+是心肌兴奋-收缩耦联的触发物，血钙降低使钙内流减少、肌浆Ca2+不足，收缩力减弱。血钙升高才使收缩增强；舒张速度主要取决于钙泵和Na+-Ca2+交换体对Ca2+的清除，与收缩降低无对应关系"},{"q":"神经纤维动作电位的上升支是由于","o":["K+内流","K+外流","Na+内流","Na+外流","Cl-外流"],"a":2,"e":"动作电位上升支由电压门控钠通道开放、Na+快速内流形成，膜电位由-90mV升至+30mV左右。K+外流形成下降支即复极相；Cl-外流不是神经纤维动作电位的主要离子流。钠通道在去极达阈电位后大量开放，形成再生性循环"},{"q":"小肠上皮细胞吸收速度最快的糖是","o":["果糖","甘露糖","半乳糖","木糖","核糖"],"a":2,"e":"己糖吸收快于戊糖，己糖中以半乳糖和葡萄糖最快，二者经SGLT-1与Na+耦联进行继发性主动转运。果糖次之，经GLUT5易化扩散；甘露糖最慢；木糖和核糖属戊糖，吸收很慢。葡萄糖与半乳糖共用同一载体，故两者吸收速度相近"},{"q":"关于心电图的叙述，不正确的是","o":["反映心肌机械收缩过程","P波反映兴奋在心房传导过程中电位变化","QRS波反映兴奋在心室传导中电位变化","T波反映心室肌复极过程中的电位变化","P-R间期代表窦房结的兴奋由心房到达心室所需的时间"],"a":0,"e":"心电图记录心肌兴奋过程中体表的电位变化，反映兴奋的起源、传导与恢复，不反映机械收缩。P波、QRS波分别反映心房和心室去极化的电位变化，T波反映心室复极，P-R间期代表兴奋由心房传到心室的时间"},{"q":"高血钙时导致慢反应细胞传导性增高的原因","o":["膜对Ca2+的通透性增大","膜对Na+的通透性增大","膜对K+的通透性增大","0期去极加快加强","Ca2+通道复活加快"],"a":3,"e":"慢反应细胞0期去极依赖L型钙通道，高血钙使钙内流增多，0期去极速度和幅度增大，传导性增高。膜对钾通透性增大使膜电位负值增大、传导减慢；钙通道复活加快影响4期和自律性，不直接加强0期去极"},{"q":"静脉注射大剂量的去甲肾上腺素引起尿量减少的主要原因是","o":["肾小囊内压升高","滤过膜通透性降低","肾小球滤过面积减少","血浆胶体渗透压升高","肾小球毛细血管血压降低"],"a":4,"e":"大剂量去甲肾上腺素强烈收缩肾入球小动脉，肾小球毛细血管血压明显下降，有效滤过压降低，尿量减少。血浆胶体渗透压升高见于大量输注白蛋白；肾小囊内压升高见于尿路梗阻；滤过膜通透性与滤过面积改变不由此介导"},{"q":"在突触传递过程中，突触前膜去极化可促使","o":["Na+内流","K+外流","Mg2+内流","Ca2+内流","Cl-内流"],"a":3,"e":"动作电位到达突触前膜使其去极化，电压门控钙通道开放，Ca2+内流触发囊泡与前膜融合并释放递质。Na+内流产生的是动作电位本身；K+外流参与复极；Mg2+抑制递质释放而非触发释放。递质释放量与Ca2+内流量呈正变关系"},{"q":"临床上治疗消化道疾病，服用阿托品以后，会出现口干现象。下列哪一项是其产生的原因","o":["使唾液分泌非条件反射不能完成","使唾液分泌的条件反射消失","引起唾液腺功能暂时消失","阻断唾液腺N受体，唾液分泌减少","阻断唾液腺M受体，唾液分泌减少"],"a":4,"e":"阿托品阻断唾液腺M胆碱受体，副交感的促分泌作用被阻断，唾液减少而出现口干。N受体位于神经-肌接头和神经节，阻断后表现为肌无力而非口干；唾液腺本身功能并未消失，唾液分泌反射弧也未中断"},{"q":"O型血的红细胞膜上有","o":["A抗原","B抗原","O抗原","H抗原","E抗原"],"a":3,"e":"O型红细胞缺乏A、B抗原，但保留H抗原，H抗原是A、B抗原的前体物质。O抗原并不存在，O型只是按缺乏A、B抗原命名；E抗原本不属于ABO血型系统。H抗原由岩藻糖基转移酶催化生成，O型者H抗原暴露最多"},{"q":"听觉感受器位于","o":["椭圆囊","半规管","基底膜","球囊","鼓膜"],"a":2,"e":"听觉感受器是位于基底膜上的螺旋器毛细胞，基底膜振动使毛细胞纤毛弯曲而完成换能。椭圆囊和球囊感受直线加速度与位置，半规管感受旋转变速；鼓膜是传音结构而非感受器。毛细胞顶部纤毛与盖膜接触，基底膜振动使其剪切弯曲"},{"q":"影响正常人收缩压最主要的因素是","o":["循环血量","每搏输出量","心率","外周阻力","大动脉弹性"],"a":1,"e":"每搏输出量决定收缩期进入主动脉的血量，是影响收缩压最主要的因素，搏出量增大时收缩压明显升高。外周阻力主要影响舒张压；心率加快使舒张压升高更明显；大动脉弹性主要影响脉压；循环血量是基础条件"},{"q":"Hb氧饱和度的大小主要取决于血液中的","o":["PO2","PN2","PCO2","Hb含量","pH值"],"a":0,"e":"Hb氧饱和度主要取决于PO2，二者呈氧解离曲线关系，PO2升高则饱和度升高。PCO2和pH通过波尔效应改变Hb对氧的亲和力，影响曲线位置而非饱和度；Hb含量影响的是血氧含量。氧解离曲线呈S形，上段平坦，中段陡峭"},{"q":"骨骼肌产生强直收缩的刺激条件是","o":["足够强度和持续时间的单刺激","足够强度的单刺激","足够强度和时间变化率的单刺激","间隔大于单收缩收缩期的连续阈刺激","间隔小于单收缩收缩期的连续阈刺激"],"a":4,"e":"连续刺激的间隔短于单收缩的收缩期时，各次收缩发生融合，形成强直收缩。间隔大于收缩期只产生单收缩或收缩的总和；单刺激无论强度多大只引起一次单收缩；刺激强度只决定是否达到阈值。强直收缩的张力大于单收缩，因胞质Ca2+持续升高"},{"q":"胆碱能Ｍ型受体的阻断剂是","o":["阿托品","普萘洛尔","酚妥拉明","河豚毒素","筒箭毒"],"a":0,"e":"阿托品阻断M胆碱受体，是M受体阻断剂。普萘洛尔阻断β受体，酚妥拉明阻断α受体；筒箭毒阻断N2受体，河豚毒素阻断钠通道。M受体激动可产生腺体分泌增加、平滑肌收缩、瞳孔缩小和心率减慢等效应，阿托品可全部拮抗"},{"q":"下列哪一个不是神经纤维兴奋传导的特征","o":["双向传导","绝缘性","易疲劳","结构完整","功能完整"],"a":2,"e":"神经纤维传导兴奋具有双向性、绝缘性、相对不疲劳性和结构功能完整性，易疲劳不属于其特征。突触传递才易疲劳，因递质耗竭所致；双向传导和绝缘性均为神经纤维的特点。神经纤维连续兴奋虽消耗能量，但恢复较快"},{"q":"窦房结细胞最大复极电位的绝对值变小，是由于它的细胞膜对下列哪种离子的电导降低","o":["K+","Na+","Cl-","Ca2+","Ca2+和Na+"],"a":0,"e":"窦房结细胞最大复极电位取决于IK外流，IK衰减使K+电导降低，膜电位负值减小、绝对值变小。Na+和Ca2+内流增强影响的是4期自动去极速度；Cl-电导变化不参与最大复极电位的形成"},{"q":"对心室肌细胞有效不应期特征的叙述，错误的是","o":["此期可产生局部兴奋","阈上刺激能引起动作电位","相当于心室收缩期+舒张早期","此期持续时间较长","此期等于绝对不应期+局部反应期"],"a":1,"e":"有效不应期内任何强度的刺激都不能再引起动作电位，故阈上刺激能引起动作电位的说法错误。该期相当于心室收缩期加舒张早期，历时较长；局部反应期只能产生局部兴奋，不能产生动作电位。不应期长使心肌不会像骨骼肌那样发生强直收缩"},{"q":"内源性凝血过程一般开始于","o":["组织细胞释放因子Ⅲ","血小板聚集","接触激活因子Ⅻ","Ca2＋的参与","因子X的激活"],"a":2,"e":"内源性凝血由因子Ⅻ接触带负电表面而被激活启动，随后依次激活Ⅺ、Ⅸ、Ⅷ等因子。组织细胞释放因子Ⅲ启动的是外源性途径；血小板聚集提供磷脂表面，Ca2+是辅因子，因子Ⅹ激活处于共同途径"},{"q":"睡眠的产生是由于","o":["脑干网状结构上行抑制系统的作用","脑干网状结构上行激动系统的作用","下丘脑的情绪反应中枢兴奋","迷走-胰岛素系统兴奋","小脑皮质兴奋引起"],"a":0,"e":"睡眠由脑干网状结构上行抑制系统活动增强、上行激动系统活动减弱所致。上行激动系统兴奋维持觉醒，其作用被阻断才入睡；下丘脑情绪中枢、迷走-胰岛素系统与小脑均不决定睡眠的发生。上行激动系统主要经丘脑非特异投射维持皮质觉醒"},{"q":"神经冲动抵达末梢时，引起递质释放主要依赖于下列哪种离子的作用","o":["Na+","Cl-","Mg2+","Ca2+","K+"],"a":3,"e":"神经冲动抵达末梢引起Ca2+内流，胞质Ca2+升高促使突触小泡与前膜融合，以出胞方式释放递质。Na+内流与K+外流维持动作电位；Mg2+抑制递质释放；Ca2+是耦联刺激与分泌的关键离子"},{"q":"以下关于可兴奋细胞动作电位的描述，正确的是","o":["动作电位是细胞受刺激时出现的快速而不可逆的电位变化","在动作电位的去极相，膜电位由内正外负变为内负外正","动作电位的大小不随刺激强度和传导距离而改变","动作电位的传导距离随刺激强度的大小而改变","不同的细胞，动作电位的幅度都相同"],"a":2,"e":"动作电位具全或无特性，幅度不随刺激强度增大而增大，也不随传导距离增加而衰减。动作电位是可逆的电位变化，去极相膜电位由内负外正变为内正外负；不同细胞动作电位的幅度并不相同。动作电位沿膜不衰减传导，是细胞兴奋的标志"},{"q":"由于眼球前后径过长而导致的近视，为了使远处来自物体的平行光线能聚焦到视网膜上，可配戴合适度数的","o":["凸透镜","凹透镜","平面透镜","圆柱形透镜","棱镜"],"a":1,"e":"近视眼因眼球前后径过长，平行光线聚焦于视网膜之前，需配戴凹透镜使光线适度发散后延。凸透镜用于远视和老视；圆柱透镜矫正散光；棱镜用于矫正斜视或复视。凹透镜焦距为负值，度数按屈光度计算，使焦点后移至视网膜"},{"q":"下列有关血浆清除率的描述正确的是","o":["相对于单位时间被肾完全清除了某物质的血浆毫升数","清除血浆中一定量某物质的能力","清除一定量体液的能力","将一定容积血浆中某物质完全清除掉的能力","将血浆中某物质清除到终尿中的能力"],"a":0,"e":"血浆清除率指两肾在单位时间内能将多少毫升血浆中的某物质完全清除，单位为ml/min。它描述的是被完全清除的血浆容积，不是清除某物质的量；将某物质清除到终尿是排泄的结果而非定义。菊粉清除率可代表肾小球滤过率"},{"q":"CO2在血液中运输的主要形式是","o":["物理溶解","形成碳酸","形成碳氧血红蛋白","形成氨基甲酰血红蛋白","形成碳酸氢盐"],"a":4,"e":"CO2在血液中约88%以HCO3-形式运输，由碳酸酐酶催化CO2与水生成碳酸后解离而成。物理溶解约占5%，氨基甲酰血红蛋白约占7%；碳氧血红蛋白是CO与Hb结合，与CO2运输无关"},{"q":"通气/血流比值异常，所致肺泡与血液间气体交换不足，常表现为","o":["缺O2明显，CO2潴留不明显","缺O2不明显，CO2潴留明显","缺O2和CO2潴留都不明显","缺O2和CO2潴留不会出现","只表现为CO2潴留"],"a":0,"e":"通气/血流比值失调时氧的交换受扩散限速影响更明显，而CO2扩散系数大约为氧的20倍，潴留常被代偿，故表现为缺O2明显而CO2潴留不明显。CO2潴留明显见于肺泡通气不足；比值增大时部分肺泡通气被浪费"},{"q":"下列哪种物质不属于第二信使","o":["cAMP","DG","IP3","cGMP","AC"],"a":4,"e":"腺苷酸环化酶是催化ATP生成cAMP的效应器酶，不是第二信使。cAMP、cGMP、DG和IP3均为胞内第二信使，其中DG与IP3由磷脂酶C水解PIP2产生。激素与膜受体结合后经这些信使把信号传入细胞内"},{"q":"下列关于胃液分泌的描述哪一项是错误的","o":["主细胞分泌胃蛋白酶原","主细胞分泌内因子","壁细胞分泌盐酸","幽门腺和贲门腺分泌黏液","黏液细胞分泌黏液"],"a":1,"e":"内因子由壁细胞分泌，与维生素B12结合后便于其在回肠吸收；主细胞只分泌胃蛋白酶原。盐酸由壁细胞分泌，黏液由黏液细胞及贲门腺、幽门腺分泌，均与内因子无关。壁细胞还分泌内因子，与维生素B12的吸收有关"},{"q":"心室肌细胞的有效不应期的长短主要取决于","o":["动作电位0期去极速度","动作电位1期复极速度","动作电位2期复极速度","动作电位3期复极速度","动作电位4期复极速度"],"a":2,"e":"有效不应期的长短主要取决于2期平台的持续时间，平台期延长则不应期延长，心肌因而不会发生强直收缩。0期去极速度影响传导速度；1期和3期复极速度改变动作电位时程，但决定不应期长短的关键是平台期"},{"q":"影响毛细血管前括约肌舒缩活动的主要因素是","o":["交感舒血管神经纤维末梢释放的乙酰胆碱","副交感神经末梢释放的乙酰胆碱","肾上腺髓质释放的肾上腺素","局部代谢产物增多","交感神经末梢释放去甲肾上腺素"],"a":3,"e":"毛细血管前括约肌主要受局部代谢产物浓度调节，代谢产物积聚使其舒张，血流恢复后产物被冲走又重新收缩。交感缩血管纤维主要调节阻力血管总张力；肾上腺素经β2受体舒张骨骼肌血管，但不主导局部血流分配"},{"q":"以下哪项因素可以抑制胰岛素的分泌","o":["交感神经兴奋","血中氨基酸及脂肪酸增加","胃肠激素","迷走神经兴奋","血糖升高"],"a":0,"e":"交感神经兴奋经α2受体抑制胰岛素分泌，去甲肾上腺素直接抑制胰岛B细胞。血糖升高是最强的促分泌因素；氨基酸、脂肪酸和胃肠激素均促进胰岛素释放；迷走神经兴奋也促进分泌。胰岛素是唯一降低血糖的激素，其分泌受血糖、氨基酸和神经共同调节"},{"q":"下列关于神经纤维动作电位的描述，正确的是","o":["刺激强度小于阈值时，出现低幅度的动作电位","刺激强度达到阈值时，再增加刺激强度，则动作电位的幅度随之增大","动作电位一旦产生，可沿细胞膜作电紧张传播","动作电位的大小随着传导距离的增加而变小","不同可兴奋细胞动作电位的幅度和持续时间可以不一样"],"a":4,"e":"不同可兴奋细胞的动作电位幅度和持续时间各异，心肌可达数百毫秒，神经纤维仅1～2毫秒。刺激低于阈值不产生动作电位，达阈值后再增强幅度也不再增大；动作电位不衰减传导，也不是电紧张性扩布"},{"q":"正常心电图中代表心室肌复极是","o":["P波","QRS波","T波","S-T段","P-R间期"],"a":2,"e":"T波代表心室肌复极过程的电位变化，其方向与QRS主波一致。P波反映心房去极，QRS波反映心室去极，S-T段反映动作电位平台期，P-R间期反映兴奋由心房传到心室的时间。T波方向与QRS主波方向一致，反映心室复极的不同步"},{"q":"引起神经细胞兴奋的阈电位是指细胞膜","o":["对Ca2+通透性突然增大时的临界膜电位值","对K+通透性突然减小时的临界膜电位值","对K+通透性突然增大时的临界膜电位值","对Na+通透性突然增大时的临界膜电位值","对Na+通透性突然减小时的临界膜电位值"],"a":3,"e":"阈电位是使膜上钠通道大量开放、Na+内流出现再生性循环的临界膜电位，约-70～-60mV。钾通透性降低只影响静息电位和兴奋性高低；钙通道开放与慢反应细胞0期去极有关，不构成神经细胞阈电位的定义"},{"q":"细胞内能使底物蛋白质磷酸化的酶是","o":["磷酸二酯酶","腺苷酸环化酶","蛋白激酶A","鸟苷酸环化酶","磷脂酶C"],"a":2,"e":"蛋白激酶A由cAMP激活，催化底物蛋白质的丝氨酸或苏氨酸残基磷酸化。腺苷酸环化酶催化生成cAMP，是PKA的上游酶；磷酸二酯酶降解cAMP；磷脂酶C参与DG和IP3的生成。PKA磷酸化后可调节代谢酶、离子通道和转录因子"},{"q":"关于Cl-在近端小管重吸收的描述正确的是","o":["大部分在前半段被重吸收","与HCO3-重吸收竞争转运体","主要在前半段主动重吸收","可通过细胞旁途径被动重吸收","不存在跨细胞途径重吸收"],"a":3,"e":"Cl-在近端小管主要经细胞旁途径被动重吸收，由后半段小管液Cl-浓度升高形成的浓度差驱动。前半段以Na+、葡萄糖和氨基酸重吸收为主，Cl-吸收较少；Cl-重吸收与HCO3-分泌相耦联，并非竞争同一转运体"},{"q":"下列哪种物质对胃酸的分泌没有促进作用","o":["乙酰胆碱","糖皮质激素","组胺","生长抑素","促胃液素"],"a":3,"e":"生长抑素抑制壁细胞分泌盐酸，是胃酸分泌的抑制性调节物。乙酰胆碱经M3受体、组胺经H2受体、促胃液素经CCK-B受体均促进胃酸分泌；糖皮质激素可增强胃酸分泌。胃酸分泌受乙酰胆碱、组胺、促胃液素和生长抑素共同调节"},{"q":"降钙素的主要作用是","o":["升高血钙和血磷","降低血钙和血磷","降低血钙、升高血磷","升高血钙、降低血磷","主要参与正常血钙的调节"],"a":1,"e":"降钙素抑制破骨细胞活动、减少骨钙释放，同时抑制肾小管重吸收钙和磷，使血钙、血磷均降低。升高血钙的是甲状旁腺激素和维生素D；PTH升血钙而降低血磷，与降钙素的作用方向不同。降钙素由甲状腺C细胞分泌，血钙升高时释放增多"},{"q":"将动物的外周化学感受器完全切除后","o":["动脉血PCO2升高10%，不能使呼吸发生明显变化","动脉血pH值升高，不能使呼吸发生明显变化","肌肉运动时呼吸不会加强","缺氧可通过中枢化学感受器使呼吸加强","该动物对低氧环境的适应能力显著降低"],"a":4,"e":"外周化学感受器是低氧刺激呼吸的唯一途径，切除后机体对低氧的通气反应丧失，适应低氧环境的能力显著降低。CO2仍可通过中枢化学感受器兴奋呼吸，故PCO2升高10%仍有明显效应；低氧对中枢是抑制而非兴奋"},{"q":"肿瘤压迫导致局部组织水肿的原因是","o":["血浆胶体渗透压降低","组织液静水压降低","毛细血管壁通透性增加","毛细血管血压增高","淋巴和（或）静脉回流受阻"],"a":4,"e":"肿瘤压迫淋巴管和静脉，组织液回流受阻而在组织间隙积聚，形成局部水肿。毛细血管血压增高见于心力衰竭和静脉淤血；血浆胶体渗透压降低见于低蛋白血症；通透性增加见于炎症。有效滤过压升高使组织液生成增多，回流受阻则液体在间隙积聚"},{"q":"肾小管中对Cl-是主动重吸收的部位是","o":["近曲小管","髓袢升支粗段","髓袢升支细段","髓袢降支粗段","髓袢降支细段"],"a":1,"e":"髓袢升支粗段通过Na+-K+-2Cl-同向转运体主动重吸收Cl-，是Cl-主动重吸收的主要部位。近曲小管Cl-以被动重吸收为主；髓袢降支细段对Cl-通透性低；升支细段以被动扩散为主"},{"q":"水分子快速通过细胞膜主要依靠","o":["单纯扩散","水通道","载体蛋白","非门控离子通道","水泵"],"a":1,"e":"水分子主要经水通道蛋白快速跨膜转运，该过程不耗能，属被动转运。单纯扩散通过的水量有限；载体蛋白转运葡萄糖和氨基酸；离子通道不允许水通过；哺乳动物细胞膜不存在水泵。水通道蛋白在肾小管和红细胞中分布丰富，并受ADH调节"},{"q":"异相睡眠的主要特点有","o":["脑电波呈现同步化慢波","血压下降","心率减慢","做梦","生长激素分泌明显升高"],"a":3,"e":"异相睡眠期脑电呈去同步化快波，眼球快速运动，多数梦境在此期出现。同步化慢波和生长激素分泌明显增多属慢波睡眠；异相睡眠时血压升高、心率和呼吸加快而非减慢。异相睡眠期肌电活动明显减弱，又称快速眼动睡眠"},{"q":"给家兔静脉注射一定量乳酸引起呼吸加强主要是通过","o":["刺激中枢化学感受器","刺激外周化学感受器","抑制呼吸中枢","刺激呼吸中枢","刺激中枢和外周化学感受器"],"a":1,"e":"乳酸使血浆H+浓度升高，H+不易透过血脑屏障，主要通过刺激外周化学感受器反射性加强呼吸。中枢化学感受器对脑脊液H+敏感而对血中H+反应慢；呼吸中枢受刺激不是主要途径，抑制呼吸中枢更不符合"},{"q":"凝血酶原酶复合物的组成是","o":["FⅢ-FⅦ-Ca2+-PL","FⅩ-FⅤ-Ca2+-PL","FⅡ-FⅩ-Ca2+-PL","FⅨ-FⅦ-Ca2+-PL","FⅤ-FⅧ-Ca2+-PL"],"a":1,"e":"凝血酶原酶复合物即因子Ⅹa-Ⅴ-Ca2+-磷脂复合物，催化凝血酶原转变为凝血酶。FⅢ-FⅦa-Ca2+-PL是外源性途径激活因子Ⅹ的复合物；FⅨa-Ⅷa-Ca2+-PL是内源性途径激活因子Ⅹ的复合物；因子Ⅱ是底物而非组分"},{"q":"眼折光系统的组成结构是","o":["角膜、房水、晶状体和视网膜","角膜、晶状体、玻璃体和视网膜","角膜、房水、视网膜和玻璃体","角膜、房水、晶状体和玻璃体","角膜、晶状体、玻璃体和睫状体"],"a":3,"e":"眼的折光系统由角膜、房水、晶状体和玻璃体四种折光体组成，光线经此折射成像于视网膜。视网膜是感光换能部位，不属折光体；睫状体通过改变晶状体曲率参与调节，也不是折光介质。四种折光体的折射率相差不大，折射主要发生在角膜前表面"},{"q":"原尿在肾脏被重吸收的比率约为","o":["65%","85%","89%","95%","99%"],"a":4,"e":"肾小球滤过生成的原尿约99%被肾小管和集合管重吸收，每日终尿仅1.5L左右。近端小管重吸收约65%的滤液，加上髓袢、远曲小管和集合管，总重吸收率远高于85%或95%；89%不是常用数值"},{"q":"甲状腺激素的生理功能不包括下列哪一项","o":["促进能量代谢","影响物质代谢","促进生长发育","提高中枢神经系统兴奋性","抑制心血管活动"],"a":4,"e":"甲状腺激素提高心肌对儿茶酚胺的敏感性，使心率加快、心肌收缩力增强、心输出量增加，并非抑制心血管活动。促进能量代谢、影响物质代谢、促进生长发育和提高中枢神经系统兴奋性均属其正常作用"},{"q":"引起醛固酮分泌减少的主要因素是","o":["循环血量减少","血液中K+浓度升高","血液中K+浓度降低","血浆晶体渗透压降低","血浆晶体渗透压升高"],"a":2,"e":"血K+浓度升高直接刺激肾上腺球状带分泌醛固酮，血K+浓度降低则使醛固酮分泌减少。循环血量减少经肾素-血管紧张素系统使醛固酮增多；血浆晶体渗透压改变主要影响ADH释放，不是醛固酮的主要调节因素"},{"q":"尿液的稀释主要发生在下列哪个部位","o":["髓袢升支细段","髓袢降支粗段","髓袢升支粗段","髓袢降支细段","远曲小管"],"a":4,"e":"远曲小管和集合管对水不通透，ADH缺乏时水不被重吸收，小管液进一步被稀释而形成低渗尿。髓袢升支粗段主动重吸收NaCl而对水不通透，主要参与逆流倍增和髓质高渗的形成；降支细段对水通透，属浓缩环节"},{"q":"血中激素浓度极低，但生理作用却非常显著，其原因是","o":["激素的半衰期非常长","激素的特异性很高","激素分泌的持续时间非常长","细胞内存在高效能的生物放大系统","激素在体内降解速度慢"],"a":3,"e":"激素与受体结合后经G蛋白、第二信使和酶促级联反应逐级放大，少量激素即可产生显著效应。激素半衰期短、降解快，血中浓度低正因如此；特异性只决定作用对象，不解释效应强度。即使血中浓度很低，受体结合后仍可触发显著的级联放大"},{"q":"如果在高原上吸入气PO2大于60mmHg，Hb氧饱和度水平可为","o":["40%～60%","60%～70%","70%～80%","80%～90%","90%以上"],"a":4,"e":"氧解离曲线在PO2高于60mmHg时呈平坦段，PO2略高于60mmHg时Hb氧饱和度仍可达90%以上。低于60mmHg才进入陡坡段，饱和度迅速下降；40%～60%见于严重低氧血症"},{"q":"与组织液的生成与回流无关的因素包括","o":["毛细血管血压","毛细血管血压壁通透性","血浆晶体渗透压","血浆胶体渗透压","组织液静水压"],"a":2,"e":"组织液生成与回流取决于有效滤过压，由毛细血管血压、血浆胶体渗透压、组织液静水压和组织液胶体渗透压决定，与血浆晶体渗透压无关。晶体渗透压主要维持细胞内外水平衡，其在毛细血管两侧基本相等；胶体渗透压才是主要渗透因素"},{"q":"中性粒细胞的主要功能是","o":["产生抗体","吞噬细菌","参与止血","释放组胺","参与蠕虫反应"],"a":1,"e":"中性粒细胞具有活跃的变形、趋化和吞噬能力，是急性化脓性感染时的主要吞噬细胞。产生抗体的是浆细胞，释放组胺的是嗜碱性粒细胞和肥大细胞，参与蠕虫反应的是嗜酸性粒细胞。中性粒细胞在血中停留约6～8小时，进入组织后寿命更短"},{"q":"安静时，细胞膜外正内负的稳定状态称为","o":["极化","超极化","反极化","复极化","去极化"],"a":0,"e":"安静时膜两侧保持内负外正的稳定电位差，称为极化状态。膜内负值增大称超极化，负值减小称去极化；反极化指膜电位变为内正外负。极化状态由钠泵维持的离子分布和膜的选择通透性决定，是细胞兴奋的基础"},{"q":"发汗的基本中枢位于","o":["脊髓","延髓","中脑","下丘脑","大脑皮质"],"a":3,"e":"发汗属散热反应，其基本中枢位于下丘脑，受视前区-下丘脑前部温度敏感神经元调控。脊髓和延髓参与部分整合但不是发汗的基本中枢；大脑皮质对发汗仅有行为性影响。汗腺受交感胆碱能纤维支配，温热刺激经下丘脑整合后引起全身性发汗"},{"q":"外周阻力和心率不变而每搏输出量增多时，动脉血压的变化主要是","o":["收缩压升高，脉压增大","舒张压升高，脉压变小","收缩压降低，舒张压升高","收缩压升高，舒张压降低","收缩压升高，脉压不变"],"a":0,"e":"每搏输出量增多使收缩期进入主动脉的血量增加，收缩压明显升高，舒张压升高较少，脉压增大。外周阻力增大主要升高舒张压并使脉压减小；心率加快同样以舒张压升高为主；大动脉弹性降低才使脉压增大"},{"q":"腹下神经兴奋时，将引起","o":["膀胱逼尿肌收缩","膀胱逼尿肌舒张","尿道内括约肌舒张","尿道外括约肌收缩","尿道外括约肌舒张"],"a":1,"e":"腹下神经属交感神经，兴奋时使膀胱逼尿肌舒张、尿道内括约肌收缩，促进储尿。盆神经兴奋使逼尿肌收缩、尿道内括约肌舒张而排尿；尿道外括约肌受阴部神经支配，属躯体运动控制。腹下神经起自腰骶髓，属交感神经，与盆神经的作用相互拮抗"},{"q":"下列生理过程与K+的跨膜扩散无关的是","o":["快反应细胞动作电位的3期复极化","慢反应细胞动作电位的0期去极化","快反应细胞的静息电位","快反应细胞动作电位的1期复极化","慢反应细胞动作电位的4期自动去极化"],"a":1,"e":"慢反应细胞0期去极由L型钙通道介导Ca2+内流，与K+跨膜扩散无关。快反应细胞1期由Ito钾电流介导，3期由IK钾电流介导，静息电位主要由IK1决定；慢反应细胞4期有IK衰减参与"},{"q":"下列哪种活动不是机体的排泄作用","o":["肠道排出食物残渣","结肠与直肠排出胆色素","呼吸道排出CO2","皮肤分泌的汗液","肾脏排出的尿液"],"a":0,"e":"排泄指机体将代谢终产物经血液循环由排泄器官排出，肠道排出食物残渣属排遗而非排泄。呼吸道排出CO2、皮肤分泌汗液、肾脏排出尿液均为排泄；结肠与直肠排出胆色素也属排泄途径。排泄器官包括肾、肺、皮肤和消化道，其中肾最为重要"},{"q":"平滑肌细胞中钙离子-钙调蛋白复合物的作用位点存在于","o":["致密体","肌钙蛋白与大量Ca2+解离","肌动蛋白","原肌球蛋白","肌球蛋白"],"a":4,"e":"Ca2+-钙调蛋白复合物激活肌球蛋白轻链激酶，使肌球蛋白调节轻链磷酸化，故作用位点在肌球蛋白。致密体是细肌丝的附着点，本身不是酶的作用位点；平滑肌无肌钙蛋白，原肌球蛋白不承担钙受体功能"},{"q":"对于M型受体的叙述，错误的是","o":["属于胆碱能受体","其阻断剂为阿托品","能与毒蕈碱发生特异性结合","存在于副交感神经节后纤维支配的效应器细胞膜上","存在于神经肌肉接头后膜上"],"a":4,"e":"M受体存在于副交感节后纤维支配的效应器及交感节后纤维支配的汗腺等处，神经-肌接头后膜为N2受体。M受体能与毒蕈碱特异结合，可被阿托品阻断，属胆碱能受体；N受体才是筒箭毒的阻断对象"},{"q":"骨髓中自我复制能力最强的细胞是","o":["造血干细胞","定向组细胞","前体细胞","网织红细胞","淋巴细胞"],"a":0,"e":"造血干细胞具有高度自我更新和多向分化能力，是骨髓中自我复制能力最强的细胞。定向祖细胞和前体细胞已失去自我更新能力；网织红细胞是成熟中的红细胞，淋巴细胞的分化方向受限。造血干细胞主要存在于骨髓，也可少量存在于外周血和脐血"},{"q":"引起红细胞沉降率减慢的因素是","o":["红细胞叠连增多","血浆胆固醇含量增多","血浆白蛋白含量增多","血浆球蛋白含量增多","血浆纤维蛋白原含量增多"],"a":2,"e":"血沉快慢取决于红细胞叠连，血浆白蛋白增多抑制叠连而使血沉减慢。胆固醇、球蛋白和纤维蛋白原增多均促进叠连使血沉加快；红细胞叠连增多本身就使血沉加快。血沉测定用抗凝血静置1小时读取血浆柱高度，即红细胞沉降率"},{"q":"体循环和肺循环相比，基本相同的是","o":["心脏做功量","心输出量","动脉血压","动脉血含氧量","外周阻力"],"a":1,"e":"体循环与肺循环串联，左右心室每搏输出量相等，故两循环的心输出量基本相同。体循环动脉压和外周阻力远高于肺循环，肺动脉压很低，右心做功量明显小于左心。肺循环阻力小、压力低，有利于气体交换并防止肺水肿"},{"q":"造成呼出气中CO2含量低于肺泡气的原因是","o":["潮气量","无效腔中的新鲜空气","肺泡气中的新鲜空气","补吸气量中的新鲜空气","残气量中的新鲜空气"],"a":1,"e":"呼出气由无效腔气和肺泡气混合而成，无效腔中的新鲜空气稀释了肺泡气，使呼出气CO2含量低于肺泡气。潮气量、补吸气量和残气量只是肺容积指标，不解释浓度差异；肺泡气本身CO2含量最高。无效腔容积约150ml，约占潮气量的三分之一"},{"q":"在心动周期中，房室瓣开放始于","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期初","心房收缩期末"],"a":0,"e":"等容舒张期室内压降至低于房内压时房室瓣开放，血液由心房快速流入心室，故房室瓣开放始于等容舒张期末。快速充盈期末和减慢充盈期末瓣膜早已开放；心房收缩期是心室充盈的最后助力阶段。此时室内压低于房内压，瓣膜两侧的压力差使其开放"},{"q":"下丘脑室旁核主要分泌下列哪种激素","o":["催乳素","缩宫素","生长激素","黄体生成素","促卵泡激素"],"a":1,"e":"下丘脑室旁核大细胞神经元主要分泌缩宫素，视上核以血管升压素为主。催乳素和生长激素由腺垂体分泌；黄体生成素与促卵泡激素亦为腺垂体激素，受下丘脑释放激素调控。室旁核和视上核的轴突经下丘脑-垂体束投射至神经垂体"},{"q":"胰岛素对血糖水平的调节通过以下哪种分泌方式进行","o":["自分泌","远距分泌","旁分泌","神经分泌","外分泌"],"a":1,"e":"胰岛素由胰岛B细胞分泌后经血液运输至全身靶组织发挥作用，属远距分泌。旁分泌指作用于邻近细胞，如胰岛D细胞生长抑素作用于A、B细胞；自分泌作用于分泌细胞自身；神经分泌指神经元分泌激素入血"},{"q":"能使机体功能状态保持相对稳定的是","o":["非自动控制系统","负反馈控制系统","正反馈控制系统","前馈控制系统","混合调节系统"],"a":1,"e":"负反馈使受控变量的偏差向相反方向纠正，是维持内环境稳态最主要的调节方式。正反馈使偏差进一步扩大，如分娩和血液凝固；前馈在干扰到来之前提前调节；非自动控制系统没有反馈回路。负反馈是自动控制系统中最常见的调节形式，如减压反射和血糖调节"},{"q":"心肌收缩能力的增强可通过下列哪一途径实现","o":["增加参与收缩的肌纤维数目","增加肌小节的初长度","增加兴奋时肌浆内Ca2+浓度","心肌发生完全强直收缩","降低主动脉的血压水平"],"a":2,"e":"心肌收缩能力取决于兴奋-收缩耦联中胞质Ca2+水平和肌钙蛋白对Ca2+的敏感性，增加肌浆Ca2+可直接增强收缩。心肌细胞数目固定，不能靠增加参与收缩的肌纤维数目增强收缩；心肌不发生完全强直收缩；初长度属异长自身调节"},{"q":"α受体的阻断剂是","o":["阿托品","普萘洛尔","筒箭毒","河豚毒素","酚妥拉明"],"a":4,"e":"酚妥拉明阻断α肾上腺素能受体，使血管舒张、血压下降。普萘洛尔阻断β受体，阿托品阻断M受体，筒箭毒阻断N2受体，河豚毒素阻断钠通道。酚妥拉明阻断α受体后血管舒张，可用于嗜铬细胞瘤的诊断和高血压危象的处理"},{"q":"在动物实验中，按压家兔双侧颈动脉窦可引起","o":["心率加快","心肌收缩力减弱","外周血管收缩","心交感神经活动增强","心迷走神经活动减弱"],"a":1,"e":"压迫颈动脉窦使压力感受器传入冲动增多，经减压反射使心迷走紧张增强、心交感紧张减弱，心肌收缩力减弱、心率减慢。心率加快、外周血管收缩和心交感活动增强均与减压反射效应相反。血压下降时该反射减弱，交感紧张回升，属负反馈调节"},{"q":"心动周期中，主动脉压最高见于","o":["心房收缩期末","等容收缩期末","快速射血期末","减慢射血期末","等容舒张期末"],"a":2,"e":"快速射血期心室肌强烈收缩，室内压超过主动脉压，血液快速射入主动脉，主动脉压达最高值。等容收缩期主动脉瓣尚未开放；减慢射血期室内压已下降；等容舒张期主动脉压已回落。此时主动脉压约达120mmHg，随后进入减慢射血期而略降"},{"q":"钙通道阻断剂维拉帕米对浦肯野细胞动作电位的影响是","o":["0期除极幅度降低","0期除极速度减慢","1期复极时程缩短","2期复极时程缩短","3期复极时程缩短"],"a":3,"e":"维拉帕米阻断L型钙通道，减少2期内向钙电流，使平台期缩短、动作电位时程缩短。浦肯野细胞0期由快钠通道介导，钙通道阻断剂对其影响小；1期由Ito决定，3期以钾电流为主。维拉帕米因此减慢房室传导，临床用于室上性心动过速"},{"q":"脑电波的形成机制是大量皮层神经元发生","o":["动作电位","诱发电位","兴奋性突触后电位","抑制性突触后电位","突触后电位同步总和"],"a":4,"e":"脑电波由大量皮质神经元的突触后电位同步总和形成，呈节律性电位变化。单个神经元的动作电位时程太短且不同步，不能形成脑电节律；诱发电位是特定刺激引起的局部反应。皮质神经元排列整齐、同步活动，是形成节律性电位的基础"},{"q":"交感和副交感神经节前纤维释放的递质是","o":["肾上腺素","去甲肾上腺素","乙酰胆碱","肾上腺素和去甲肾上腺素","乙酰胆碱和去甲肾上腺素"],"a":2,"e":"交感和副交感神经节前纤维均释放乙酰胆碱，作用于神经节N1受体。去甲肾上腺素是多数交感节后纤维的递质；肾上腺髓质分泌肾上腺素和去甲肾上腺素入血，并非节前纤维的递质。节后纤维则不同，副交感节后释放ACh，多数交感节后释放去甲肾上腺素"},{"q":"中医学在古代生理学阶段作出卓越贡献的著作是","o":["本草纲目","黄帝内经","金匮要略","伤寒杂病论","千金要方"],"a":1,"e":"《黄帝内经》系统论述藏象、经络、气血等理论，奠定中医生理学基础。本草纲目属药物学著作；伤寒杂病论与金匮要略重在辨证论治；千金要方为方书。《难经》补充了脉学内容，《诸病源候论》偏重病因病机，成书均晚于《内经》"},{"q":"体温调节中枢在","o":["下丘脑","中脑","延髓","脊髓","大脑皮质"],"a":0,"e":"体温调节的基本中枢在下丘脑，视前区-下丘脑前部含温度敏感神经元，能整合温度信息并调节产热与散热。延髓含呼吸和心血管等基本中枢；脊髓只完成部分反射整合；大脑皮质参与行为性体温调节。调定点学说认为该区神经元群决定体温的调定水平"},{"q":"窦房结能成为心脏正常起搏点的原因是","o":["4期自动去极速度慢","阈电位与最大复极电位差距大","0期去极速度低","自律性高","动作电位无明显平台期"],"a":3,"e":"窦房结P细胞4期自动去极速度快、最大复极电位绝对值小，自律性最高，故成为心脏正常起搏点。4期去极慢、阈电位与最大复极电位差距大都会降低自律性；0期去极速度低和无平台期是慢反应细胞的一般特点"},{"q":"调节毛细血管前括约肌舒缩活动的主要因素是","o":["交感神经末梢释放去甲肾上腺素","交感副交感神经末梢释放乙酰胆碱","血管紧张素","组织的局部代谢产物","肾上腺髓质释放的肾上腺素"],"a":3,"e":"毛细血管前括约肌的舒缩主要受局部代谢产物如腺苷、CO2、H+和乳酸浓度调节，代谢产物增多使其舒张。交感缩血管纤维主要调节阻力血管总张力；血管紧张素使血管收缩；肾上腺素经β2受体舒张骨骼肌血管但不主导局部调节"},{"q":"下列能够促进胆汁分泌的因素是","o":["血管活性肠肽","生长抑素","促胰液素","抑胃肽","神经降压素"],"a":2,"e":"促胰液素作用于胆管上皮细胞，促进水和HCO3-分泌，使胆汁量和碳酸氢盐含量增加。生长抑素、抑胃肽和神经降压素均抑制胆汁分泌；血管活性肠肽主要促进小肠液分泌，对胆汁的作用弱于促胰液素"},{"q":"安静时微循环中真毛细血管网的状态是","o":["经常关闭","经常开放","持续关闭","持续开放","交替开放"],"a":4,"e":"安静时微循环中真毛细血管网交替开放，同一时间内仅约20%开放，其开闭由局部代谢产物调节。经常或持续关闭使组织缺血；全部持续开放则大量血液淤滞于毛细血管，回心血量减少。微循环的血流分配主要靠毛细血管前括约肌的开闭完成"},{"q":"下列关于吞咽的叙述，错误的是","o":["是一个复杂的反射活动","可分为口腔期、咽期和食管期","是一个条件反射的过程","可以随意发动","吞咽时软腭上升，咽喉壁向前突出"],"a":2,"e":"吞咽是复杂的反射活动，第一期口腔期可由意识随意发动，但整个过程并非条件反射。吞咽分口腔期、咽期和食管期，咽期由延髓吞咽中枢控制而不可随意；吞咽时软腭上升封闭鼻咽，咽后壁向前突出。食管期靠食管蠕动和重力把食团送入胃内"},{"q":"在氧分压较低的高原上，呼吸将代偿性增强，这主要依赖于下列何种感受器对呼吸中枢的兴奋作用","o":["颈动脉窦压力感受器","颈动脉体化学感受器","主动脉弓压力感受器","主动脉体化学感受器","延髓化学感受器"],"a":1,"e":"高原低氧主要刺激颈动脉体化学感受器，经窦神经传入兴奋呼吸中枢，使呼吸代偿性加深加快。颈动脉窦和主动脉弓压力感受器感受血压变化；主动脉体的作用弱于颈动脉体；低氧对延髓中枢是抑制而非兴奋"},{"q":"孕激素的作用不包括下列哪一项","o":["使子宫内膜产生分泌期变化为受精卵着床做准备","抑制子宫平滑肌收缩","促进乳腺腺泡发育","抑制能量代谢过程使体温降低","使血管和消化道平滑肌紧张性降低"],"a":3,"e":"孕激素使基础体温升高0.3～0.5℃，通过影响下丘脑体温调节中枢使散热减少，故使体温降低的说法错误。使子宫内膜转化为分泌期、抑制子宫平滑肌收缩、促进乳腺腺泡发育、降低血管和消化道平滑肌张力均属其作用"},{"q":"下列哪种细胞合成雄激素结合蛋白","o":["生精细胞","支持细胞","基底细胞","睾丸内皮细胞","间质细胞"],"a":1,"e":"雄激素结合蛋白由曲细精管的支持细胞合成，与雄激素结合以维持曲细精管内高浓度睾酮。间质细胞合成和分泌睾酮本身；生精细胞是发育中的精子细胞；基底细胞属上皮支持成分，不合成雄激素结合蛋白"},{"q":"关于局部兴奋的特征，叙述错误的是","o":["电位大小随刺激强度而改变","可总和","无不应期","有全或无现象","衰减性传导"],"a":3,"e":"局部兴奋由阈下刺激引起，其幅度随刺激强度改变，可总和、无不应期、呈电紧张性衰减扩布，不存在全或无现象。全或无是动作电位的特征；局部兴奋不能沿膜远距离传导，也不会在到达阈电位前自行增大"},{"q":"下列关于心肌与骨骼肌的不同的描述，哪项是正确的","o":["只有心肌是由肌小节组成的","只有骨骼肌的收缩机制可用滑行理论解释","从心肌的长度-曲线关系中，看不出最适初长","骨骼肌的收缩是有等级性的，而心肌的收缩是“全或无”的","只有骨骼肌有粗、细两种肌丝"],"a":3,"e":"骨骼肌以运动单位为单位分级募集，收缩强度随参与肌纤维数目改变；心肌经闰盘形成功能合胞体，收缩呈全或无。心肌同样由肌小节构成，收缩也符合滑行理论；心肌长度-张力关系同样存在最适初长"},{"q":"房室交界区传导减慢可致","o":["P波增宽","QRS波群增宽","T波增宽","P-R间期延长","ST段延长"],"a":3,"e":"房室交界区传导速度慢，兴奋经此延搁时间延长，心电图上表现为P-R间期延长。P波增宽反映心房去极时间延长；QRS波群增宽反映心室传导障碍；T波改变反映心室复极异常。房室交界传导速度仅约0.02m/s，是兴奋传导最慢的部位"},{"q":"在动物中脑四叠体间横断脑干时，呼吸的变化是","o":["呼吸节律基本正常","呈节律性喘息式呼吸","出现深而慢的呼吸","出现长吸式呼吸","呼吸停止"],"a":0,"e":"在中脑四叠体之间横断脑干，延髓呼吸中枢保留完整，呼吸节律基本正常。长吸式呼吸见于脑桥中部以上横断；喘息式呼吸见于延髓受损；深而慢的呼吸为中枢抑制表现；呼吸停止需累及延髓。该动物血压与呼吸均基本维持，说明延髓是呼吸节律的基本中枢"},{"q":"副交感神经节前纤维释放的递质是","o":["ACh","NE","5-HT","ACh和NE","NE和5-HT"],"a":0,"e":"副交感神经节前纤维释放乙酰胆碱，作用于神经节N1受体。去甲肾上腺素是多数交感节后纤维的递质；5-羟色胺为中枢递质，不参与自主神经节的传递。交感与副交感节前纤维均为胆碱能纤维，节后纤维则因部位而异"},{"q":"下列关于甲状腺激素代谢的描述，哪一项是正确的","o":["T4代谢比T3快","T4主要在肝内代谢","T4代谢后可转变为T3","T4在外周组织代谢较少","T4与T3不能在肾脏代谢"],"a":2,"e":"T4在周围组织经脱碘酶转变为活性更强的T3，是其代谢的重要去路，故该项正确。T4半衰期约7天，长于T3的1.5天，A项所谓T4代谢比T3快与之相反。T4主要在外周组织代谢转变，D项说外周代谢较少属错误。肝、肾均参与其代谢，E项称不能在肾脏代谢站不住"},{"q":"房-室延搁的生理意义是","o":["使心房、心室不会同时收缩","使心室肌有效不应期延长","增强心肌收缩力","使心室肌不会产生完全强直收缩","降低心肌的收缩力"],"a":0,"e":"房室延搁使心房兴奋传至心室时心房收缩已结束，心房、心室依次收缩，保证心室充盈。心室肌有效不应期延长源于心肌本身电生理特性，B项归因子宫房延搁不成立。心室不产生完全强直收缩是不应期长的结果，D项属另一机制。C、E所述收缩力变化并非延搁的生理意义"},{"q":"血小板减少导致皮肤出现自发性出血斑点的主要原因是","o":["血小板不能聚集成团","血小板不能释放足够的血管活性物质","不能修复和保持血管内皮细胞完整性","血凝块回缩障碍","血小板黏附减少"],"a":2,"e":"血小板可填充血管内皮细胞间隙，参与修复并维持血管壁完整性，其减少时红细胞易外渗形成出血斑点。不能聚集成团（A项）与黏附减少（E项）主要妨碍止血栓形成，并非自发性出血点的主因。血凝块回缩障碍（D项）源于血小板收缩蛋白，与此无关"},{"q":"关于胃液分泌的叙述，下列哪项是错误的","o":["壁细胞分泌盐酸","幽门腺分泌黏液","主细胞分泌胃蛋白酶","壁细胞分泌内因子","黏液细胞分泌糖蛋白"],"a":2,"e":"主细胞分泌的是无活性的胃蛋白酶原，需经盐酸激活才成为胃蛋白酶，故该项表述错误。壁细胞分泌盐酸和内因子，A、D两项正确。幽门腺与黏液细胞分泌黏液及糖蛋白，构成黏液屏障，B、E表述无误"},{"q":"比较各种体液中蛋白质浓度，正确的是","o":["细胞内液>组织液>血浆","细胞内液>血浆>组织液","血浆>组织液>细胞内液","血浆>细胞内液>组织液","血浆=细胞内液>组织液"],"a":1,"e":"细胞内液含大量酶与结构蛋白，蛋白质浓度最高；血浆次之，组织液最低，故该排序正确。A项把组织液排在血浆之前，C、D项把血浆或细胞内液次序颠倒，均不符浓度梯度。E项称血浆等于细胞内液，忽略两者显著差异"},{"q":"下列关于心肺感受器引起的心血管反射的叙述，正确的是","o":["感受器只接受心或血管壁的机械牵张","感受器不接受化学物质的刺激","心室血容量降低可引起该反射活动","可引起血压下降","可引起心交感紧张性加强"],"a":3,"e":"心肺感受器兴奋可反射性抑制心血管中枢，使心率减慢、外周血管舒张、血压下降，还可抑制抗利尿激素释放。其既感受机械牵张也接受化学物质刺激，A、B两项错误。血容量升高而非降低才引起该反射，C项相反。E项心交感紧张应减弱而非加强"},{"q":"完成一个反射所涉及的五个部位中，最易出现疲劳的是","o":["效应器","反射中枢","感受器","传入神经","传出神经"],"a":1,"e":"反射中枢内突触传递依赖递质释放与受体结合，连续活动易致递质耗竭，故最易疲劳。感受器、传入与传出神经主要传导动作电位，不易疲劳，C、D、E项均非薄弱环节。效应器（A项）的疲劳远晚于中枢突触"},{"q":"骨骼肌终板膜上的受体是","o":["α受体","β1受体","Ｎ2受体","Ｎ1受体","Ｍ受体"],"a":2,"e":"骨骼肌终板膜上是N2型胆碱受体，属离子通道型受体，乙酰胆碱与之结合后开放阳离子通道。N1受体（D项）位于自主神经节突触后膜和肾上腺髓质。M受体（E项）分布于副交感节后纤维支配的效应器。α、β受体（A、B项）为肾上腺素受体，均不在终板膜"},{"q":"正常成年男性的血细胞在血液中所占的容积百分比是","o":["20%～30%","30%～40%","40%～50%","60%～65%","70%～80%"],"a":2,"e":"血细胞比容指血细胞在血液中所占容积百分比，成年男性正常约40%～50%。20%～30%（A项）与30%～40%（B项）明显偏低，多见于贫血。60%～65%（D项）与70%～80%（E项）过高，超出正常范围"},{"q":"在壁细胞完全缺乏的人，下列哪种情况不会发生","o":["消化蛋白质能力降低","维生素B12吸收减少","胃蛋白酶激活降低或消失","肠道细菌生长加速","碳酸氢盐分泌减少"],"a":0,"e":"蛋白质消化主要在小肠由胰蛋白酶等完成，壁细胞缺乏不致蛋白质消化能力明显降低，故该情况不会发生。内因子缺乏使维生素B12吸收减少（B项）。无盐酸则胃蛋白酶原难以激活（C项），杀菌减弱致细菌繁殖（D项）。胃酸减少使促胰液素释放下降，碳酸氢盐分泌随之减少（E项）"},{"q":"在寒冷环境中，机体不会出现下列哪项反应","o":["交感神经紧张性增高","皮肤小动脉收缩","皮肤血流量降低","皮下动-静脉吻合支开放增多","皮肤温度升高"],"a":4,"e":"寒冷时皮肤小动脉收缩、血流量减少，皮肤温度随之降低，故皮肤温度升高不会出现。交感神经紧张性增高（A项）、小动脉收缩（B项）、血流减少（C项）均为正常保温反应。皮下动静脉吻合支在寒冷时关闭而非开放增多，D项亦属错误表述"},{"q":"球-管平衡的生理意义是","o":["尿量不会因肾小球滤过率的增减出现大幅度变动","维持肾小球滤过率恒定","维持肾髓质高渗梯度","保证肾小管重吸收的正常进行","保证肾小管分泌的正常进行"],"a":0,"e":"球管平衡指近端小管重吸收率恒定占滤过率的65%～70%，使尿量不因滤过率增减而大幅波动。维持滤过率恒定靠肾自身调节，B项混同概念。肾髓质高渗梯度由髓袢和直小血管形成，C项归属错误。D、E所述重吸收与分泌的正常进行并非该平衡的意义"},{"q":"O2分压最高的部位是","o":["动脉血","静脉血","组织细胞","毛细血管","肺泡气"],"a":4,"e":"肺泡气氧分压约100mmHg，高于动脉血及毛细血管血，是体内氧分压最高处。静脉血（B项）约40mmHg，组织细胞（C项）更低，均为氧被摄取后的结果。动脉血（A项）因与静脉血混合，氧分压略低于肺泡气"},{"q":"关于能量代谢的描述，错误的是","o":["肌肉活动能显著提高产热量","环境温度低于20℃时，代谢增加","精神紧张可致机体产热量显著增加","平静思考问题时，脑组织产热量明显升高","在睡眠和在活跃的精神状态下，脑中葡萄糖代谢明显不同"],"a":3,"e":"平静思考时脑组织代谢增加甚微，产热量无明显升高，故该项错误。肌肉活动（A项）是影响产热最显著的因素。环境温度低于20℃（B项）及精神紧张（C项）分别通过寒战性产热和交感兴奋使产热增加。E项脑葡萄糖代谢在睡眠与活跃状态下差异很小，该表述本身成立"},{"q":"怀孕期间胎盘大量分泌的雌激素主要是下列哪一种","o":["雌酮","孕酮","β-雌二醇","雌三醇","绒毛膜促性腺激素"],"a":3,"e":"胎盘利用胎儿提供的雄激素前体大量合成雌三醇，是妊娠期主要的雌激素。β-雌二醇（C项）主要由卵巢卵泡与黄体分泌。雌酮（A项）量少。孕酮（B项）属孕激素，绒毛膜促性腺激素（E项）为蛋白激素，均非雌激素"},{"q":"肾维持体内水平衡主要通过下列哪项调节活动实现","o":["肾小球滤过量","近曲小管与髓袢的重吸收水量","远曲小管和集合管的重吸收水量","肾小管的分泌功能","集合管的分泌功能"],"a":2,"e":"远曲小管和集合管在抗利尿激素作用下改变对水的通透性，是肾调节水平衡的关键部位。近曲小管与髓袢（B项）重吸收水量大而恒定，不受激素调节。肾小球滤过（A项）与分泌功能（D、E项）不主导水平衡调节"},{"q":"脑桥呼吸调整中枢的主要功能是","o":["限制吸气相的时间","接受迷走神经传入的信息","激活延髓呼吸中枢","形成基本的呼吸节律","抑制吸气切断机制的活动"],"a":0,"e":"脑桥呼吸调整中枢促进吸气向呼气转换，限制吸气相时限，使节律趋于完善。基本呼吸节律形成于延髓，D项张冠李戴。该中枢是促进而非抑制吸气切断机制，E项相反。激活延髓呼吸中枢（C项）与接受迷走传入（B项）均非其主要功能"},{"q":"对于凝血、抗凝及纤维蛋白溶解的叙述，错误的是","o":["外源性凝血激活途径完全不依靠血浆内的凝血因子","Ca2＋是血液凝固过程不可缺少的离子","许多凝血因子是在肝脏合成的","小血管内已形成的凝血块还可逐渐溶解","纤维蛋白降解产物一般不能再凝固"],"a":0,"e":"外源性凝血虽由组织因子启动，但其后仍需因子VII、X、V、II等多种血浆因子参与，说它完全不依靠血浆因子错误。钙离子（B项）参与多个凝血环节不可缺少。多数凝血因子（C项）在肝合成。小血管内已形成的血栓可逐渐溶解（D项），纤维蛋白降解产物（E项）不能再凝固"},{"q":"甲状旁腺过度增生或形成腺瘤时会出现下列哪项变化","o":["血磷升高","血钙降低","血钙升高","血钙降低、血磷升高","血钙升高、血磷降低"],"a":4,"e":"甲状旁腺激素促进骨钙释放、肾重吸收钙并活化维生素D，使血钙升高，同时抑制肾小管重吸收磷使血磷降低。A项血磷升高与B项血钙降低均与其升钙降磷作用相反。D项血钙降低、血磷升高是维生素D缺乏的表现。C项只提血钙，未反映血磷变化"},{"q":"属于类固醇激素的是","o":["甲状腺素","甲状旁腺素","胰岛素","氢化可的松","生长激素"],"a":3,"e":"氢化可的松属糖皮质激素，为类固醇（甾体）激素。甲状腺素（A项）是胺类衍生物。甲状旁腺素（B项）、胰岛素（C项）、生长激素（E项）均为肽类或蛋白质激素，不属类固醇"},{"q":"在随意运动期间，腱器官提供给中枢神经系统的信息是","o":["肌肉长度的变化","运动的速度","肌肉血液供应情况","肌肉张力的变化","肌肉内的温度变化"],"a":3,"e":"腱器官位于肌腱，感受肌肉张力变化，传入冲动引起反牵张反射以调节肌力、防止损伤。肌肉长度变化（A项）由肌梭感受。运动速度（B项）、血液供应（C项）、温度（E项）均非腱器官的检测对象"},{"q":"膜受体的化学本质是","o":["糖类","脂类","蛋白质","核糖核酸","胺类"],"a":2,"e":"膜受体化学本质多为蛋白质（糖蛋白），借构象变化传递信号。糖类（A项）多作为细胞识别的糖被成分。脂类（B项）是膜骨架而非受体。核糖核酸（D项）与胺类（E项）不构成膜受体主体"},{"q":"心室肌细胞的有效不应期较长，一直要延续到","o":["心室舒张早期","舒张晚期","收缩期开始","整个收缩期","整个舒张期"],"a":0,"e":"心室肌有效不应期约200～300ms，从0期延续至复极3期约-60mV，相当于整个收缩期加舒张早期。心室舒张晚期（B项）时不应期多已结束。收缩期开始（C项）仅是其中一段。若延续至整个舒张期（E项）则心脏无法舒张充盈"},{"q":"维持机体稳态的重要途径是","o":["正反馈调节","负反馈调节","前馈调节","免疫调节","适应性凋节"],"a":1,"e":"负反馈使受控变量偏离后回调，是维持稳态最重要、最普遍的途径。正反馈（A项）使活动不断增强直至完成，如分娩、凝血，不维持稳态。前馈（C项）属预先调节，免疫调节（D项）与适应性调节（E项）针对特定功能，均非维持稳态的基本方式"},{"q":"对肾单位的描述不正确的是","o":["是肾脏的基本功能单位","与集合管共同完成肾脏的泌尿功能","可分为皮质肾单位和近髓肾单位","近髓肾单位多于皮质肾单位","近髓肾单位与尿液浓缩和稀释关系大"],"a":3,"e":"肾单位中皮质肾单位约占85%～90%，近髓肾单位仅约10%～15%，故近髓肾单位多于皮质肾单位错误。肾单位（A项）是基本功能单位，与集合管（B项）共同完成泌尿。近髓肾单位髓袢长，与尿液浓缩稀释关系密切，C、E项正确"},{"q":"输血时下列哪一种血型的人最不易找到合适的给血者","o":["O型，Rh阳性","A型，Rh阳性","B型，Rh阳性","AB型，Rh阳性","O型，Rh阴性"],"a":4,"e":"O型Rh阴性者红细胞无A、B及Rh(D)抗原，只能接受O型Rh阴性血，而该血型在人群中稀少，最难获得合适供血。AB型Rh阳性（D项）理论上可接受各型血，最易获得。A、B、C型的Rh阳性者供血来源广，均不如O型Rh阴性困难"},{"q":"交感神经节对冠脉循环的影响是","o":["直接引起冠脉舒张","间接引起冠脉收缩","间接引起血流量减少","间接引起血流量增多","导致心肌代谢水平降低"],"a":3,"e":"心交感神经兴奋使心肌代谢增强，产生大量腺苷、二氧化碳等代谢产物，继发引起冠脉舒张、血流量增多，此作用占主导。直接激动冠脉α受体引起收缩（A、B项）作用较弱并被掩盖。血流量是增多而非减少，C项相反。心肌代谢水平是升高而非降低，E项错误"},{"q":"在机体的排泄途径中，排出的物质种类最多，数量最大的部位是","o":["呼吸道","消化道","肾脏","皮肤汗腺","泪腺"],"a":2,"e":"肾是机体最主要排泄器官，排出尿素、肌酐、尿酸及多余水和电解质，种类最多、数量最大。肺（A项）主要排二氧化碳和少量水。消化道（B项）排胆色素等。皮肤汗腺（D项）排汗，泪腺（E项）分泌泪液，量均有限"},{"q":"受交感和副交感神经双重支配的是","o":["皮肤血管","多数汗腺","皮肤竖毛肌","膀胱逼尿肌","肾上腺髓质"],"a":3,"e":"膀胱逼尿肌受副交感（盆神经，收缩）与交感（腹下神经，舒张）双重支配。皮肤血管（A项）、多数汗腺（B项）、竖毛肌（C项）仅受交感支配。肾上腺髓质（E项）相当于交感神经节后结构，只受交感节前纤维支配"},{"q":"在缺铁性贫血的实验室检查中，哪项指标最能说明体内储备的铁缺乏","o":["血清铁降低","血清铁蛋白降低","总铁结合力增加","小细胞低色素","转铁蛋白降低"],"a":1,"e":"血清铁蛋白反映体内贮存铁，是储备铁缺乏最敏感、最早的指标。血清铁降低（A项）与总铁结合力升高（C项）反映循环铁变化，出现较晚。小细胞低色素（D项）为贫血形态学表现。转铁蛋白（E项）水平并非储备铁指标"},{"q":"自律细胞产生自动节律性兴奋的基础是","o":["4期自动去极化","0期去极化","1期快速复极化","2期缓慢复极化","3期缓慢复极化"],"a":0,"e":"自律细胞4期膜电位不稳定，钠或钙内流渐增、钾外流渐减，自动去极化达阈电位即自发兴奋，是自律性的基础。0期去极化（B项）是兴奋的表现而非起搏机制。1、2、3期（C、D、E项）为复极过程，与自动节律无关"},{"q":"实现胃容受性舒张的途径是","o":["迷走神经","交感神经","壁内神经丛","抑胃肽","促胰液素"],"a":0,"e":"胃容受性舒张经迷走神经的迷走-迷走反射实现，传出为抑制性纤维，释放血管活性肠肽或一氧化氮使胃底胃体舒张。交感神经（B项）参与应激反应。壁内神经丛（C项）非该反射主要通路。抑胃肽（D项）、促胰液素（E项）为体液因素，不实现容受性舒张"},{"q":"调节降钙素分泌最主要的因素是","o":["血钙浓度","胰高血糖素","缩胆囊素","进食刺激","促胃液素"],"a":0,"e":"降钙素由甲状腺C细胞分泌，血钙升高是其分泌的最主要刺激，通过降钙、降磷发挥作用。进食后胰高血糖素（B项）、缩胆囊素（C项）、促胃液素（E项）等可刺激其分泌，但属次要，均非主导因素"},{"q":"“谈虎色变”是由于","o":["副交感神经兴奋所致","交感神经兴奋所致","第一信号系统的活动所致","第二信号系统的活动所致","非条件反射活动所致"],"a":3,"e":"谈虎色变以语言文字为信号建立条件反射，属人类特有的第二信号系统活动。第一信号系统（C项）以具体声音、气味等为信号，人和动物共有。非条件反射（E项）为先天本能。交感和副交感兴奋（A、B项）只是伴随的情绪反应，非本质原因"},{"q":"窦房结细胞的起搏活动是由于","o":["K+递减性外流","K+递减性内流","K+递减性外流+Na+内流","K+递减性内流+Na+内流","K+递减性外流+Na+内流+Ca2+内流"],"a":4,"e":"窦房结P细胞4期自动去极化由钾外流递减、自律电流介导的钠内流及T型钙内流共同促成。单纯钾递减外流（A项）主要是浦肯野细胞的机制。只提钠内流（B、C项）或漏掉钙内流（C项）均不完整，D项钾内流方向错误"},{"q":"汗液与血浆成分相比较，正确的是","o":["脂类浓度相等","尿素氮浓度高于血浆","葡萄糖浓度高于血浆","氯化钠浓度低于血浆","氯化钠浓度高于血浆"],"a":3,"e":"汗腺导管重吸收钠、氯，汗液为低渗液，氯化钠浓度明显低于血浆。汗液尿素浓度可略高于血浆（B项），但非本题所取。葡萄糖（C项）在汗中几乎测不出，不会高于血浆。E项与D项相反。脂类（A项）含量极微，无可比性"},{"q":"关于糖皮质激素和肾上腺素关系的描述，下列哪一项正确","o":["糖皮质激素促进肾上腺素的合成","糖皮质激素促进肾上腺素的释放","肾上腺素抑制糖皮质激素的合成","肾上腺素抑制糖皮质激素的释放","两者之间没有联系"],"a":0,"e":"糖皮质激素诱导肾上腺髓质嗜铬细胞合成苯乙醇胺氮位甲基移位酶，促进去甲肾上腺素转为肾上腺素，故促进其合成。肾上腺素（C、D项）对糖皮质激素合成释放无明显负反馈抑制。两者并非毫无联系，E项错误。促进释放（B项）并非其主要作用"},{"q":"大脑皮质体表感觉代表区的投射规律是","o":["身体一侧的感觉投射到同侧皮层","下肢代表区在皮层感觉区的底部","中央后回是体表感觉的主要代表区，称第一感觉区","代表区大小与感觉精细程度无关","第一感觉区产生的感觉定位不明确，性质不清晰"],"a":2,"e":"体表感觉第一代表区位于中央后回，定位明确、感觉清晰。身体一侧感觉投射到对侧皮层，A项同侧错误。下肢代表区在皮层顶部，B项底部错误。代表区大小与感觉精细程度成正比，D项无关错误。E项定位不明确是第二感觉区特点"},{"q":"受精的过程不包括下列哪一项","o":["精子通过宫颈、宫体和输卵管","精子进入卵巢","精子获能","顶体反应","精子与卵子融合为合子"],"a":1,"e":"精子在输卵管壶腹部与卵子相遇受精，并不进入卵巢。精子获能（C项）、顶体反应（D项）、精卵融合成合子（E项）均为受精的必要环节。精子经宫颈、宫体、输卵管运行（A项）是抵达受精部位的过程"},{"q":"关于胰岛素分泌的神经调节，下列描述错误的是哪一项","o":["胰岛受迷走神经与交感神经支配","迷走神经可通过M受体促进胰岛素的分泌","迷走神经可通过刺激胃肠激素释放促进胰岛素分泌","交感神经可通过α受体抑制胰岛素的分泌","交感神经可通过刺激胃肠激素释放抑制胰岛素分泌"],"a":4,"e":"交感神经并非通过刺激胃肠激素释放来抑制胰岛素分泌，胃肠激素多促进胰岛素分泌，故该项错误。胰岛受迷走与交感双重支配（A项）。迷走经M受体（B项）及刺激胃肠激素（C项）促分泌。交感经α受体（D项）抑制分泌，均正确"},{"q":"大脑皮质体表感觉区中第二感觉区的结构或功能特点是","o":["位于中央后回与岛叶之间","倒置安排","接受双侧投射","不接受痛觉传入信息","感觉定位明确"],"a":2,"e":"第二感觉区接受双侧投射，定位不明确、感觉较粗略。其位于中央后回底部与岛叶之间，但A项表述并非最本质特征。该区排列不若第一感觉区严格倒置，B项倒置安排不准确。它与痛觉有关，D项不接受痛觉错误。E项定位明确是第一感觉区特点"},{"q":"心交感神经活动加强，可引起","o":["心率减慢、传导加速、心肌收缩力减弱","心率加快、传导加速、心肌收缩力减弱","心率减慢、传导减慢、心肌收缩力加强","心率减慢、传导加速、心肌收缩力加强","心率加快、传导加速、心肌收缩力加强"],"a":4,"e":"心交感神经兴奋释放去甲肾上腺素作用于β1受体，产生正性变时、变传导、变力作用，表现为心率加快、传导加速、收缩力加强。其余选项多含心率减慢或收缩力减弱，与交感兴奋效应相反"},{"q":"夜盲症患者，夜晚看不清物体的主要原因是","o":["视蛋白增多","视紫蓝质缺乏","视黄醛增多","视紫红质缺乏","视紫红质过多"],"a":3,"e":"夜盲症因维生素A缺乏致视杆细胞视紫红质合成不足，暗适应能力下降。视紫蓝质（B项）是视锥细胞色素，与明视觉色觉相关。视黄醛（C项）增多不会致病。E项视紫红质过多与夜盲无关。A项视蛋白增多亦非病因"},{"q":"关于HCO3-在近端小管重吸收的描述正确的是","o":["与H+的分泌无关","重吸收率约为35%","滞后于Cl-的重吸收","以CO2的形式重吸收","管腔膜对HCO3-的通透性好"],"a":3,"e":"管腔中碳酸氢根与氢离子结合成碳酸，经碳酸酐酶分解为二氧化碳后扩散入细胞，故以二氧化碳形式重吸收。该过程依赖氢离子分泌，A项无关错误。近端小管重吸收碳酸氢根约80%～85%，B项35%过低。碳酸氢根优先于氯重吸收，C项滞后错误。管腔膜对碳酸氢根通透性差，E项错误"},{"q":"对于血小板的聚集起重要作用的物质是","o":["纤维蛋白原","凝血酶","钙离子","ADP与TXA2","钠离子"],"a":3,"e":"ADP与血栓烷A2由活化血小板释放，是强的聚集诱导剂，在血小板聚集中最为重要。纤维蛋白原（A项）提供聚集的桥梁。钙离子（C项）为辅助因子。凝血酶（B项）虽可促聚集但非最关键。钠离子（E项）作用很小"},{"q":"关于糖皮质激素对物质代谢的作用，下列哪一项正确","o":["能对抗胰岛素对血糖的作用","能抑制糖异生，降低血糖","促进肝外组织蛋白质的合成","促进脂肪合成","糖皮质激素分泌过多可致低血糖"],"a":0,"e":"糖皮质激素促进糖异生、减少外周摄取葡萄糖，升高血糖，可对抗胰岛素的降糖作用。B项抑制糖异生、降低血糖与其作用相反。它促进蛋白质分解，C项合成错误。促进脂肪分解而非合成，D项错误。分泌过多致高血糖，E项低血糖错误"},{"q":"血氧饱和度是指","o":["血氧容量占血氧含量的百分比","血氧含量占血氧容量的百分比","溶解氧量占血氧容量的百分比","溶解氧量占血氧含量的百分比","氧合Hb占Hb总量的百分比"],"a":1,"e":"血氧饱和度指血氧含量占血氧容量的百分比。A项将其颠倒。溶解氧量（C、D项）占比极小，与饱和度定义无关。E项氧合血红蛋白占血红蛋白总量虽可从侧面反映，但教材标准定义为血氧含量与血氧容量之比"},{"q":"下列造成心室肌传导阻滞的因素中，错误的是","o":["心肌细胞0期除极速度明显减慢","心肌不应期延长","快钠通道失活","静息电位的绝对值稍增大","动作电位幅度减小"],"a":3,"e":"静息电位绝对值稍增大时，快钠通道备用增多，0期去极化速度与幅度反而增大，传导加快，不会造成阻滞，故该项错误。0期除极减慢（A项）、不应期延长（B项）、快钠通道失活（C项）、动作电位幅度减小（E项）均可减慢传导"},{"q":"下列关于胆汁的描述，正确的是","o":["消化期时只有胆囊胆汁排入小肠","非消化期无胆汁分泌","胆汁中不含脂肪消化酶","胆汁中与消化和吸收有关的成分是胆固醇","胆盐可促进蛋白质的消化和吸收"],"a":2,"e":"胆汁中不含脂肪消化酶，但含胆盐、胆固醇、卵磷脂、胆色素等。消化期肝胆汁与胆囊胆汁均排入小肠，A项只有胆囊胆汁错误。非消化期肝仍持续分泌胆汁并储存于胆囊，B项错误。与消化吸收有关的是胆盐，D项胆固醇错误。胆盐促脂肪而非蛋白质消化吸收，E项错误"},{"q":"7次跨膜受体是指","o":["酪氨酸激酶受体","酪氨酸激酶结合型受体","鸟苷酸环化酶受体","G蛋白耦联受体","离子通道型受体"],"a":3,"e":"G蛋白耦联受体为7次跨膜受体，通过G蛋白与效应器传递信号。酪氨酸激酶受体（A、B项）为单次跨膜。鸟苷酸环化酶受体（C项）亦单次跨膜。离子通道型受体（E项）由多个亚基组成，均非7次跨膜"},{"q":"下列关于食管下括约肌的叙述，正确的是","o":["由环形肌极度增厚形成","食管蠕动波到达时舒张","由骨骼肌构成","由三层平滑肌构成","主要受激素调节"],"a":1,"e":"食管蠕动波到达时下括约肌舒张，使食团顺利入胃。该括约肌为功能性结构，并无环形肌极度增厚的解剖基础，A项不准确。它由平滑肌构成，C项骨骼肌错误。并非三层平滑肌，D项错误。其活动主要受神经调节，E项主要受激素调节错误"},{"q":"士的宁与破伤风毒素可引起骨骼肌痉挛，其原因是破坏了闰绍细胞功能从而阻断","o":["传入侧支性抑制","回返性抑制","去极化抑制","周围性抑制","突触前抑制"],"a":1,"e":"闰绍细胞介导α运动神经元的回返性抑制，士的宁与破伤风毒素阻断其抑制性递质甘氨酸的作用，使该抑制消失而致痉挛。传入侧支性抑制（A项）由另一类中间神经元介导。去极化抑制（C项）、周围性抑制（D项）、突触前抑制（E项）机制不同"},{"q":"平静呼吸过程中胸内压的变化是","o":["吸气时小于大气压，呼气时大于大气压","吸气、呼气时均小于大气压，吸气、呼气末均等于大气压","吸气、呼气时及吸气末、呼气末均小于大气压","吸气时大于大气压，呼气时小于大气压","呼气时比吸气时胸内压更低"],"a":2,"e":"平静呼吸时胸内压始终低于大气压，吸气时更负、呼气时负值减小，吸气末与呼气末仍为负压。A、D项认为呼气相可高于大气压，错误。B项吸气末呼气末等于大气压不符。E项呼气时胸内压负值减小而非更低"},{"q":"心电图P-R间期延长，表示","o":["心房肥大","心房内传导速度减慢","房室交界区传导速度减慢","心室内传导速度减慢","心室肥大"],"a":2,"e":"P-R间期反映心房除极至心室除极的时程，其中主要耗费于房室交界区传导，故延长表示房室交界区传导减慢。心房肥大（A项）主要改变P波形态。心房内（B项）、心室内（D项）传导减慢影响P波或QRS时限。心室肥大（E项）主要改变QRS波"},{"q":"脑电图的主要波形，按频率由高到低依次排列为","o":["α-β-θ-δ","β-α-θ-δ","α-β-δ-θ","β-α-δ-θ","δ-θ-β-α"],"a":1,"e":"脑电波按频率由高到低为β（14～30Hz）、α（8～13Hz）、θ（4～7Hz）、δ（0.5～3Hz）。A项把α置于β之前，C、D项把δ与θ顺序颠倒，E项完全反向，均不符频率排序"},{"q":"下列细胞中，吞噬能力最强的是","o":["单核巨噬细胞","中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","淋巴细胞"],"a":0,"e":"单核-巨噬细胞体积大、吞噬能力强，可吞噬大颗粒、衰老细胞与病原体，为吞噬能力最强者。中性粒细胞（B项）吞噬细菌活跃但范围与能力不及巨噬细胞。嗜酸性（C项）、嗜碱性（D项）粒细胞及淋巴细胞（E项）吞噬作用弱或无"},{"q":"快适应感觉器，即最容易发生适应的感受器是","o":["伤害性感受器","触觉感受器","肺牵张感受器","肌梭","颈动脉窦感受器"],"a":1,"e":"触觉感受器属快适应感受器，刺激持续时传入冲动迅速减少，利于感受新异刺激。伤害性感受器（A项）几乎不适应。肺牵张感受器（C项）、肌梭（D项）、颈动脉窦感受器（E项）均为慢适应，负责持续监测"},{"q":"从实验大鼠体内取一段小肠，放置于适宜的环境当中，观察到小肠平滑肌仍然进行节律性的收缩和舒张。这种特性属于下列哪一项","o":["有自动节律性","传导性好","有较强的收缩性","兴奋性比较高","伸展性良好"],"a":0,"e":"离体小肠平滑肌在适宜环境中仍能自主节律性舒缩，表明其本身具有自动节律性，属肌源性活动。传导性（B项）指兴奋扩散，收缩性（C项）指产生张力，兴奋性（D项）指产生兴奋的能力，伸展性（E项）指被拉长特性，均非题干所指"},{"q":"支配骨骼肌的躯体运动神经释放的递质为","o":["肾上腺素","去甲肾上腺素","儿茶酚胺","多巴胺","乙酰胆碱"],"a":4,"e":"支配骨骼肌的躯体运动神经末梢释放乙酰胆碱，作用于终板膜N2受体。肾上腺素（A项）、去甲肾上腺素（B项）、儿茶酚胺（C项）为肾上腺素能递质。多巴胺（E项）为中枢递质，均非躯体运动神经递质"},{"q":"当血钾浓度轻度升高时，心肌的兴奋性将","o":["增大","减小","不变","先增大后减小","先减小后增大"],"a":0,"e":"血钾轻度升高时心肌静息电位负值减小，与阈电位距离缩短，兴奋性增大。重度升高才因钠通道失活使兴奋性降低，B项笼统说减小不当。C项不变错误。先增大后减小（D项）描述的是由轻度到重度的全过程，非轻度升高时的表现"},{"q":"当全身小动脉狭窄时，此时动脉血压的主要表现为","o":["收缩压增高","收缩压降低","收缩压、舒张压均增高，但以舒张压明显","收缩压、舒张压均增高，但以收缩压明显","舒张压降低、收缩压增高"],"a":2,"e":"小动脉狭窄使外周阻力增大，而舒张压高低主要取决于外周阻力，故舒张压升高更明显，收缩压亦升高但幅度较小。A、B项只提单一收缩压变化不全面。D项以收缩压明显与外周阻力机制相反。E项舒张压降低错误"},{"q":"直接给机体活动提供能量的物质是","o":["磷酸肌酸","ADP","ATP","环磷酸腺苷","葡萄糖"],"a":2,"e":"三磷酸腺苷是机体各项生命活动的直接供能物质。磷酸肌酸（A项）为高能磷酸储备。二磷酸腺苷（B项）为水解产物。环磷酸腺苷（D项）为第二信使。葡萄糖（E项）为主要能源物质，但需氧化生成三磷酸腺苷后才能供能"},{"q":"下列哪项属于小肠的运动形式","o":["袋状往返运动","容受性舒张","集团蠕动","多袋推进运动","分节运动"],"a":4,"e":"分节运动是小肠特有的主要运动形式，利于食糜与消化液混合及吸收。袋状往返运动（A项）、多袋推进运动（D项）、集团蠕动（C项）均属大肠运动。容受性舒张（B项）为胃的运动形式"},{"q":"关于促肾上腺皮质激素分泌的调节，下列哪一项正确","o":["受促甲状腺激素释放激素的调节","受糖皮质激素的负反馈调节","受肾上腺素的负反馈调节","受促甲状腺激素的调节","与睡眠无关"],"a":1,"e":"促肾上腺皮质激素分泌受下丘脑促肾上腺皮质激素释放激素促进，并受糖皮质激素负反馈抑制。促甲状腺激素释放激素（A项）调节促甲状腺激素。肾上腺素（C项）不参与负反馈。促甲状腺激素（D项）作用于甲状腺。该激素分泌有昼夜节律，与睡眠相关，E项无关错误"},{"q":"当脊髓前角α-运动神经元的传出冲动增加时，可引起","o":["γ-运动神经元的传出冲动增加","梭内肌收缩","肌梭的敏感性增强","梭外肌收缩","梭内肌与梭外肌同时收缩"],"a":3,"e":"α运动神经元支配梭外肌，其冲动增加直接引起梭外肌收缩，产生肌力。γ运动神经元（A项）支配梭内肌。梭内肌收缩（B项）与肌梭敏感性增强（C项）为γ神经元兴奋的结果。D、E项混淆两类神经元"},{"q":"下列关于前列腺素的描述，哪一项是错误的","o":["前列腺素的前体为花生四烯酸","前列腺素半衰期短，在体内代谢极快","前列腺素属于循环激素，能对全身功能进行调节","前列腺素来源于细胞膜磷脂","前列腺素主要在肺和肝灭活"],"a":2,"e":"前列腺素多在局部组织生成并就近发挥作用，属局部激素，不通过血液循环远距离调节全身，故该项错误。其前体为花生四烯酸（A项），来源细胞膜磷脂（D项），半衰期短、代谢快（B项），主要在肺和肝灭活（E项），均正确"},{"q":"慢适应感受器的生理意义是","o":["有利于发现高频刺激","有利于感受所有刺激","有利于对某些功能状态进行长期持续的监测","有利于感受新的刺激","有利于机体对新事物的变化作出反应"],"a":2,"e":"慢适应感受器持续发放冲动，利于对血压、姿势等某一功能状态进行长期监测。发现高频刺激（A项）、感受新刺激（D项）、对新变化反应（E项）为快适应感受器的功能。感受所有刺激（B项）笼统不当"},{"q":"心动周期中，主动脉压最低见于","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末"],"a":4,"e":"心动周期中动脉血压在舒张期持续下降，至等容收缩期末主动脉瓣开放前达最低。快速充盈期末（B项）、减慢充盈期末（C项）血压仍较高。心房收缩期末（D项）已进入舒张末。等容舒张期（A项）血压尚在较高水平"},{"q":"神经调节的基本方式是","o":["适应","反射","反应","正反馈调节","负反馈调节"],"a":1,"e":"神经调节的基本方式是反射，其结构基础为反射弧。适应（A项）、反应（C项）为一般生理概念。正反馈（D项）、负反馈（E项）是调节方式，均非神经调节的基本方式"},{"q":"骨骼肌收缩完成后，回收胞内钙离子的钙泵位于","o":["横管","高尔基体膜","肌膜","肌质网膜","线粒体膜"],"a":3,"e":"骨骼肌舒张时，肌质网膜上的钙泵将胞质钙离子主动泵回肌质网，降低胞内钙浓度。横管（A项）传导动作电位。高尔基体膜（B项）、肌膜（C项）、线粒体膜（E项）均非回收钙的主要部位"},{"q":"心肌不会产生强直收缩的原因是","o":["心脏是机能上的合胞体","心肌呈“全或无”收缩","心肌的有效不应期特别长","心肌肌浆网不发达，Ca2+贮存少","心肌肌浆网发达，Ca2+贮存多"],"a":2,"e":"心肌有效不应期长达200～300ms，相当于整个收缩期加舒张早期，此期不能再兴奋，故不会融合成强直收缩。心脏为功能合胞体（A项）、全或无收缩（B项）与同步性有关。肌浆网不发达（D项）影响收缩强度，非主因。E项与事实相反"},{"q":"心室肌细胞动作电位平台期形成机制主要是下列哪些离子跨膜流动的综合结果","o":["Na+内流，K+外流","Na+内流，Cl-外流","Na+内流，Cl-内流","Ca2+内流，K+外流","K+内流，Na+外流"],"a":3,"e":"平台期由钙内流与钾外流处于平衡而形成，膜电位维持于0mV左右。钠内流（A、B、C项）主要为0期去极化机制。钾内流、钠外流（E项）方向错误，不符合平台期离子流"},{"q":"可引起氧解离曲线右移的因素是","o":["血液中PCO2增高","血液中PCO2降低","血液中pH值增高","血液中PO2增高","血液中2,3-二磷酸甘油酸减少"],"a":0,"e":"二氧化碳分压增高、氢离子浓度升高、温度升高、2,3-二磷酸甘油酸增多均使氧解离曲线右移，血红蛋白释氧增加。二氧化碳分压降低（B项）、pH增高（C项）、2,3-二磷酸甘油酸减少（E项）使曲线左移。氧分压增高（D项）主要影响氧含量饱和度，不直接决定曲线移位"},{"q":"血液中绝大多数的凝血因子合成部位是","o":["脾","肝","肾","骨髓","肺"],"a":1,"e":"绝大多数凝血因子在肝合成，肝功能受损常致凝血障碍。脾（A项）主要破坏血细胞。肾（C项）分泌促红细胞生成素。骨髓（D项）生成血细胞。肺（E项）不是凝血因子合成部位"},{"q":"在中脑上、下丘之间切断脑干的动物将出现","o":["肢体麻痹","去大脑僵直","脊休克","腱反射加强","动作不精细"],"a":1,"e":"中脑上下丘之间切断脑干后，高位中枢对网状结构抑制区的易化被中断，易化区相对占优，抗重力肌肌紧张增强，出现去大脑僵直。肢体麻痹（A项）、脊休克（C项）见于脊髓损伤。腱反射加强（D项）、动作不精细（E项）非该模型典型表现"},{"q":"神经肌肉接头处的递质是","o":["肾上腺素","去甲肾上腺素","多巴胺","乙酰胆碱","5-羟色胺"],"a":3,"e":"神经肌肉接头处递质为乙酰胆碱，作用于终板膜N2受体。肾上腺素（A项）、去甲肾上腺素（B项）、多巴胺（C项）、5-羟色胺（E项）均非该接头递质"},{"q":"心室肌细胞与浦肯野细胞动作电位的主要区别在于","o":["1期复极化的速度","平台期复极化的机制","3期复极化的机制","4期自动去极化的有无","0期复极化的速度"],"a":3,"e":"心室肌细胞4期膜电位稳定无自动去极化，浦肯野细胞4期有缓慢自动去极化而具自律性，此为二者主要区别。两者0期（E项）、1期（A项）、2期（B项）、3期（C项）的形成机制基本相似"},{"q":"第一心音的出现标志着","o":["心室收缩开始","心室舒张开始","心房收缩开始","心房舒张开始","心室射血开始"],"a":0,"e":"第一心音在心室收缩开始时出现，主要由房室瓣关闭产生，标志心室收缩开始。心室舒张开始（B项）由第二心音标志。心房收缩（C项）、心房舒张（D项）不产生第一心音。射血开始（E项）晚于第一心音"},{"q":"关于经典化学性突触传递的叙述，正确的是","o":["双向传递","不易疲劳","有突触延搁现象","突触后电位不能总和","直接引起突触后膜产生动作电位"],"a":2,"e":"化学性突触传递需经递质释放、扩散、与受体结合等步骤，存在突触延搁。其为单向传递，A项双向错误。突触易疲劳，B项错误。突触后电位可发生总和，D项不能总和错误。需总和达阈电位才引发动作电位，E项直接引起错误"},{"q":"细胞一次兴奋后，兴奋性最低的是","o":["绝对不应期","相对不应期","超常期","低常期","局部反应期"],"a":0,"e":"绝对不应期内无论刺激多强都不能再次兴奋，兴奋性为零，是最低点。相对不应期（B项）兴奋性低但可兴奋。超常期（C项）高于正常。低常期（D项）低于正常但高于绝对不应期。局部反应期（E项）非标准分期"},{"q":"关于心肌生物电活动的叙述，正确的是","o":["迷走神经兴奋引起心房肌细胞去极化","交感神经兴奋引起心室肌细胞超极化","细胞外高钠可引起心肌细胞超极化","细胞外高钾可引起心肌细胞去极化","细胞外低钠可引起心肌细胞去极化"],"a":3,"e":"细胞外钾升高使心肌静息电位负值减小，膜去极化。迷走神经兴奋使钾外流增加致心房肌超极化，A项相反。交感兴奋加强钙内流致去极化，B项超极化错误。细胞外高钠（C项）不明显改变静息电位。低钠（E项）主要影响0期幅度"},{"q":"维生素D3代谢障碍时会出现下列哪些变化","o":["血磷升高","血钙降低","血钙升高","血钙降低、血磷升高","血钙升高、血磷降低"],"a":1,"e":"维生素D3促进小肠吸收钙磷并参与骨钙化，代谢障碍时钙吸收减少，出现血钙降低。血磷（A项）多随之降低而非升高。血钙升高（C项）及血钙升高伴血磷降低（D、E项）均与维生素D缺乏表现不符"},{"q":"在细胞膜的物质转运中，Na+跨膜转运的方式是","o":["单纯扩散和易化扩散","单纯扩散和主动转运","易化扩散和主动转运","易化扩散和入胞","单纯扩散，易化扩散和主动转运"],"a":2,"e":"钠顺浓度梯度经通道或载体以易化扩散方式内流，逆浓度梯度时由钠泵以主动转运方式泵出。钠为带电离子不能单纯扩散，A、B、E项含单纯扩散错误。入胞（D项）非钠的转运方式"},{"q":"胆汁中有利胆作用的成分是","o":["胆盐","胆固醇","卵磷脂","胆色素","黏蛋白"],"a":0,"e":"胆盐在回肠重吸收后经门静脉回肝，促进肝细胞分泌胆汁，具有利胆作用。胆固醇（B项）、卵磷脂（C项）、胆色素（D项）、黏蛋白（E项）均无此利胆效应"},{"q":"在心动周期中，房室瓣关闭始于","o":["快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末","快速射血期末"],"a":2,"e":"心房收缩结束后心室开始收缩，室内压升高推动房室瓣关闭，故房室瓣关闭始于心房收缩期末。快速充盈期（A项）、减慢充盈期（B项）房室瓣开放。等容收缩期末（D项）房室瓣早已关闭。快速射血期末（E项）关闭的是半月瓣"},{"q":"引起组织细胞产生动作电位的单一刺激必须是","o":["物理刺激","化学刺激","电刺激","阈刺激或阈上刺激","生物刺激"],"a":3,"e":"刺激须达阈强度（阈刺激）或超过阈强度（阈上刺激）才能使细胞产生动作电位，阈下刺激仅引起局部电位。物理（A项）、化学（B项）、电（C项）、生物（E项）只是刺激性质，能否引发动作电位取决于强度是否达阈值"},{"q":"在突触传递中，突触后神经元上局部反应发生总和的情况是","o":["EPSP和IPSP都可发生总和","IPSP发生时间总和","EPSP发生时间总和","IPSP发生空间总和","EPSP发生空间总和"],"a":0,"e":"兴奋性突触后电位与抑制性突触后电位均为局部电位，都可通过时间总和与空间总和叠加，两者之间还可发生代数总和。B、C项只提单一类型，D、E项只提单一总和方式，均不全面"},{"q":"参与G蛋白耦联信号转导过程的信号蛋白不包括","o":["G蛋白","G蛋白效应器","酪氨酸激酶","第二信使","蛋白激酶"],"a":2,"e":"G蛋白耦联信号通路包括受体、G蛋白、G蛋白效应器、第二信使和蛋白激酶。酪氨酸激酶属酶联受体通路成分，不参与该过程。G蛋白（A项）、效应器（B项）、第二信使（D项）、蛋白激酶（E项）均为该通路成员"},{"q":"下列关于唾液分泌调节的描述，正确的是","o":["仅受神经调节","仅受体液调节","条件反射和体液调节同时存在","非条件反射和体液因素同时存在","仅受自身调节"],"a":0,"e":"唾液分泌完全受神经调节，副交感兴奋分泌大量稀薄唾液，交感兴奋分泌少量黏稠唾液，无体液调节参与。B项仅体液、C与D项体液因素同时存在、E项仅自身调节均不符。胃肠液才受神经体液双重调节"},{"q":"以下属于多个单位平滑肌的是","o":["消化道","虹膜肌","输尿管","子宫","小血管"],"a":1,"e":"虹膜肌属多单位平滑肌，各细胞独立受神经支配，无自发节律。消化道（A项）、输尿管（C项）、子宫（D项）为单单位平滑肌，细胞间有缝隙连接、可同步收缩。小血管（E项）多归为单单位或过渡型，非典型多单位"},{"q":"维持肾髓质高渗梯度的主要结构是","o":["小叶间动脉","弓形动脉","弓形静脉","网状小血管","直小血管"],"a":4,"e":"直小血管通过逆流交换保留溶质，维持肾髓质高渗梯度而不被血流带走。小叶间动脉（A项）、弓形动脉（B项）、弓形静脉（C项）不参与该梯度维持。网状小血管（D项）非关键结构；髓袢是建立梯度的主要部位"},{"q":"关于终板电位的叙述正确的是","o":["是去极化电位","终板电位的大小与ACh的释放量无关","终板电位是由Ca2+内流产生的","有不应期","是全或无的"],"a":0,"e":"终板电位是乙酰胆碱作用后钠内流为主引起的去极化局部电位，可总和、无不应期、幅度与乙酰胆碱释放量成正比。B项与释放量无关错误。主要由钠而非钙内流产生，C项错误。D项有不应期、E项全或无均为动作电位特性，不适用于终板电位"},{"q":"有关女子基础体温的描述，哪一项是错误的","o":["随雌激素水平波动而变化","随孕激素及其代谢产物的变化而波动","在排卵前短暂降低","排卵后升高0、5℃左右","基础体温改变可作为判定排卵期的标志之一"],"a":0,"e":"基础体温主要随孕激素及其代谢产物波动，排卵后升高约0.5℃，排卵前短暂降低，可作为判定排卵的标志。雌激素（A项）并非其波动主因。B、C、D、E项所述均正确"},{"q":"安静状态下，紧张性活动起主导作用的神经纤维是","o":["心交感神经","心迷走神经","交感舒血管神经","副交感舒血管神经","脊髓背根舒血管纤维"],"a":1,"e":"安静状态下心迷走神经紧张性占主导，使心率维持在低于窦房结固有频率的水平。心交感（A项）在运动应激时占优。交感舒血管（C项）、副交感舒血管（D项）、脊髓背根舒血管纤维（E项）不主导安静时心脏调节"},{"q":"关于肺顺应性的叙述，错误的是","o":["与非弹性阻力呈正变关系","容易扩张的肺，顺应性大","可用单位压力引起的容积变化来衡量","表示在外力作用下肺的可扩展性","与弹性阻力呈反变关系"],"a":0,"e":"肺顺应性与弹性阻力呈反变，而与非弹性阻力（气道阻力）无直接正变关系，故该项错误。易扩张的肺顺应性大（B项）。可用单位压力引起的容积变化衡量（C项）。表示外力下肺的可扩展性（D项）。与弹性阻力反变（E项），均正确"},{"q":"慢性肺心病病人体内长时间低O2和CO2潴留，这种病人呼吸中枢兴奋性的维持主要依靠","o":["高CO2刺激外周化学感受器","高CO2刺激中枢化学感受器","缺O2刺激外周化学感受器","缺O2刺激中枢化学感受器","缺O2直接刺激呼吸中枢"],"a":2,"e":"慢性肺心病者长期二氧化碳潴留使中枢化学感受器对二氧化碳敏感性降低，呼吸兴奋性维持主要依靠缺氧对外周化学感受器的刺激。高二氧化碳（A、B项）此时作用减弱。缺氧对中枢呼吸中枢为抑制，D、E项刺激中枢错误"},{"q":"副交感神经系统兴奋所引起的机体变化不包括","o":["支气管平滑肌舒张","心跳减慢","促进胃肠运动","促进消化液分泌","促进胰岛素分泌"],"a":0,"e":"副交感兴奋使支气管平滑肌收缩而非舒张，故支气管平滑肌舒张不包括在内。心跳减慢（B项）、胃肠运动加强（C项）、消化液分泌增加（D项）、胰岛素分泌增加（E项）均为副交感兴奋效应。支气管舒张是交感β2受体作用"},{"q":"原尿和血浆相比较，在成分上不同的是","o":["K+含量","蛋白质含量","葡萄糖含量","Na+含量","酸碱物质含量"],"a":1,"e":"原尿除几乎不含大分子蛋白质外，水、葡萄糖、电解质、氨基酸等成分与血浆基本相同。钾（A项）、葡萄糖（C项）、钠（D项）、酸碱物质（E项）含量均与血浆相近，蛋白质（B项）是唯一显著不同者"},{"q":"血浆晶体渗透压降低时可引起","o":["组织液减少","组织液增加","红细胞萎缩","红细胞膨胀和破裂","尿量减少"],"a":3,"e":"血浆晶体渗透压降低时水进入红细胞，使其膨胀甚至破裂溶血。晶体渗透压升高才致红细胞皱缩，C项相反。组织液量主要受胶体渗透压影响，A、B项归属错误。尿量减少（E项）与晶体渗透压升高相关，非本题情形"},{"q":"心肌细胞分为快反应细胞和慢反应细胞的主要依据是","o":["0期去极化的速率","平台期的长短","动作电位复极化的速度","4期自动去极化快慢","3期自动复极化速度"],"a":0,"e":"快反应细胞0期由快钠通道介导去极化迅速，慢反应细胞0期由慢钙通道介导去极化缓慢，分类依据即0期去极化速率。平台期长短（B项）、复极速度（C项）、4期自动去极（D项）、3期复极（E项）均非快慢反应细胞的划分标准"},{"q":"血管损伤后止血栓能正确定位于损伤部位有赖于血小板的哪项特征","o":["黏附","聚集","收缩","吸附","释放"],"a":0,"e":"血小板黏附于损伤处暴露的胶原等，是止血栓准确定位于损伤部位的前提。聚集（B项）使血小板相互黏着成团。收缩（C项）致血块回缩。吸附（D项）、释放（E项）为其他功能，均不决定定位"},{"q":"心肌等长调节主要是改变了下列哪一因素","o":["心室舒张末期压力","心肌收缩能力","肌小节长度","主动脉血压","心力储备"],"a":1,"e":"等长调节通过改变心肌内在收缩能力来调节泵血，不改变肌小节初长度。心室舒张末期压力（A项）与肌小节长度（C项）属异长调节因素。主动脉血压（D项）为后负荷。心力储备（E项）为泵血潜力指标，非调节因素"},{"q":"根据神经纤维兴奋传导速度对其进行的分类中，自主神经节前纤维属于哪一类","o":["Ａα","Ａβ","Ａγ","B","Ｃ"],"a":3,"e":"按埃兰格-加瑟分类，自主神经节前纤维为有髓的B类纤维。Aα（A项）、Aβ（B项）、Aγ（C项）为有髓躯体神经纤维。C类（E项）为无髓纤维，包括自主神经节后纤维和痛觉纤维"},{"q":"维持躯体姿势的最基本反射是","o":["翻正反射","肌紧张","腱反射","屈肌反射","交叉伸反射"],"a":1,"e":"肌紧张是持续缓慢牵拉肌腱引起的紧张性牵张反射，是维持躯体姿势最基本的反射。翻正反射（A项）恢复体位。腱反射（C项）为快速单突触反射。屈肌反射（D项）、交叉伸反射（E项）属保护性反射"},{"q":"下列叙述中，哪一项是条件反射的特点","o":["先天遗传而获得","后天训练而建立","种族共有的反射","是一种初级的神经活动","反射弧固定不变"],"a":1,"e":"条件反射是后天在生活实践中通过训练建立的暂时性联系，反射弧可变。先天遗传（A项）、种族共有（C项）、反射弧固定（E项）为非条件反射特点。它属高级而非初级神经活动，D项错误"},{"q":"关于用力呼吸的描述，错误的是","o":["吸气时有辅助吸气肌参加活动","呼气和吸气都是主动的","呼气时有胸锁乳突肌参加收缩","用力呼吸使潮气量加大","用力呼吸时，肺内压变动程度增大"],"a":2,"e":"胸锁乳突肌为辅助吸气肌，在用力吸气时收缩，不在呼气时收缩，故该项错误。用力呼吸时辅助吸气肌参与（A项）。呼气和吸气均主动（B项）。潮气量加大（D项）。肺内压变动增大（E项），均正确"},{"q":"关于微终板电位的叙述，正确的是","o":["表现“全或无”特性","有不应期","是个别囊泡的自发释放在终板膜上引起的微小的电变化","是大量囊泡的自发释放在终板膜上引起的较大的电变化","是神经末梢单个动作电位引起的终板膜上的电变化"],"a":2,"e":"微终板电位是安静时个别囊泡自发释放少量乙酰胆碱在终板膜引起的微小去极化，约0.5mV。它不表现全或无（A项），无不应期（B项）。大量囊泡释放（D项）产生的是终板电位。单个动作电位引起（E项）亦为终板电位，非微终板电位"},{"q":"机体各种功能活动释放的能量中，最终不能转化为热能的是","o":["心脏泵血并推动血液流动","细胞合成各种功能蛋白质","兴奋在神经纤维上传导","肌肉收缩对外界物质做功","内、外分泌腺体的活动"],"a":3,"e":"肌肉收缩对外界做功使能量以机械能形式离开机体，不能最终转化为热能。心脏泵血（A项）、蛋白质合成（B项）、神经传导（C项）、腺体分泌（E项）所耗能量最终均变为热能"},{"q":"心室功能曲线反映下列哪种关系","o":["心率和心输出量","心率和搏功","搏功和心室充盈压","搏功和心输出量","心室充盈压和心率"],"a":2,"e":"心室功能曲线反映搏功（或心输出量）随心室充盈压（前负荷）变化的关系，体现异长自身调节。心率（A、B、E项）非该曲线坐标。搏功与心输出量（D项）之间非该曲线所表达的关系"},{"q":"下列关于激素的生理作用描述，哪一项不正确","o":["调节新陈代谢、维持内环境稳态","促进细胞的增殖与分化","影响神经系统的发育和功能","促进生殖器官的发育成熟","营养作用"],"a":4,"e":"激素主要通过调节代谢、生长、发育、生殖和神经系统功能发挥作用，并不直接提供营养。调节新陈代谢维持稳态（A项）、促进增殖分化（B项）、影响神经发育功能（C项）、促进生殖器官成熟（D项）均为其生理作用"},{"q":"肾脏近端小管进行重吸收的特点是","o":["重吸收的物质种类少","各种物质的重吸收量少","受到体液因素调节","主要受神经因素调节","小管液与上皮细胞内液保持等渗"],"a":4,"e":"近端小管重吸收为等渗性重吸收，小管液与上皮细胞内液保持等渗。其重吸收种类多、量大，A、B项错误。近端小管重吸收基本不受神经体液因素调节，C、D项错误"},{"q":"糖皮质激素的作用是下列哪一项","o":["抑制糖原分解","使血糖浓度升高","使肾脏排水能力降低","促进黏蛋白合成","使红细胞数量减少"],"a":1,"e":"糖皮质激素促进糖异生并减少外周组织摄取利用葡萄糖，使血糖浓度升高。抑制糖原分解（A项）与其升糖作用不符。使肾排水能力降低（C项）、促进黏蛋白合成（D项）、红细胞减少（E项）均非其作用"},{"q":"儿茶酚胺可调节心肌生物电活动，对其作用机制描述正确的是","o":["加强浦肯野细胞4期内向电流If","复极化2期Ca2+内流减慢","慢反应细胞0期Ca2+内流减慢","窦房结细胞4期自动去极速度加快","快反应细胞动作电位上升速度减慢"],"a":3,"e":"儿茶酚胺激动β受体，使窦房结4期自律电流及钙内流增强，自动去极化加快，心率上升。它使平台期钙内流加强而非减慢，B项错误。使慢反应细胞0期钙内流加快，C项错误。使快反应细胞0期上升加快，E项错误"},{"q":"在下列关于肌紧张的描述中，错误的是","o":["屈肌的肌紧张表现明显","主要的生理意义是维持站立姿势","肌紧张的反射中枢在脊髓","肌紧张的感受器是肌梭","脑干网状结构中有肌紧张的易化区"],"a":0,"e":"维持姿势的肌紧张以伸肌（抗重力肌）表现最明显，屈肌不明显，故该项错误。其生理意义为维持站立姿势（B项）。中枢在脊髓（C项）。感受器为肌梭（D项）。脑干网状结构存在易化区（E项），均正确"},{"q":"下列关于曲张体的叙述，错误的是","o":["为神经与效应器发生联系的部位","内含贮存递质的小泡","只存在于肾上腺素能神经末梢","为神经末梢的结节状装置","为非定向突触"],"a":2,"e":"曲张体为自主神经节后纤维末梢的串珠状膨大，既见于肾上腺素能也见于胆碱能等神经末梢，说只存在于肾上腺素能神经末梢错误。其为神经与效应器联系部位（A项），含递质小泡（B项），呈结节状（D项），属非定向突触（E项）"},{"q":"与葡萄糖耦联转运的离子是","o":["Na+","K+","C1-","Ca2+","Fe2+"],"a":0,"e":"小肠与肾小管对葡萄糖的重吸收依赖钠-葡萄糖同向转运，属继发性主动转运，与钠耦联。钾（B项）、氯（C项）、钙（D项）、亚铁离子（E项）均非葡萄糖耦联转运离子"},{"q":"在动物实验中，暂时夹闭家兔一侧颈总动脉可引起","o":["心率减慢","心肌收缩力减弱","外周血管收缩","心交感神经活动减弱","心迷走神经活动增强"],"a":2,"e":"夹闭一侧颈总动脉使颈动脉窦压下降，压力感受器传入减少，反射性引起心交感与交感缩血管活动加强，外周血管收缩、血压升高。心率应加快（A项错）。收缩力应加强（B项错）。心交感活动应加强（D项错）。心迷走应减弱（E项错）"},{"q":"下列能引起胰液分泌减少的因素是","o":["胃酸","蛋白质分解产物","促胃液素","促胰液素","胰多肽"],"a":4,"e":"胰多肽抑制胰腺外分泌，使胰液分泌减少。胃酸（A项）刺激促胰液素释放。蛋白质分解产物（B项）与促胃液素（C项）均促进胰液分泌。促胰液素（D项）促进胰液尤其碳酸氢盐分泌"},{"q":"下列关于甲状腺激素合成的描述，哪一项是错误的","o":["合成甲状腺激素的原料是碘和甲状腺球蛋白","T4的数量多于T3","甲状腺激素有结合型和游离型两种运输形式","甲状腺腺泡上皮摄碘的过程是被动转运","抑制甲状腺过氧化酶可抑制甲状腺激素的合成"],"a":3,"e":"甲状腺腺泡上皮摄碘由碘泵（钠-碘同向转运体）主动完成，可逆浓度梯度浓集碘，非被动转运，故该项错误。原料为碘和甲状腺球蛋白（A项）。T4多于T3（B项）。有结合型与游离型（C项）。抑制过氧化酶阻断合成（E项），均正确"},{"q":"判断组织兴奋性高低最常用的简便指标是","o":["阈电位","时值","阈强度","强度-时间变化率","刺激的频率"],"a":2,"e":"阈强度是衡量兴奋性高低最常用的简便指标，阈强度越小兴奋性越高，越大则越低。时值（B项）、强度-时间变化率（D项）亦可反映但不够简便。阈电位（A项）为爆发动作电位的临界膜电位。刺激频率（E项）非兴奋性指标"},{"q":"具有“全或无”特征的电信号是","o":["终板电位","感受器电位","兴奋性突触后电位","抑制性突触后电位","动作电位"],"a":4,"e":"动作电位由电压门控Na+通道再生性开放产生，达阈电位即爆发固定幅度，不随刺激增强而变大，故呈全或无。终板电位、感受器电位及兴奋性、抑制性突触后电位皆属局部电位，幅度随刺激分级变化、可总和并电紧张扩布，均无全或无特征"},{"q":"最能反映血液中红细胞数量相对值的是","o":["血液比重","血液黏滞性","血细胞比容","血液渗透压","血红蛋白含量"],"a":2,"e":"血细胞比容为血细胞在全血中所占容积百分比，红细胞占绝大多数，故其数值直接反映红细胞数量的相对值。血液比重受血浆蛋白与红细胞共同影响，黏滞性还取决于血浆成分，血红蛋白含量反映携氧能力而非数量相对值，均不如比容贴切"},{"q":"胃大部分切除的患者出现贫血的主要原因是","o":["壁细胞减少","黏液减少","维生素B12吸收减少","碳酸氢盐减少","胃蛋白酶活性减弱"],"a":2,"e":"胃大部切除后壁细胞及内因子分泌锐减，维生素B12需与内因子结合才能在回肠吸收，缺乏致巨幼红细胞性贫血，是术后贫血主因。黏液、碳酸氢盐减少主要削弱黏膜屏障引起炎症，胃蛋白酶活性减弱影响消化而非造血，均非贫血关键"},{"q":"以下哪项不属于细胞膜蛋白质的功能","o":["作为转运蛋白参与物质转运","作为离子通道参与物质转运","作为抗原决定簇","参与信息传递","作为ATP酶，分解ATP"],"a":2,"e":"细胞膜蛋白主要承担物质转运（载体、通道）、酶催化（如ATP酶）及受体信息传递等功能。抗原决定簇多为膜外侧糖蛋白或糖脂的糖链，属糖被识别标志，并非膜蛋白本身的功能范畴，故该项不属膜蛋白功能"},{"q":"下列有关同一细胞兴奋传导的叙述，哪项是错误的","o":["动作电位可沿细胞膜传导到整个细胞","传导方式是通过产生局部电流刺激未兴奋部位，使之也出现动作电位","在有髓纤维是跳跃传导","有髓纤维传导动作电位的速度比无髓纤维快","动作电位的幅度随传导距离增加而减小"],"a":4,"e":"动作电位沿膜传导时靠局部电流刺激邻近未兴奋部位重新爆发，幅度不因距离增加而衰减，这是全或无的必然结果。有髓纤维借助郎飞结跳跃传导，速度高于无髓纤维；局部电流与跳跃传导表述均正确，唯幅度递减违背全或无"},{"q":"神经中枢内有抑制活动，其中突触后抑制的形成是由于","o":["突触前膜释放的神经递质减少","抑制一个兴奋性中间神经元","兴奋一个抑制性中间神经元","中间神经元末梢释放的递质减少","突触后膜产生的EPSP减小"],"a":2,"e":"突触后抑制由传入侧支兴奋抑制性中间神经元，其末梢释放抑制性递质使突触后膜Cl-内流、K+外流而超极化，产生IPSP。突触前膜释放递质减少属突触前抑制的机制；EPSP减小只是结果而非抑制形成的原因"},{"q":"室性期前收缩之后出现代偿间歇的原因是","o":["窦房结的兴奋延迟发放","窦房结的兴奋少发放一次","室性期前收缩有效不应期特别长","窦房结的兴奋落在期前收缩的有效不应期内","窦房结的兴奋提前发放"],"a":3,"e":"室性期前收缩后，紧接着的窦房结正常兴奋恰好落在期前收缩的有效不应期内，无法引起心室再次兴奋，须待下一次窦性激动才恢复，故出现代偿间歇。窦房结并未停发或延迟发放，期前收缩的不应期也非特别延长，关键在于时相巧合"},{"q":"大脑皮质的本体感觉代表区位于","o":["第二感觉区","颞叶皮质","运动辅助区","中央前回","中央后回"],"a":3,"e":"大脑皮质本体感觉代表区主要位于中央前回运动区，接受来自关节、肌肉、肌梭的深感觉投射，与随意运动的发起部位重叠。中央后回为第一感觉区，主司皮肤痛温触等浅感觉；第二感觉区、颞叶皮质及运动辅助区均非本体感觉的主要代表区"},{"q":"在细胞膜脂质成分中，几乎全部分布在膜的内侧并与第二信使DC和IP3的产生有关的是","o":["磷脂酰胆碱","鞘酯","磷脂酰乙醇胺","磷脂酰丝氨酸","磷脂酰肌醇"],"a":4,"e":"磷脂酰肌醇主要分布于膜内侧，其磷酸化产物PIP2经磷脂酶C水解生成IP3与DG两个第二信使，分别促钙释放与激活蛋白激酶C。磷脂酰胆碱、鞘脂、磷脂酰乙醇胺及磷脂酰丝氨酸虽也是膜脂，但不参与该信号通路"},{"q":"微循环中与体温调节有关的关键组成部分是","o":["后微动脉","通血毛细血管","毛细血管前括约肌","真毛细血管","动-静脉吻合支"],"a":4,"e":"动-静脉吻合支管壁富含平滑肌，受交感神经调控，可快速改变皮肤血流量以调节散热，是微循环中体温调节的关键结构。后微动脉、毛细血管前括约肌主要调节真毛细血管血流，通血毛细血管与真毛细血管侧重物质交换"},{"q":"快反应自律细胞是","o":["心房肌细胞","窦房结细胞","心室肌细胞","浦肯野氏细胞","房室结细胞"],"a":3,"e":"浦肯野细胞属快反应自律细胞，0期由快Na+通道介导去极迅速，4期存在If起搏电流而具自律性。心室肌、心房肌虽为快反应但无自律性；窦房结、房室结为慢反应自律细胞，0期依赖Ca2+内流"},{"q":"鼓膜温度可用来检测脑内温度，其数值最接近下列哪个部位的温度","o":["大脑","小脑","中脑","下丘脑","延髓"],"a":3,"e":"鼓膜与下丘脑同属脑深部温度代表，血供丰富且受环境温度影响小，其温度最接近下丘脑即体温调节中枢的核心温度。大脑、小脑、中脑、延髓虽也在颅内，但鼓膜温度实测对应的是下丘脑水平，临床以此反映中枢温度"},{"q":"纤维蛋白降解产物的主要作用是","o":["促进凝血酶的活性","防止血小板的激活","对抗血液凝固","促进纤维蛋白单体聚合","抑制纤维蛋白溶解"],"a":2,"e":"纤维蛋白降解产物是纤溶酶水解纤维蛋白（原）的产物，可抑制凝血酶、阻碍纤维蛋白单体聚合与血小板聚集，总体对抗血液凝固并促纤溶。它不促进凝血酶活性、不助聚合，也不抑制纤溶，恰与相反表述相悖"},{"q":"影响神经系统发育的最重要的激素是","o":["糖皮质激素","生长激素","盐皮质激素","肾上腺素","甲状腺激素"],"a":4,"e":"甲状腺激素促进中枢神经系统发育与髓鞘形成，婴幼儿缺乏致呆小症，是影响神经系统发育最重要的激素。生长激素主要促躯体生长，糖皮质激素、盐皮质激素及肾上腺素参与应激与水盐代谢，对神经发育影响远不及甲状腺激素"},{"q":"用直流电刺激神经干，通电时的兴奋是发生在","o":["阴极下方","阳极下方","阴极下方或阳极下方均可","阴极或阳极之间","阴极或阳极以外的地方"],"a":0,"e":"直流电刺激神经干时，通电瞬间阴极下方膜发生去极化达到阈电位而爆发动作电位，阳极下方则超极化。断电刺激时兴奋出现在阳极，故需区分通电与断电；阴极与阳极之间或以外区域不构成有效刺激部位"},{"q":"关于雄激素的描述，下列哪一项是正确的","o":["是含氮类激素","以双氢睾酮分泌量最多","游离的雄激素不能发挥生物学作用","主要在肾脏灭活","是雌二醇前体"],"a":4,"e":"睾酮经芳香化酶作用可转化为雌二醇，故雄激素是雌二醇合成的前体。雄激素属类固醇而非含氮激素；分泌量最多的是睾酮而非双氢睾酮；具生物活性的是游离型；其灭活主要在肝脏而非肾脏"},{"q":"一次大量饮清水后，尿量增多的主要原因是","o":["血压升高","血浆胶体渗透压降低","肾小球毛细血管血压升高","血浆晶体渗透压降低","循环血量增加"],"a":3,"e":"一次大量饮清水使血浆晶体渗透压降低，减弱对下丘脑渗透压感受器的刺激，抗利尿激素释放减少，远曲小管与集合管重吸收水下降，尿量显著增加，称水利尿。血压、胶体渗透压及肾小球毛细血管压在此并非主要因素"},{"q":"在脊髓作为反射中枢的反射活动中，不包括","o":["屈肌反射","腱反射","血管张力反射","排尿反射","翻正反射"],"a":4,"e":"屈肌反射、腱反射、血管张力反射与排尿反射的初级中枢均在脊髓。翻正反射需中脑（红核、上丘等）参与整合，属于脑水平反射，切断脊髓的动物不能完成，故不属于以脊髓为中枢的反射活动"},{"q":"下列关于胰岛素的描述，哪项是错误的","o":["促进糖原合成","促进糖的贮存和利用，使血糖降低","促进脂肪和蛋白质的分解和利用","是维持正常代谢和生长所不可缺少的重要激素之一","缺乏时血糖升高，可形成糖尿病"],"a":2,"e":"胰岛素促进葡萄糖摄取、糖原合成与贮存利用，从而降低血糖，并促进脂肪与蛋白质合成、抑制其分解，是维持正常代谢与生长的关键激素，缺乏致糖尿病。促进脂肪和蛋白质分解与胰岛素作用相反，属胰高血糖素等的作用"},{"q":"十二指肠内容物返流入胃对黏膜屏障有破坏作用的物质是","o":["碳酸氢盐","高渗溶液","胆汁酸","黏蛋白","氨基酸"],"a":2,"e":"胆汁酸为两性表面活性剂，返流入胃可破坏胃黏膜表面黏液-碳酸氢盐屏障，增加H+反向扩散而损伤黏膜。碳酸氢盐、黏蛋白是屏障的保护成分，氨基酸、高渗溶液无此去污破坏作用，均非返流致损的关键物质"},{"q":"对长期大量用糖皮质激素治疗疾病的患者，下列哪一项分析不正确","o":["患者可表现出向心性肥胖","患者血液皮质激素水平较高","患者血液中促肾上腺皮质激素水平较高","患者肾上腺皮质束状带萎缩","所治的疾病痊愈后不应突然停药"],"a":2,"e":"长期大量外源糖皮质激素经负反馈抑制下丘脑-垂体-肾上腺轴，使ACTH分泌减少，肾上腺皮质束状带因失刺激而萎缩，血中皮质激素升高，出现向心性肥胖。故ACTH水平升高之说与负反馈相悖，为错误项"},{"q":"下述关于超速压抑的描述，不正确的是","o":["高频起搏点驱使低频起搏点跟随低频率起搏点搏动","频率差别越大，抑制效应越强","窦房结停搏后，首先由受压抑程度较小的房室交界起搏","窦房结对心室的控制中断后，可出现一段时间的心室停搏","为避免撤去超速抑制时诱发的心脏停搏，中断人工起搏器时应逐步减慢其驱动频率"],"a":0,"e":"超速压抑指高频起搏点以其较高频率驱动低频起搏点，使后者跟随高频搏动，频率差越大抑制越强；窦房结控制中断后可有一段时间心脏停搏，故撤除人工起搏须逐步减速。题干所称跟随低频率起搏点搏动恰与驱动方向相反"},{"q":"关于Rh血型的下列叙述，正确的是","o":["汉族人群中Rh阴性率为90%","抗Rh抗体是不完全抗体","血浆抗Rh因子为天然抗体","Rh阴性者的血液不可输给Rh阳性者","红细胞表面没有D抗原者为Rh阳性"],"a":1,"e":"抗Rh抗体多为免疫性IgG，属不完全抗体，不能在盐水介质中直接凝集红细胞。汉族Rh阴性率约1%而非90%；抗Rh非天然抗体；Rh阴性血可输给Rh阳性者；红细胞无D抗原者为Rh阴性，故其余各项均错"},{"q":"下列关于缺O2对呼吸影响的叙述，正确的是","o":["直接兴奋延髓呼吸中枢","直接兴奋脑桥呼吸中枢","严重缺O2时呼吸加深加快","轻度缺O2时呼吸加深加快","对呼吸有抑制作用"],"a":3,"e":"轻度缺氧时外周化学感受器（颈动脉体、主动脉体）受刺激，传入冲动兴奋延髓呼吸中枢，使呼吸加深加快；严重缺氧则直接抑制呼吸中枢使呼吸减弱。缺氧并不直接兴奋延髓或脑桥中枢，其兴奋效应依赖外周感受器"},{"q":"中枢化学感受器最敏感的刺激物是","o":["血液中的[H+]","脑脊液中的[H+]","血液中的[CO2]","脑脊液中的[CO2]","脑脊液中［O2］"],"a":1,"e":"中枢化学感受器位于延髓腹外侧，对脑脊液中的H+最敏感；CO2透过血脑屏障后生成H+而间接起作用。血液H+不易通过血脑屏障，脑脊液中CO2本身及O2均非直接刺激，故脑脊液H+为最敏感刺激物"},{"q":"不影响心肌细胞自律性的因素是","o":["最大复极电位","阈电位","有效不应期","4期自动去极速度","最大复极电位与阈电位差距"],"a":2,"e":"心肌自律性取决于4期自动去极速度、最大复极电位水平、阈电位及二者差距，与有效不应期长短无关。有效不应期反映兴奋后恢复时间，影响的是兴奋性而非自律性，故为不影响自律性的因素"},{"q":"下列关于应激反应的描述，哪一项是正确的","o":["促肾上腺皮质激素浓度降低","糖皮质激素浓度降低","儿茶酚胺含量降低","对有害刺激的抵抗力提高","是一种特异性反应"],"a":3,"e":"应激反应是机体遭受有害刺激时出现的非特异性适应反应，以ACTH和糖皮质激素分泌增加为特征，可提高对有害刺激的耐受与抵抗力。血中ACTH、糖皮质激素、儿茶酚胺均升高而非降低，且反应属非特异性"},{"q":"决定细胞在单位时间内能够产生兴奋的最多次数是","o":["绝对不应期","相对不应期","超常期","恢复期","低常期"],"a":0,"e":"绝对不应期内无论多大刺激都不能再产生兴奋，其时程决定了细胞单位时间内爆发动作电位的最大值。相对不应期、超常期与低常期兴奋性虽有变化但均可再兴奋，不决定最高兴奋频率"},{"q":"安静时，散发热量最多的方式是","o":["辐射","传导","对流","蒸发","加温吸入气体"],"a":0,"e":"安静、环境温度适宜时辐射是主要散热方式，依靠体表向周围物体发射红外线，占总散热量最大比例。传导需直接接触冷物体，对流依赖空气流动，蒸发在高温时才成主要方式，加温吸入气体散热量极微"},{"q":"盆神经兴奋时，将引起","o":["膀胱逼尿肌收缩","膀胱逼尿肌舒张","尿道内括约肌收缩","尿道外括约肌收缩","尿道外括约肌舒张"],"a":0,"e":"盆神经属副交感神经，兴奋时节后纤维释放ACh，使膀胱逼尿肌收缩、尿道内括约肌舒张，促进排尿。尿道外括约肌由阴部神经（躯体神经）支配，其舒缩不受盆神经直接控制，逼尿肌舒张则与排尿相悖"},{"q":"影响正常人舒张压的主要因素是","o":["大动脉弹性","心输出量","阻力血管的口径","血液的黏滞性","血管长度"],"a":2,"e":"外周阻力是形成舒张压的关键，阻力血管（小动脉、微动脉）口径缩小使心舒期血液外流减慢，舒张压明显升高。大动脉弹性主要影响脉压，心输出量更多影响收缩压，血液黏滞性与血管长度作用相对次要"},{"q":"机体缺氧、PCO2升高，以及使用麻醉剂等药物的情况下，神经中枢内最易受到影响的功能是","o":["神经元兴奋","神经冲动传导","神经胶质细胞绝缘作用","突触传递","血管壁扩散距离"],"a":3,"e":"突触传递需经递质释放、受体结合等多个环节，能量依赖高且对缺氧、CO2潴留及麻醉剂最敏感，易率先发生障碍。神经元兴奋、冲动传导及胶质细胞绝缘相对耐受，血管壁扩散距离并非神经中枢功能"},{"q":"进行腹式呼吸的吸气时，下述哪块肌肉收缩为主","o":["肋间外肌","腹直肌","肋间内肌","膈肌","斜角肌"],"a":3,"e":"腹式呼吸以膈肌舒缩为主，吸气时膈肌收缩下移，腹腔脏器推向下致腹壁隆起。肋间外肌收缩主要形成胸式呼吸，肋间内肌与腹直肌参与用力呼气，斜角肌为辅助吸气肌，均非腹式呼吸的主要动力"},{"q":"引起促胰液素释放的因素由强至弱的排列顺序为","o":["脂酸钠、蛋白质分解产物、盐酸","蛋白质分解产物、脂酸钠、盐酸","盐酸、脂酸钠、蛋白质分解产物","盐酸、蛋白质分解产物、脂酸钠","蛋白质分解产物、盐酸、脂酸钠"],"a":3,"e":"促胰液素由十二指肠S细胞释放，刺激因素强弱依次为盐酸、蛋白质分解产物、脂酸钠，盐酸是其最强刺激。若把蛋白质分解产物或脂酸钠列首位即混淆了促胰液素与缩胆囊素的排序，后者以蛋白质分解产物最强"},{"q":"下列关于IPSP产生过程的叙述，错误的是","o":["突触前膜去极化，Ca2+进入突触前膜内","K+内流突触后膜去极化产生IPSP","释放抑制性递质","突触后膜对Cl-、K+通透性增强","囊泡与前膜融合破裂"],"a":1,"e":"IPSP由突触前膜释放抑制性递质，使突触后膜对Cl-、K+通透性增高，Cl-内流、K+外流导致超极化；K+内流引起去极化是错误表述。突触前膜去极化、Ca2+内流及囊泡融合释放均属正常突触传递环节"},{"q":"记录神经纤维动作电位时，加入选择性离子通道阻断剂河鲀毒素，会出现什么结果","o":["静息电位变小","静息电位变大","去极相不出现","超射不出现","以上都不正确"],"a":2,"e":"河鲀毒素选择性阻断电压门控Na+通道，动作电位0期去极由Na+内流产生，故去极相不能出现。静息电位主要由K+外流形成，受影响小；超射消失是去极受阻的结果，但根本变化在于去极相缺失"},{"q":"下列可以使氧解离曲线左移的是","o":["血液PCO2降低","血液H+浓度升高","温度升高","血液PCO2升高","红细胞中2,3-DPG浓度升高"],"a":0,"e":"血液PCO2降低使H+浓度下降，血红蛋白对O2亲和力增高，氧解离曲线左移。H+浓度升高、温度升高、2,3-DPG增多均促曲线右移，利于释氧；PCO2升高亦右移，故仅PCO2降低符合左移"},{"q":"乙酰胆碱通过增加心肌细胞膜上通道的通透性而影响心肌细胞的电活动，不能引起下列哪种生理变化","o":["阈电位绝对值增大","动作电位时程缩短","静息电位绝对值增大","窦房结细胞4期自动去极速度减慢","膜对钾离子的通透性增加"],"a":0,"e":"ACh使心肌细胞膜K+通透性增加，静息电位绝对值增大、窦房结4期自动去极减慢、动作电位时程缩短，从而抑制心脏。它并不使阈电位绝对值增大，该项为迷走作用不能引起的电生理变化"},{"q":"下列哪个是人体内最大、最复杂的内分泌器官","o":["甲状腺","肾上腺","消化道","卵巢","下丘脑"],"a":2,"e":"消化道黏膜广泛分布胃泌素、促胰液素、缩胆囊素等多种胃肠激素细胞，数量与种类居全身之首，是人体最大、最复杂的内分泌器官。甲状腺、肾上腺、卵巢及下丘脑虽重要，但规模与激素种类均不及消化道"},{"q":"空腹时，大肠最常见的运动形式是","o":["集团蠕动","分节运动","紧张性收缩","袋状往返运动","多袋推进运动"],"a":3,"e":"袋状往返运动是空腹时大肠最常见的形式，由环形肌不规则收缩使结肠袋内容物来回移位，利于吸收水分。集团蠕动多见于进食后，分节运动为小肠主要形式，紧张性收缩是基础张力，多袋推进运动推进性较强"},{"q":"心交感与心迷走神经节前纤维末梢释放的递质是","o":["乙酰胆碱","去甲肾上腺素","肾上腺素","多巴胺","5-羟色胺"],"a":0,"e":"心交感与心迷走神经均属自主神经，其节前纤维末梢释放的递质都是乙酰胆碱，作用于节后神经元N受体。节后纤维则不同：心交感释放去甲肾上腺素作用于β1受体，心迷走释放ACh作用于M受体，勿与节前混淆"},{"q":"决定心室肌细胞0期去极速度的因素是","o":["Na+通道开放速度","Na+通道失活的速度","Na+通道复活速度","Na+-K+泵活性","Na+-Ca2+泵活性"],"a":0,"e":"心室肌0期去极由快Na+通道开放、Na+快速内流引起，其去极速度和幅度取决于Na+通道的开放速度与数量。通道失活、复活及Na+-K+泵活性影响的是后续时相或离子稳态，不决定0期上升支速度"},{"q":"肺的弹性回缩力见于","o":["吸气初","呼气初","呼气末","吸气末","整个呼吸过程中"],"a":4,"e":"肺弹性回缩力源于肺组织弹性纤维与肺泡表面张力，始终存在且方向向内，使肺倾向于回缩。吸气时它对抗吸气肌、呼气时成为呼气动力，故贯穿整个呼吸过程，而非仅见于某一时相"},{"q":"轻触眼角膜引起眨眼动作，该调节方式属于","o":["神经反射","神经体液调节","激素远距分泌","旁分泌","自身调节"],"a":0,"e":"轻触角膜刺激角膜感觉神经末梢，冲动经三叉神经传入、面神经传出引起眨眼，属典型的神经反射。该过程无需激素参与，故非神经体液调节或激素远距分泌、旁分泌；自身调节是不依赖神经体液的内部适应，也不符合"},{"q":"高血压患者与正常人相比，下列指标明显增高的是","o":["每搏输出量","心输出量","心脏做功量","心指数","射血分数"],"a":2,"e":"高血压患者动脉血压长期升高，心室射血时需克服更大后负荷，每搏做功及每分功显著增加，故心脏做功量明显增高。每搏输出量、心输出量、心指数与射血分数在早期高血压未必增高，甚至可正常"},{"q":"在牵张反射活动中，肌梭的传入神经纤维有","o":["Ⅲ和Ⅳ类纤维","Ⅰa和Ⅱ类纤维","Ⅰa和Ⅰb纤维","Ⅰ和Ⅱ类纤维","Ⅱ和Ⅲ类纤维"],"a":1,"e":"牵张反射中肌梭的传入纤维为Ⅰa类（螺旋形末梢，感受长度变化）和Ⅱ类（花枝样末梢）纤维。Ⅰb类来自腱器官，Ⅲ、Ⅳ类为细纤维主要传导痛觉等，均非肌梭传入，故与肌梭相关的是Ⅰa和Ⅱ类"},{"q":"有关静息电位的叙述，哪项是错误的","o":["由K+外流所致，相当于K+的平衡电位","膜内电位较膜外为负","各种细胞的静息电位数值是不相同的","是指细胞安静时膜内外两侧的电位差","由Na+外流所致，相当于Na+的平衡电位"],"a":4,"e":"静息电位主要由K+外流形成，接近K+平衡电位，表现为膜内负于膜外，不同细胞数值各异。由Na+外流所致、相当于Na+平衡电位的说法恰好颠倒，Na+平衡电位对应的是动作电位超射而非静息电位"},{"q":"下列关于肾素-血管紧张素系统（RAS）功能的叙述，正确的是","o":["仅对血压进行调节","主要实现对动脉血压的短期调节","仅存在全身性的体液调节作用","失血可导致该系统活动抑制","功能异常与高血压的发病有关"],"a":4,"e":"肾素-血管紧张素-醛固酮系统既调节血压与水盐平衡，也参与心血管重构，其功能异常与原发性高血压发病密切相关。该系统并非仅调血压或仅全身性作用，失血时反而激活而非抑制，也不属于短期调节为主"},{"q":"细肌丝组成中含量最高的蛋白类型是","o":["肌动蛋白","原肌球蛋白","肌球蛋白","肌钙蛋白","肌纤蛋白"],"a":0,"e":"细肌丝由肌动蛋白、原肌球蛋白和肌钙蛋白组成，其中肌动蛋白含量最高，构成细肌丝主体并含横桥结合位点。肌球蛋白属粗肌丝；原肌球蛋白、肌钙蛋白为调节蛋白，含量远低于肌动蛋白"},{"q":"由下丘脑视上核和室旁核合成的缩血管物质是","o":["血管紧张素","血管升压素","内皮素","去甲肾上腺素","5-羟色胺"],"a":1,"e":"血管升压素（抗利尿激素）由下丘脑视上核与室旁核合成，经轴突运输至神经垂体释放，具收缩血管与抗利尿作用。血管紧张素来自肝源性血管紧张素原，内皮素由血管内皮生成，去甲肾上腺素、5-羟色胺为神经递质"},{"q":"为心室肌细胞动作电位4期逆浓度梯度外运提供能量的是","o":["Cl-泵","Ca2+泵","Na+泵","浓度梯度","K+泵"],"a":2,"e":"心室肌4期通过Na+-K+泵主动将Na+逆浓度梯度泵出、K+泵入，消耗ATP以恢复离子分布，为逆浓度外运提供能量的正是Na+泵。Ca2+泵、Cl-泵不主导此过程，浓度梯度是顺浓度扩散的动力而非耗能来源"},{"q":"切断动物双侧迷走神经后会出现","o":["呼吸频率加快","呼气幅度减小","吸气相缩短","呼气相延长","呼吸频率减慢，幅度增大"],"a":4,"e":"迷走神经传入参与肺牵张反射（黑-伯反射），切断双侧迷走神经后该反射消失，吸气不再被及时终止，致吸气相延长、呼吸变深变慢。故表现为呼吸频率减慢、幅度增大，而非频率加快或呼气幅度减小"},{"q":"下列关于唾液分泌调节的叙述，正确的是","o":["神经调节只有非条件反射","交感神经兴奋时分泌减少","唾液分泌中枢位于丘脑","使用阿托品后，分泌减少","睡眠时分泌减少"],"a":3,"e":"唾液分泌由副交感胆碱能纤维主导，阿托品阻断M受体使分泌显著减少。唾液分泌中枢在延髓而非丘脑；神经调节兼有非条件与条件反射，非仅非条件反射；交感兴奋主要使分泌黏稠、量不一定减少"},{"q":"用于分析比较不同身材个体心功能的常用指标是","o":["每分输出量","心指数","射血分数","心脏作功量","心力储备"],"a":1,"e":"心指数是以单位体表面积计算的心输出量，剔除了身材差异，便于比较不同个体心功能。心输出量、每分输出量受体型影响大，射血分数反映泵血效率，心力储备反映最大潜力，均不适合跨身材比较"},{"q":"正常情况下不能经肾小球滤过的物质是","o":["Na+、Cl-、HCO3-等电解质","血浆白蛋白","葡萄糖","氨基酸","甘露醇"],"a":1,"e":"肾小球滤过膜有机械屏障与负电荷屏障，血浆白蛋白分子大且带负电，几乎不能滤过。Na+、Cl-、HCO3-等电解质及葡萄糖、氨基酸可自由滤过，甘露醇亦可滤过，故仅白蛋白属正常不能滤过物质"},{"q":"呼吸过程中肺内压的变化是","o":["吸气时大于大气压，呼气时小于大气压","吸气、呼气时均小于大气压","吸气时小于大气压，呼气时大于大气压","吸气及呼气时均大于大气压","吸气末等于大气压，呼气时小于大气压"],"a":2,"e":"吸气时胸廓扩大、肺容积增大致肺内压低于大气压，空气入肺；呼气时肺回缩、肺内压高于大气压，气体排出。吸气末与呼气末肺内压均等于大气压，故吸气低于、呼气高于大气压的表述正确"},{"q":"下列关于大动脉硬化导致心血管系统变化的叙述，错误的是","o":["收缩压升高","舒张压降低","脉压增大","大动脉顺应性下降","脉搏波传播速度减慢"],"a":4,"e":"大动脉硬化使管壁顺应性下降、弹性贮器作用减弱，收缩压升高、舒张压降低、脉压增大，脉搏波传播速度因管壁变硬而加快而非减慢。故传播速度减慢与硬化后果相反，为错误叙述"},{"q":"下列关于神经纤维兴奋传导特征的叙述，错误的是","o":["双向传导","绝缘性","兴奋节律不改变","总和","对内环境敏感"],"a":3,"e":"神经纤维兴奋传导具双向性、绝缘性、相对不疲劳性，且动作电位全或无使兴奋节律不改变，对内环境变化敏感。总和是突触传递的特征，需多个突触电位叠加，单根神经纤维的传导不具备，故为错误项"},{"q":"刺激阈值指的是","o":["用最小刺激强度，刚刚引起组织兴奋的最短作用时间","保持一定的刺激强度不变，能引起组织兴奋的最适作用时间","保持一定的刺激时间和强度-时间变化率不变，引起组织发生兴奋的最小刺激强度","刺激时间不限，能引起组织兴奋的最适刺激强度","刺激时间不限，能引起组织最大兴奋的最小刺激强度"],"a":2,"e":"阈强度指在刺激时间与强度-时间变化率固定的条件下，刚能引起组织兴奋的最小刺激强度，即刺激阈值。保持这两个条件是定义前提。仅强调最短作用时间或最适强度、不固定变化率的定义均不准确"},{"q":"自主神经节前纤维释放的递质是","o":["ACh和NE","NE","5-HT","ACh","NE和5-HT"],"a":3,"e":"交感和副交感神经的节前纤维末梢均释放乙酰胆碱，作用于节后神经元或肾上腺髓质嗜铬细胞的N受体。节后纤维递质则不同，多数交感节后释放去甲肾上腺素，故ACh和NE并列或NE、5-HT单独均不适用于节前纤维"},{"q":"心迷走节后纤维末梢释放的递质主要与下列哪一种受体结合","o":["M受体","N受体","α受体","β1受体","β2受体"],"a":0,"e":"心迷走节后纤维末梢释放乙酰胆碱，与心肌细胞膜上的M型胆碱能受体结合，经G蛋白开放K+通道，引起负性变时、变传导、变力作用。N受体位于神经节突触后膜，α、β1、β2为肾上腺素能受体，均非迷走节后效应受体"},{"q":"下列疾病中，能够使肺通气/血流比值增高最明显的是","o":["肺纤维化形成","肺水肿","支气管哮喘发作","肺栓塞","肺癌"],"a":3,"e":"肺栓塞时肺动脉分支阻塞，病变肺区血流中断而通气仍存在，通气/血流比值显著升高，形成功能性死腔。肺纤维化、肺水肿主要损害弥散或通气，支气管哮喘使通气下降致比值降低，均不及栓塞升高明显"},{"q":"心室肌细胞动作电位的时程主要取决于","o":["Na+内流的速度","Cl-内流的速度","Ca2+内流的速度","K+外流的速度","Na+外流的速度"],"a":2,"e":"心室肌动作电位时程主要取决于2期平台期，平台由Ca2+缓慢内流与K+外流平衡维持，故Ca2+内流速度是关键决定因素。Na+内流主导0期、K+外流主导3期复极，均不决定平台时长"},{"q":"心室等容收缩期瓣膜的状态是","o":["房室瓣开放，动脉瓣关闭","房室瓣关闭，动脉瓣关闭","房室瓣关闭，动脉瓣开放","房室瓣开放，动脉瓣开放","房室瓣、动脉瓣间无规律开关"],"a":1,"e":"等容收缩期室内压迅速升高但尚未超过动脉压，房室瓣已关闭而动脉瓣仍未开放，两瓣均关闭使心室容积不变。房室瓣开放见于充盈期，动脉瓣开放始于射血期，故只有双关闭符合等容收缩"},{"q":"动作电位的“全或无”特性是指同一细胞动作电位的幅度","o":["不受细胞外K+浓度的影响","不受细胞外Na+浓度的影响","与刺激强度和传导距离无关","与静息电位无关","与Na+通道的状态无关"],"a":2,"e":"全或无指同一细胞动作电位一旦产生即达固定幅度，其大小与刺激强度无关，且传导中不衰减故与传导距离无关。细胞外Na+浓度、Na+通道状态及静息电位会影响幅度，但这些并非全或无定义所指"},{"q":"调节心血管活动的最基本中枢是","o":["脊髓","延髓","脑桥","下丘脑","大脑皮层"],"a":1,"e":"调节心血管活动的最基本中枢位于延髓，含心迷走中枢、心交感中枢与交感缩血管中枢，可独立维持基本心血管反射。脊髓为初级中枢，脑桥、下丘脑、大脑皮层为较高级整合部位，均非最基本中枢"},{"q":"成年人生长激素分泌过多，将导致下列哪种疾病发生","o":["地方性甲状腺肿","单纯性甲状腺肿","侏儒症","巨人症","肢端肥大症"],"a":4,"e":"成年后骨骺已闭合，生长激素分泌过多不能再使骨纵向生长，而致肢端肥大症，表现为手足增大、下颌突出等。侏儒症为幼年GH缺乏，巨人症为幼年GH过多，甲状腺肿与GH无关"},{"q":"纯胃液是无色的酸性液体，下列有关其pH值的描述正确的是","o":["0、9～1、5","2、5～3、0","3、5～4、5","5、0","6、5～7、5"],"a":0,"e":"纯胃液为无色酸性液体，pH约0.9～1.5，高酸度由壁细胞分泌HCl形成，有助于杀菌和激活胃蛋白酶原。2.5以上、3.5～4.5、5.0及6.5～7.5均偏中性或弱酸，与胃液强酸环境不符"},{"q":"微循环中真毛细血管的主要作用是","o":["调节外周阻力","调节体温","引流淋巴液","实现血液与组织液之间的物质交换","促进血液回流"],"a":3,"e":"真毛细血管管壁仅单层内皮细胞，通透性高、血流缓慢，是血液与组织液进行物质交换的主要场所。调节外周阻力靠微动脉，调节体温靠动-静脉吻合支，引流淋巴与促进回流并非真毛细血管的主要功能"},{"q":"下述形成心室肌细胞动作电位的离子基础，错误的是","o":["0期主要是Na+内流","1期主要是Cl-外流","2期主要是Ca2+内流","3期主要是K+外流","4期有K+内流"],"a":1,"e":"心室肌1期（快速复极初期）主要由瞬时外向K+电流引起，而非Cl-外流；0期为Na+内流，2期为Ca2+内流，3期为K+外流，4期有Na+-K+泵活动及K+内流。故1期归因Cl-外流错误"},{"q":"交感神经节前纤维释放的递质是","o":["ACh","NE","5-HT","ACh和NE","NE和5-HT"],"a":0,"e":"交感神经节前纤维末梢释放乙酰胆碱，作用于节后神经元N受体。去甲肾上腺素为多数交感节后纤维递质，5-HT与该系统无关，ACh和NE并列混淆了节前与节后，故节前递质只能是ACh"},{"q":"红细胞沉降率的快慢主要取决于红细胞的","o":["体积","表面积","数量","比重","叠连"],"a":4,"e":"红细胞沉降率主要取决于红细胞叠连，叠连后总表面积与容积比减小、摩擦阻力下降，血沉加快。红细胞数量、体积、表面积及比重并非决定血沉的关键，血浆成分改变也是通过影响叠连而起作用"},{"q":"下列关于窦房结细胞Ca2+通道的叙述中，错误的是","o":["是电压门控性通道","选择性高，只允许Ca2+通透","激活的阈电位水平为-40mV","参与窦房结细胞4期自动去极化","激活、失活以及再复活的时间均比Na+通道长"],"a":1,"e":"窦房结Ca2+通道为电压门控T型/L型通道，选择性不高，除Ca2+外也可通透Na+等，激活阈约-40mV，参与4期自动去极，且激活、失活、复活时间均长于Na+通道。故只允许Ca2+通透之说错误"},{"q":"控制呼吸基本节律的神经元位于","o":["脊髓前角","延髓","中脑","脑桥背外侧部","下丘脑"],"a":1,"e":"控制呼吸基本节律的神经元位于延髓，包括吸气神经元与呼气神经元构成的呼吸中枢，可产生节律性呼吸运动。脑桥背外侧部参与调整呼吸时相，脊髓前角为运动传出通路，中脑、下丘脑属更高级调节"},{"q":"下列哪种物质在胃排空的速度最慢","o":["糖、蛋白和脂肪的混合物","糖与蛋白的混合物","脂肪","蛋白质","糖"],"a":2,"e":"胃排空速度按糖、蛋白质、脂肪依次减慢，脂肪进入十二指肠后通过肠抑胃素、迷走-迷走反射等强烈抑制胃运动，故排空最慢。糖与蛋白混合物、蛋白质排空较快，糖最快，混合物介于其间"},{"q":"细胞膜上不衰减形式传播的电活动是","o":["动作电位","静息电位","终板电位","感受器电位","局部电位"],"a":0,"e":"动作电位以局部电流方式沿膜再生性传播，每一处都重新爆发相同幅度，故不衰减。静息电位是安静时的跨膜电位差不传播；终板电位、感受器电位与局部电位均为电紧张扩布，幅度随距离衰减"},{"q":"在突触传递中，当突触前神经元受到较高频率刺激时，引起突触后神经发放冲动减少的原因是","o":["突触前神经元出现适应","突触前神经产生的兴奋减少","突触后神经出现适应","神经递质与受体结合能力减弱","突触前神经元末梢的神经递质耗竭"],"a":4,"e":"突触前神经元受高频持续刺激时，末梢内神经递质释放速度超过合成与再摄取补充，导致递质耗竭，突触后电位减小、发放冲动减少。此为突触前变化，非突触前或突触后出现适应，也非受体结合力减弱"},{"q":"关于正常尿液的产生，描述正确的是","o":["每昼夜的尿量为2000～3000ml","尿液的渗透压高于血浆渗透压","尿液的pH值与饮食情况无关","尿液可检出少量葡萄糖","尿液中不能检出蛋白质和红细胞"],"a":4,"e":"正常尿液中不含蛋白质与红细胞，因滤过膜屏障及肾小管重吸收使其不被排出。正常尿量约1000～2000ml/昼夜，渗透压可高可低随饮水而变，pH受饮食影响，葡萄糖被完全重吸收故尿中检不出"},{"q":"兴奋性突触后电位与抑制性突触后电位的共同特征是","o":["突触前膜释放的递质性质一样","突触后膜均去极化","突触前膜均去极化","突触后膜对离子通透性一样","产生的突触后电位的最终效应一样"],"a":2,"e":"EPSP与IPSP产生的前提都是突触前膜去极化、Ca2+内流触发递质释放，故突触前膜均去极化是共同特征。二者递质性质不同；EPSP为去极化、IPSP为超极化；离子通透性与最终效应均相反"},{"q":"心室肌细胞的静息电位相当于","o":["EK","ENa","ECa","Ecl","EK及ENa的中间值"],"a":0,"e":"心室肌细胞静息时膜对K+通透性最高，K+外流达平衡，静息电位接近K+平衡电位EK。ENa对应动作电位超射，ECa参与平台期，ECl与抑制性电位相关，EK及ENa中间值说法不符合静息状态"},{"q":"下列关于肾上腺皮质分泌激素的描述，哪一项是错误的","o":["肾上腺皮质分泌的激素是维持生命所必需的","球状带分泌醛固酮","束状带分泌皮质醇","网状带分泌性激素","合成肾上腺皮质激素的原料是磷脂"],"a":4,"e":"肾上腺皮质激素属类固醇，合成原料是胆固醇而非磷脂。球状带分泌醛固酮、束状带分泌皮质醇、网状带分泌性激素，这些激素为维持生命必需，故原料为磷脂的表述错误"},{"q":"下列关于消化器官神经支配的叙述，正确的是","o":["交感神经节后纤维释放乙酰胆碱","所有副交感神经节后纤维均释放乙酰胆碱","去除外来神经后，内在神经仍能完成局部反射","外来神经对内在神经无调节作用","内在神经丛均存在于黏膜下和平滑肌间"],"a":2,"e":"消化管内在神经丛可独立完成局部反射，去除外来神经后仍能调节局部运动与分泌，故该叙述正确。多数交感节后纤维释放去甲肾上腺素而非ACh；外来神经对内在神经有调节作用，并非无调节"},{"q":"细胞膜外表面的糖链","o":["可以作为离子通道","可以作为膜受体参与跨膜信号转导","可以作为离子泵","可以作为细胞特异性识别标志","能分解ATP"],"a":3,"e":"细胞膜外表面的糖链构成糖被，参与细胞识别、黏附与免疫应答，是细胞特异性的识别标志。离子通道、离子泵及受体多为膜蛋白，糖链本身不能形成通道或泵，也不直接分解ATP"},{"q":"第二心音的产生主要由于","o":["房室瓣开放","房室瓣关闭","动脉瓣开放","动脉瓣关闭","乳头肌及腱索的振动"],"a":3,"e":"第二心音发生于心室舒张开始时，主要由主动脉瓣与肺动脉瓣（动脉瓣）突然关闭、血流冲击引起的振动产生。第一心音才是房室瓣关闭所致；动脉瓣开放与房室瓣开放不产生心音，乳头肌腱索振动非主因"},{"q":"静息心指数等于","o":["每搏输出量/心室舒张末期容积","心输出量/体表面积","每搏输出量/体表面积","心室舒张末期容积/体表面积","每分功/体表面积"],"a":1,"e":"静息心指数指安静空腹状态下单位体表面积的心输出量，即心输出量/体表面积，用于比较不同身材个体的心功能。每搏输出量/体表面积是每搏指数；每搏输出量/心室舒张末期容积为射血分数"},{"q":"心迷走神经活动加强，可引起","o":["心率减慢、传导加速、心肌收缩力减弱","心率加快、传导加速、心肌收缩力减弱","心率减慢、传导减慢、心肌收缩力减弱","心率减慢、传导加速、心肌收缩力加强","心率加快、传导加速、心肌收缩力加强"],"a":2,"e":"心迷走神经兴奋释放ACh作用于M受体，引起心率减慢（负性变时）、房室传导减慢（负性变传导）与心肌收缩力减弱（负性变力）。凡出现传导加速或收缩力加强、心率加快的选项均与迷走抑制效应不符"},{"q":"ACh与突触后膜受体结合产生效应后，清除的主要方式是","o":["被突触前膜重新摄取","被胆碱酯酶分解","随血流到达肾脏排出","随血流带到肝脏破坏","被单胺氧化酶分解"],"a":1,"e":"突触间隙中的乙酰胆碱主要被胆碱酯酶迅速水解为胆碱和乙酸而终止作用，胆碱可被前膜再摄取利用。ACh并非以原形被突触前膜直接摄取，也不依赖肝肾清除，单胺氧化酶降解的是单胺类递质"},{"q":"主动脉在维持舒张压中起重要作用，主要是因为主动脉","o":["血管口径大","管壁厚","对血液的摩擦阻力小","血流速度快","管壁具有可扩张性和弹性"],"a":4,"e":"主动脉管壁具可扩张性和弹性，心室收缩时贮血并缓冲压力，舒张时弹性回缩继续推动血液外流，从而维持舒张压。口径大、管壁厚、摩擦阻力小不是主因，血流速度快反而不利于舒张压维持"},{"q":"下列哪种情况可抑制促胃液素释放","o":["迷走神经兴奋","胃内pH值高于6","胃内pH值低于1、5","胃内肽浓度升高","扩张胃窦"],"a":2,"e":"胃内pH降至1.5以下时，H+直接抑制胃窦G细胞释放促胃液素，形成负反馈，故胃内pH低于1.5可抑制其释放。迷走神经兴奋、胃内肽浓度升高、扩张胃窦均刺激释放；pH高于6时抑制解除、释放增加"},{"q":"交感神经紧张时，尿量减少的主要原因是","o":["循环血量减少","血浆胶体渗透压升高","肾小球滤过膜通透性降低","肾小球毛细血管血压降低","肾小囊内压升高"],"a":3,"e":"交感神经紧张时肾动脉及入球小动脉收缩，肾血流量与肾小球毛细血管血压下降，有效滤过压降低，肾小球滤过率减小致尿量减少。循环血量、胶体渗透压、滤过膜通透性及囊内压在此并非主要机制"},{"q":"皮肤快痛发生时，表现出来的特点是","o":["定位不确准","持续时间较长","是一种刺痛","疼痛发生较慢","由C类纤维传导"],"a":2,"e":"皮肤快痛由Aδ类有髓纤维传导，潜伏期短、定位准确、呈尖锐刺痛，持续时间短。定位不准、持续时间长、发生慢且由C类纤维传导的是慢痛，故快痛的特点为刺痛"},{"q":"在1mmHg分压差下，每分钟通过呼吸膜扩散的某种气体的毫升数称为该气体的","o":["肺扩散能力","肺扩散容量","呼吸膜通透性","肺扩散指数","肺通气/血流比值"],"a":1,"e":"肺扩散容量指在1mmHg分压差下，每分钟经呼吸膜扩散的气体毫升数，用于衡量肺换气功能。肺扩散能力非规范术语，呼吸膜通透性仅为影响因素，肺扩散指数、通气/血流比值均非此定义"},{"q":"IPSP发生时，突触后膜电位的状态是","o":["超射","去极化","反极化","超极化","复极化"],"a":3,"e":"IPSP时抑制性递质使突触后膜对Cl-、K+通透性增高，Cl-内流、K+外流引起膜电位更负，即超极化。去极化、反极化、超射为兴奋性电位变化，复极化是动作电位上升后的回降过程，均非IPSP状态"},{"q":"下列关于肺循环的叙述，正确的是","o":["血流阻力大","肺循环压力高","血容量波动小","血流量仅受神经调节","低氧可使肺部血管收缩"],"a":4,"e":"肺循环特点是低压、低阻、高容量，血流量大且受重力与神经体液双重影响。与体循环不同，肺泡低氧引起肺小动脉收缩（缺氧性肺血管收缩），使血流转向通气良好区，故该叙述正确"},{"q":"动物见到食物就引起唾液分泌，这属于","o":["非条件反射","非自动控制","负反馈控制","正反馈控制","前馈控制"],"a":4,"e":"动物见到食物即分泌唾液属条件反射，是中枢根据预期信号提前发动的反应，属前馈控制，可预先准备消化。非条件反射是食物直接刺激引起；负反馈、正反馈依赖结果反馈，非自动控制无反馈环节，均不符"},{"q":"单根神经纤维受到刺激而兴奋，当它的兴奋性处于低常期时，相当于其动作电位的","o":["阈电位","去极相","超射时期","负后电位","正后电位"],"a":4,"e":"低常期相当于动作电位的正后电位（后超极化）时期，此时膜电位略低于静息电位，兴奋性低于正常。负后电位对应超常期；阈电位、去极相、超射时期均处于绝对不应期或兴奋性恢复初期，不属低常期"},{"q":"O2与CO2的扩散系数相比较","o":["前者大，因为O2可与血红蛋白结合","前者小，因为O2的溶解度低","前者大，因为O2分压梯度大","前者小，因为O2的相对分子质量小","基本相同"],"a":1,"e":"气体扩散系数与溶解度成正比、与分子量平方根成反比，CO2溶解度远大于O2，故O2扩散系数小于CO2，主要因O2溶解度低。与Hb结合、分压梯度及相对分子质量均非决定扩散系数的直接因素"},{"q":"合成血红蛋白的基本原料是","o":["蛋白质和铁","蛋白质和铜","蛋白质和锌","蛋白质和钙","蛋白质和磷"],"a":0,"e":"合成血红蛋白的基本原料是蛋白质（珠蛋白）和铁，铁以Fe2+形式参与血红素合成，缺铁致缺铁性贫血。铜、锌、钙、磷虽为机体所需元素，但并非血红蛋白合成的必需基本原料"},{"q":"关于精子的运行，下列哪一项描述是正确的","o":["精液呈酸性","精子的运行只依靠自身的运动","排卵期宫颈黏液稀薄有利于精子运行","接近卵子的精子可达2～5×108个","孕酮有利于精子运行"],"a":2,"e":"排卵期雌激素水平高，使宫颈黏液稀薄、拉丝度增加，利于精子穿透与运行，故该叙述正确。精液呈弱碱性而非酸性；精子运行还依赖子宫与输卵管运动；到达卵子附近者仅数百个而非2～5×10^8"},{"q":"生命活动的基本特征不包括下列哪一项","o":["新陈代谢","生殖","兴奋性","适应性","生长发育"],"a":4,"e":"生命活动的基本特征包括新陈代谢、兴奋性、适应性和生殖，是生物共有且缺一不可的属性。生长发育是多数生物的生命周期现象，但通常不列入基本特征，故为不包括项"},{"q":"滤过分数是指","o":["肾小球滤过率/肾血浆流量","肾血浆流量/肾血流量","肾血流量/肾血浆流量","肾小球滤过率/肾血流量","肾血流量/心输出量"],"a":0,"e":"滤过分数指肾小球滤过率与肾血浆流量之比，约为19%，表示流经肾脏的血浆有多少比例被滤过。肾血浆流量/肾血流量为血浆占比，滤过率/肾血流量及肾血流量/心输出量等均非滤过分数定义"},{"q":"霍尔丹(Haldane)效应是指","o":["O2与Hb的结合可促使CO2的结合","CO2与Hb的结合可促使氧的结合","O2与Hb的解离可促使CO2的释放","CO2与Hb的结合可促使氧的释放","O2与Hb的结合可促使CO2的释放"],"a":4,"e":"霍尔丹效应指血红蛋白与O2结合后促使CO2释放、与O2解离后促进CO2结合，即氧合血红蛋白酸性较强、携带CO2能力下降。正确项为O2与Hb结合促使CO2释放，其余选项把结合与释放关系颠倒"},{"q":"激烈运动时，骨骼肌能量代谢的主要途径是","o":["葡萄糖的有氧氧化","葡萄糖的无氧酵解","脂肪酸代谢","氨基酸代谢","蛋白质代谢"],"a":1,"e":"激烈运动时骨骼肌耗能急剧增加且供氧相对不足，主要依靠葡萄糖无氧酵解快速生成ATP并产生乳酸。有氧氧化需充足氧供、产能多但慢；脂肪酸、氨基酸、蛋白质代谢不是剧烈运动的主要供能途径"},{"q":"人的心率超过180次/分时心输出量减少的主要原因是","o":["心室充盈不足","心室射血无力","射血分数减少","心力储备不足","等容舒张期变短"],"a":0,"e":"心率超过180次/分时心动周期尤其舒张期显著缩短，心室来不及充盈，每搏输出量明显下降，尽管心率增快仍致心输出量减少。射血分数、心力储备、等容舒张期缩短均非主要原因，关键在于充盈不足"},{"q":"临床上用简便方法测定能量代谢时，必须取得哪项数据","o":["呼吸商","非蛋白呼吸商","食物的氧热价","身高和体重","单位时间内的耗O2量"],"a":4,"e":"临床简便测定能量代谢需测定单位时间耗O2量，结合氧热价即可计算产热量。呼吸商、非蛋白呼吸商用于判断底物；食物氧热价需已知；身高体重用于体表面积计算，均非必须取得的数据"},{"q":"柠檬酸钠的抗凝血机制是","o":["激活了纤维蛋白溶解系统","破坏血浆中凝血酶原激活物","增加了血浆中Na＋","去掉了血浆中的纤维蛋白原","与血浆中的Ca2＋结合形成可溶性络合物"],"a":4,"e":"柠檬酸钠抗凝机制是与血浆中Ca2+结合形成可溶性络合物，降低游离Ca2+浓度，阻断凝血过程多个环节而抗凝，常用于体外抗凝。它不激活纤溶、不破坏凝血酶原激活物、不去除纤维蛋白原"},{"q":"下列凝血因子中，需要维生素K参与其合成的是","o":["因子Ⅰ、因子Ⅲ、因子Ⅷ、因子Ⅻ","因子Ⅱ、因子Ⅶ、因子Ⅸ、因子Ⅹ","因子Ⅲ、因子Ⅴ、因子Ⅶ、因子Ⅺ","因子Ⅲ、因子Ⅷ、因子Ⅹ、因子Ⅺ","因子Ⅴ、因子Ⅷ、因子Ⅸ、因子Ⅺ"],"a":1,"e":"依赖维生素K合成的凝血因子为Ⅱ、Ⅶ、Ⅸ、Ⅹ，其谷氨酸残基需维生素K参与羧化才能与Ca2+结合发挥活性。因子Ⅰ、Ⅲ、Ⅴ、Ⅷ、Ⅺ、Ⅻ等不依赖维生素K，故含这些因子的组合均不正确"},{"q":"关于细胞膜流动性的叙述，错误的是","o":["细胞膜流动性的高低与温度有关","出胞过程有赖于细胞膜的流动性","膜脂质中胆固醇含量越高，膜流动性越低","膜蛋白含量越高，膜流动性越低","膜脂质中饱和脂肪酸越多，膜的流动性越高"],"a":4,"e":"膜流动性受温度、脂肪酸饱和度与胆固醇调节：温度升高流动性增大，饱和脂肪酸越多、胆固醇越多则流动性越低，出胞亦依赖膜的流动性。故饱和脂肪酸越多流动性越高之说与事实相反"},{"q":"下述关于神经末梢释放外周递质的叙述，错误的是","o":["全部交感神经节后纤维均释放NE","交感神经节前纤维释放ACh","副交感神经节前纤维释放ACh","全部副交感神经节后纤维均释放ACh","躯体运动神经纤维释放ACh"],"a":0,"e":"多数交感节后纤维释放去甲肾上腺素，但支配汗腺、骨骼肌血管的交感节后纤维释放ACh，故全部交感节后均释放NE错误。交感与副交感节前纤维及躯体运动纤维均释放ACh，副交感节后也释放ACh"},{"q":"当一伸肌被过度牵拉时张力会突然降低，其原因是","o":["疲劳","负反馈","回返性抑制","腱器官兴奋","肌梭敏感性降低"],"a":3,"e":"伸肌被过度牵拉时，腱器官（高尔基腱器官）兴奋，冲动经Ⅰb纤维传入，通过抑制性中间神经元使该肌运动神经元抑制、肌肉张力骤降，即反牵张反射，以防肌腱损伤。疲劳、负反馈非特异机制，回返性抑制为中枢内另一类抑制"},{"q":"胰岛素分泌调节中，最重要的因素是","o":["血中游离脂肪酸","血糖浓度","神经调节","胰岛素自身调节","肾上腺素"],"a":1,"e":"血糖浓度是调节胰岛素分泌最重要的因素，血糖升高直接刺激胰岛B细胞分泌胰岛素，降低则分泌减少。游离脂肪酸、神经调节、肾上腺素及胰岛素自身调节虽有作用，但重要性均不及血糖"},{"q":"下列关于甲状旁腺激素的描述，错误的是哪一项","o":["其分泌主要受血浆中Ca2+浓度的调节","直接刺激破骨细胞的溶骨","主要增加小肠黏膜对Ca2+的吸收","直接刺激肾脏远曲小管重吸收Ca2+","主要作用是升高血钙、降低血磷"],"a":2,"e":"甲状旁腺激素主要作用于骨与肾，直接刺激破骨细胞溶骨、促进远曲小管重吸收Ca2+，总体升血钙降血磷，其分泌受血浆Ca2+负反馈调节。它增加小肠Ca2+吸收是经激活维生素D间接实现，并非直接主要作用"},{"q":"呼吸是指","o":["呼气和吸气合称","气体进出肺的过程","机体与外界环境之间进行气体交换的过程","肺泡与血液之间进行气体交换过程","呼吸运动"],"a":2,"e":"呼吸是机体与外界环境之间的气体交换过程，包括外呼吸（肺通气与肺换气）、气体运输和内呼吸三个环节。仅呼气和吸气合称、气体进出肺或肺泡与血液交换都只是部分环节，呼吸运动是动力过程而非全部"},{"q":"自律性最高的细胞是","o":["窦房结细胞","心房肌细胞","房室交界细胞","浦肯野细胞","心室肌细胞"],"a":0,"e":"窦房结细胞4期自动去极速度最快，自律性最高，是心脏正常起搏点，控制全心脏节律。房室交界、浦肯野细胞也有自律性但较低，为潜在起搏点；心房肌、心室肌为工作细胞无自律性"},{"q":"排便反射的初级中枢位于","o":["脊髓腰骶段","脑桥","脊髓胸段","中脑","延髓"],"a":0,"e":"排便反射的初级中枢位于脊髓腰骶段，直肠充盈刺激感受器，冲动传至该中枢并上传至大脑皮层产生便意。脑桥、中脑、延髓及脊髓胸段均非排便反射初级中枢所在"},{"q":"内呼吸是指","o":["肺泡与肺毛细血管血液之间的气体交换","组织细胞与毛细血管血液之间的气体交换","细胞器之间的气体交换","线粒体膜内外的气体交换","细胞内的生物氧化过程"],"a":1,"e":"内呼吸指组织细胞与毛细血管血液之间的气体交换，包括O2进入细胞与CO2进入血液，并包含细胞内氧化代谢。肺泡与肺毛细血管的交换属外呼吸；细胞器间、线粒体膜内外及单纯生物氧化均非内呼吸定义"},{"q":"正常人安静时通气/血液比值为","o":["0、64","0、84","0、94","1、0","2、0"],"a":1,"e":"正常人安静时全肺通气/血流比值约为0.84，表明肺泡通气量与肺血流量相匹配，换气效率最佳。0.64、0.94偏离正常，1.0与2.0偏高提示通气相对过剩，均非正常安静值"},{"q":"震颤麻痹的产生主要是由于","o":["纹状体的多巴胺递质系统功能异常","黑质的多巴胺递质系统功能受损","红核的神经递质释放量异常","下丘脑的调节功能异常","边缘系统的调节功能异常"],"a":1,"e":"震颤麻痹（帕金森病）主要因中脑黑质多巴胺能神经元受损，纹状体多巴胺含量显著减少，导致对间接通路的抑制减弱，出现静止性震颤与运动迟缓。病变在黑质而非纹状体本身，红核、下丘脑、边缘系统非主要部位"},{"q":"下列哪项不属于小脑的功能","o":["调节内脏活动","维持身体平衡","维持姿势","协调随意运动","调节肌紧张"],"a":0,"e":"小脑的功能包括维持身体平衡（前庭小脑）、协调随意运动与调节肌紧张（脊髓小脑、皮质小脑），并参与运动学习。调节内脏活动主要由下丘脑与脑干自主神经中枢完成，不属小脑功能，故为不包括项"},{"q":"下列哪一类神经纤维属C类神经纤维","o":["初级肌梭传入纤维","皮肤温觉传入纤维","交感神经节前纤维","交感神经节后纤维","皮肤的触-压觉传入纤维"],"a":3,"e":"交感神经节后纤维多为无髓细纤维，属C类，传导慢。初级肌梭传入为Ⅰa、Ⅱ类，皮肤温觉传入及触-压觉传入多为Aδ或Aβ类有髓纤维，交感节前纤维为B类有髓纤维，均不属C类"},{"q":"在寒冷环境中，机体主要依靠下列哪种方式来增加产热量","o":["肝脏代谢加强","脑代谢增强","战栗产热","食物特殊动力效应","骨骼肌运动产热"],"a":2,"e":"战栗产热是寒冷中主要产热方式，骨骼肌发生不随意节律性收缩，短时间内产热量显著增加。A项肝脏代谢加强实为缓慢的非战栗产热；B项脑代谢在寒冷中基本恒定；D项食物特殊动力效应由进食引起，与寒冷无关；E项骨骼肌随意运动产热受意识控制，并非主要代偿途径"},{"q":"下面关于A型血的叙述，正确的是","o":["红细胞膜上有A凝集原","血浆中有抗A凝集素","红细胞膜上有抗A凝集素","血浆中有A凝集原","红细胞膜上有B凝集原"],"a":0,"e":"ABO血型依据红细胞膜上凝集原命名，A型者红细胞膜含A凝集原，血浆中则含抗B凝集素。B项血浆抗A凝集素实为B型血的特征；C项凝集素存在于血浆而非红细胞膜；D项凝集原位于红细胞膜而非血浆；E项B凝集原属于B型血，A型者不含"},{"q":"制备坐骨神经-腓肠肌标本后，如果将腓肠肌浸泡在加入筒箭毒的任氏液中，再刺激坐骨神经。请问腓肠肌的变化是","o":["收缩强度不变","强直收缩","没有反应","收缩加强","收缩减弱"],"a":2,"e":"筒箭毒能特异性阻断神经-肌接头后膜的N2型ACh受体，使终板电位无法产生，神经冲动不能传给肌细胞，故刺激坐骨神经后腓肠肌无反应。A项收缩强度不变、D项收缩加强均以接头传递完整为前提；B项强直收缩是高频刺激的正常表现；E项收缩减弱意味着部分传递仍存，均不符合完全阻断的效应"},{"q":"红细胞所需的能量主要来自","o":["葡萄糖的有氧氧化","糖异生","糖原分解","糖酵解","脂肪酸氧化"],"a":3,"e":"成熟红细胞无线粒体，不能进行有氧氧化，其能量几乎全部来自胞质中的无氧糖酵解。A项葡萄糖有氧氧化需线粒体参与，成熟红细胞无法完成；B项糖异生是合成葡萄糖的途径而非供能方式；C项糖原分解并非红细胞主要能量来源；E项脂肪酸氧化同样依赖线粒体，均与红细胞的供能特点不符"},{"q":"使内环境理化性质保持相对恒定的调节方式属于","o":["神经调节","体液调节","自身调节","免疫调节","负反馈调节"],"a":4,"e":"负反馈调节是维持内环境稳态的基本机制，通过反馈信息抑制或减弱原发活动，使各项理化指标在设定点附近保持相对稳定。A项神经调节、B项体液调节、C项自身调节是实现调节的途径，本身不等于维持恒定的反馈机制；D项免疫调节主要承担防御功能，均非维持理化性质相对恒定的核心机制"},{"q":"红细胞在血管外破坏的主要场所是","o":["肾、肝","脾、骨髓","肾、脾","胸腺、骨髓","胸腺、肝"],"a":1,"e":"衰老红细胞的血管外破坏主要在脾和骨髓，由其中巨噬细胞吞噬降解，血红蛋白分解后铁被再利用。A项肾主要与血管内溶血及红细胞生成素分泌有关，并非血管外破坏的主要场所；C项肾、脾组合不当；D项胸腺是T细胞成熟场所；E项胸腺、肝均非红细胞破坏的主要部位"},{"q":"下列情况中，能够使肺通气/血流比值减少最明显的是","o":["人体处于直立位时的肺尖","肺水肿","支气管哮喘发作","肺栓塞","肺癌"],"a":2,"e":"通气/血流比值减小表示肺泡通气相对不足、血流相对过多，形成功能性分流。支气管哮喘发作时气道广泛痉挛狭窄，通气量明显下降而血流相对保留，故比值减少最明显。A项直立位肺尖因血流减少更显著，比值反而增大；D项肺栓塞使局部血流中断，比值增大形成死腔；B项肺水肿虽也可致分流，但哮喘对通气的削弱更突出"},{"q":"肾小管中不能主动重吸收Na+的部位是","o":["近曲小管","髓袢细段","髓袢升支粗段","远曲小管","集合管"],"a":1,"e":"髓袢细段（尤其降支细段）对Na+通透性低且缺乏主动重吸收机制，其主要功能与水的通透及髓质渗透梯度形成有关。A项近曲小管重吸收约65%的Na+；C项髓袢升支粗段通过Na+-K+-2Cl-同向转运体主动重吸收Na+；D项远曲小管与E项集合管均在醛固酮调节下主动重吸收Na+，故均不符合"},{"q":"逆行性遗忘症的机制可能是","o":["第一级记忆发生扰乱","第二级记忆发生扰乱","第三级记忆发生扰乱","第一级记忆至第二级记忆过程发生扰乱","海马环路的损害"],"a":1,"e":"逆行性遗忘表现为不能回忆脑损伤前已获得的经历，其机制在于已储存的第二级记忆受到扰乱。A项第一级记忆为瞬时感觉登记，扰乱后仅影响即刻信息；D项第一级向第二级转化障碍及E项海马环路损害主要导致顺行性遗忘，即新信息无法巩固；C项第三级记忆为永久保存部分，通常不受此类遗忘影响"},{"q":"集合管上皮细胞向管腔内分泌NH3的过程是属于","o":["易化扩散","单纯扩散","出胞","原发性主动转运","继发性主动转运"],"a":1,"e":"集合管上皮细胞产生的NH3为脂溶性小分子，可顺浓度梯度以单纯扩散方式进入管腔，与管腔内H+结合成NH4+随尿排出，是排酸保碱的重要环节。A项易化扩散需载体或通道介导，NH3不需；C项出胞用于大分子颗粒释放；D项原发性主动转运与E项继发性主动转运均需耗能并逆浓度差，不符合NH3被动扩散的特点"},{"q":"脊髓前角α-运动神经元被称为躯体骨骼肌运动反射的","o":["效应器","运动单位","最后公路","感受器","传出途径"],"a":2,"e":"脊髓前角α运动神经元接受来自各级中枢和外周传入的会聚信息，其轴突支配骨骼肌梭外肌纤维，是所有躯体运动反射传出信息的最后汇集通路，故称最后公路。A项效应器指肌肉或腺体本身；B项运动单位由一个α运动神经元及其支配的肌纤维构成；D项感受器与E项传出途径均不指该神经元本身"},{"q":"机体内各种感觉传入纤维在第二级神经元换元后，唯一不投射到丘脑的感觉是","o":["嗅觉","听觉","视觉","本体感觉","痛觉"],"a":0,"e":"嗅觉是唯一在二级神经元换元后不投射丘脑的感觉，其传入经嗅神经、嗅球直接投射至嗅皮质及边缘系统。B项听觉、C项视觉、D项本体感觉与E项痛觉均需在丘脑换元后再投射到相应大脑皮质区域，丘脑是这些感觉传导的共同换元站，故只有嗅觉例外"},{"q":"上消化道出血诱发肝性脑病的主要机制是","o":["失血性休克","肠道细菌作用下产氨增加","脑组织缺血缺氧","水、电解质紊乱","血脑屏障破坏"],"a":1,"e":"上消化道出血时大量血液进入肠道，血红蛋白等蛋白质在肠道细菌作用下分解产生大量氨，肝功能受损时无法有效清除，血氨升高进入脑组织诱发肝性脑病。A项失血性休克、C项脑缺血缺氧可加重脑损伤但非主要诱因；D项水电解质紊乱为继发因素；E项血脑屏障破坏并非出血诱发脑病的核心机制"},{"q":"人体功能调节方式中处于主导地位的是","o":["神经调节","体液调节","自身调节","全身调节","免疫调节"],"a":0,"e":"神经调节在人体功能调节中处于主导地位，依靠反射弧快速、精确地整合各方信息，协调各系统活动以适应内外环境变化。B项体液调节作用缓慢广泛，多受神经调节控制；C项自身调节范围局限、幅度小；D项全身调节并非独立的基本调节方式；E项免疫调节主要承担防御与监视，均不居主导地位"},{"q":"血浆中葡萄糖进入红细胞内的过程是属于","o":["单纯扩散","载体介导的易化扩散","通道介导的易化扩散","继发性主动转运","入胞"],"a":1,"e":"葡萄糖进入红细胞依赖膜上GLUT1载体蛋白，顺浓度梯度转运且不消耗ATP，属于载体介导的易化扩散。A项单纯扩散适用于脂溶性小分子，葡萄糖为水溶性不能自由透过；C项通道介导的易化扩散转运离子而非葡萄糖；D项继发性主动转运需借助离子梯度耗能，如小肠吸收葡萄糖；E项入胞用于大分子颗粒，均不符合"},{"q":"关于影响肺换气的因素，叙述错误的是","o":["气体扩散速率与呼吸膜厚度成反比","扩散速率与呼吸膜面积成正比","通气/血流比值增大有利于换气","通气/血流比值减小不利于换气","扩散速率与气体分压差成正比"],"a":2,"e":"通气/血流比值增大意味着肺泡通气相对过剩而血流不足，部分气体无法与血液交换，形成功能性死腔，反而不利于换气，故该项叙述错误。A项气体扩散速率与呼吸膜厚度成反比、B项与面积成正比、E项与分压差成正比均符合斐克定律；D项比值减小形成功能性分流，同样不利于换气，表述正确"},{"q":"关于哺乳类动物的心脏，下列描述不正确的是","o":["细胞外K+浓度增加，引起细胞膜去极化","细胞外K+浓度增加，引起细胞膜钾电导增加","低血钾时，心室肌动作电位时程缩短","细胞外K+浓度增加时，心室肌动作电位幅度增加","细胞外高钙可对抗高血钾"],"a":2,"e":"细胞外K+浓度降低时，心肌细胞膜钾电导下降，复极过程延缓，动作电位时程应当延长而非缩短，故该叙述不正确。A项细胞外K+升高使静息电位上移即去极化，B项同时使钾电导增加，均为高钾的效应；E项高钙可稳定细胞膜、对抗高钾对心肌的抑制，属正确描述"},{"q":"交感缩血管神经节后纤维末梢释放的递质是","o":["5-羟色胺","血管紧张素Ⅱ","乙酰胆碱","肾上腺素","去甲肾上腺素"],"a":4,"e":"交感缩血管神经的节后纤维末梢释放去甲肾上腺素，作用于血管平滑肌的α受体引起收缩，是维持血管张力和调节血压的主要途径。A项5-羟色胺主要由血小板及中枢某些神经元释放；C项乙酰胆碱为支配汗腺及骨骼肌血管舒张的交感节后纤维递质；D项肾上腺素主要来自肾上腺髓质；B项血管紧张素Ⅱ为体液因子而非该神经递质"},{"q":"可以反映肺通气过程中的阻力的指标是","o":["潮气量","功能残气量","肺活量","补吸气量","时间肺活量"],"a":4,"e":"时间肺活量（用力呼气量）测定用力呼气时各时相呼出的气量，因呼气用力且受气道口径影响，能敏感反映呼吸道阻力变化，气道阻塞时明显降低。A项潮气量、B项功能残气量、C项肺活量、D项补吸气量均为静态肺容量指标，不受呼气时间限制，不能反映通气过程中的动态阻力，故均不符合"},{"q":"全血的密度主要取决于","o":["红细胞的数量","渗透压的高低","白细胞的数量","血浆蛋白的数量","血小板的数量"],"a":0,"e":"全血密度主要由其中的有形成分决定，红细胞数量最多且密度较大，故红细胞数量是全血密度的主要决定因素。B项渗透压取决于溶质颗粒浓度，与密度无直接对应；C项白细胞和E项血小板数量极少，对全血密度影响微小；D项血浆蛋白主要影响血浆胶体渗透压和黏滞性，对全血密度的作用远不及红细胞"},{"q":"心室肌细胞绝对不应期的产生是由于","o":["Na+通道处于激活状态","Na+通道处于备用状态","Ca2+通道处于激活状态","Ca2+通道处于失活状态","Na+通道处于失活状态"],"a":4,"e":"心室肌细胞兴奋后，快Na+通道在进入激活状态后迅速转为失活状态，在膜电位恢复到一定水平前不能重新被激活，此期无论多大刺激都无法产生新的动作电位，构成绝对不应期。A项激活状态为通道开放瞬间，并非不应期成因；B项备用状态为兴奋前通道可激活的状态；C、D项Ca2+通道主要参与平台期，与快反应细胞绝对不应期的产生无关"},{"q":"与骨骼肌收缩相比，平滑肌收缩","o":["横桥激活的机制不同","都具有自律性","不需要胞质内Ca2+浓度升高","没有粗肌丝的滑行","横桥周期更短"],"a":0,"e":"平滑肌与骨骼肌虽都以粗、细肌丝滑行和横桥周期产生张力，但横桥激活机制不同：平滑肌经Ca2+与钙调蛋白结合激活肌球蛋白轻链激酶，使肌球蛋白轻链磷酸化后才启动横桥，骨骼肌则是Ca2+与肌钙蛋白结合直接暴露结合位点。C项两者收缩均需胞质Ca2+升高；D项平滑肌同样存在肌丝滑行；E项平滑肌横桥周期更长而非更短；B项并非所有平滑肌都有自律性"},{"q":"正常条件下，终尿量约占肾小球滤过量的","o":["30%","20%","10%","5%","1%"],"a":4,"e":"正常成人肾小球滤过量约180L/d，而终尿量仅约1.5L/d，终尿量约占滤过量的1%，表明原尿中约99%的水和溶质被肾小管重吸收。A项30%、B项20%、C项10%、D项5%均远高于实际比例，若滤过液中如此大比例排出，将造成严重脱水与电解质紊乱，与正常肾脏强大的重吸收功能不符"},{"q":"关于铁的吸收，下列叙述正确的是","o":["食物中铁80%以上被吸收","吸收主要在回肠","高铁比亚铁易吸收","胃酸缺乏不利于吸收","铁离子与铁蛋白结合后由肠腔进人肠上皮细胞"],"a":3,"e":"铁主要在十二指肠和空肠上段以亚铁形式吸收，胃酸可将食物中的高铁还原为亚铁并促进其溶解，故胃酸缺乏不利于铁吸收。A项食物中铁仅约10%被吸收，远低于80%；B项吸收主要部位不是回肠；C项亚铁比高铁易吸收；E项铁与铁蛋白结合是细胞内储存形式，而非由肠腔进入肠上皮细胞的转运方式"},{"q":"催化肾小管分泌H+的酶是","o":["羟化酶","脱羧酶","过氧化物酶","磷酸化酶","碳酸酐酶"],"a":4,"e":"肾小管上皮细胞分泌H+依赖碳酸酐酶，该酶催化CO2与H2O结合生成H2CO3，随即解离出H+供分泌、HCO3-被重吸收，是排酸保碱的关键。A项羟化酶参与维生素D活化等反应；B项脱羧酶催化脱羧；C项过氧化物酶参与甲状腺激素合成及过氧化氢分解；D项磷酸化酶催化磷酸解，均不参与H+分泌的生成过程"},{"q":"儿童佝偻病主要是缺乏下列哪种物质","o":["铁","锌","镁","钙","铜"],"a":3,"e":"佝偻病主要因维生素D缺乏导致钙、磷吸收障碍和骨矿化不良，在所给矿物质中钙缺乏最为关键，故补充钙与维生素D是防治核心。A项铁缺乏致缺铁性贫血；B项锌缺乏影响生长发育与味觉；C项镁缺乏多表现为神经肌肉兴奋性改变；E项铜缺乏影响造血与结缔组织，均非佝偻病的主要病因"},{"q":"下列关于心室肌细胞快钠通道特征的描述，哪一项是不正确的","o":["激活快","复活快","对钠离子具有高度选择性","电压依从性","可被Mn2+阻断"],"a":4,"e":"心室肌快Na+通道具有激活快、复活快、电压依从性及对Na+高度选择性等特征，可被河鲀毒素阻断；Mn2+阻断的是Ca2+通道而非快钠通道，故该项描述不正确。A项激活快、B项复活快、C项离子选择性高、D项电压依从性均为快钠通道的固有属性，表述正确"},{"q":"脑内多巴胺能神经元主要位于","o":["脑桥蓝斑","中脑黑质","低位脑干","纹状体","低位脑干中缝核"],"a":1,"e":"脑内多巴胺能神经元胞体主要集中于中脑黑质，其轴突投射至纹状体构成黑质-纹状体通路，参与运动调节，该通路变性导致帕金森病。A项脑桥蓝斑为去甲肾上腺素能神经元主要聚集地；C项低位脑干、E项中缝核主要为5-羟色胺能神经元所在；D项纹状体是多巴胺能纤维的投射靶区而非胞体所在"},{"q":"血液中H+浓度升高加强呼吸运动的主要作用途径是","o":["刺激外周化学感受器","刺激中枢化学感受器","直接刺激延髓呼吸中枢","刺激脑桥呼吸调整中枢","直接刺激脊髓呼吸中枢"],"a":0,"e":"血液中H+浓度升高时，因H+难以透过血脑屏障，主要刺激颈动脉体和主动脉体的外周化学感受器，反射性兴奋呼吸中枢使呼吸加强。B项中枢化学感受器对H+敏感但受血脑屏障阻隔，主要感受CO2升高引起的脑脊液H+变化；C、D、E项所述直接刺激呼吸中枢或脑桥、脊髓中枢均非H+发挥作用的主要途径"},{"q":"肺总容量等于","o":["潮气量+肺活量","潮气量+功能残气量","功能残气量+肺活量","残气量+补吸气量","残气量+肺活量"],"a":4,"e":"肺总容量为最大吸气后肺内所含的全部气体量，等于肺活量与残气量之和，反映肺的最大扩张容积。A项潮气量+肺活量重复计算了潮气量；B项潮气量+功能残气量实为错误组合；C项功能残气量已含补呼气量，与肺活量相加会重复；D项残气量+补吸气量仅为部分容积，均不等于肺总容量"},{"q":"二氧化碳分压由高到低的顺序一般是","o":["呼出气，肺泡气，组织细胞，静脉血","静脉血，呼出气，肺泡气，组织细胞","肺泡气，静脉血，组织细胞，呼出气","组织细胞，静脉血，肺泡气，呼出气","呼出气，组织细胞，静脉血，肺泡气"],"a":3,"e":"CO2由组织细胞代谢产生，故其分压以细胞内最高，依次经静脉血、肺泡气向外扩散，呼出气中分压最低。静脉血CO2分压高于肺泡气才得以在肺泡处释放CO2；A、B、C、E各项将呼出气或肺泡气置于高位，违背CO2由组织向肺泡再向外界扩散的分压梯度，故均错误"},{"q":"以下关于心室肌相对不应期的描述，不正确的是","o":["膜内电位为-60mV～80mV","Na+通道部分复活","刺激阈值高于正常","本期内产生的动作电位时程较长","兴奋传导速度较慢"],"a":3,"e":"相对不应期中部分Na+通道已复活，给予阈上刺激可产生动作电位，但因参与兴奋的Na+通道数量有限且复极因素仍存，产生的动作电位时程较短、幅度较低、传导较慢，故时程较长的描述不正确。A项膜内电位约-60～-80mV、B项Na+通道部分复活、C项刺激阈值高于正常、E项传导速度较慢均符合相对不应期特点"},{"q":"正常人耳声音频率的最敏感范围是","o":["1000～10000Hz","5000～10000Hz","1000～3000Hz","100～20000Hz","20～20000Hz"],"a":2,"e":"人耳可听范围为20～20000Hz，而听觉最敏感的频率范围是1000～3000Hz，恰与人类言语频率一致，听阈在此区间最低。D项100～20000Hz与E项20～20000Hz描述的是可听范围而非最敏感范围；A项1000～10000Hz、B项5000～10000Hz覆盖高频区，敏感度已下降，均非最敏感区间"},{"q":"近端小管的重吸收率始终占肾小球滤过率的比例为","o":["50%","55%","60%","65%","80%"],"a":3,"e":"近端小管是重吸收的主要部位，无论肾小球滤过率如何变化，其重吸收量始终约占滤过量的65%，此即球-管平衡，可防止尿量因滤过波动而大幅改变。A项50%、B项55%、C项60%均低于实际比例；E项80%接近包括髓袢在内的整个肾小管重吸收总量，而非近端小管单独所占份额"},{"q":"骨骼肌收缩过程中胞内钙离子的主要来源是","o":["细胞外钙离子内流","肌钙蛋白与大量钙离子解离","与钙调蛋白结合的钙离子解离释放","肌质网内钙离子释放","肌质网膜上钙泵的转运"],"a":3,"e":"骨骼肌兴奋-收缩耦联时，动作电位经横管传入激活终池膜上的钙释放通道，使肌质网内储存的Ca2+大量释放入胞质，这是收缩所需Ca2+的主要来源。A项细胞外Ca2+内流在骨骼肌并非主要途径；B项肌钙蛋白是与Ca2+结合而非释放Ca2+；C项钙调蛋白主要参与平滑肌收缩；E项钙泵的作用是把Ca2+泵回肌质网以引起舒张"},{"q":"下列可促进胰液分泌的因素是","o":["迷走神经兴奋","降钙素基因相关肽","生长抑素","支配胰的内脏大神经","胆盐"],"a":0,"e":"迷走神经兴奋时末梢释放乙酰胆碱，作用于胰腺腺泡细胞促进胰酶分泌，是促进胰液分泌的重要因素。B项降钙素基因相关肽与C项生长抑素均抑制胰液分泌；D项支配胰的内脏大神经属交感神经，兴奋时抑制分泌并使血管收缩；E项胆盐主要促进胆汁分泌与脂肪消化，不直接促进胰液分泌"},{"q":"神经中枢内兴奋传递的活动中，发生后发放现象的神经元联系方式主要是","o":["辐散式联系","聚合式联系","环式联系","单线式联系","链锁式联系"],"a":2,"e":"环式联系中神经元通过中间神经元形成闭合回路，兴奋可在回路中反复环路传播，即使原刺激停止仍持续发放，构成后发放现象的结构基础。A项辐散式联系使一个神经元兴奋扩布给多个神经元；B项聚合式联系实现信息会聚；D项单线式联系为点对点传递；E项链锁式联系主要扩大空间作用范围，均不产生后发放"},{"q":"右心衰竭时组织液生成增加导致水肿，主要原因是","o":["毛细血管血压增高","血浆胶体渗透压降低","组织液静水压降低","组织液胶体渗透压增高","血浆晶体渗透压降低"],"a":0,"e":"右心衰竭时心室射血功能下降，静脉回流受阻导致体循环静脉淤血，毛细血管血压升高，有效滤过压增大使组织液生成增多而形成水肿。B项血浆胶体渗透压降低主要见于低蛋白血症或肾病；C项组织液静水压降低虽促进生成但非心衰主因；D项组织液胶体渗透压增高见于毛细血管通透性增加；E项晶体渗透压主要影响细胞内外水平衡"},{"q":"判断组织兴奋性高低最常用的指标是","o":["刺激频率","刺激强度","动作电位","阈电位","阈强度"],"a":4,"e":"兴奋性高低通常以阈强度衡量，阈强度是引起组织产生动作电位的最小刺激强度，与兴奋性呈反比，故是最常用的指标。A项刺激频率影响收缩形式而非兴奋性；B项刺激强度需达到阈值才生效，本身不是衡量尺度；C项动作电位为兴奋的表现而非指标；D项阈电位为膜电位临界值，虽相关但不作为常用衡量指标"},{"q":"神经细胞兴奋时，首先产生扩布性动作电位的部位是","o":["胞体","树突","轴突始段","轴突","轴突末梢"],"a":2,"e":"轴突始段（轴丘）膜上电压门控Na+通道密度最高、阈电位最低，是神经元兴奋时首先爆发动作电位并向外扩布的部位，又称触发区。A项胞体与B项树突主要接受和整合突触输入，其膜兴奋性较低；D项轴突为传导部位而非起始部位；E项轴突末梢负责递质释放，均非首先产生扩布性动作电位之处"},{"q":"关于神经纤维静息电位的形成机制，下述哪项是错误的","o":["细胞外的K+浓度小于细胞内的K+浓度","细胞膜对Na+有点通透性","细胞膜主要对K+有通透性","加大细胞外的K+浓度，会使静息电位绝对值加大","细胞内Na+浓度低于细胞外Na+浓度"],"a":3,"e":"静息电位主要由K+外流形成，接近K+平衡电位；加大细胞外K+浓度会减小膜内外K+浓度差，使K+外流减少，静息电位绝对值减小而非加大，故该叙述错误。A项细胞外K+低于细胞内、B项膜对Na+有少量通透、C项膜主要对K+通透、E项细胞内Na+低于细胞外均为静息电位形成的相关正确事实"},{"q":"下列哪个部位不存在中枢温度感受器","o":["PO/AH","小脑","中脑","下丘脑","下丘脑后部"],"a":1,"e":"中枢温度感受器分布于下丘脑尤其是视前区-下丘脑前部（PO/AH），也见于中脑、下丘脑后部及脑干网状结构，而小脑不存在中枢温度感受器。A项PO/AH是热敏与冷敏神经元最集中的部位；C项中脑、E项下丘脑后部均含温度敏感神经元；D项下丘脑为体温调节中枢所在，均不符合题意"},{"q":"启动外源性凝血途径的物质是","o":["因子Ⅲ","因子Ⅻ","PF3","Ca2＋","凝血酶原"],"a":0,"e":"外源性凝血途径由血管外组织释放的因子Ⅲ（组织因子）启动，因子Ⅲ与因子Ⅶa、Ca2+形成复合物进而激活因子Ⅹ。B项因子Ⅻ是内源性凝血途径的启动因子；C项PF3（血小板因子3）为血小板膜磷脂，参与凝血复合物形成但非启动物质；D项Ca2+为凝血过程中的必需离子；E项凝血酶原是凝血酶的前体，均非启动者"},{"q":"关于神经纤维的静息电位，下述哪项是错误的","o":["它是膜外为正、膜内为负的电位","接近于钾离子的平衡电位","在不同的细胞，其大小可以不同","它是个稳定的电位","相当于钠离子的平衡电位"],"a":4,"e":"静息电位是膜外为正、膜内为负的电位，主要由K+外流形成，其数值接近K+平衡电位而非Na+平衡电位，故该叙述错误。A项膜外正膜内负、B项接近K+平衡电位、C项不同细胞大小可不同、D项为相对稳定的电位均属静息电位的正确特征，Na+平衡电位对应的是动作电位峰值附近的水平"},{"q":"在突触前易化的形成过程中，其主要结构或机制是","o":["与突触前抑制的结构基础完全不同，没有轴-轴式突触","中间神经元释放5-HT，使突触前膜产生高频率动作电位","有更多的Ca2+进入突触前轴突末梢","突触前膜释放神经递质减少","突触后膜产生的EPSP数量增多"],"a":2,"e":"突触前易化的结构与突触前抑制类似，均以轴-轴式突触为基础，其机制是使动作电位期间有更多Ca2+进入突触前轴突末梢，递质释放增多而产生易化。A项两者结构基础相同，均存在轴-轴突触；B项5-HT并非该过程的通用机制；D项递质释放减少是突触前抑制的表现；E项EPSP增多是易化的结果而非突触前机制"},{"q":"Hb实际结合的氧量主要决定于动脉血的","o":["pH值","PCO2","2,3-DPG的浓度","PO2","Hb浓度"],"a":3,"e":"Hb实际结合的氧量即血氧饱和度，主要取决于动脉血PO2，二者关系呈氧解离曲线的S形，PO2升高时Hb与O2结合显著增加。A项pH、B项PCO2、C项2,3-DPG通过改变Hb对O2的亲和力使曲线位移，属影响因素但非主要决定因素；E项Hb浓度决定血氧容量即最大携氧能力，不决定实际结合比例"},{"q":"神经垂体释放的激素有","o":["催乳素与生长激素","缩宫素与催乳素","抗利尿激素与缩宫素","抗利尿激素与促黑激素","催乳素与血管升压素"],"a":2,"e":"神经垂体本身不合成激素，仅储存并释放下丘脑视上核与室旁核合成的抗利尿激素（血管升压素）和缩宫素。A项催乳素与生长激素、B项缩宫素与催乳素中的催乳素、E项中的催乳素均由腺垂体分泌；D项促黑激素亦属腺垂体，均非神经垂体释放的激素"},{"q":"低氧对呼吸的兴奋作用是通过","o":["直接兴奋延髓吸气神经元","直接兴奋呼吸中枢","直接兴奋脑桥呼吸调整中枢","刺激中枢化学感受器而兴奋呼吸中枢","刺激外周化学感受器而实现的反射性效应"],"a":4,"e":"低氧对呼吸的兴奋作用完全通过刺激颈动脉体和主动脉体的外周化学感受器实现，是反射性效应；低氧对呼吸中枢本身为抑制作用，故整体表现为兴奋。A、B、C项所述直接兴奋延髓、呼吸中枢或脑桥中枢均不符合，D项中枢化学感受器主要感受CO2及脑脊液H+变化且低氧对其无兴奋作用，均错误"},{"q":"自主神经节后纤维释放的主要递质是","o":["ACh和NE","NE","5-HT","ACh","NE和5-HT"],"a":0,"e":"自主神经节后纤维的主要递质为乙酰胆碱和去甲肾上腺素：副交感节后纤维及支配汗腺等的交感节后纤维释放ACh，多数交感节后纤维释放NE。B项仅NE、D项仅ACh均不全面；C项5-HT主要见于中枢及胃肠道；E项NE和5-HT的组合遗漏了分布广泛的ACh，故均不准确"},{"q":"健康成年人在强体力劳动时，心输出量约可达到","o":["5～6L/min","30L/min","60L/min","120L/min","150L/min"],"a":1,"e":"健康成人安静时心输出量约5～6L/min，强体力劳动时因心率加快和每搏输出量增加，心输出量可增至约30L/min，约为安静时的5倍。A项5～6L/min为安静状态水平；C项60L/min、D项120L/min、E项150L/min远超正常心脏的泵血极限，均不符合生理实际"},{"q":"下丘脑在内脏调节中的作用不包括","o":["摄食","水平衡","生物节律","内分泌","排便反射"],"a":4,"e":"下丘脑是调节内脏活动的高级中枢，参与摄食、水平衡、生物节律及内分泌等功能的整合，但排便反射的基本中枢位于脊髓骶段，不属于下丘脑调节范畴。A项摄食、B项水平衡、C项生物节律、D项内分泌均为下丘脑的重要功能，故排除"},{"q":"在一定血压范围内，肾血流量能保持相对稳定主要靠","o":["神经调节","体液调节","免疫调节","自身调节","多种调节"],"a":3,"e":"在动脉血压一定范围内（约80～180mmHg），肾血流量通过入球小动脉平滑肌的肌源性自身调节保持相对稳定，压力升高时血管收缩、压力降低时舒张，以维持滤过恒定。A项神经调节主要在应激等情况下起作用；B项体液调节、C项免疫调节并非此血压范围内稳定的主要机制；E项多种调节笼统，均不准确"},{"q":"肝素抗凝血的主要机制是","o":["抑制凝血酶原的激活","增强抗凝血酶Ⅲ与凝血酶的亲和力","促进纤维蛋白吸附凝血酶","抑制因子X的激活","去除血浆中游离的Ca2＋"],"a":1,"e":"肝素主要通过与抗凝血酶Ⅲ结合，使其构象改变并显著增强其与凝血酶及因子Ⅹa等的亲和力，加速对这些凝血因子的灭活而发挥抗凝作用。A项抑制凝血酶原激活、D项抑制因子Ⅹ激活均非其主要机制；C项促进纤维蛋白吸附凝血酶不符合；E项去除Ca2+为草酸盐等抗凝剂的机制"},{"q":"下列关于激素作用的特征的描述，哪一项正确","o":["很多激素都可以影响全身，所以没有特异性","激素浓度很低，但有高效放大作用","激素的生理功能是相互独立的","胰岛素和糖皮质激素是相互拮抗的激素","胰岛素和糖皮质激素是相互协同的激素"],"a":1,"e":"激素在血中浓度极低，但通过靶细胞的受体结合及级联放大效应产生显著生理作用，体现微量高效的特点。A项激素作用具有特异性，只作用于靶细胞，所谓没有特异性错误；C项各激素功能相互联系而非独立；E项胰岛素与糖皮质激素在糖代谢上实为拮抗，协同的说法错误"},{"q":"主要在回肠吸收的物质是","o":["果糖","甘油","氨基酸","维生素B12","内因子"],"a":3,"e":"维生素B12是主要在回肠末端吸收的物质，其吸收依赖胃壁细胞分泌的内因子与之结合形成复合物，再经回肠特异性受体介导摄入。A项果糖、B项甘油、C项氨基酸主要在小肠上段吸收；E项内因子是胃分泌的糖蛋白，本身不被吸收而是辅助B12吸收，均不符合"},{"q":"关于球旁细胞的描述错误的是","o":["系入球小动脉管壁的特殊分化细胞","能感受血浆Na+浓度的变化","能释放肾素","受交感神经的支配","在醛固酮的分泌调节中起重要作用"],"a":1,"e":"球旁细胞是入球小动脉管壁特殊分化的肌上皮样细胞，主要感受入球小动脉壁的牵张即肾灌注压变化，并释放肾素，受交感神经支配，在醛固酮分泌调节中起重要作用。感受小管液Na+浓度变化的是致密斑而非球旁细胞，且对象为小管液而非血浆，故该项描述错误"},{"q":"关于单突触反射的特点，正确的是","o":["神经中枢内很多见","参与的中枢范围很广","需要多个突触活动","反射效应产生较慢","反射时短"],"a":4,"e":"单突触反射的传入神经元与传出神经元仅在中枢内形成一次突触联系，如膝反射，故突触延搁最少、反射时最短。A项单突触反射在中枢内并不多见；B项其中枢范围局限而非广泛；C项仅经过一个突触，无需多个突触活动；D项其反射效应产生迅速而非较慢，均不符合"},{"q":"人体感受外界环境温度降低刺激的主要感受器是","o":["中枢冷敏神经元","皮肤热感受器","皮肤冷感受器","中枢热敏神经元","外周温度感受器"],"a":2,"e":"外界环境温度降低时，皮肤中的冷感受器兴奋性升高，将冷信息传入下丘脑体温调节中枢，启动产热与保温反应，是感受环境降温的主要感受器。A项中中枢冷敏神经元感受的是核心温度变化；B项皮肤热感受器在温度升高时兴奋；D项中枢热敏神经元感受核心温度升高；E项外周温度感受器为泛称，其中冷感受器特异地感受降温刺激"},{"q":"下列物质都能引起尿量增多，其中通过渗透性利尿机制实现的是","o":["心房钠尿肽","生理盐水","呋塞米","甘露醇","缓激肽"],"a":3,"e":"甘露醇可被肾小球滤过但几乎不被肾小管重吸收，使小管液渗透压升高，阻碍水的重吸收而产生渗透性利尿。A项心房钠尿肽通过抑制Na+重吸收及扩张血管利钠利尿；B项生理盐水主要扩充血容量、抑制ADH；C项呋塞米抑制髓袢升支粗段Na+-K+-2Cl-转运，属利尿剂但非渗透性机制；E项缓激肽通过扩血管等作用，均不同"},{"q":"ABO血型系统的天然抗体是","o":["IgA","IgD","IgM","IgE","IgG"],"a":2,"e":"ABO血型系统的天然抗体属于IgM，多为完全抗体，不能通过胎盘，出生后若因输血等免疫刺激产生的抗体则为IgG。A项IgA主要存在于黏膜分泌液；B项IgD主要为B细胞表面受体；D项IgE与过敏反应及寄生虫免疫相关；E项IgG为免疫性抗体，可通过胎盘，均非ABO系统的天然抗体类型"},{"q":"人体功能活动的神经调节特点是","o":["反应速度慢","作用广泛而持久","调节敏感性差","迅速、准确和短暂","调节有局限性"],"a":3,"e":"神经调节通过反射弧实现，其特点是反应迅速、定位准确、作用时间短暂且影响范围局限，适于快速应答。A项反应速度慢、B项作用广泛而持久是体液调节的特点；C项调节敏感性差不符合，神经调节精确；E项调节有局限虽部分正确，但最典型的概括应为迅速、准确、短暂，故A、B、C更不符合"},{"q":"促进某些生理过程逐步加强直至完成是依靠体内的","o":["非自动控制系统","负反馈控制系统","正反馈控制系统","前馈控制系统","神经和内分泌系统"],"a":2,"e":"正反馈控制的反馈信息使原发活动进一步加强，直至某一生理过程完成，如排尿、排便、分娩及血液凝固等。A项非自动控制系统无反馈；B项负反馈使活动减弱趋于稳定，维持稳态；D项前馈为提前预警性调节；E项神经和内分泌系统是执行调节的结构基础而非控制方式，均不符合题意"},{"q":"机体对抗蠕虫幼体感染的主要防御机制是","o":["中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","单核巨噬细胞","淋巴细胞"],"a":1,"e":"嗜酸性粒细胞胞质颗粒含主要碱性蛋白等，可杀伤蠕虫等寄生虫，并在IgE介导下参与抗蠕虫免疫，是防御蠕虫感染的主要细胞。A项中性粒细胞主要吞噬细菌；C项嗜碱性粒细胞释放组胺等参与过敏；D项单核巨噬细胞主要吞噬病原体与呈递抗原；E项淋巴细胞介导特异性免疫，均非抗蠕虫的主要效应细胞"},{"q":"将成束粗肌丝固定在一起的结构称为","o":["Z线","M线","肌钙蛋白","原肌球蛋白","H带"],"a":1,"e":"M线位于肌节暗带中央，由连接蛋白将成束粗肌丝固定并维持其排列，是粗肌丝的锚定结构。A项Z线位于肌节两端，是细肌丝附着和肌节的分界；C项肌钙蛋白与D项原肌球蛋白均为细肌丝上的调节蛋白，参与收缩调控；E项H带为暗带中央仅含粗肌丝的区域，并非固定结构"},{"q":"酸性食糜进入小肠引起大量胰液分泌的主要机制是","o":["小肠黏膜释放促胃液素","小肠黏膜释放促胰液素","小肠黏膜释放缩胆囊素","迷走神经兴奋","交感神经兴奋"],"a":1,"e":"酸性食糜进入小肠后，盐酸刺激小肠黏膜S细胞释放促胰液素，后者作用于胰腺导管细胞，促进水和HCO3-大量分泌，以中和胃酸。A项促胃液素主要刺激胃酸分泌；C项缩胆囊素主要由蛋白质分解产物和脂肪刺激释放，促胰酶分泌；D项迷走神经兴奋与E项交感神经兴奋均非酸性食糜引起大量胰液分泌的主要机制"},{"q":"在肺水肿、肺充血等病理情况下，呼吸浅快的主要原因是激发了","o":["中枢化学感受器的活动","加压反射","肺牵张反射","外周化学感受器的活动","大脑皮质的活动"],"a":2,"e":"肺水肿、肺充血时肺顺应性下降，吸气时肺扩张受限，气管支气管壁的牵张感受器兴奋，经迷走神经传入抑制吸气、促使呼气，使呼吸变浅而快，此即肺牵张反射被激活的表现。A项中枢化学感受器主要感受CO2；B项加压反射为心血管反射；D项外周化学感受器主要感受低氧等；E项大脑皮质活动非浅快呼吸的主要机制"},{"q":"肌梭感受器的适宜刺激是","o":["梭外肌收缩","梭外肌松弛","梭外肌受牵拉","梭内肌紧张性降低","梭内肌受压迫"],"a":2,"e":"肌梭与梭外肌纤维平行排列，其适宜刺激是梭外肌受牵拉而被拉长，感受肌肉长度变化，引发牵张反射。A项梭外肌收缩时肌梭随之缩短、张力解除，传入减少；B项梭外肌松弛使肌梭传入减少；D项梭内肌紧张性降低与E项梭内肌受压迫均非引起肌梭兴奋的适宜刺激"},{"q":"下列关于中心静脉压的叙述，错误的是","o":["指右心房和胸腔大静脉的血压","可反映心脏射血功能和回心血量的关系","中心静脉压比外周静脉压稍高","可作为临床输液量和速度的参考指标","心脏射血功能下降或输液过多可使中心静脉压升高"],"a":2,"e":"中心静脉压指右心房及胸腔大静脉内的血压，反映心脏射血功能与回心血量的关系，正常约5～12cmH2O，可作为输液量速度的参考。其数值低于外周静脉压，故所谓比外周静脉压稍高的说法错误。A项定义、B项意义、D项临床应用、E项射血功能下降或输液过多使其升高均表述正确"},{"q":"夏天大量出汗，引起尿量减少的主要原因是","o":["血压降低","血浆胶体渗透压升高","肾小球毛细血管血压升高","血浆晶体渗透压升高","循环血量增多"],"a":3,"e":"大量出汗时水分丢失多于电解质，使血浆晶体渗透压升高，刺激下丘脑渗透压感受器，促使抗利尿激素分泌增加，远曲小管和集合管重吸收水增多，尿量减少。A项血压降低仅在严重脱水时出现；B项血浆胶体渗透压主要受蛋白影响，出汗对其影响小；C项肾小球毛细血管血压升高会增加滤过；E项循环血量增多与大量出汗相反"},{"q":"脊髓前角中参与协调运动的闰绍细胞，其轴突末梢释放的神经递质是","o":["5-羟色胺","甘氨酸","多巴胺","乙酰胆碱","γ-氨基丁酸"],"a":1,"e":"闰绍细胞是脊髓前角的抑制性中间神经元，接受α运动神经元轴突侧支的兴奋后，其轴突末梢释放甘氨酸，作用于α运动神经元使其发生抑制，形成反馈抑制以限制运动神经元过度兴奋。A项5-羟色胺、C项多巴胺主要为脑内递质；D项乙酰胆碱为运动神经元及部分自主神经递质；E项γ-氨基丁酸虽也是抑制性递质，但闰绍细胞释放的是甘氨酸"},{"q":"给家兔吸入气中增加一定量N2后观察到呼吸运动加强，主要原因是","o":["刺激中枢化学感受器","刺激外周化学感受器","抑制呼吸中枢","刺激呼吸中枢","刺激中枢和外周化学感受器"],"a":1,"e":"吸入气中增加N2使吸入气氧分压下降，造成动脉血低氧，低氧刺激颈动脉体和主动脉体的外周化学感受器，反射性兴奋呼吸中枢使呼吸加强。A项中枢化学感受器对低氧不敏感；C项抑制呼吸中枢与呼吸加强矛盾；D项低氧对呼吸中枢为抑制而非兴奋；E项低氧并不刺激中枢化学感受器，故均错误"},{"q":"一个突触囊泡中神经递质释放进入突触间隙，所引发的兴奋性突触后电位属于","o":["动作电位","局部电位","静息电位","阈电位","负后电位"],"a":1,"e":"单个突触囊泡释放递质在突触后膜引起的兴奋性突触后电位幅度很小，属于局部电位，可发生时间总和与空间总和，并以电紧张方式扩布，不具有全或无及不衰减传导特性。A项动作电位为可扩布的锋电位；C项静息电位为未兴奋时的膜电位；D项阈电位为触发动作电位的临界水平；E项负后电位为动作电位后的电位波动，均不符合EPSP属性"},{"q":"兴奋性突触后电位在突触后膜上发生的电位变化为","o":["极化","超极化","后电位","复极化","去极化"],"a":4,"e":"兴奋性突触后电位是突触后膜对Na+（及K+）通透性改变、以Na+内流为主引起的局部去极化，使膜电位向阈电位靠近，提高神经元兴奋性。A项极化为静息时的外正内负状态；B项超极化使膜电位远离阈电位，为抑制性突触后电位的表现；C项后电位与D项复极化均为动作电位过程中的电位时相，均非EPSP的变化"},{"q":"下列哪种情况尿量不会增加","o":["尿崩症","糖尿病","静脉注射甘露醇","肾血浆流量增加","交感神经兴奋"],"a":4,"e":"交感神经兴奋时肾血管收缩，肾血流量和肾小球滤过率下降，同时促进Na+重吸收，使尿量减少，故不会引起尿量增加。A项尿崩症因抗利尿激素缺乏致水重吸收障碍；B项糖尿病因血糖过高产生渗透性利尿；C项甘露醇为渗透性利尿剂；D项肾血浆流量增加使滤过增多，均导致尿量增加"},{"q":"华法林在体内可以具有抗凝作用，其生理机制是","o":["可使血管内皮光滑，延缓血液凝固","可去除血浆中的Ca2+","可加强抗凝血酶Ⅲ的抗凝作用","可抑制因子Ⅱ、因子Ⅶ、因子Ⅸ、因子Ⅹ等维生素K依赖性凝血因子的合成","可加强肝素的抗凝作用"],"a":3,"e":"华法林通过拮抗维生素K，抑制肝脏合成维生素K依赖性凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ，使其前体不能羧化激活，从而延缓凝血。A项使血管内皮光滑并非其作用；B项去除Ca2+为枸橼酸盐等体外抗凝剂机制；C项加强抗凝血酶Ⅲ为肝素机制；E项加强肝素作用不符合，华法林与肝素机制不同"},{"q":"近端小管重吸收Na+对下列哪组物质的重吸收有促进作用","o":["K+、Cl-","H2O、Cl-、HCO3-","H+、K+","H2O、H+、K+","H+、HCO3-"],"a":1,"e":"近端小管重吸收Na+后，使小管液呈负电位并形成渗透压差，促进Cl-经细胞旁途径重吸收、水随之渗透重吸收，同时通过Na+-H+交换促进HCO3-重吸收。A项K+重吸收主要受醛固酮等调节；C、E项H+为分泌而非重吸收，其过程与Na+-H+交换偶联；D项含H+且组合不当"},{"q":"下列关于大肠功能的叙述，正确的是","o":["大肠可吸收氨基酸","大肠液有保护肠黏膜、润滑粪便的作用","大肠内的细菌可合成维生素A和D","大肠液的消化酶可分解脂肪","大肠是人体消化和吸收的主要场所"],"a":1,"e":"大肠液富含黏液和碳酸氢盐，可保护肠黏膜免受机械损伤并润滑粪便，利于排便。A项大肠主要吸收水和电解质而非氨基酸；C项大肠细菌合成的是维生素K和B族维生素，而非A、D；D项大肠液基本不含消化酶，不能分解脂肪；E项消化和吸收的主要场所在小肠，均错误"},{"q":"下列哪一项是胃蛋白酶作用的最适宜pH值","o":["0、5～1、0","1、8～3、5","5、0～6、0","6、1～7、0","8、0～9、0"],"a":1,"e":"胃蛋白酶由主细胞分泌的胃蛋白酶原在酸性环境中激活而成，其最适pH约为1.8～3.5，在胃酸提供的强酸环境中活性最高。A项0.5～1.0酸度过高；C项5.0～6.0、D项6.1～7.0、E项8.0～9.0的近中性或碱性环境会使胃蛋白酶失活，均非其最适pH"},{"q":"心肌异长自身调节通过改变下列哪一项实现","o":["肌小节初长度","肌钙蛋白活性","肌浆游离Ca2+浓度","心肌收缩能力","横桥ATP酶活性"],"a":0,"e":"心肌异长自身调节即Frank-Starling机制，通过改变心室舒张末期容积（前负荷）使肌小节初长度改变，从而调整心肌收缩强度和搏出量，使搏出量与回心血量相匹配。B项肌钙蛋白活性、C项肌浆游离Ca2+、E项横桥ATP酶活性涉及收缩能力的改变；D项心肌收缩能力属于等长自身调节，均非异长调节的机制"},{"q":"人的基本生命中枢位于","o":["脑桥","延髓","下丘脑","丘脑","中脑"],"a":1,"e":"延髓内含调节呼吸和心血管活动的基本中枢，维持机体最基本的生命活动，故称基本生命中枢，损伤可危及生命。A项脑桥含呼吸调整中枢；C项下丘脑为较高级的内脏调节中枢，调节体温、摄食等；D项丘脑为感觉换元站；E项中脑含视听防御反射中枢，均非基本生命中枢所在"},{"q":"当神经冲动到达运动神经末梢时，可引起接头前膜的","o":["K+通道开放","Ca2+通道开放","Na+通道开放","Cl-通道开放","Cl-通道关闭"],"a":1,"e":"神经冲动到达运动神经末梢时，接头前膜去极化使电压门控Ca2+通道开放，Ca2+内流促使突触囊泡以出胞方式释放乙酰胆碱，实现神经-肌接头传递。A项K+通道开放与复极有关；C项Na+通道开放主要参与动作电位上升支而非末梢递质释放的触发；D、E项Cl-通道变化与抑制性效应相关，均非此处的关键事件"},{"q":"可反映肺在外力作用下的可扩张性的是","o":["黏滞阻力","气道阻力","肺扩散容量","肺顺应性","通气血流比值"],"a":3,"e":"肺顺应性为单位跨肺压变化引起的肺容积变化，反映肺在外力作用下的可扩张性，与弹性阻力互为倒数，肺泡表面活性物质可增加肺顺应性。A项黏滞阻力和B项气道阻力属于非弹性阻力；C项肺扩散容量反映气体交换能力；E项通气/血流比值反映通气与血流匹配，均不表示肺的可扩张性"},{"q":"肌牵张反射使","o":["同一关节的协同肌发生抑制","受牵拉的肌肉发生收缩","同一关节的拮抗肌发生兴奋","其他关节的肌肉也同时发生收缩","伸肌和屈肌都收缩"],"a":1,"e":"牵张反射指骨骼肌受外力牵拉而伸长时，反射性引起同一肌肉收缩，包括腱反射和肌紧张，是维持姿势的基本反射。A项同一关节协同肌抑制与C项拮抗肌兴奋属于交互抑制；D项其他关节肌肉收缩为链式反射；E项伸肌屈肌同时收缩不符合牵张反射的局部、同侧、同名肌收缩特点"},{"q":"脊髓闰绍细胞轴突末梢释放的递质是","o":["５－羟色胺","谷氨酸","γ－氨基丁酸","甘氨酸","多巴胺"],"a":3,"e":"脊髓闰绍细胞为抑制性中间神经元，其轴突末梢释放甘氨酸，对α运动神经元产生反馈抑制，防止肌肉过度收缩。A项５-羟色胺、C项γ-氨基丁酸、E项多巴胺虽可为抑制性或调质性递质，但非闰绍细胞所释放；B项谷氨酸为兴奋性递质，均不符合闰绍细胞的递质特征"},{"q":"关于心室肌相对不应期的描述，不正确的是","o":["膜内电位为-60mV至-80mV水平","Na+通道大部分已复活","引起期前兴奋所需的刺激阈值高于正常","此期内产生的动作电位时程较长","引起期前兴奋所需的刺激阈值低于正常"],"a":4,"e":"相对不应期中大部分Na+通道已复活，但兴奋性尚未完全恢复，引起期前兴奋所需刺激阈值高于正常，所谓低于正常的说法不正确。A项膜内电位约-60至-80mV、B项Na+通道大部分复活、C项阈值高于正常均为该期特点"},{"q":"尿崩症的患者，排出大量低渗尿的始发因素是","o":["下丘脑病变","血管升压素分泌增多","醛固酮分泌增多","远曲小管和集合管上皮细胞V1受体缺乏","垂体病变"],"a":0,"e":"尿崩症患者排出大量低渗尿的始发因素是下丘脑病变，使视上核、室旁核合成抗利尿激素减少，远曲小管和集合管重吸收水障碍。B项血管升压素分泌增多会使尿量减少，与尿崩症相反；C项醛固酮分泌增多主要影响Na+重吸收；D项V1受体缺乏见于肾性尿崩症，且集合管主要为V2受体；E项垂体病变虽也可致中枢性尿崩，但以下丘脑病变为常见始发因素"},{"q":"心迷走神经节前纤维起源于","o":["脊髓中间外侧柱","脊髓灰质前角","延髓疑核和背核","延髓孤束核","心内神经节"],"a":2,"e":"心迷走神经的节前纤维起源于延髓疑核和迷走神经背核，其节前纤维下行至心内神经节换元，节后纤维支配心脏，释放乙酰胆碱使心率减慢、传导减慢。A项脊髓中间外侧柱为交感神经节前神经元所在；B项脊髓前角为运动神经元；D项孤束核接受心血管传入；E项心内神经节为迷走节后神经元换元处，均非起源部位"},{"q":"不属于红细胞生理特性和功能的是","o":["可塑变形性","悬浮稳定性","趋化性","渗透脆性","运输氧气和二氧化碳"],"a":2,"e":"红细胞的生理特性包括可塑变形性、悬浮稳定性和渗透脆性，其主要功能是运输氧气和二氧化碳，不具备趋化性。趋化性是白细胞向化学刺激物定向移动的能力，属于白细胞的特性，故不属于红细胞。A、B、D项为红细胞三大特性，E项为其主要功能，均不符合题意"},{"q":"在实验中，需要运用较强的阈上刺激才可使得心室肌再次兴奋，发生在以下哪一时期","o":["绝对不应期","有效不应期","超常期","局部反应期","相对不应期"],"a":4,"e":"相对不应期中Na+通道仅部分复活，心肌兴奋性低于正常，须用较强的阈上刺激才能引发再次兴奋，且产生的动作电位幅度低、时程短、传导慢。A项绝对不应期与B项有效不应期无论刺激多强均不能产生动作电位；C项超常期兴奋性高于正常，阈下刺激即可兴奋；D项局部反应期仅产生局部电位而不能扩布，均不符合"},{"q":"下列关于胆盐肠肝循环的叙述，正确的是","o":["胆盐在空肠末端被吸收","每次重吸收约7%","由肝静脉返回肝脏","每次进餐后可循环5～6次","返回的胆盐对肝胆汁分泌有促进作用"],"a":4,"e":"胆盐随胆汁入小肠后，约95%在回肠末端被重吸收，经门静脉返回肝脏，再随胆汁排入肠道，此即肠肝循环；返回肝脏的胆盐可促进肝细胞分泌胆汁。A项吸收部位为回肠末端而非空肠；B项重吸收率约95%而非7%；C项经门静脉而非肝静脉回肝；D项每次进餐后约循环2～3次，均错误"},{"q":"对肺牵张反射的叙述，错误的是","o":["是由肺扩张或缩小引起的反射","又称黑–伯反射","在人体平静呼吸时不起重要作用","支气管壁内存在牵张感受器","是调节人体呼吸运动的主要反射"],"a":4,"e":"肺牵张反射由肺扩张或缩小引起，又称黑-伯反射，感受器位于支气管和细支气管壁，在人体平静呼吸时不参与，主要于深呼吸或病理状态时限制吸气、促使呼气。称其为调节人体呼吸运动的主要反射不符合事实，平静呼吸主要靠呼吸中枢节律性活动，故该项错误；其余关于定义、别名、感受器及平静呼吸的表述均正确"},{"q":"丘脑特异投射系统的功能特点是","o":["调节内脏功能","引起特定感觉并激发大脑皮质发出神经冲动","改变大脑皮质兴奋状态","维持机体觉醒状态","协调随意运动"],"a":1,"e":"丘脑特异投射系统经接替核换元后，投射至大脑皮质特定区域，具有点对点关系，功能是引起特定感觉并激发大脑皮质发出神经冲动。C项改变大脑皮质兴奋状态、D项维持机体觉醒状态为非特异投射系统的功能；A项调节内脏功能主要由下丘脑及边缘系统承担；E项协调随意运动属小脑及锥体外系功能，均不符合"},{"q":"关于ABO血型系统遗传规律的叙述，正确的是","o":["A型血和B型血的父母，只能生下来A型血或B型血的孩子","A型血和A型血的父母，只能生下来A型血或O型血的孩子","B型血和B型血的父母，只能生下来B型血的孩子","AB型血和O型血的父母，只能生下来AB型血或O型血的孩子","AB型血和A型血的父母，只能生下来A型血或B型血的孩子"],"a":1,"e":"A型血基因型可为IAIA或IAi，两个A型父母的后代基因型只可能为IAIA、IAi或ii，表现型为A型或O型，不会出现B型或AB型。A项A型与B型父母可生出A、B、AB或O型子女；C项两个B型父母可生O型子女；D项AB型与O型父母只能生A型或B型子女；E项AB型与A型父母可生A、B或AB型，均错误"},{"q":"下列关于胰液的叙述，正确的是","o":["每日分泌量约5L","pH为6、8～7、2","在一定范围内，HCO3-浓度与分泌速率成正变关系","无机盐主要由腺泡细胞分泌","胰酶主要由小导管细胞分泌"],"a":2,"e":"胰液分泌速率加快时，导管细胞分泌的HCO3-浓度随之升高，在一定范围内二者呈正变关系，有助于中和进入小肠的胃酸。A项每日分泌量约1～2L而非5L；B项pH约7.8～8.4而非6.8～7.2；D项无机盐主要由导管细胞分泌；E项胰酶主要由腺泡细胞分泌，均错误"},{"q":"心动周期是指","o":["心脏机械活动周期","心脏生物电活动周期","心音活动周期","心率变化周期","室内压变化周期"],"a":0,"e":"心动周期指心脏从一次收缩开始到下一次收缩开始所经历的时间，即心脏的机械活动周期，包括心房和心室的收缩期与舒张期。B项心脏生物电活动周期为心动周期中的电变化，非其定义；C项心音、D项心率变化、E项室内压变化均为伴随现象或局部指标，不能完整概括心动周期"},{"q":"全血的黏滞性主要取决于","o":["血浆蛋白含量","红细胞数量","白细胞数量","红细胞的叠连","NaCl的浓度"],"a":1,"e":"全血黏滞性主要取决于红细胞数量，红细胞数量越多、比容越高，血液黏滞性越大，是影响血流阻力的关键因素。A项血浆蛋白含量主要决定血浆黏滞性而非全血；C项白细胞数量极少，影响微小；D项红细胞叠连可影响黏滞性但不如数量根本；E项NaCl浓度主要影响渗透压，均非主要决定因素"},{"q":"内环境稳态是指","o":["细胞内液中各种理化因素保持相对稳定","细胞外液中各种理化性质保持相对稳定","细胞内外液中各种理化性质保持相对稳定","血液中各种理化性质保持相对稳定","体液中各种理化性质保持相对稳定"],"a":1,"e":"内环境即细胞外液，内环境稳态指细胞外液的理化性质如温度、pH、渗透压等保持相对稳定，是细胞正常生命活动的必要条件。A项细胞内液不属于内环境；C项细胞内外液合并表述不当；D项血液仅为细胞外液的一部分；E项体液范围过大，包括细胞内液，均不能准确表述内环境稳态"},{"q":"在浦肯野细胞的人工浸浴液中加入河鲀毒素后给予刺激，强度足够强，作用时间足够长，其动作电位的变化是","o":["产生的动作电位不变","仍然有去极化现象产生，且去极速度变慢","没有动作电位产生","去极化的速度较快","是由于K+内流引起的"],"a":1,"e":"河鲀毒素选择性阻断快Na+通道，浦肯野细胞动作电位的快钠内流被取消，但其膜上尚有Ca2+通道可介导Ca2+内流，故仍可产生去极化，只是去极化速度明显变慢、幅度减小。A项动作电位不变忽略了钠通道被阻断；C项完全无动作电位忽略了钙内流；D项去极速度较快与阻断效应相反；E项去极化并非由K+内流引起，均错误"},{"q":"盆神经受到损伤时，排尿反射的障碍主要表现为","o":["少尿","多尿","尿失禁","尿潴留","尿频"],"a":3,"e":"盆神经为支配膀胱的副交感神经，兴奋时使逼尿肌收缩、尿道内括约肌舒张以完成排尿；其损伤后排尿反射的传出通路中断，逼尿肌不能收缩，尿液无法排出而潴留。A项少尿、B项多尿多与肾功能或ADH有关；C项尿失禁见于骶髓以上损伤导致逼尿肌反射亢进；E项尿频为膀胱刺激表现，均不符合"},{"q":"促黑激素的产生部位是","o":["下丘脑促垂体区","下丘脑视上核","下丘脑室旁核","腺垂体","神经垂体"],"a":3,"e":"促黑激素由腺垂体中间部的黑素细胞刺激素细胞产生，可促进皮肤黑素细胞合成黑色素。A项下丘脑促垂体区分泌释放/抑制激素调节腺垂体；B项视上核、C项室旁核合成抗利尿激素与缩宫素；E项神经垂体仅储存释放下丘脑激素，均非促黑激素的产生部位"},{"q":"能够减慢心率，使心电图P-R间期延长的药物可能是","o":["阿托品","普萘洛尔","肾上腺素","去甲肾上腺素","酚妥拉明"],"a":1,"e":"普萘洛尔为β受体阻滞剂，可抑制窦房结自律性使心率减慢，并延缓房室结传导使P-R间期延长。A项阿托品阻断M受体，解除迷走抑制使心率加快；C项肾上腺素兴奋β1受体使心率加快；D项去甲肾上腺素主要升压，可反射性减慢心率但不延长P-R间期；E项酚妥拉明阻断α受体，可反射性心率加快，均不符合"},{"q":"下列关于类固醇激素作用机制的描述，哪一项是错误的","o":["启动DNA转录，促进mRNA形成","诱导新蛋白质生成","直接作用于细胞膜受体","减少新蛋白质的生成","调节基因表达"],"a":2,"e":"类固醇激素为脂溶性小分子，可透过细胞膜进入靶细胞，与胞质或核内受体结合形成复合物，启动DNA转录、促进mRNA形成并诱导新蛋白质合成，从而调节基因表达。直接作用于细胞膜受体是肽类及儿茶酚胺等水溶性激素的作用方式，故该项错误。A、B、E均为类固醇激素基因调节机制的环节；D项减少某些蛋白质生成亦属其调节效应"},{"q":"第二心音的出现标志着","o":["心室收缩开始","心室舒张开始","心房收缩开始","心房舒张开始","心室射血开始"],"a":1,"e":"第二心音主要由主动脉瓣和肺动脉瓣关闭时的振动产生，发生于心室舒张开始之际，标志心室收缩期结束、舒张期开始。A项心室收缩开始与第一心音（房室瓣关闭）相关；C项心房收缩开始、D项心房舒张开始均与第二心音无关；E项心室射血开始发生在第一心音之后、半月瓣开放时，均不符合"},{"q":"关于顺应性的叙述，错误的是","o":["弹性阻力小，顺应性大","弹性阻力大，顺应性小","不易扩展的组织顺应性大","易扩展的组织顺应性大","肺泡表面活性物质使肺顺应性增加"],"a":2,"e":"顺应性是单位压力变化引起的容积变化，与弹性阻力成反比；不易扩展的组织弹性阻力大、顺应性小，故该叙述错误。A项弹性阻力小则顺应性大、B项弹性阻力大则顺应性小均正确；D项易扩展的组织顺应性大、E项肺泡表面活性物质降低表面张力使肺顺应性增加，表述均正确"},{"q":"终尿中的K+主要是由下列哪段肾小管分泌","o":["近端小管","髓袢降支细段","髓袢降支粗段","髓袢升支粗段","远端小管"],"a":4,"e":"终尿中的K+主要由远端小管（远曲小管和集合管）的主细胞分泌，受醛固酮调节，Na+重吸收时形成管内负电位促进K+排出。A项近端小管主要重吸收K+；B项髓袢降支细段、C项降支粗段、D项升支粗段主要参与髓质渗透梯度和Na+、Cl-重吸收，均非K+分泌的主要部位"},{"q":"房-室延搁产生的部位在","o":["房室束","结间束","房室交界","窦房结","希氏束"],"a":2,"e":"房-室延搁产生于房室交界区，此处细胞纤维细小、传导速度缓慢，使兴奋由心房传至心室延搁约0.1秒，保证心房收缩完成后心室才收缩，利于心室充盈。A项房室束、E项希氏束传导速度快；B项结间束为心房内传导通路；D项窦房结为起搏点，均非延搁部位"},{"q":"胆汁中与消化有关的成分是","o":["胆盐","胆色素","胆固醇","脂肪酸","碳酸氢盐"],"a":0,"e":"胆汁中与消化有关的成分是胆盐，其可将脂肪乳化成微滴，增加脂肪酶作用面积，并形成混合微胶粒促进脂肪酸和甘油一酯的吸收。B项胆色素为血红蛋白代谢产物，属排泄物；C项胆固醇为胆汁成分但过多可成结石；D项脂肪酸为脂肪消化产物而非胆汁固有成分；E项碳酸氢盐主要起中和胃酸作用，均非消化脂肪的关键成分"},{"q":"血清与血浆的主要区别在于血清中缺乏","o":["纤维蛋白原","纤维蛋白","凝血因子","血小板","Ca2+"],"a":0,"e":"血清是血液凝固后析出的淡黄色液体，凝血过程中纤维蛋白原已转变为纤维蛋白并被消耗，故血清中缺乏纤维蛋白原，这是其与血浆的主要区别。B项纤维蛋白为凝块成分，不存在于液体中；C项血清中仍含多种凝血因子；D项血小板在凝血中被消耗，但非主要区别；E项Ca2+在血清中仍存在，主要区别为纤维蛋白原"},{"q":"支配汗腺的交感神经节后纤维释放","o":["血管活性肠肽","三磷酸腺苷","去甲肾上腺素","乙酰胆碱","5-羟色胺"],"a":3,"e":"支配汗腺的交感神经节后纤维属于胆碱能纤维，末梢释放乙酰胆碱，作用于汗腺M受体促进发汗；这是交感神经中的例外。A项血管活性肠肽、B项三磷酸腺苷为某些非肾上腺素非胆碱能纤维的递质；C项去甲肾上腺素为多数交感节后纤维的递质；E项5-羟色胺主要见于中枢和胃肠道，均不符合汗腺支配特点"},{"q":"在日常生活中，看到或听到酸梅时，唾液分泌会增多。其产生机制是","o":["条件反射","非条件反射","体液调节","自身调节","条件反射和非条件反射"],"a":0,"e":"看到或听到酸梅引起的唾液分泌是后天建立的，酸梅的形状、名称作为信号与进食多次结合后形成条件反射，属于条件反射。B项非条件反射是先天固有的，如食物直接刺激口腔引起唾液分泌；C项体液调节、D项自身调节不属于神经反射范畴；E项该过程仅为条件反射，不涉及非条件反射成分，均不符合"},{"q":"红细胞渗透脆性指的是","o":["红细胞对高渗盐溶液的抵抗力","红细胞在低渗盐溶液中膨胀破裂的特性","红细胞在生理盐溶液中破裂的特性","红细胞耐受机械撞击的能力","红细胞相互撞击破裂的特性"],"a":1,"e":"红细胞渗透脆性指红细胞在低渗盐溶液中因吸水膨胀而破裂溶血的特性，脆性越大对低渗溶液抵抗力越小。A项红细胞对高渗盐溶液表现为皱缩而非破裂；C项生理盐水中红细胞形态正常；D项耐受机械撞击的能力为机械脆性；E项红细胞相互撞击破裂并非渗透脆性的定义，均不符合"},{"q":"正常眼看6米以外的物体时，在视网膜上形成","o":["小而倒置的虚像","倒置的虚像","小而倒置的实像","倒置的实像","直立的实像"],"a":2,"e":"正常眼视6米以外物体时，睫状肌松弛、晶状体扁平，光线经折光系统在视网膜上形成缩小、倒置的实像，由视神经传入皮质后经中枢处理被感知为正立物像。A、B项虚像不能在视网膜上清晰成像；D项虽为倒置实像但未强调缩小；E项直立的实像不符合视网膜成像特点，均不准确"},{"q":"CO中毒引起的缺氧比Hb减少(贫血)所致的缺氧更严重，这是因为","o":["动脉血PO2降低","血氧容量降低","血氧含量降低","HbO2的O2释放量减少","氧解离曲线右移"],"a":3,"e":"CO与Hb亲和力远高于O2，形成碳氧血红蛋白不仅占据携氧位点使血氧含量下降，还使氧解离曲线左移，HbO2中的O2不易释放给组织，故组织缺氧较贫血更严重。A项动脉血PO2在CO中毒时正常；B项血氧容量降低并非主要，贫血时容量亦降低；C项血氧含量降低两者均有；E项氧解离曲线实为左移而非右移，均不符合"},{"q":"在心动周期中，下列哪一时期的心室内压最低","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末"],"a":1,"e":"快速充盈期内血液快速流入心室，室内压降至全周期最低点，随后减慢充盈期及心房收缩期逐渐回升。A项等容舒张期末室内压虽已大幅下降但仍高于其后；C项减慢充盈期末、D项心房收缩期末室内压因充盈而升高；E项等容收缩期末室内压已升至较高水平，均非最低点"},{"q":"左心室的搏功比右心室的大，其主要原因是","o":["每搏输出量不同","左、右心室容积不同","体循环和肺循环的血流速度不同","体循环和肺循环的平均动脉压不同","体循环和肺循环的血流途径长短不同"],"a":3,"e":"左心室将血液泵入体循环，需克服较高的动脉压，而右心室仅需克服肺循环低压，二者每搏输出量基本相等，故左心室搏功显著大于右心室的主要原因在于体循环与肺循环的平均动脉压不同。A项每搏输出量两者相近；B项容积差异非主因；C项血流速度、E项途径长短对搏功影响远不及压力差"},{"q":"下列受体中，属于门控通道型的有","o":["M受体","N受体","β1受体","α受体","β2受体"],"a":1,"e":"N型乙酰胆碱受体本身即为配体门控离子通道，与ACh结合后通道开放，Na+内流引起终板电位或突触后电位。A项M受体、C项β1受体、D项α受体、E项β2受体均属G蛋白偶联受体，通过第二信使间接发挥作用，并非离子通道型受体，故均不符合"},{"q":"尿液流经尿道刺激感受器，使膀胱逼尿肌收缩增强，直至排完尿液是","o":["自身调节","负反馈调节","正反馈调节","神经-体液调节","体液调节"],"a":2,"e":"排尿过程中尿液流经尿道刺激感受器，传入冲动进一步加强膀胱逼尿肌收缩，直至尿液排尽才停止，此为正反馈调节，使排尿过程迅速完成。A项自身调节为局部组织不依赖神经体液的调节；B项负反馈使活动减弱趋于稳定，与排尿不断加强相反；D项神经-体液调节、E项体液调节均不能概括这一自我强化的过程"},{"q":"正常情况下，心脏正常的节律来自","o":["窦房结","房室结","希氏束","浦肯野纤维","左右束支"],"a":0,"e":"窦房结自律细胞4期自动去极化速度最快，自律性最高，控制心脏的正常节律，称为正常起搏点，由它主导的节律为窦性心律。B项房室结、C项希氏束、D项浦肯野纤维、E项左右束支均有自律性但频率较低，属潜在起搏点，正常情况下受窦房结超速驱动抑制而不表现出来"},{"q":"红细胞表面积与体积之比下降可引起红细胞","o":["变形性增强","渗透脆性增大","悬浮稳定性增强","对低渗盐溶液的抵抗力增强","运输氧气的能力增加"],"a":1,"e":"红细胞表面积与体积之比下降时，细胞趋于球形，可扩张的余地减小，在低渗环境中更易吸水破裂，即渗透脆性增大、对低渗盐溶液的抵抗力减弱。A项变形性随之下降而非增强；C项悬浮稳定性主要与表面电荷及叠连有关；D项抵抗力增强与脆性增大相反；E项运氧能力取决于Hb而非表面积体积比"},{"q":"严重丝虫病导致下肢水肿的原因是","o":["血浆胶体渗透压降低","组织液静水压降低","毛细血管通透性增加","毛细血管血压增高","淋巴和（或）静脉回流受阻"],"a":4,"e":"丝虫寄生于淋巴管引起淋巴管阻塞，使下肢淋巴回流受阻，组织液中的蛋白质和液体不能经淋巴系统回流入血，积聚于组织间隙形成水肿，久者可致象皮肿。A项血浆胶体渗透压降低主要见于低蛋白血症；B项组织液静水压降低非丝虫病机制；C项毛细血管通透性增加见于炎症；D项毛细血管血压增高见于心衰或静脉淤血，均非丝虫病水肿的主要原因"},{"q":"下列糖皮质激素分泌调节的描述中，哪一项是正确的","o":["受神经垂体调节","促肾上腺皮质激素是调节糖皮质激素合成和释放的最重要因素","糖皮质激素的基础分泌不受促肾上腺皮质激素影响","呈现日节律波动，午夜最高，觉醒起床前最低","促肾上腺皮质激素抑制束状带生长"],"a":1,"e":"糖皮质激素由肾上腺皮质束状带分泌，其合成释放主要受腺垂体促肾上腺皮质激素调控，该激素既维持基础分泌，又于应激时大量释放，故为最重要因素。A项实为腺垂体而非神经垂体调节；C项基础分泌同样依赖ACTH支持；D项日节律应为清晨最高、午夜最低；E项ACTH促进而非抑制束状带生长"},{"q":"中性粒细胞吞噬细菌的跨膜物质转运方式属于","o":["易化扩散","继发性主动转运","入胞","原发性主动转运","出胞"],"a":2,"e":"中性粒细胞吞噬细菌时胞膜内陷包裹颗粒形成吞噬体，属于入胞中的吞噬，需消耗能量并依赖细胞骨架完成。易化扩散与继发性主动转运只转运小分子或离子，无法摄取细菌颗粒；原发性主动转运如钠泵仅转运离子；出胞为分泌颗粒排出，方向相反"},{"q":"下列哪项是甲状腺激素在体内贮存的特点","o":["贮存于细胞外","贮存量不是很大","主要贮存形式是T3、T4","没有贮存的甲状腺激素，需要时合成","主要贮存形式是一碘酪氨酸和二碘酪氨酸"],"a":0,"e":"甲状腺激素以甲状腺球蛋白胶质形式贮存于滤泡腔内，属于细胞外贮存，储量丰富可供机体使用数周，这是其显著特点。B项贮存量实则很大，并非不大；D项并非不贮存而随用随合成；E项一碘、二碘酪氨酸只是合成中间物，并非主要贮存形式"},{"q":"在中脑上、下叠体之间切断脑干的动物，出现四肢伸直、头尾昂起、脊柱挺硬，表现出抗重力肌的肌紧张加强，称为去大脑僵直。其原因是脑干网状结构","o":["抑制区活动增强","易化区活动增强","组织受到破坏","组织受到刺激","出现抑制解除"],"a":1,"e":"中脑上、下叠体之间横断切断了高位中枢对网状结构抑制区的易化性影响，抑制区活动减弱而易化区活动相对增强，抗重力肌肌紧张亢进形成去大脑僵直。A项抑制区活动实则减弱；C项组织并未被破坏，而是上位联系中断；E项抑制解除说法笼统，直接机制是易化区活动占优势"},{"q":"去甲肾上腺素释放后在突触间隙被清除的主要方式是","o":["酶促降解","突触前末梢重摄取","进入突触后细胞","胶质细胞摄取","进入细胞外液被带走"],"a":1,"e":"去甲肾上腺素释放后主要经突触前膜转运体重新摄取回末梢，即重摄取，占清除量的绝大部分，再摄入囊泡循环利用。酶促降解如单胺氧化酶仅占次要；进入突触后细胞与胶质细胞摄取均非主要途径；进入细胞外液被带走更不符合其清除特点"},{"q":"下列能增强肾脏对尿液浓缩稀释的因素是","o":["血中葡萄糖浓度升高","血中血管升压素浓度升高","血中醛固酮浓度升高","血中血管紧张素浓度升高","血中肾素浓度升高"],"a":1,"e":"血管升压素提高远曲小管和集合管对水的通透性，促进水重吸收使尿液浓缩，缺乏时尿液稀释，故它同时增强肾的浓缩与稀释功能。血糖升高超过肾糖阈引起渗透性利尿；醛固酮主要调节钠钾与细胞外液量；血管紧张素与肾素主要通过收缩血管和调节滤过发挥作用"},{"q":"小管液中尿素浓度最高的部位是","o":["近端小管","远端小管","髓袢升支","髓袢降支","内髓部集合管"],"a":4,"e":"内髓部集合管在抗利尿激素作用下大量重吸收水，而尿素不易随水透出，使小管液尿素被高度浓缩，浓度达全程最高，并参与髓质高渗梯度形成。近端小管与髓袢降支尿素浓度较低；髓袢升支对尿素几乎不通透；远端小管尿素浓度远低于内髓集合管"},{"q":"下列物质中，不易通过红细胞膜的是","o":["O2和CO2","尿素","H2O","HCO3-","K+和Na+"],"a":4,"e":"红细胞膜对Na+、K+通透性很低，需依靠钠泵主动转运维持胞内高钾低钠的离子分布，故不易自由通过。O2和CO2为脂溶性气体可自由扩散；H2O经水通道快速通透；尿素可经载体易化扩散通过；HCO3-借助阴离子交换体跨膜，均较容易通过"},{"q":"后负荷增大引起肌肉缩短速度减小的原因是","o":["改变初长度","改变最适初长度","横桥周期延长","横桥数目增加","ATP酶活性增加"],"a":2,"e":"后负荷增大时肌肉须先产生更大张力才能缩短，横桥与细肌丝结合、摆动、解离的周期延长，故缩短速度减慢，此即张力-速度关系的机制。初长度由前负荷决定而非后负荷；最适初长度为定值；后负荷增大不增加横桥数目，也不提高ATP酶活性"},{"q":"关于等长收缩的叙述，正确的是","o":["收缩过程中不消耗能量","肌节长度明显缩短","没有发生对外做功","多发生在与肢体运动有关的肌肉中","肌肉张力保持不变"],"a":2,"e":"等长收缩时肌肉张力增加但长度不变，没有位移因而未对外做功，如维持姿势的肌收缩。该过程仍大量消耗ATP；肌节长度基本不变而非明显缩短；它多见于维持体位的姿势肌，而非主要参与肢体运动；收缩中张力明显升高，并非保持不变"},{"q":"小儿麻痹症遗留的肢体肌肉萎缩主要是由于","o":["脊髓血液供应不足","神经肌接头部位的兴奋传递功能降低","失去了运动神经对肌肉的营养作用","高位中枢的抑制作用加强","高位中枢对脊髓的易化作用减弱"],"a":2,"e":"脊髓前角运动神经元受损后，肌肉失去神经的营养性作用，蛋白合成减弱、肌纤维逐渐萎缩，即失神经支配性萎缩。脊髓供血不足并非主要机制；神经肌接头兴奋传递降低只是功能影响；高位中枢抑制加强或易化减弱均不解释局部肌肉萎缩"},{"q":"人体造血的主要原料是","o":["铁和维生素B12","维生素B12和叶酸","蛋白质和钙","蛋白质和铁","铁、蛋白质和维生素B6"],"a":3,"e":"红细胞生成以蛋白质和铁为基本原料，铁参与血红素合成，蛋白质提供珠蛋白，缺乏时导致缺铁性贫血。维生素B12和叶酸是DNA合成的成熟因子，缺乏引起巨幼红细胞性贫血；钙主要参与凝血与骨代谢，并非造血原料；维生素B6参与血红素合成但不是主要原料"},{"q":"下列关于促胃液素作用的描述，错误的是","o":["促进盐酸大量分泌","抑制肝胆汁分泌","促进胃黏膜生长","促进胃的运动","促进小肠液的分泌"],"a":1,"e":"促胃液素由胃窦G细胞分泌，可强烈刺激壁细胞分泌盐酸，促进胃黏膜生长和胃运动，并刺激小肠液与肝胆汁分泌。B项称抑制肝胆汁分泌与事实相反，实为促进；其余选项所述促进盐酸分泌、胃黏膜生长、胃运动及小肠液分泌均为其真实作用"},{"q":"关于睾丸功能的描述，下列哪项是错误的","o":["具有产生精子与雄激素的双重作用","精原细胞产生精子","支持细胞对精子起营养作用","间质细胞产生睾酮","睾丸生精功能与内分泌功能互不影响"],"a":4,"e":"睾丸兼具生精与内分泌双重功能，支持细胞营养生精细胞，间质细胞分泌睾酮，且睾酮对生精必不可少，两功能相互依存。E项称二者互不影响错误；B项精原细胞为生精细胞之源，D项间质细胞产睾酮，A项双重作用，均属正确描述"},{"q":"动物实验中，可使家兔呼吸停止的操作是","o":["在延髓和脊髓之间横断","在脑桥上、中部横断","在中脑和脑桥之间横断","切除大脑皮层","在延髓和脑桥之间横断"],"a":0,"e":"呼吸中枢位于延髓，在延髓与脊髓之间横断使延髓呼吸中枢与脊髓运动神经元联系中断，呼吸肌失去驱动而呼吸停止。脑桥上中部横断仅致长吸式呼吸，呼吸未停；中脑与脑桥之间横断保留延髓中枢；切除大脑皮层或延髓与脑桥间横断均不使呼吸停止"},{"q":"能引起血液凝固延缓或停止的因素是","o":["将血液收置在表面粗糙的玻璃管中","将血液的温度由20℃升高到37℃","在血液中加入肝素","在血液中加入少许生理盐水","在血中加入纱布块"],"a":2,"e":"肝素通过增强抗凝血酶Ⅲ活性，灭活凝血酶及多种凝血因子，发挥强大抗凝作用，使血液凝固延缓或停止。粗糙玻璃管与纱布提供接触激活表面、加速凝血；升温至37℃利于酶促反应、促进凝固；加入生理盐水只是稀释，无抗凝作用"},{"q":"下列哪种情况尿量的减少与肾小球滤过率降低无密切关系","o":["入球小动脉阻塞时","大失血时","肾小囊内压升高时","大量出汗时","输尿管堵塞时"],"a":3,"e":"大量出汗时失水多于失盐，血浆晶体渗透压升高，刺激抗利尿激素分泌，远曲小管和集合管重吸收水增加，尿量减少，此与肾小球滤过率无密切关系。入球小动脉阻塞、肾小囊内压升高、输尿管堵塞均直接降低滤过率；大失血使肾灌注下降、滤过率降低"},{"q":"体液中最活跃的部分是","o":["细胞内液","组织液","血浆","淋巴","脑脊液"],"a":2,"e":"血浆在心血管内不断循环，与组织液及外界迅速交换，是体液中最活跃的部分，承担物质运输枢纽。细胞内液虽占体液大部分但相对封闭；组织液为细胞直接环境但流动局限；淋巴回流缓慢；脑脊液更新慢且局限于中枢，均不及血浆活跃"},{"q":"离体肾动脉灌流实验发现，当动脉灌注压在80～160mmHg范围内变动时，肾血流量可保持相对稳定。其原因是","o":["肾脏血管无神经支配","肾脏血管无激素调节","肾动脉血流量与全身血压高低无关","肾血流量有自身调节作用","灌注压高低对肾血流量无任何作用"],"a":3,"e":"肾血流量在一定灌注压范围内保持稳定，源于肾血管的自身调节：灌注压升高时入球小动脉平滑肌收缩、阻力增加，压力降低时舒张，使血流量相对恒定。肾脏血管确有神经与激素支配；肾血流量与全身血压并非完全无关；灌注压超出该范围仍会影响肾血流量"},{"q":"血管平滑肌细胞膜表面，能与普萘洛尔发生特异性结合的是","o":["α受体","β1受体","β2受体","M受体","N受体"],"a":2,"e":"普萘洛尔为非选择性β受体阻断剂，血管平滑肌上主要为β2受体，与其特异性结合后可阻断舒血管效应。α受体由酚妥拉明等阻断；β1受体主要分布于心脏；M受体可被阿托品阻断；N受体则由筒箭毒阻断，均非普萘洛尔在血管上的主要靶点"},{"q":"属于局部电位的是","o":["终板电位","神经纤维动作电位","窦房结P细胞动作电位","锋电位","后电位"],"a":0,"e":"终板电位是神经肌接头处乙酰胆碱作用于终板膜产生的去极化，属于局部电位，可总和、无不应期、随距离衰减。神经纤维动作电位、窦房结P细胞动作电位及锋电位均为可传播的动作电位；后电位属动作电位组成部分，亦非局部电位"},{"q":"在心动周期中，主动脉瓣关闭始于","o":["快速射血期初","减慢射血期初","等容舒张期初","快速充盈期初","减慢充盈期初"],"a":2,"e":"心室射血末期室内压降至低于主动脉压，主动脉瓣关闭，标志等容舒张期开始，此后室内压急剧下降而容积不变。快速射血期初主动脉瓣反而开放；减慢射血期瓣膜仍开启；快速充盈期初是房室瓣开放；减慢充盈期与主动脉瓣关闭无关"},{"q":"在肠道中，与葡萄糖实现联合转运的离子是","o":["Na+","K+","Ca2+","Cl-","H+"],"a":0,"e":"小肠黏膜上皮刷状缘的钠-葡萄糖同向转运体，借助Na+顺浓度梯度的势能，将葡萄糖与Na+一起转入细胞，属继发性主动转运。K+主要由钠泵转运；Ca2+参与肌肉收缩与分泌；Cl-常与HCO3-交换；H+与肽类、氨基酸转运相关，均不与葡萄糖联合转运"},{"q":"下列关于胰腺分泌HCO3-的叙述，正确的是","o":["迷走神经兴奋可引起HCO3-大量分泌","缩胆囊素可引起HCO3-大量分泌","HCO3-由胰腺内腺泡细胞分泌","可防止胃酸对十二指肠黏膜的侵蚀","生长抑素可促进HCO3-分泌"],"a":3,"e":"胰液中的HCO3-由胰腺导管上皮细胞分泌，可中和进入十二指肠的胃酸，保护肠黏膜免受侵蚀。迷走神经兴奋主要促酶分泌；缩胆囊素亦以促酶为主，促HCO3-的是促胰液素；HCO3-并非腺泡细胞分泌；生长抑素抑制而非促进分泌"},{"q":"下列哪一项是缩宫素的主要生理作用","o":["刺激输卵管收缩","抑制乳汁分泌","促进子宫平滑肌收缩","促进非孕子宫舒张","发动分娩子宫收缩的决定因素"],"a":2,"e":"缩宫素直接作用于子宫平滑肌，促进其收缩，对妊娠子宫尤为敏感，是其最主要的生理作用。它对输卵管收缩作用弱；并不抑制乳汁分泌，而是促进排乳；对非孕子宫使其舒张并非主要作用；发动分娩是多种因素综合结果，缩宫素并非决定因素"},{"q":"与血液凝固密切相关的血浆成分是","o":["氯化钠","葡萄糖","白蛋白","球蛋白","纤维蛋白原"],"a":4,"e":"纤维蛋白原即凝血因子Ⅰ，在凝血酶作用下转变为纤维蛋白，交织成网形成血凝块，是凝血的直接物质基础。氯化钠维持渗透压；葡萄糖供能；白蛋白维持胶体渗透压并运输；球蛋白含多种抗体，均不直接参与凝血"},{"q":"以下关于1，25-二羟维生素D3的描述中，哪一项是正确的","o":["作用靶点在骨、肾和大肠","主要在肝脏由7-脱氢胆固醇转化生成","在血浆中以游离状态存在","促进小肠黏膜对钙的吸收，抑制小肠对磷的吸收","促进肾小管对钙、磷的重吸收"],"a":4,"e":"1,25-二羟维生素D3可促进肾小管对钙、磷的重吸收，并促进小肠吸收钙磷、参与骨钙化。其靶器官为小肠、骨和肾，大肠并非主要靶点；它由7-脱氢胆固醇经皮肤、肝、肾逐步转化，并非主要在肝生成；血浆中多与结合蛋白结合而非游离；它促进而非抑制小肠吸磷"},{"q":"人唾液中除含有唾液淀粉酶外，还含有下列哪种酶","o":["蛋白水解酶","肽酶","溶菌酶","脂肪酶","麦芽糖酶"],"a":2,"e":"唾液除唾液淀粉酶外还含溶菌酶，可水解细菌细胞壁肽聚糖，发挥口腔局部抗菌作用。唾液中无蛋白水解酶与肽酶；不含脂肪酶，脂肪消化主要靠胰脂肪酶；麦芽糖酶存在于小肠刷状缘，唾液淀粉酶只将淀粉分解为麦芽糖和糊精"},{"q":"脊髓前角运动神经元轴突末梢释放的递质是","o":["５－羟色胺","去甲肾上腺素","乙酰胆碱","多巴胺","γ-氨基丁酸"],"a":2,"e":"脊髓前角运动神经元属胆碱能神经元，其轴突末梢在神经肌接头释放乙酰胆碱，作用于终板膜N型受体引起肌细胞兴奋。5-羟色胺、多巴胺主要为中枢递质；去甲肾上腺素为交感节后多数纤维递质；γ-氨基丁酸是中枢抑制性递质"},{"q":"关于卵巢功能的调节，下列哪一项描述是错误的","o":["受下丘脑-腺垂体-卵巢轴的影响","下丘脑分泌促性腺激素释放激素刺激腺垂体分泌促卵泡激素和黄体生成素","促卵泡激素和黄体生成素刺激卵巢分泌雌激素和孕激素","雌激素和孕激素对下丘脑和腺垂体都只有负反馈的调节作用","卵巢功能活动的周期性变化包括卵子的生成和激素水平两个方面"],"a":3,"e":"卵巢功能受下丘脑-腺垂体-卵巢轴调节，雌激素在卵泡成熟前对下丘脑和腺垂体产生正反馈，诱发LH峰，故并非只有负反馈。A项轴调节、B项GnRH促FSH与LH、C项促性腺激素刺激性激素分泌、E项周期变化均属正确描述"},{"q":"接受同一人的血液，第二次输血时才出现输血反应见于","o":["A型或B型","O型或AB型","Rh阴性血型","Rh阳性血型","A型的不同亚型之间"],"a":2,"e":"Rh阴性者首次接受Rh阳性血液后产生抗D抗体，第二次输入同型血时抗体与供血红细胞结合，发生凝集反应。ABO血型天然存在抗体，首次输血即可反应；Rh阳性者一般无抗D抗体；A型亚型不合少见且多为首次即反应"},{"q":"心室肌细胞动作电位的膜电位接近与Na+平衡电位，是下列哪一时相","o":["阈电位","极化倒转最大值","动作电位1期","动作电位平台期","最大复极电位"],"a":1,"e":"心室肌0期去极化达峰值时膜电位由负变正，即极化倒转最大值，此时Na+内流使膜电位接近Na+平衡电位。阈电位只是触发去极化的临界值；1期为短暂复极，平台期由Ca2+内流维持；最大复极电位为自律细胞4期最负电位"},{"q":"身处海拔3000米的高原，自觉呼吸困难，这主要是由于","o":["血氧容量下降","Hb含量减少","血氧饱和度下降","血液供应不足","动脉血氧分压升高"],"a":2,"e":"海拔3000米处大气氧分压降低，动脉血氧分压随之下降，使血红蛋白氧饱和度降低，组织供氧不足而呼吸困难。血氧容量取决于Hb量，初到高原并不下降；Hb含量短期不变；血液供应不足并非主因；动脉血氧分压实为降低而非升高"},{"q":"中枢温度敏感神经元分布最多的部位在","o":["延髓","脊髓","大脑皮层运动区","脑干网状结构","下丘脑"],"a":4,"e":"下丘脑是体温调节中枢，含大量对温度敏感的中枢温度敏感神经元，尤其是视前区-下丘脑前部，感受局部血温变化并整合调节。延髓、脊髓仅含少量温度敏感神经元；大脑皮层运动区与运动有关；脑干网状结构主要与觉醒和肌紧张相关"},{"q":"支配肌梭的神经纤维属于","o":["Aα纤维","Aβ纤维","Aγ纤维","Aδ纤维","B类纤维"],"a":2,"e":"支配肌梭内肌纤维的传出纤维为γ运动神经元轴突，属Aγ纤维，调节梭内肌收缩以维持肌梭敏感性。Aα纤维支配梭外肌并传导本体感觉；Aβ纤维传导触压觉；Aδ纤维传导快痛与冷觉；B类为自主神经节前纤维"},{"q":"肾小管重吸收葡萄糖的部位在","o":["髓袢降支","髓袢升支","近端小管","远端小管","集合管"],"a":2,"e":"近端小管是重吸收的主要部位，原尿中葡萄糖几乎全部在此通过钠-葡萄糖同向转运被重吸收，故尿中无糖。髓袢降支主要重吸收水；髓袢升支重吸收NaCl而不透水；远端小管和集合管重吸收量小，且正常情况下管液中已无葡萄糖"},{"q":"人体生理学的任务是阐明","o":["细胞的生命现象","器官的功能活动","人体与环境相互关系","正常生命活动及规律","生物的生命现象"],"a":3,"e":"人体生理学以正常人体的生命活动及其规律为研究任务，阐明各系统功能及整体调节机制。细胞生命现象、器官功能活动只是其研究层次之一；人体与环境的相互关系属交叉内容；生物的生命现象范围过泛，非人体生理学专属"},{"q":"大多数可兴奋细胞接受刺激发生反应的共有表现是产生","o":["神经冲动","收缩","分泌","动作电位","局部电位"],"a":3,"e":"可兴奋细胞受刺激后共同的兴奋标志是产生动作电位，神经、肌、腺细胞均以此作为快速反应形式。神经冲动专指神经纤维的动作电位；收缩与分泌是不同细胞各自的效应，并非共有；局部电位不具全或无特性，不是兴奋的共有表现"},{"q":"以每平方米体表面积的产热量来衡量，下述哪项不是影响能量代谢的因素","o":["体重","环境温度","肌肉运动","精神紧张程度","食物"],"a":0,"e":"影响能量代谢的主要因素为肌肉运动、环境温度、食物及精神情绪活动；以每平方米体表面积计算时，体重本身并不直接影响产热量。环境温度通过寒战或散热改变代谢；肌肉运动最显著；精神紧张提高肌张力与激素分泌；食物有特殊动力效应"},{"q":"下列由小肠腺分泌的酶是","o":["肠淀粉酶","肠脂肪酶","肠激酶","胆固醇酯酶","核糖核酸酶"],"a":2,"e":"小肠腺分泌的肠激酶可激活胰蛋白酶原为胰蛋白酶，是小肠液中的特征性酶。肠淀粉酶、肠脂肪酶并非小肠腺主要分泌，消化淀粉与脂肪主要靠胰酶；胆固醇酯酶来自胰液；核糖核酸酶亦主要由胰腺分泌"},{"q":"肺活量是指","o":["自然呼吸时，一次呼出或吸入的气量","尽力吸气后能尽力呼出的气量","每分钟吸入或呼出的气量","平静呼气后再尽力呼出的气量","平静吸气后再尽力吸入的气量"],"a":1,"e":"肺活量指尽力吸气后尽力呼出的最大气量，反映肺一次通气的最大能力。自然呼吸一次的气量为潮气量；每分钟进出气量为每分通气量；平静呼气后再尽力呼出为补呼气量；平静吸气后再尽力吸入为补吸气量"},{"q":"以下跨膜信号转导途径中，信号传递速度最快的是","o":["G蛋白偶联受体","酪氨酸激酶受体","酪氨酸激酶结合型受体","鸟苷酸环化酶受体","离子通道型受体"],"a":4,"e":"离子通道型受体本身即为离子通道，配体结合后通道立即开放，离子跨膜流动在毫秒级完成，故传递最快。G蛋白偶联受体需经G蛋白与第二信使；酪氨酸激酶受体及其结合型涉及磷酸化级联；鸟苷酸环化酶受体经cGMP，均需多级反应，速度较慢"},{"q":"测定基础代谢率时的基础状态不包括下列哪一项","o":["空腹","无体力活动和精神紧张","环境温度20～25℃","清醒","深睡状态"],"a":4,"e":"基础代谢率测定要求基础状态：清醒、空腹、安静无体力活动与精神紧张、环境温度20～25℃。深睡时代谢率进一步降低，且不易配合测量，不属基础状态。空腹排除食物特殊动力效应；适温避免体温调节产热；清醒安静是必要条件"},{"q":"EPSP的产生是由于突触后膜提高了下列哪些离子的通透性","o":["Ca2+、Na+，尤其是Ca2+","K+、Na+，尤其是K+","Na+、K+，尤其是Na+","Na+、Cl-、，尤其是Na+","Na+、Cl-，尤其是Cl-"],"a":2,"e":"兴奋性突触后电位由突触后膜对Na+、K+通透性升高引起，尤以Na+内流占优势，使膜去极化。A项以Ca2+为主描述的是突触前递质释放；B项以K+为主则为抑制性变化；D、E项强调Cl-内流，属于抑制性突触后电位的机制"},{"q":"下列关于胃酸分泌的描述，错误的是","o":["分泌过程是耗能过程","质子泵在H+分泌中起关键作用","壁细胞分泌盐酸增多时，血浆pH值将下降","H+的分泌与K+的细胞内转运相偶联","由壁细胞分泌"],"a":2,"e":"壁细胞分泌H+时，细胞内生成的HCO3-被排入血液，形成餐后碱潮，血浆pH短暂升高而非下降，故该描述错误。胃酸分泌依赖质子泵主动转运、消耗ATP；H+-K+-ATP酶将H+泵出、K+泵入，二者偶联；盐酸确由壁细胞分泌"},{"q":"胃内含有消化蛋白质的胃蛋白酶，且处于一个强酸的环境，而胃不会被自身消化。这种胃黏膜自我保护机制与下列哪一个屏障作用有关","o":["碳酸氢盐屏障","凝胶保护层","细胞屏障","黏液-碳酸氢盐屏障","黏液屏障"],"a":3,"e":"胃黏液-碳酸氢盐屏障由黏液层与HCO3-共同构成，黏液阻挡H+反向弥散，HCO3-中和渗入的H+，使黏液层近腔面酸性、近细胞面中性，保护胃黏膜。单纯碳酸氢盐或黏液屏障表述不全；凝胶保护层与细胞屏障并非该保护机制的标准表述"},{"q":"下列关于神经纤维轴浆运输的描述，错误的是","o":["平时不断进行","有顺向和逆向运输","有快速和慢速运输","不直接消耗ATP","为神经元活动和存活所必需"],"a":3,"e":"轴浆运输依赖微管、驱动蛋白与动力蛋白，需水解ATP供能，故不直接消耗ATP的说法错误。轴浆运输持续进行，分顺向与逆向、快速与慢速，对维持神经元结构、递质与细胞器更新及存活必不可少"},{"q":"贫血时血氧指标的变化是","o":["血氧容量不变，血氧饱和度下降","血氧容量和血氧含量均下降","血氧容量不变，血氧含量下降","动脉血氧分压下降","动脉血氧分压升高"],"a":1,"e":"贫血时血红蛋白减少，血氧容量与血氧含量均随之下降，但肺摄氧与血氧饱和度、动脉血氧分压基本正常。A项血氧饱和度下降并非贫血特征；C项容量不变与实际不符；D、E项动脉血氧分压改变主要见于呼吸或循环障碍，而非贫血"},{"q":"提高自律细胞自律性的因素是","o":["最大复极电位绝对值减小","阈电位水平上移","4期自动去极化速度增快","最大复极电位水平下降","0期去极化速度增快"],"a":2,"e":"自律细胞4期自动去极化速度增快，使膜电位更快达到阈电位，单位时间内兴奋次数增多，自律性升高。阈电位上移、最大复极电位水平下降都加大与阈电位的差距，降低自律性；0期去极化速度增快主要增强传导性而非自律性"},{"q":"交感缩血管神经过度兴奋时，对下列哪一器官的血管收缩作用最强","o":["骨骼肌","皮肤","心脏","脑","肝脏"],"a":1,"e":"交感缩血管纤维在皮肤血管分布最密集，兴奋时释放去甲肾上腺素作用于α受体，引起强烈收缩，皮肤血流量可显著减少。骨骼肌血管以β2舒血管受体为主；冠状血管受局部代谢调节为主；脑血管自身调节强、交感影响小；肝脏血管收缩不及皮肤显著"},{"q":"用毒毛花苷G抑制钠泵活动后，细胞功能发生的变化有","o":["静息电位绝对值增大","动作电位幅度降低","Na+-Ca2+交换增加","细胞质渗透压降低","动作电位幅度增大"],"a":1,"e":"毒毛花苷G抑制钠泵后，细胞内Na+积聚、膜内外Na+浓度差减小，动作电位0期Na+内流驱动力下降，幅度降低。静息电位绝对值因Na+外漏增多而减小而非增大；Na+-Ca2+交换减弱使胞内Ca2+增加；细胞渗透压升高而非降低，水分内流可致细胞肿胀"},{"q":"关于钠泵的表述，错误的是","o":["具有ATP酶活性","能帮助Na+从细胞膜外进入膜内","属于二聚体蛋白质","对细胞生物电的产生具有重要意义","参与细胞正常体积的维持"],"a":1,"e":"钠泵即Na+-K+-ATP酶，每分解一分子ATP将3个Na+泵出、2个K+泵入，故帮助Na+由膜内移向膜外才正确，题目所述方向相反。钠泵具ATP酶活性、为二聚体蛋白；它建立Na+、K+梯度，是生物电产生基础，并维持细胞正常体积"},{"q":"慢性肾功能衰竭大多数患者有轻度、中度贫血，其原因与肾脏哪种激素分泌有关","o":["肾素","血管紧张素Ⅱ","醛固酮","前列腺素","促红细胞生成素"],"a":4,"e":"肾脏分泌促红细胞生成素，慢性肾功能衰竭时该激素生成减少，骨髓红系造血受抑，患者出现轻中度贫血。肾素参与血压调节；血管紧张素Ⅱ主要由ACE作用于血管紧张素Ⅰ生成；醛固酮调节钠钾；前列腺素为局部舒血管物质，均非贫血主因"},{"q":"促进女性青春期乳腺发育的最主要的激素是下列哪一种","o":["生长激素","催乳素","雌激素","催产素","甲状腺激素"],"a":2,"e":"雌激素促进女性青春期乳腺导管系统发育，是此期乳腺发育最主要的激素，孕激素则促进腺泡发育。生长激素参与全身生长；催乳素主要促进产后乳汁生成；催产素促排乳；甲状腺激素影响代谢，均非青春期乳腺发育的主导因素"},{"q":"气体扩散速率与下列因素的关系是","o":["分压差小则扩散快","与各气体分子量的平方根成正比","与扩散面积成反比","与温度成反比","与溶解度成正比"],"a":4,"e":"气体扩散速率与气体在溶液中的溶解度成正比，溶解度大者扩散更快。分压差越小扩散越慢；速率与分子量平方根成反比而非正比；与扩散面积成正比而非反比；与温度成正比而非反比"},{"q":"肺功能衰竭患者往往缺O2显著，CO2潴留不明显，其原因是","o":["CO2的分子量比O2的分子量大","肺泡毛细血管血液与肺泡之间的O2分压差大于CO2分压差","O2的溶解度大于CO2的溶解度","肺泡毛细血管血液与肺泡之间的CO2分压差大于O2分压差","CO2的扩散系数是O2的20倍"],"a":4,"e":"CO2在肺泡膜的扩散系数约为O2的20倍，远大于O2，故肺功能衰竭时O2交换先受限、缺氧显著，而CO2仍可充分弥散，潴留不明显。A项分子量差异并非决定因素；C项O2溶解度实小于CO2；D项颠倒了分压差关系，O2分压差本就大于CO2"},{"q":"引起伤害性感受器兴奋的致痛物质是","o":["Na+、Cl-","二氧化碳","乙酰胆碱","缓激肽","一氧化氮"],"a":3,"e":"缓激肽是组织损伤时激肽系统激活产生的致痛物质，可直接兴奋伤害性感受器并引起血管扩张。Na+、Cl-参与动作电位形成而非致痛；CO2主要调节呼吸与脑血流；乙酰胆碱为神经递质；一氧化氮为舒血管因子，均非主要致痛物质"},{"q":"B型血中的红细胞与A型血的血清相混，将发生的现象是","o":["红细胞聚集","红细胞凝集","红细胞叠连","血液凝固","红细胞吞噬"],"a":1,"e":"B型红细胞表面有B抗原，A型血清中含抗B凝集素，二者相遇发生抗原抗体反应，红细胞聚集成团即凝集。聚集与叠连多为血流状态改变引起的可逆性堆叠；血液凝固需凝血因子参与形成纤维蛋白；吞噬由巨噬细胞完成，均非此现象"},{"q":"能将蛋白质分子有选择性地转运到细胞内的物质转运方式是","o":["载体介导的易化扩散","原发性主动转运","继发性主动转运","液相入胞","受体介导入胞"],"a":4,"e":"受体介导入胞通过配体与细胞膜特异性受体结合，选择性地将蛋白质等大分子摄入细胞，如LDL的摄取。载体介导易化扩散转运小分子；原发与继发性主动转运转运离子和小分子；液相入胞无选择性地吞入细胞外液，均不具备选择性转运蛋白质的特点"},{"q":"下列生理或病理过程属于正反馈的是","o":["体位由平卧转变为直立时，通过压力感受性反射使血压回升","激素水平降低时，其与相应受体的亲和力及受体的表达数量均增加","大失血使血压降低，心脏血供不足，心输出量减少而进一步降低血压","应激反应中，血中ACTH和肾上腺糖皮质激素水平持续升高","有关寒冷信息通过视、听等感觉传入中枢即引起产热增加"],"a":3,"e":"应激反应一旦启动，下丘脑-腺垂体-肾上腺皮质轴逐级兴奋，血中ACTH与糖皮质激素持续升高，反应不断增强直至应激原消除，属于正反馈式放大。A项压力感受性反射是典型负反馈；B项受体上调属负反馈性代偿；E项是条件反射性产热，无输出回输环节"},{"q":"胃酸分泌过多可导致胃溃疡，引起胃疼痛，服用雷尼替丁后可以缓解。其机制是下列的哪一项","o":["阻断M受体，使胃酸分泌减少","使胃平滑肌舒张","阻断H2受体，使胃酸分泌减少","阻断氢泵的作用，使胃酸分泌减少","使生长抑素分泌增多"],"a":2,"e":"雷尼替丁为H2受体阻断剂，可竞争性阻断壁细胞组胺H2受体，抑制胃酸分泌，从而缓解胃酸过多所致胃溃疡疼痛。阻断M受体是抗胆碱药机制；胃平滑肌舒张不减少胃酸；氢泵抑制为质子泵抑制剂机制；生长抑素增多亦非其作用"},{"q":"关于神经纤维动作电位产生机制的叙述，错误的是","o":["加大细胞外Na+浓度，动作电位幅度会减小","其去极过程是由于Na+内流形成的","其复极过程是由于K+外流形成的","膜电位去极到阈电位时Na+通道迅速大量开放","该动作电位的形成与Ca2+无关"],"a":0,"e":"动作电位幅度取决于膜两侧Na+浓度差，加大细胞外Na+浓度会增大驱动力、使幅度升高而非减小，故该叙述错误。去极由Na+内流形成、复极由K+外流形成；达阈电位时Na+通道大量开放；该神经纤维动作电位主要由Na+、K+参与，与Ca2+无关"},{"q":"在兴奋收缩耦联过程中起主要媒介作用的离子是","o":["Na+","K+","Cl-","Ca2+","Mg2+"],"a":3,"e":"兴奋收缩耦联中，动作电位沿横管传到终池，触发终池释放Ca2+，Ca2+与肌钙蛋白结合启动横桥循环，故Ca2+是主要媒介离子。Na+参与动作电位去极；K+参与复极；Cl-与抑制性电位有关；Mg2+为多种酶的辅因子，均非耦联媒介"},{"q":"心电图中代表两心室去极化和复极化的时间是","o":["P-P间期","S-T段","P-R间期","Q-T间期","R-R间期"],"a":3,"e":"Q-T间期从QRS波群起点至T波终点，代表两心室去极化与复极化的总时间。P-P间期与R-R间期反映心动周期；P-R间期为房室传导时间；S-T段为心室缓慢复极阶段，只反映平台期，不能代表全部去极与复极"},{"q":"下述关于浦肯野细胞起搏离子流If的描述，哪一项是错误的","o":["由于超极化而激活","阈电位约为-50mV","充分激活的膜电位为-100mV","可被铯所阻断","是钙离子流"],"a":4,"e":"浦肯野细胞的If是超极化激活的内向离子流，以Na+内流为主而非钙离子流，可被铯阻断，随复极至-100mV左右充分激活，推动4期自动去极化。超极化激活、被铯阻断及充分激活电位均为其特性；钙离子流主要参与平台期，并非If的成分"},{"q":"渗透性利尿的直接机制是","o":["血浆晶体渗透压升高","肾小球滤过率增加","血浆胶体渗透压升高","肾小管和集合管对水的通透性降低","肾小管和集合管内小管液溶质浓度增加"],"a":4,"e":"渗透性利尿时小管液中溶质浓度升高，渗透压增大，阻碍水的重吸收，使尿量增多，直接机制即肾小管与集合管内小管液溶质浓度增加。血浆晶体或胶体渗透压改变影响的是组织液与血容量；滤过率增加不是渗透性利尿的机制；水通透性降低为尿崩症机制"},{"q":"兴奋性突触后电位属于","o":["静息电位","去极化性电紧张电位","动作电位","阈电位","超极化性电紧张电位"],"a":1,"e":"兴奋性突触后电位是突触后膜轻度去极化产生的电紧张电位，幅度随刺激增强而增大、可总和、可衰减，故属去极化性电紧张电位。静息电位为未受刺激时的膜电位；动作电位具全或无并可传播；阈电位是触发动作电位的临界值；超极化性电紧张电位为抑制性突触后电位"},{"q":"肾脏不能分泌的激素是","o":["血管紧张素Ⅱ","促红细胞生成素","肾素","羟化维生素D3","前列腺素"],"a":0,"e":"血管紧张素Ⅱ由肝产生的血管紧张素原经肾素和ACE逐步水解生成，主要转换部位在肺，肾脏本身并不分泌。肾素、促红细胞生成素、羟化维生素D3及前列腺素均可由肾脏产生或分泌，参与血压、造血与钙磷代谢调节"},{"q":"心交感神经调节心脏活动时，跨膜信号转导过程中数量增多的第二信使是","o":["cAPM","cGMP","IP3","DG","Ca2+"],"a":0,"e":"心交感神经末梢释放去甲肾上腺素，作用于心肌β1受体，经Gs蛋白激活腺苷酸环化酶，使第二信使cAMP增多，产生正性变时变力作用。cGMP为心迷走神经NO通路信使；IP3与DG属α受体磷脂酶C通路；Ca2+是胞内第三信使而非该通路中增多的第二信使"},{"q":"在各段肾小管中，重吸收量占首位的部位是","o":["髓袢升支粗段","髓袢升支细段","近端小管","远曲小管","集合管"],"a":2,"e":"近端小管重吸收量居各段之首，原尿中约65%～70%的水、Na+及其他溶质在此被重吸收。髓袢升支粗段主要重吸收NaCl；升支细段通透性低；远曲小管与集合管重吸收量少且受激素调节，并非重吸收的主要部位"},{"q":"下列物质中与肾外髓部高渗梯度形成有关的是","o":["氯化钠","氯化钾","尿素","葡萄糖","肌酐"],"a":0,"e":"肾外髓部高渗梯度主要由髓袢升支粗段主动重吸收NaCl形成，该段不透水，NaCl外移使小管外渗透压升高。尿素主要参与内髓部高渗梯度形成；氯化钾、葡萄糖、肌酐均非建立髓质渗透梯度的关键溶质"},{"q":"关于G蛋白耦联受体的叙述，错误的是","o":["本身不具备酶的活性","是膜受体中最大的家族","可直接激活腺苷酸环化酶","是一种7次跨膜受体","本身不具备通道结构，但可通过第二信使调控离子通道的活动"],"a":2,"e":"G蛋白耦联受体本身无酶活性，与配体结合后先激活G蛋白，再由G蛋白α亚基调节腺苷酸环化酶等效应器，不能直接激活，故该叙述错误。它是最大的膜受体家族、具7次跨膜结构；虽无通道结构，但可经第二信使调控离子通道活动"},{"q":"甲状腺滤泡上皮细胞的聚碘作用是通过继发性主动转运实现的，抑制下列哪项功能活动可以导致甲状腺的聚碘障碍","o":["I-通道","钠泵","钠-碘交换体","钠-钙交换体","质子泵"],"a":1,"e":"甲状腺聚碘由Na+-I-同向转运体完成，属继发性主动转运，其驱动力来自钠泵消耗ATP建立的细胞内外Na+梯度，抑制钠泵后梯度消失，聚碘障碍。I-通道、钠-钙交换体与质子泵均不参与聚碘过程；碘的有机化还需过氧化物酶，但本题所问为聚碘的驱动环节"},{"q":"肾脏维持水平衡的功能主要靠调节下列哪项活动来实现","o":["肾小球滤过量","肾小管的分泌功能","近曲小管的重吸收水量","远曲小管与髓袢的重吸收水量","远曲小管与集合管的重吸收水量"],"a":4,"e":"远曲小管与集合管对水的重吸收受抗利尿激素调节，是肾脏维持水平衡的主要环节，可根据机体缺水与否大幅调整尿量。肾小球滤过量在正常情况下较恒定；肾小管分泌主要排泌代谢物；近曲小管重吸收水量固定、不受激素调节；髓袢主要建立渗透梯度"},{"q":"临床上，采用质子泵抑制剂治疗急性胰腺炎的主要机制是","o":["减少促胰液素的分泌","增加缩胆囊素的分泌","减少生长抑素的分泌","兴奋迷走神经","兴奋交感神经"],"a":0,"e":"质子泵抑制剂抑制胃酸分泌，使进入十二指肠的H+减少，对S细胞刺激减弱，促胰液素分泌随之下降，胰液与胆汁分泌减少，胰腺得以休息，故用于急性胰腺炎。它并不直接增加缩胆囊素或兴奋迷走、交感神经；生长抑素分泌变化也非主要机制"},{"q":"生理情况下，肾小球的滤过分数约为","o":["10%","20%","30%","40%","50%"],"a":1,"e":"滤过分数为肾小球滤过率与肾血浆流量之比，正常约为19%～20%，即流经肾脏的血浆约五分之一被滤过。10%过低；30%、40%与50%均明显高于正常，超出实际滤过比例"},{"q":"以下哪种肌肉肌细胞间存在的缝隙连接最少","o":["膀胱","消化道","睫状肌","小血管平滑肌","子宫平滑肌"],"a":2,"e":"睫状肌属多单位平滑肌，肌细胞间缝隙连接很少，各纤维独立收缩、精细调节晶状体曲率。膀胱、消化道与子宫平滑肌属单个单位，缝隙连接丰富，可实现同步收缩；小血管平滑肌亦以缝隙连接协调收缩，均非最少"},{"q":"属于负反馈调节的生理过程有","o":["分娩过程","排尿反射","减压反射","血液凝固","射乳反射"],"a":2,"e":"减压反射中血压升高兴奋迷走、抑制交感使血压回降，血压下降则反向调节，输出反复修正偏差，属典型负反馈。分娩、排尿、血液凝固与射乳反射一旦启动即不断加强直至完成，均为正反馈过程"},{"q":"副交感神经节后纤维释放的递质是","o":["ACh","NE","5-HT","ACh和NE","NE和5-HT"],"a":0,"e":"副交感神经节后纤维为胆碱能纤维，末梢释放乙酰胆碱，作用于效应器M型受体。去甲肾上腺素为交感节后多数纤维的递质；5-羟色胺主要为中枢与肠神经递质；副交感节后纤维并不释放NE，亦不释放5-HT"},{"q":"关于胃排空的叙述，下列哪一项不正确","o":["混合性食物在进餐后4～6小时完全排空","糖类食物排空最快，蛋白质最慢","胃的蠕动是胃排空的动力","迷走神经兴奋促进胃排空","液体食物排空速度快于固体食物"],"a":1,"e":"胃排空速度一般为糖类最快、蛋白质次之、脂肪最慢，故蛋白质最慢的说法不正确。混合性食物需4～6小时排空；胃蠕动提供排空动力；迷走神经兴奋促进胃运动与排空；液体食物排空快于固体食物，均属正确叙述"},{"q":"动物实验中，在气管插管外口连接一根1、0m长的橡皮管，观察到动物呼吸加深加快，其主要原因是","o":["肺牵张反射增强","动脉血中PO2升高","动脉血中pH值升高","气道阻力增加","动脉血中PCO2升高"],"a":4,"e":"气管插管外接长管增加了解剖死腔，呼出气体中的CO2被重复吸入，动脉血PCO2升高，刺激中枢与外周化学感受器，使呼吸加深加快。肺牵张反射增强会抑制吸气；死腔增加并不使PO2或pH升高；气道阻力增加不是主要原因"},{"q":"关于致密斑的描述正确的是","o":["位于近端小管的起始部","是感受Na+含量变化的感受器","是肾素的分泌细胞","可调节血管升压素的释放","是晶体渗透压感受器"],"a":1,"e":"致密斑位于远曲小管起始部，可感受小管液中Na+含量变化，将信息传给球旁细胞调节肾素释放，参与管球反馈。它不位于近端小管；肾素由球旁细胞分泌；血管升压素释放受渗透压与容量调节；晶体渗透压感受器在下丘脑"},{"q":"一般血型抗原都是红细胞膜上的","o":["糖原","蛋白质","磷脂","脂蛋白","糖脂或糖蛋白"],"a":4,"e":"血型抗原多为红细胞膜上的糖脂或糖蛋白，其特异性由寡糖链末端糖基决定，如ABO抗原。糖原为储能多糖；蛋白质与磷脂单独存在不构成血型抗原特异性；脂蛋白主要运输脂类，均非血型抗原的化学本质"},{"q":"可以被兴奋性G蛋白（Gs）激活的是","o":["磷酸二酯酶","腺苷酸环化酶","鸟苷酸环化酶","磷脂酶C","蛋白激酶A"],"a":1,"e":"兴奋性G蛋白Gs被受体激活后，其α亚基结合GTP并激活腺苷酸环化酶，使cAMP生成增加。磷酸二酯酶降解cAMP；鸟苷酸环化酶生成cGMP；磷脂酶C由Gq激活；蛋白激酶A是cAMP的下游效应分子，均不被Gs直接激活"},{"q":"心输出量是指","o":["每搏输出量","左右心室输出的总血液量","每分钟左心室所泵出的血量","心房进入心室的血量","每分钟两心房进入心室的血量"],"a":2,"e":"心输出量指每分钟一侧心室泵出的血量，通常指左心室，等于每搏输出量乘以心率。每搏输出量为一次心跳的射血量；左右心室输出总量相加并非心输出量定义；心房进入心室的血量与心室充盈有关，不等于泵出量"},{"q":"肾小管中，重吸收Na+最多的部位是","o":["近端小管","髓袢降支","髓袢升支","远端小管","集合管"],"a":0,"e":"近端小管重吸收Na+最多，约占滤过Na+的65%～70%，与Na+-葡萄糖、Na+-氨基酸同向转运及Na+-H+交换密切相关。髓袢降支几乎不重吸收Na+；髓袢升支、远端小管与集合管重吸收量依次减少，主要参与浓缩与电解质平衡调节"},{"q":"对于氧解离曲线的描述，正确的是","o":["氧解离曲线的纵轴可以用血液中氧气的浓度来表示","曲线上段和中段主要反映Hb与O2的结合","曲线下段反映Hb与O2的解离","PO2逐渐升高，血氧含量也直线增加","氧解离曲线受多种因素的影响可以发生上移或下移的变化"],"a":2,"e":"氧解离曲线下段对应低PO2范围，坡度陡峭，反映HbO2迅速解离释放O2，满足组织代谢需要。纵轴以血氧饱和度或氧含量表示而非氧气浓度；PO2升高时曲线趋于平坦，血氧含量不成直线增加；上中段主要反映Hb与O2结合，曲线移位是影响因素作用的结果"},{"q":"下列关于心率的描述，错误的是","o":["正常人安静时为60～100次/分","新生儿心率较成年人慢","女性心率比男性稍快","运动员平时心率较慢","妊娠、甲亢病人心率较快"],"a":1,"e":"新生儿心率明显快于成人，安静时可达120～140次/分，故该叙述错误。成人安静心率60～100次/分；女性稍快于男性；运动员因迷走张力较高而心率较慢；妊娠、甲亢时代谢增高使心率加快"},{"q":"内源性凝血与外源性凝血的主要区别在于","o":["有无血小板参与","有无Ca2＋参与","凝血酶原激活过程","纤维蛋白形成过程","凝血因子Ⅹ的激活过程"],"a":4,"e":"内源性与外源性凝血的主要区别在于凝血因子Ⅹ的激活途径：内源性由Ⅻ因子启动经Ⅺ、Ⅸ、Ⅷ形成复合物激活Ⅹ，外源性由组织因子与Ⅶ直接激活Ⅹ。两者均有Ca2+参与；纤维蛋白形成过程相同；血小板在生理止血中均参与，并非主要区别"},{"q":"推测膜蛋白肽链中可能存在的跨膜α螺旋数目，其主要依据是肽链中所含有的","o":["氨基酸总数目","疏水性氨基酸数目","亲水性氨基酸数目","疏水性氨基酸片段数目","亲水性氨基酸片段数目"],"a":3,"e":"跨膜α螺旋由约20个疏水性氨基酸残基构成，故据肽链中疏水性氨基酸片段的数目可推测跨膜螺旋数目。氨基酸总数只反映肽链长度；孤立疏水氨基酸数目不足以形成跨膜段；亲水性氨基酸及其片段多位于膜外或胞质侧，不用于推测跨膜螺旋"},{"q":"骨骼肌发生等张收缩时，长度不发生改变的结构是","o":["肌原纤维","肌小节","H带","暗带","明带"],"a":3,"e":"等张收缩时肌肉缩短，暗带长度等于粗肌丝长度，保持不变；明带与H带随细肌丝滑行而缩短，肌小节随之变短。肌原纤维由肌小节串联而成，整体缩短；最适初长度是长度而非结构，与题意不符"},{"q":"下列关于冠脉循环解剖特点的叙述，正确的是","o":["冠脉开口于肺动脉根部","冠脉小分支以垂直方向穿入心肌","冠脉易在心肌舒张时被压迫","心肌毛细血管网分布较少","冠脉侧支血流量丰富"],"a":1,"e":"冠状动脉小分支以垂直方向穿入心肌，心肌收缩时易受压迫，故冠脉循环受心肌节律性收缩影响显著。冠脉开口于主动脉根部而非肺动脉；舒张期心肌放松、冠脉受压解除、血流量增加，收缩期反而被压迫；心肌毛细血管网极为丰富；冠脉侧支细小、血流量少"},{"q":"能阻断终板膜上胆碱能受体的是","o":["有机磷","筒箭毒","普萘洛尔","氯吡格雷","河豚毒素"],"a":1,"e":"筒箭毒可特异性阻断终板膜上的N2型胆碱能受体，竞争性抑制乙酰胆碱作用，使骨骼肌松弛。有机磷抑制胆碱酯酶、增强胆碱能作用；普萘洛尔阻断β受体；氯吡格雷抑制血小板聚集；河豚毒素阻断Na+通道，均不阻断终板膜受体"},{"q":"凝血酶的主要作用是","o":["加速凝血因子Ⅶ复合物的形成","加速凝血酶原酶复合物的形成","激活凝血因子Ⅰ","激活凝血因子Ⅻ","促进血小板聚集"],"a":2,"e":"凝血酶的主要作用是水解凝血因子Ⅰ即纤维蛋白原，使其转变为纤维蛋白单体，进而聚合成纤维蛋白网。它不加速Ⅶ复合物形成；凝血酶原酶复合物形成于凝血酶生成之前；Ⅻ因子为内源性凝血启动因子；血小板聚集主要由ADP与血栓素等介导"},{"q":"以下属于单个单位平滑肌的是","o":["竖毛肌","睫状肌","输尿管","虹膜肌","大血管平滑肌"],"a":2,"e":"输尿管平滑肌属单个单位平滑肌，细胞间缝隙连接丰富，可自发节律性收缩并同步传播，类似消化道与子宫。竖毛肌、睫状肌、虹膜肌及大血管平滑肌属多单位平滑肌，缝隙连接少，受神经单独支配、收缩较独立"},{"q":"女性月经周期中，体温最低的时间是","o":["月经期","排卵前","排卵后","排卵日","增殖期"],"a":3,"e":"排卵日前后雌激素水平达峰后骤降，基础体温降至周期最低，排卵后孕激素升高使体温上升0.3～0.6℃，故体温最低在排卵日。月经期与增殖期体温较低但不若排卵日明显；排卵后因孕激素作用体温处于高位"},{"q":"副交感神经对代谢的影响是","o":["促进甲状旁腺素分泌","促进胰高血糖素分泌","促进糖原分解","促进胰岛素分泌","促进甲状腺激素的释放"],"a":3,"e":"副交感神经兴奋时末梢释放乙酰胆碱，作用于胰岛B细胞M受体，促进胰岛素分泌，有利于餐后合成代谢与血糖利用。它抑制而非促进胰高血糖素分泌；促进糖原合成而非分解；甲状旁腺素与甲状腺激素的分泌主要受体液因素调节"},{"q":"肾小球有效滤过压等于","o":["肾小囊内压-（肾小球毛细血管血压+血浆胶体渗透压）","肾小囊内压-（肾小球毛细血管血压-血浆胶体渗透压）","血浆胶体渗透压-（肾小球毛细血管血压+肾小囊内压）","肾小球毛细血管血压-（肾小囊内压+血浆胶体渗透压）","肾小球毛细血管血压-肾小囊内压+血浆胶体渗透压"],"a":3,"e":"肾小球有效滤过压等于肾小球毛细血管血压减去肾小囊内压与血浆胶体渗透压之和，是滤过的动力。A、B项把肾小囊内压置于被减位置，公式颠倒；C项以胶体渗透压为动力减毛细血管血压，方向错误；E项将胶体渗透压作为加项，符号错误"},{"q":"静息电位的数值（绝对值）变大称作","o":["极化","去极化","复极化","超极化","反极化"],"a":3,"e":"静息电位绝对值增大即膜两侧电位差加大、膜更负，称为超极化。极化为静息时膜内负外正的状态；去极化为膜电位向0mV方向减小；复极化为去极化后回到静息水平；反极化为膜内变正、超出0mV"},{"q":"可使心室肌兴奋性增高的因素是","o":["Na+通道少量失活","静息电位绝对值加大","阈电位下移","细胞外液Ca2+浓度增加","Na+通道处于备用状态"],"a":2,"e":"阈电位下移使膜电位更易达到触发水平，与静息电位差距减小，心室肌兴奋性增高。Na+通道少量失活使可用通道减少，兴奋性降低；静息电位绝对值加大增大与阈电位差距；细胞外Ca2+升高使阈电位上移；Na+通道处于备用状态是正常静息时的状态，并非增高因素"},{"q":"可兴奋细胞包括","o":["神经元、骨骼肌细胞、角质上皮细胞","肌细胞、腺细胞、角质上皮细胞","神经元、腺细胞、骨细胞","神经元、骨骼肌细胞、心肌细胞","神经元、骨骼肌细胞、骨细胞"],"a":3,"e":"可兴奋细胞包括神经元、骨骼肌细胞与心肌细胞等，受刺激后能产生动作电位。角质上皮细胞与骨细胞不具兴奋性；腺细胞虽可分泌，但教材所列典型可兴奋细胞为神经与肌细胞，含角质或骨细胞的选项均应排除"},{"q":"肾交感神经兴奋时，下列说法正确的是","o":["入球小动脉收缩幅度小于出球小动脉的收缩幅度","可减弱近端小管对水和氯化钠的通透性","可使有效滤过压增加","引起球旁细胞分泌肾素","对肾血流量无影响"],"a":3,"e":"肾交感神经兴奋时释放去甲肾上腺素，激活球旁细胞β1受体，引起肾素分泌，启动RAS系统。入球小动脉收缩幅度大于出球小动脉；它增强近端小管对水和NaCl的重吸收；入球收缩使滤过压下降；肾血流量明显减少"},{"q":"交叉配血试验的次侧是指","o":["供血者的红细胞与受血者的红细胞进行配血","供血者的红细胞与受血者的血浆进行配血","供血者的血浆与受血者的红细胞进行配血","供血者的血浆与受血者的血浆进行配血","供血者的红细胞与受血者的骨髓造血细胞进行配血"],"a":2,"e":"交叉配血次侧是将供血者血浆与受血者红细胞相混，检查供血者抗体是否凝集受血者红细胞。主侧为供血者红细胞加受血者血浆；红细胞与红细胞、血浆与血浆相混均不能配血；受血者骨髓造血细胞不参与交叉配血"},{"q":"最理想的血管内抗凝剂是","o":["肝素","柠檬酸钠","草酸钠","氯化钙","氯化钠"],"a":0,"e":"肝素通过激活抗凝血酶Ⅲ发挥强大抗凝作用，体内体外均有效，是血管内抗凝首选。柠檬酸钠与草酸钠通过螯合Ca2+抗凝，多用于体外；氯化钙提供Ca2+反而促凝；氯化钠无抗凝作用"},{"q":"自身调节指组织、细胞在不依赖于神经、体液调节的情况下对刺激所产生的","o":["适应性反应","旁分泌反应","稳态反应","非自控调节","前馈调节"],"a":0,"e":"自身调节指组织细胞不依赖神经和体液调节，自身对刺激产生的适应性反应，如肾血流量在一定血压范围内的稳定。旁分泌是局部化学信号调节；稳态是内环境相对稳定状态；前馈是预判性调节，非自控调节表述亦不准确"},{"q":"下列哪个物质可激活胃蛋白酶原","o":["Cl-","Na+","Ca2+","盐酸","内因子"],"a":3,"e":"盐酸可激活胃蛋白酶原，使其转变为胃蛋白酶，并为该酶提供酸性作用环境。Cl-随盐酸分泌但本身不激活酶原；Na+、Ca2+无此作用；内因子促进维生素B12吸收，与胃蛋白酶原激活无关"},{"q":"关于睾酮刺激男性副性征的叙述，下列哪项是错误的","o":["体毛发达","头发生长茂盛","皮脂腺分泌旺盛","肌肉发达","声调低沉"],"a":1,"e":"睾酮作为雄激素使体毛发达、皮脂腺分泌旺盛、肌肉发达并致声调低沉，但过度作用导致脱发，并非头发生长茂盛，故该项错误。其余选项所述体毛、皮脂、肌肉与声调改变均为雄激素的典型副性征作用"},{"q":"正常情况下，肺泡气PO2发生较大变化时，组织PO2只发生很小变化，这主要是因为","o":["体内氧储备多","组织血流量代偿性增加","Hb具有氧缓冲功能","组织耗氧量可随肺泡气PO2变化而变化","呼吸运动增强，摄氧增多"],"a":2,"e":"血红蛋白具氧缓冲功能：肺泡气PO2大幅变化时，氧解离曲线上段平坦使血氧饱和度变化小，组织PO2因而相对稳定。体内氧储备有限；组织血流量代偿有限；组织耗氧量并不随肺泡气PO2大幅波动；呼吸增强是低氧时的反应而非缓冲机制"},{"q":"让受试者先用力作深吸气，然后以最快的速度尽力呼出气体，分别测量第1、2、3秒末的呼出气量，计算其占肺活量的百分数，分别称为第1、2、3秒的","o":["通气储量百分比","最大随意通气量","肺泡通气量","深吸气量","时间肺活量"],"a":4,"e":"深吸气后以最快速度尽力呼气，第1、2、3秒末呼出气量占肺活量的百分比称为时间肺活量，又称用力呼气量，用于评价通气功能。通气储量百分比为最大随意通气量与静息通气量之差；肺泡通气量扣除无效腔；深吸气量为补吸气量与潮气量之和"},{"q":"视网膜中存在着感光的视杆细胞和视锥细胞，其中视觉最敏感的部位在","o":["视盘周边部","视网膜周边部","黄斑","中央凹","视神经乳头"],"a":3,"e":"中央凹仅含视锥细胞且与双极、节细胞呈一对一联系，是视觉最敏锐部位。黄斑整体敏锐但中央凹最精确；视盘周边部与视网膜周边部以视杆细胞为主、分辨力低；视神经乳头无感光细胞，为生理盲点"},{"q":"管球反馈是指","o":["肾小球滤过率增大，近端小管重吸收率增加","肾小球滤过率减少，近端小管重吸收率减少","肾小球滤过率增大或减少，近端小管的重吸收率始终占肾小球滤过率的65%～70%。","近端小管重吸收率减少，肾小球滤过率减少","近端小管重吸收率增加，肾小球滤过率增大"],"a":2,"e":"管球反馈表现为近端小管重吸收率始终占肾小球滤过率的65%～70%，滤过率增大或减小时重吸收率相应变化，使终尿量保持稳定。A、B、D、E项仅描述单方向变动或片面因果，未体现重吸收率与滤过率保持固定比例的核心特征"},{"q":"正常情况下看近物时，动眼神经兴奋使睫状肌收缩，从而悬韧带松弛，可使眼调节表现为","o":["晶状体曲度增大","晶状体曲度减小","瞳孔缩小","角膜曲度增大","角膜曲度减小"],"a":0,"e":"看近物时动眼神经兴奋使睫状肌收缩、悬韧带松弛，晶状体因自身弹性变凸、曲度增大，折光力增强使物像聚焦于视网膜。曲度减小为看远物时；瞳孔缩小属近反射但由瞳孔括约肌完成；角膜曲度不受睫状肌调节"},{"q":"关于大脑初级运动皮层的特征，错误的是","o":["对躯体运动的交叉性支配","功能代表区的大小与运动的精细程度有关","运动区定位的总体安排是倒置的","接受来自皮肤的浅感觉传入","接受来自关节肌腱等深部的感觉冲动"],"a":3,"e":"大脑初级运动皮层主要接受来自关节、肌腱等深部本体感觉传入，以指导运动，而非皮肤浅感觉。其对躯体运动交叉性支配；代表区大小与运动精细程度相关；定位总体呈倒置安排，均属正确特征"},{"q":"对于O2在血液中的结合运输的叙述，正确的是","o":["混合静脉血流经肺泡时，由于肺泡PO2高，Hb与O2迅速解离","动脉血流经组织时，由于组织细胞PO2低，HbO2迅速解离","动脉血流经肺泡时，由于肺泡PO2高，Hb与O2迅速结合","静脉血流经组织时，由于组织细胞PO2低，HbO2迅速解离","静脉血流经组织时，由于组织细胞PO2高，Hb与O2迅速结合"],"a":1,"e":"动脉血流经组织时，组织细胞PO2低，血红蛋白氧饱和度下降，HbO2迅速解离释放O2供组织利用。混合静脉血流经肺泡时因肺泡PO2高而与O2结合而非解离；动脉血并不流经肺泡；静脉血流经组织时PO2更低，解离主要发生在动脉血流经组织阶段"},{"q":"下列因素均可引起抗利尿激素的分泌，其中最为敏感的因素是","o":["循环血量减少","血浆晶体渗透压升高","动脉血压下降","寒冷刺激","精神紧张"],"a":1,"e":"血浆晶体渗透压升高是刺激抗利尿激素分泌最敏感的因素，仅升高1%～2%即可引起明显分泌，下丘脑渗透压感受器对此高度敏感。循环血量减少与动脉血压下降需较大幅度变化才生效；寒冷与精神紧张为次要影响因素"},{"q":"下列关于能量代谢影响因素的描述，错误的是","o":["肌肉运动是影响能量代谢最显著的因素","环境温度在30～35℃时，能量代谢最稳定","情绪激动、烦恼、愤怒、恐惧及焦虑等，能量代谢可显著增高","环境温度＜10℃时，能量代谢明显增加是由于寒战和肌肉张力增高所致","进食全蛋白质食物，可使机体额外增加30%的热量"],"a":1,"e":"能量代谢最稳定的环境温度在20～30℃的中性区，30～35℃已接近或超过体温调节的阈上范围，机体需加强散热、代谢不再最稳定，故该项错误。肌肉运动影响最显著；情绪激动提高代谢；低于10℃时寒战与肌张力增高使产热增加；全蛋白质食物特殊动力效应约增30%"},{"q":"胆碱能Ｎ型受体的阻断剂是","o":["筒箭毒","普萘洛尔","酚妥拉明","河豚毒素","阿托品"],"a":0,"e":"筒箭毒是胆碱能N型受体阻断剂，可阻断神经肌接头与自主神经节突触后膜的N受体。普萘洛尔阻断β肾上腺素能受体；酚妥拉明阻断α受体；河豚毒素阻断电压门控Na+通道；阿托品阻断M型胆碱能受体"},{"q":"下列血液检查正常参考值中不正确的是","o":["男性血细胞比容为40%～50%","出血时间为<9min","白细胞数目为（4、0～10、0）×109/L","正常成年人血小板数目为（100～300）×109/L","正常成年男性红细胞沉降率正常值0～20mm/h"],"a":4,"e":"正常成年男性红细胞沉降率为0～15mm/h，女性为0～20mm/h，故男性0～20mm/h的数值不正确。男性血细胞比容40%～50%；出血时间小于9分钟；白细胞（4.0～10.0）×10^9/L；血小板（100～300）×10^9/L，均属正常参考范围"},{"q":"下丘脑渗透压感受器最敏感的刺激是","o":["血压升高","血浆胶体渗透压升高","肾小球毛细血管血压升高","血浆晶体渗透压升高","循环血量增多"],"a":3,"e":"下丘脑渗透压感受器对血浆晶体渗透压升高最敏感，其变化直接刺激抗利尿激素分泌并引起渴觉。血压升高与肾小球毛细血管血压升高主要影响压力感受器；血浆胶体渗透压变化主要影响组织液生成；循环血量增多抑制ADH分泌"},{"q":"骨骼肌收缩过程中肌张力增加的原因是","o":["最适初长度不断变大","横桥结合数目增多","肌肉收缩速度增加","前负荷不断增加","接受的刺激强度增加"],"a":1,"e":"骨骼肌收缩时胞内Ca2+升高，使更多横桥与细肌丝结合并进入循环，同时工作的横桥数目增多，肌张力随之增加。最适初长度为定值；收缩速度与张力呈反变，速度增加不使张力升高；前负荷在收缩前已确定；刺激强度对单根肌纤维量效关系不适用"},{"q":"心室肌动作电位3期复极是由于膜对哪种离子通透性增高所致","o":["K+","Na+","Cl-","Ca2+","Mg2+"],"a":0,"e":"3期复极由快反应细胞延迟整流K+通道开放、K+顺浓度梯度外流所致，膜电位回到静息水平。Na+内流引发0期去极，Ca2+内流形成2期平台，均非3期复极机制；Cl-与Mg2+在该期无主导作用"},{"q":"在牛蛙脊髓反射的实验中，反射时间的长短主要取决于","o":["刺激强度的高低","刺激持续时间的长短","中枢突触的多少","神经纤维传导速度的快慢","传入与传出纤维的长度"],"a":2,"e":"反射时主要消耗在中枢突触传递的突触延搁，突触越多反射时间越长。神经纤维传导速度与传入传出纤维长度所占时间极短，刺激强度与波宽只决定是否达到阈值，均不决定反射时长"},{"q":"实验过程中心室肌对刺激不产生反应，在下列可能的原因中，哪一项是错误的","o":["刺激强度太弱","电刺激的波宽太窄","心肌处在不应期中","Na+通道处在备用状态","心肌细胞除极到-50mV"],"a":3,"e":"Na+通道处于备用状态正是细胞可被兴奋的前提，此时刺激应能引发反应，作为不反应的原因错误。刺激过弱或波宽太窄达不到阈强度，心肌处于不应期、除极到-50mV使通道失活，均可导致无反应"},{"q":"当血钾逐步升高时，心肌的兴奋性","o":["逐步升高","逐步降低","先降低后升高","先升高后降低","基本不变"],"a":3,"e":"轻度高血钾使静息电位上移、距阈电位变近，兴奋性升高；显著高血钾使Na+通道失活，兴奋性降低乃至消失，故呈先升高后降低。持续升高或持续降低都不符合这一双向变化"},{"q":"视杆细胞的视紫红质属于","o":["G蛋白偶联受体","酪氨酸激酶受体","鸟苷酸环化酶受体","化学门控通道","电压门控通道"],"a":0,"e":"视紫红质为G蛋白偶联受体，光照后激活转导蛋白再激活磷酸二酯酶。酪氨酸激酶受体与鸟苷酸环化酶受体属酶联受体，化学门控与电压门控通道属离子通道，均非视紫红质类型"},{"q":"损毁家兔下丘脑室上核，将出现下列哪种变化","o":["尿量不变，尿液浓度没有变化","尿量增加，尿液浓缩","尿量增加，尿液稀释","尿量减少，尿液浓缩","尿量减少，尿液稀释"],"a":2,"e":"下丘脑室上核合成抗利尿激素，损毁后ADH减少，远曲小管与集合管重吸收水减少，尿量增加、尿液稀释。尿液浓缩依赖ADH，凡尿浓缩的选项与ADH缺乏相反；尿量不变也违背失水增多的事实"},{"q":"属于中枢抑制性递质的是","o":["γ－氨基丁酸、甘氨酸","乙酰胆碱","谷氨酸、门冬氨酸","多巴胺、５－羟色胺","肾上腺素、去甲肾上腺素"],"a":0,"e":"γ-氨基丁酸与甘氨酸是中枢经典抑制性递质。谷氨酸、门冬氨酸为兴奋性递质；乙酰胆碱多为兴奋性；多巴胺与5-羟色胺属单胺类调质；肾上腺素与去甲肾上腺素为儿茶酚胺类"},{"q":"红细胞悬浮稳定性差会导致","o":["溶血","凝集","凝固","血沉加快","出血时延长"],"a":3,"e":"悬浮稳定性差源于红细胞易于叠连，使血沉加快。溶血是膜破裂后血红蛋白逸出，凝集是抗原抗体反应，凝固为凝血级联激活，出血时延长多因血小板或凝血因子异常，均非悬浮稳定性指标"},{"q":"下列因素中可影响肌肉收缩能力的是","o":["前负荷","后负荷","ATP酶活性","初长度","被动张力"],"a":2,"e":"收缩能力是肌肉内在功能，取决于胞质Ca2+水平与肌球蛋白ATP酶活性。前负荷即初长度、后负荷改变收缩张力与速度但不改变收缩能力本身；被动张力来自弹性成分，不属收缩能力"},{"q":"关于微循环直捷通路的叙述，正确的是","o":["血流速度较慢","经常处于开放状态","是血液和组织细胞之间进行物质交换的主要部位","在骨骼肌组织中较少见","可以调节体温"],"a":1,"e":"直捷通路经常处于开放状态，血流速度快，使血液快速回流。物质交换的主要部位是真毛细血管；调节体温靠动静脉短路；该通路在骨骼肌并不少见，血流慢的描述也与其特点相悖"},{"q":"下列关于大脑皮层对呼吸运动调节的叙述，错误的是","o":["对呼吸运动的随意控制必须依赖于大脑皮层","大脑皮层通过控制低位脑干呼吸神经元调节呼吸","在建立与呼吸有关的条件反射的过程中，大脑皮层起重要作用","在人类平时生活中，呼吸对环境的适应并不需要大脑皮层参与","言语与唱歌反映了大脑皮层对呼吸的控制作用"],"a":3,"e":"大脑皮层对呼吸有随意调节并参与条件反射建立，言语唱歌亦体现其控制，平时适应环境也可有皮层参与，故该项错误表述成立。皮层通过控制低位脑干呼吸神经元实现调节，随意控制必须依赖皮层"},{"q":"波尔效应是指","o":["PCO2升高使Hb与O2的亲和力下降，氧解离曲线右移","PCO2升高使Hb与O2的亲和力加强，氧解离曲线左移","O2与Hb的结合可促使CO2的结合","O2与Hb的结合可促使CO2的释放","O2与Hb的解离可促使CO2的释放"],"a":0,"e":"波尔效应指PCO2升高、H+增多使Hb与O2亲和力下降，氧解离曲线右移，利于组织释氧。将亲和力写成加强、曲线左移者方向相反；O2与CO2结合释放关系属霍尔登效应，非波尔效应"},{"q":"在周围神经系统中，属于肾上腺素能神经纤维的是","o":["躯体运动神经纤维","绝大部分交感神经的节后纤维","交感神经节前纤维","副交感神经节后纤维","副交感神经的节前纤维"],"a":1,"e":"周围神经中绝大部分交感神经节后纤维释放去甲肾上腺素，属肾上腺素能纤维。躯体运动纤维、交感和副交感节前纤维以及副交感节后纤维均释放乙酰胆碱，属胆碱能纤维"},{"q":"衡量心肌细胞自律性高低的最主要指标是","o":["阈电位水平","动作电位0期去极速率","最大舒张电位水平","动作电位4期自动去极速率","2期平台期持续的时间"],"a":3,"e":"4期自动去极速率是决定自律性高低的最主要指标，速率越快越早达阈电位、自律性越高。最大舒张电位与阈电位水平也能影响但不居首要；0期去极速率反映传导，平台期长短与自律性无关"},{"q":"机体处于急性大失血状态时，最早出现的代偿反应是","o":["迷走神经兴奋","交感神经兴奋","组织液回流增加","血管紧张素系统作用加强","血浆蛋白和红细胞的恢复"],"a":1,"e":"急性大失血最早出现交感神经兴奋，通过增心率、收缩血管快速维持血压。组织液回流增加与肾素-血管紧张素系统激活稍后发生，血浆蛋白和红细胞恢复最慢，属后期代偿"},{"q":"关于雄激素的作用的叙述，下列哪一项是错误的","o":["刺激雄性附性器官发育并维持成熟状态","刺激红细胞生成","促进肌肉与骨骼生长","分泌过盛可使男子身高超出常人","维持正常的性欲"],"a":3,"e":"雄激素促进蛋白质合成与骨骼生长但加速骨骺闭合，分泌过盛导致早熟与最终身高偏矮，不会使身高超出常人。刺激附性器官发育、促红细胞生成、促肌骨生长、维持性欲均为其真实作用"},{"q":"骨骼肌细胞膜中横管的主要作用是","o":["储存Ca2+","释放乙酰胆碱","传导动作电位","降解乙酰胆碱","产生终板电位"],"a":2,"e":"横管将肌膜动作电位传导至细胞深部肌原纤维，触发兴奋收缩耦联。储存Ca2+的是肌质网终池，乙酰胆碱由接头前膜释放，终板电位产生于终板膜，乙酰胆碱降解靠胆碱酯酶"},{"q":"关于胃酸的生理作用，下列哪项是错误的","o":["能激活胃蛋白酶原，供给胃蛋白酶所需的酸性环境","可使食物中的蛋白质变性易于分解","可杀死随食物进入胃内的细菌","可促进维生素B12的吸收","盐酸进入小肠后，可促进胆汁、胰液、小肠液的分泌"],"a":3,"e":"维生素B12吸收依赖壁细胞分泌的内因子，与盐酸无关，故该项错误。盐酸能激活胃蛋白酶原并提供酸性环境、使蛋白质变性、杀菌，进入小肠后促胆汁胰液小肠液分泌均为其真实作用"},{"q":"血浆与组织液各种成分浓度的主要区别是","o":["Na+","K+","蛋白质","有机酸","尿素"],"a":2,"e":"血浆与组织液的主要成分区别是蛋白质，血浆蛋白多而组织液含量极少。Na+、K+、有机酸、尿素等小分子可自由通过毛细血管壁，两侧浓度接近，不构成主要差别"},{"q":"在近端小管，全部被重吸收的物质是","o":["Na+","肌酐","尿素","葡萄糖","氨"],"a":3,"e":"葡萄糖在近端小管被全部重吸收，正常尿中无糖。Na+只部分重吸收，肌酐基本不重吸收，尿素部分重吸收，氨主要由小管分泌排出，均非全部重吸收物质"},{"q":"关于钠泵生理作用的表述，错误的是","o":["每个活动周期能将3个Na+离子移出膜外","每个活动周期能将2个K+离子移出膜外","从膜内移出Na+，可防止水分子进入细胞内","钠泵的活动造成细胞内高K+，使许多代谢得以进行","钠泵的活动可造成膜两侧的离子势能储备"],"a":1,"e":"钠泵每周期泵出3个Na+、泵入2个K+，故将两个K+移出膜外错误，K+实为移入胞内。移出Na+可防止水进入细胞，胞内高K+利于代谢进行，活动建立膜两侧离子势能储备均为正确表述"},{"q":"能反映右心室功能的指标是","o":["心输出量","动脉压","中心静脉压","脉压","平均动脉压"],"a":2,"e":"中心静脉压反映右心房及胸腔大静脉压，与右心室前负荷和功能密切相关。心输出量、动脉压、脉压与平均动脉压更多反映左心泵血与整体循环状态，不特异反映右室功能"},{"q":"有机磷中毒的主要原因是","o":["乙酰胆碱水解加速","乙酰胆碱受体功能障碍","乙酰胆碱释放量增加","乙酰胆碱与其受体亲和力增高","胆碱酯酶活性降低"],"a":4,"e":"有机磷抑制胆碱酯酶活性，使乙酰胆碱不能被水解而在突触间隙大量蓄积，引发毒蕈碱样与烟碱样症状。并非水解加速、释放增加、受体亲和力增高或受体本身功能障碍"},{"q":"激活胰蛋白酶原的物质主要是","o":["盐酸","碳酸氢盐","胰脂肪酶","糜蛋白酶","肠激酶"],"a":4,"e":"肠激酶（肠肽酶）是激活胰蛋白酶原的主要物质，生成胰蛋白酶后再激活其他胰酶原。盐酸激活的是胃蛋白酶原，糜蛋白酶原由胰蛋白酶激活，碳酸氢盐中和胃酸，胰脂肪酶消化脂肪"},{"q":"睾酮属于下列哪一类激素","o":["类固醇激素","含氮类激素","肽类激素","蛋白质类激素","胺类激素"],"a":0,"e":"睾酮由睾丸间质细胞分泌，化学本质为类固醇（甾体）激素。含氮类、肽类、蛋白质类、胺类激素均为水溶性激素类别，与睾酮的脂溶性甾体结构不同"},{"q":"下列有关H+与NH3的分泌，正确的是","o":["H+与NH3的分泌存在相互竞争","H+与NH3的分泌存在相互促进","H+与NH3的分泌无关系","泌NH3有利于排碱保酸","泌H+抑制HCO3-的重吸收"],"a":1,"e":"H+与NH3分泌相互促进，NH3扩散入管腔与H+结合成NH4+排出，实现排酸保碱。称相互竞争或无关系者均错；泌NH3实为排酸保碱而非排碱保酸，泌H+促进而非抑制HCO3-重吸收"},{"q":"关于睾丸的功能的叙述，下列哪一项是错误的","o":["睾丸的生精功能与内分泌功能互不影响","精原细胞产生精子","具有产生精子与雄激素的双重功能","间质细胞产生睾酮","支持细胞对精子起营养作用"],"a":0,"e":"睾丸的生精功能与内分泌功能相互联系，睾酮等激素促进生精，故互不影响的说法错误。精原细胞经分裂产生精子、间质细胞分泌睾酮、支持细胞对精子起营养作用均正确"},{"q":"在等容收缩期，压力梯度正确的是","o":["房内压>室内压>主动脉压","房内压<室内压>主动脉压","房内压=室内压>主动脉压","房内压<室内压<主动脉压","房内压>室内压<主动脉压"],"a":3,"e":"等容收缩期房室瓣与半月瓣均关闭，室内压急剧上升但尚未超过主动脉压，故房内压<室内压<主动脉压。房内压>室内压属心室舒张充盈期；室内压>主动脉压则为射血期"},{"q":"关于心电图波形与心肌动作电位关系的描述，正确的是","o":["P波反映心房肌动作电位的全过程","QRS波群反映心室肌动作电位的全过程","T段反映静息期膜内外离子分布恢复的过程","心电图一个周期等于心房、心室肌细胞动作电位时程之和","心电图反映无数心肌细胞动作电位效应的总和"],"a":4,"e":"心电图是无数心肌细胞动作电位效应的综合反映。P波仅反映心房去极化而非心房动作电位全过程，QRS只反映心室去极化，T波反映复极，一个心动周期不等于心房心室动作电位时程之和"},{"q":"下列可作为心室收缩期开始标志的心音是","o":["第一心音","第二心音","第三心音","第四心音","主动脉瓣关闭音"],"a":0,"e":"第一心音由房室瓣关闭产生，标志心室收缩期开始。第二心音含主动脉瓣关闭音，标志舒张期开始；第三、第四心音与心室快速充盈和心房收缩有关，均非收缩期起点"},{"q":"易化扩散不同于单纯扩散的是","o":["需要ATP供能","借助于膜蛋白的帮助","顺浓度差转运","逆浓度差转运","转运对象是蛋白质"],"a":1,"e":"易化扩散需膜蛋白帮助，这是区别于单纯扩散之处。两者均顺浓度差、不消耗ATP；逆浓度差为主动转运；转运对象为离子或葡萄糖等小分子，而非蛋白质本身"},{"q":"内分泌细胞分泌激素到组织液的过程属于","o":["载体介导易化扩散","原发性主动转运","继发性主动转运","出胞","通道介导易化扩散"],"a":3,"e":"内分泌细胞释放激素时，分泌囊泡与细胞膜融合并将内容物排出，属出胞。载体与通道介导的易化扩散、原发性和继发性主动转运都是跨膜转运小分子的方式，不用于大分子激素释放"},{"q":"进入肺泡内的气体，可因血液在肺内分布不均而未全部与血液进行气体交换。没有发生气体交换的这部分肺泡容量，称为","o":["解剖无效腔","生理无效腔","肺泡无效腔","气道无效腔","无效腔"],"a":2,"e":"肺泡无效腔指进入肺泡但因肺内血流分布不均未与血液交换气体的肺泡容量。解剖无效腔又称气道无效腔，指呼吸道内不参与交换的气体空间；生理无效腔为解剖无效腔与肺泡无效腔之和"},{"q":"神经冲动传递至接头前膜后引起递质释放是因为","o":["Na+通道关闭","Ca2+通道开放","K+通道开发","Cl-通道开放","水通道开放"],"a":1,"e":"动作电位到达接头前膜使电压门控Ca2+通道开放，Ca2+内流触发突触囊泡胞吐释放递质。Na+、K+、Cl-及水通道开放参与膜电位变化或维持，但均非触发递质释放的直接机制"},{"q":"细胞膜在静息情况下，对下列哪种离子通透性最大","o":["K+","Na+","Cl-","Ca2+","Mg2+"],"a":0,"e":"静息状态下膜对K+通透性最大，K+外流形成接近K+平衡电位的静息电位。Na+与Ca2+通透性很小，Cl-、Mg2+在静息膜电位形成中不起主导作用"},{"q":"关于微循环直捷通路的叙述，错误的是","o":["回流速度快","经常处于开放状态","是血液和组织液进行物质交换的部位","管经比真毛细血管稍粗","骨骼肌组织中较常见"],"a":2,"e":"物质交换主要在真毛细血管进行，直捷通路管壁较厚、血流快，交换功能弱，故该项错误。回流速度快、经常开放、管径略粗于真毛细血管、在骨骼肌较常见均为直捷通路特点"},{"q":"腱器官是一种","o":["张力感受器","长度感受器","压力感受器","温度感受器","化学感受器"],"a":0,"e":"腱器官位于肌腱，感受肌肉张力变化，属张力感受器，参与反牵张反射。长度感受器为肌梭；压力、温度、化学感受器各有其适宜刺激与结构，与腱器官不同"},{"q":"下列生理过程与Ca2+内流无关的是","o":["快反应细胞动作电位的2期复极化","慢反应细胞动作电位的0期去极化","慢反应细胞动作电位的4期自动去极化","快反应细胞动作电位的1期复极化","快反应细胞动作电位的平台期"],"a":3,"e":"快反应细胞1期复极由瞬时外向K+流引起，与Ca2+内流无关。快反应细胞2期与平台期靠Ca2+内流维持，慢反应细胞0期去极由Ca2+内流产生，慢反应4期自动去极也含Ca2+内流成分"},{"q":"关于睾丸功能调节的叙述，下列哪一项是错误的","o":["促卵泡激素对生精过程有刺激作用","黄体生成素刺激间质细胞分泌睾酮","促卵泡激素对生精有始动作用","睾酮与雄激素结合球蛋白结合，促进精母细胞减数分裂","睾酮对腺垂体促卵泡激素的分泌起负反馈抑制作用"],"a":4,"e":"抑制腺垂体FSH分泌的主要是抑制素，睾酮主要负反馈LH，故该项错误。FSH对生精有始动与刺激作用，LH促间质细胞分泌睾酮，睾酮与雄激素结合球蛋白结合促精母细胞减数分裂"},{"q":"下列关于Hb与O2结合的叙述正确的是","o":["1分子Hb可以结合1分子O2","Hb与O2在氧化酶的作用下结合生成HbO2","Hb的4个亚单位间有协同效应","Hb与O2的结合曲线呈线性，而解离曲线呈S形","O2与Hb结合时将其分子中的Fe2+氧化成了Fe3+"],"a":2,"e":"血红蛋白四个亚单位间存在协同效应，使氧解离曲线呈S形。1分子Hb可结合4分子O2；结合为氧合而非氧化，Fe2+不变价；结合与解离曲线实为同一条曲线，并非一线性一S形"},{"q":"中心静脉压的最佳测定部位是","o":["左心房","右心房","肘静脉","右心室","左心室"],"a":1,"e":"中心静脉压最佳测定部位为右心房或上、下腔静脉近右房处，可反映右心前负荷。左心房、左心室、右心室腔内置管不便且非标准，肘静脉压受外周因素影响大"},{"q":"下述哪种情况会导致肾小球滤过率减少","o":["血浆胶体渗透压降低","血浆胶体渗透压增高","血浆晶体渗透压升高","血浆晶体渗透压降低","血浆蛋白质含量降低"],"a":1,"e":"血浆胶体渗透压增高使有效滤过压下降，肾小球滤过率减少。胶体渗透压降低或血浆蛋白减少则有效滤过压升高、滤过增加；血浆晶体渗透压对滤过影响很小"},{"q":"卡巴胆碱（胆碱能受体激动剂）作用于窦房结细胞产生超极化，其机制是","o":["是由于Na+-K+泵活动增强引起的","是由于Na+内流引起的","是由于K+外流引起的","是由于Ca2+外流引起的","是由于Cl-外流引起的"],"a":2,"e":"卡巴胆碱激动窦房结M受体，提高K+通透性，K+外流增加使膜超极化、自动去极减慢而心率减慢。并非Na+-K+泵活动增强，也不是Na+、Ca2+或Cl-内流所致"},{"q":"神经调节的特点是","o":["作用迅速、精确、短暂","作用缓慢、广泛、持久","非自动控制","有生物节律","局部、稳定"],"a":0,"e":"神经调节通过反射弧实现，作用迅速、精确、短暂。作用缓慢广泛持久是体液调节特点；非自动控制、有生物节律、局部稳定均不足以概括神经调节的基本特征"},{"q":"神经肌肉接头前膜释放的Ach与终板膜上的受体结合，可使终板膜","o":["对Na+、K+通透性增加，发生超极化","仅对Ca2+通透性增加，发生去极化","仅对K+通透性增加，发生超极化","对Na+、K+通透性增加，发生去极化","对ACh通透性增加，发生去极化"],"a":3,"e":"乙酰胆碱与终板膜N2受体结合，开放化学门控通道，对Na+、K+通透性增加且Na+内流为主，膜发生去极化形成终板电位。超极化、仅Ca2+或仅K+通透、ACh自身通透均不正确"},{"q":"非条件反射的特点有","o":["先天遗传获得","有固定的反射弧","中枢在皮质下结构","数量十分有限","以上都是正确的"],"a":4,"e":"非条件反射先天遗传获得，具有固定反射弧，中枢多位于皮层下结构，且数量十分有限，故以上各项均正确。条件反射则为后天建立、反射弧不固定、可消退"},{"q":"神经中枢内，通常兴奋通过一个突触所需要的时间为","o":["2、0～3、0ms","1、0～2、0ms","0、5～1、0ms","0、3～0、5ms","0、1～0、2ms"],"a":3,"e":"兴奋通过一个突触需经历递质释放、扩散、结合等步骤，耗时约0.3～0.5ms，称突触延搁。0.1～0.2ms明显偏短，1ms以上和2～3ms则过长，均不符单突触传递时间"},{"q":"下列关于睾丸功能调节的描述，哪一项是错误的","o":["受下丘脑-腺垂体-睾丸轴调节","促性腺激素释放激素是以脉冲形式分泌的","促卵泡激素和黄体生成素对生精过程均有调节作用","雄激素、抑制素可反馈调节下丘脑、腺垂体有关激素分泌","睾酮可启动生精过程、促卵泡激素维持生精过程"],"a":4,"e":"生精过程由FSH始动并维持，睾酮协同维持，故睾酮启动、FSH维持的说法颠倒错误。下丘脑-腺垂体-睾丸轴调控、GnRH脉冲式分泌、FSH与LH共同调节、雄激素和抑制素反馈均正确"},{"q":"下列哪一项是醛固酮的主要作用","o":["增加肾近曲小管保钠排钾","增加肾近曲小管排钠排钾","增加肾髓袢排钠排钾","增加肾近曲小管和集合管排钠排钾","增加肾远曲小管和集合管保钠排钾"],"a":4,"e":"醛固酮主要作用于远曲小管和集合管，促进Na+重吸收与K+分泌，即保钠排钾并保水。近曲小管与髓袢不是其主要靶点，排钠排钾的方向与醛固酮作用相反"},{"q":"在一个心动周期中，主动脉血压达到的最低值称为","o":["收缩压","舒张压","脉压","平均动脉压","循环系统平均充盈压"],"a":1,"e":"心动周期中主动脉压最低值称舒张压，出现于下一次收缩之前。收缩压为最高值，脉压是收缩压与舒张压之差，平均动脉压为全程平均值，循环系统平均充盈压为另一概念"},{"q":"不存在于血浆中的凝血因子是","o":["因子Ⅲ","因子Ⅴ","因子Ⅶ","因子Ⅸ","因子Ⅻ"],"a":0,"e":"因子Ⅲ即组织因子，存在于血管外组织细胞表面，不存在于正常血浆。因子Ⅴ、Ⅶ、Ⅸ、Ⅻ均为血浆中参与凝血的因子，可经血液检测"},{"q":"血液的组成是","o":["血浆和红细胞","血浆和白细胞","血浆和血小板","血浆和血细胞","血浆、红细胞和白细胞"],"a":3,"e":"血液由血浆和血细胞组成，血细胞包括红细胞、白细胞和血小板。仅血浆加某一类细胞都不完整，漏列血小板或白细胞的选项均不全面"},{"q":"关于雌激素的生理作用的描述，下列哪一项是错误的","o":["使输卵管平滑肌活动增强","卵泡期子宫内膜增生变厚，腺体分泌","促进肾小管对钠、水的重吸收","与促卵泡激素配合促进卵泡增生","促进蛋白质合成，有利于生长发育"],"a":1,"e":"使子宫内膜腺体分泌是孕激素在黄体期的作用，雌激素仅使内膜增生变厚，故该项错误。增强输卵管平滑肌活动、促肾小管保钠保水、协同FSH促卵泡发育、促蛋白合成均属雌激素作用"},{"q":"肾小球滤过的直接动力是","o":["肾小球有效滤过压","肾小囊内压","血浆胶体渗透压","集合管内压","组织液的静水压"],"a":0,"e":"肾小球滤过的直接动力是有效滤过压，即肾小球毛细血管血压减去血浆胶体渗透压与囊内压。囊内压和血浆胶体渗透压只是构成成分，集合管内压、组织液静水压不属于滤过动力"},{"q":"将肌细胞膜上动作电位传导至肌细胞内部肌原纤维的结构是","o":["连接肌质网","横管","纵行肌质网","终池","横桥"],"a":1,"e":"横管是肌膜向细胞内部的深陷，将表面动作电位迅速传至肌原纤维附近。连接肌质网与终池主司储钙，纵行肌质网主司摄钙，横桥为肌球蛋白与肌动蛋白结合的结构"},{"q":"下列关于电突触的叙述，错误的是","o":["结构基础为缝隙链接","单向传递","电阻低","没有潜伏期","传递速度快"],"a":1,"e":"电突触以缝隙连接为结构基础，可双向传递，故单向传递错误。其电阻低、无突触延搁、传递速度快，这些特点均与化学突触的单向性和突触延搁形成对比"},{"q":"在一个心动周期中，冠脉血流量急剧减少的时期是","o":["等容收缩期","快速射血期","减慢射血期","舒张期","心房收缩期"],"a":0,"e":"等容收缩期心肌强烈收缩压迫穿行其间的冠状动脉，冠脉血流急剧减少甚至短暂逆流。舒张期心肌放松、冠脉阻力下降，血流量反而最多；射血期与心房收缩期压迫较轻"},{"q":"消化道平滑肌细胞动作电位产生的离子基础是下列哪一项","o":["K+内流","Na+内流","Ca2+内流","Ca2+与K+内流","Na+与K+内流"],"a":2,"e":"消化道平滑肌动作电位的去极化主要由Ca2+内流引起。Na+内流仅参与部分慢波成分，K+外流引起复极而非去极，不存在Ca2+与K+同时内流或Na+与K+同时内流的组合"},{"q":"分布于横管膜上，与兴奋收缩耦联最为相关的离子通道是","o":["T型钙通道","R型钙通道","L型钙通道","受体门控钙通道","机械门控式钙通道"],"a":2,"e":"横管膜上的L型钙通道是兴奋收缩耦联的关键，感受膜去极化并触发肌质网释放Ca2+。T型、R型钙通道不位于此关键位点，受体门控与机械门控钙通道也非横管耦联的主要通道"},{"q":"视前区-下丘脑前部是","o":["控制产热活动的中枢部位","控制散热活动的中枢部位","体温调节中枢整合部位","只存在热敏神经元而不存在冷敏神经元","冷敏神经元较多"],"a":2,"e":"视前区-下丘脑前部是体温调节中枢的整合部位，同时存在热敏与冷敏神经元，整合中枢与外周温度信息。产热与散热中枢只是其下部功能区，不能代表整体；冷敏神经元也非绝对占优"},{"q":"有关发绀的叙述，正确的是","o":["出现发绀一定标志着组织缺氧","CO中毒时出现发绀","严重贫血可出现发绀","高原性红细胞增多症可出现发绀","缺氧一定会出现发绀"],"a":3,"e":"高原性红细胞增多症时脱氧血红蛋白绝对量增多，可出现发绀。发绀不一定标志组织缺氧，缺氧也不一定出现发绀，严重贫血与CO中毒者因Hb量或氧饱和度特点常不显发绀"},{"q":"血液中生物活性最强的甲状腺激素是","o":["一碘甲腺原氨酸","二碘甲腺原氨酸","三碘甲腺原氨酸","四碘甲腺原氨酸","逆-三碘甲腺原氨酸"],"a":2,"e":"三碘甲腺原氨酸即T3，与甲状腺激素受体亲和力最高、生物活性最强。四碘甲腺原氨酸T4分泌量最大但需转化为T3才显活性；一碘、二碘甲腺原氨酸及逆T3活性很弱或甚微"},{"q":"交叉配血试验的主侧是指","o":["供血者的红细胞与受血者的红细胞进行配血","供血者的红细胞与受血者的血浆进行配血","供血者的血浆与受血者的红细胞进行配血","供血者的血浆与受血者的血浆进行配血","以上均不是"],"a":1,"e":"交叉配血主侧为供血者红细胞与受血者血浆相配，检查受血者血清抗体是否凝集供血者红细胞。次侧为供血者血浆与受血者红细胞相配，红细胞与红细胞、血浆与血浆相配均无意义"},{"q":"可用来反映心脏射血前负荷的指标是","o":["心室收缩末期容积","心室舒张末期容积","心室等容舒张期容积","等容收缩期心室内压","快速射血期心室内压"],"a":1,"e":"心室舒张末期容积相当于心肌初长度，是反映心脏射血前负荷的指标。收缩末期容积与后负荷及射血程度有关，等容舒张期容积、等容收缩期与快速射血期心室内压均非前负荷"},{"q":"正常情况下，维持呼吸中枢兴奋的有效刺激是","o":["一定程度的缺氧","高浓度的CO2","一定浓度的CO2","肺牵张感受器的传入冲动","一定浓度的H+"],"a":2,"e":"一定浓度的CO2是维持正常呼吸中枢兴奋的生理性刺激，主要经中枢化学感受器兴奋呼吸。缺氧对中枢直接抑制、仅靠外周感受器起作用；高浓度CO2反而抑制中枢，肺牵张传入只调节深度"},{"q":"动脉血压突然升高时，将引起","o":["左室射血速度增快","心输出量增加","左室收缩末期容积增加","左室射血时达到最高室压的时间缩短","左室射血时的最高室内压下降"],"a":2,"e":"动脉血压突然升高使后负荷增大，等容收缩期延长、射血速度减慢，每搏输出量减少，致左室收缩末期容积增加。射血速度不会增快，心输出量不增加，最高室内压不会下降反而升高"},{"q":"下列物质中，收缩血管作用最强的是","o":["肾上腺素","肾素","血管紧张素Ⅱ","内皮素","去甲肾上腺素"],"a":3,"e":"内皮素是已知收缩血管作用最强的物质，由血管内皮细胞分泌。血管紧张素Ⅱ与去甲肾上腺素缩血管作用次之，肾上腺素作用随受体类型而异，肾素本身不直接缩血管而是生成血管紧张素"},{"q":"神经肌肉接头处前膜释放的递质是","o":["肾上腺素","多巴胺","乙酰胆碱","5-羟色胺","去甲肾上腺素"],"a":2,"e":"神经肌肉接头前膜释放的递质是乙酰胆碱，与终板膜N2受体结合产生终板电位。肾上腺素与去甲肾上腺素为交感神经递质，多巴胺与5-羟色胺主要见于中枢神经系统"},{"q":"心室肌细胞0期去极化时，钠通道在膜去极化到一定程度时，便迅速失活而关闭，钠通道完全关闭是在","o":["膜电位在-50mV水平时","膜电位在-30mV水平时","膜电位在0mV水平时","膜电位极化倒转达最大值时","膜电位复极化到平台水平时"],"a":3,"e":"心室肌0期去极时，钠通道在膜电位去极达极化倒转峰值时完全失活关闭。-50mV为阈电位附近开始去极，-30mV与0mV时尚未完全关闭，平台期已由钙内流主导"},{"q":"与IP3和DG生成有直接关系的G蛋白效应器是","o":["腺苷酸环化酶","鸟苷酸环化酶","蛋白激酶A","蛋白激酶C","磷脂酶C"],"a":4,"e":"IP3与DG由磷脂酶C水解膜磷脂PIP2生成，磷脂酶C是Gq蛋白的效应器。腺苷酸环化酶生成cAMP，鸟苷酸环化酶生成cGMP，蛋白激酶A与C为下游靶酶而非生成IP3的效应器"},{"q":"心肌细胞超常期内兴奋性高于正常，此期","o":["兴奋传导速度高于正常","动作电位幅度大于正常","0期除极速率高于正常","刺激阈值低于正常","自动节律性高于正常"],"a":3,"e":"超常期兴奋性高于正常，表现为刺激阈值低于正常，阈下刺激即可引发兴奋。此期Na+通道尚未完全恢复，动作电位幅度与0期去极速率仍低于正常，传导速度与自律性也不因此增高"},{"q":"心室肌细胞不具有的生理特性是","o":["兴奋性","自律性","传导性","收缩性","自律性和收缩性"],"a":1,"e":"心室肌工作细胞不具备自律性，其4期膜电位稳定。兴奋性、传导性、收缩性均为心室肌所具有；自律性仅见于窦房结、房室结、浦肯野等特殊传导系统细胞"},{"q":"生成组织液的有效滤过压等于","o":["（组织液胶体渗透压＋组织液静水压）－（毛细血管血压＋血浆胶体渗透压）","（血浆胶体渗透压＋组织液静水压）－（毛细血管血压＋组织液胶体渗透压）","（毛细血管血压＋血浆胶体渗透压）－（组织液胶体渗透压＋组织液静水压）","（毛细血管血压＋组织液静水压）－（血浆胶体渗透压＋组织液胶体渗透压）","（毛细血管血压＋组织液胶体渗透压）－（血浆胶体渗透压＋组织液静水压）"],"a":4,"e":"生成组织液的有效滤过压为（毛细血管血压+组织液胶体渗透压）减去（血浆胶体渗透压+组织液静水压）。前两项促使滤过，后两项促使重吸收；把血浆胶体渗透压列入促滤过侧或把组织液静水压列入血管内均错误"},{"q":"可抑制血小板聚集的物质是","o":["ADP","TXA2","PGI2","胶原","凝血酶"],"a":2,"e":"前列环素PGI2由血管内皮生成，升高血小板内cAMP，抑制血小板聚集。ADP、血栓素A2、胶原与凝血酶均为促进血小板黏附聚集的重要物质，作用方向相反"},{"q":"缺氧对呼吸中枢的直接作用是","o":["抑制","兴奋","抑制大于兴奋","抑制与兴奋相等","兴奋大于抑制"],"a":0,"e":"缺氧对呼吸中枢的直接作用是抑制，可降低中枢神经元兴奋性。整体呼吸加强来自外周化学感受器的兴奋效应，这是外周兴奋抵消中枢抑制的结果，而非中枢本身兴奋"},{"q":"近髓肾单位的主要功能是","o":["分泌醛固酮","释放抗利尿激素","释放肾素","生成尿液","浓缩和稀释尿液"],"a":4,"e":"近髓肾单位髓袢长、直小血管发达，主要功能是建立髓质渗透梯度以浓缩和稀释尿液。醛固酮由肾上腺皮质分泌，抗利尿激素由下丘脑合成，肾素由球旁细胞释放，生成尿液为所有肾单位共有"},{"q":"献血者为A型血，经交叉配血试验，主侧不凝集而次侧凝集，受血者的血型为","o":["A型","B型","AB型","O型","B型或AB型"],"a":2,"e":"供者为A型，主侧不凝集说明受者血浆无抗A抗体；次侧凝集说明供者血浆中抗B抗体与受者红细胞B抗原反应，受者兼具A、B抗原，故为AB型。O型血浆含抗A抗体会使主侧凝集"},{"q":"食物特殊动力效应最强的食物是","o":["蛋白质","糖类","脂肪","矿物质","无机盐"],"a":0,"e":"蛋白质的食物特殊动力效应最强，额外产热约相当于其热价的30%。糖类约5%～6%，脂肪约4%，矿物质与无机盐基本无特殊动力效应"},{"q":"硫氧嘧啶类药物可治疗甲状腺功能亢进，其机制是","o":["抑制T3、T4的释放","抑制碘的摄取","抑制过氧化物酶的活性，使T3、T4合成减少","使T3、T4的破坏增多","阻止T3、T4进入细胞"],"a":2,"e":"硫氧嘧啶类药物抑制甲状腺过氧化物酶，阻断碘的活化、酪氨酸碘化与偶联，使T3、T4合成减少。该类药物不抑制已合成激素的释放，不阻碍碘摄取，也不加速激素破坏或阻止其进入细胞"},{"q":"关于传导散热的叙述，不正确的是","o":["以直接传导的方式散热","皮肤的热量传给衣服","与皮肤温度有关","脂肪的热导率很高","与接触物的热导率有关"],"a":3,"e":"脂肪是热的不良导体，热导率低，皮下脂肪厚不利于传导散热，故该项错误。传导散热通过直接接触进行，皮肤温度与接触物热导率均影响散热量"},{"q":"心室肌细胞具有兴奋性的前提是Na+通道处于下列哪种状态","o":["启动","备用","激活","失活","开放"],"a":1,"e":"心室肌细胞具有兴奋性的前提是Na+通道处于备用状态，给予阈刺激即可开放产生动作电位。启动与开放指激活状态，失活状态不能被再次激活，须复极至备用状态后恢复兴奋性"},{"q":"关于钠泵生理作用的描述，错误的是","o":["钠泵能逆着浓度差将进入细胞内的Na+移出胞外","钠泵能顺着浓度差使细胞外的K+移入胞内","由于从膜内移出Na+，可防止水分子进入细胞内","钠泵的活动造成细胞内高钾，是许多反应得以进行","钠泵的活动可造成膜两侧的离子势能储备"],"a":1,"e":"钠泵逆浓度差将细胞外K+移入胞内，故顺浓度差移入K+错误。逆浓度差泵出Na+、防止水分子进入细胞、胞内高K+利于代谢、建立膜两侧离子势能储备均属其正确作用"},{"q":"当脊髓前角γ-运动神经元的传出冲动增加时，可引起","o":["肌梭传入冲动增加","梭外肌收缩减弱","梭内肌收缩减弱","α-运动神经元的传出冲动减少","α-运动神经元的传出冲动不变"],"a":0,"e":"γ-运动神经元传出冲动增加使梭内肌收缩，提高肌梭敏感性，肌梭传入冲动随之增加。梭外肌由α-运动神经元支配，γ兴奋并不使梭内肌收缩减弱，反而易化α-运动神经元"},{"q":"交感神经兴奋可引起","o":["瞳孔缩小","逼尿肌收缩","肠蠕动增强","心率加快","支气管平滑肌收缩"],"a":3,"e":"交感神经兴奋使心率加快，产生正性变时作用。其效应还有瞳孔散大、逼尿肌舒张、肠蠕动减弱与支气管平滑肌舒张，故缩小、收缩、增强类选项均与交感兴奋相反"},{"q":"关于通气/血流比值的描述，错误的是","o":["安静时正常值是0、84，即V/Q=0、84","通气/血流比值减少，反映功能性动静脉短路","通气/血流比值增大，反映肺泡无效腔增大","肺尖部的通气/血流比值增大","肺动脉栓塞时，比值减小"],"a":4,"e":"肺动脉栓塞使肺血流量减少，通气相对过剩，通气/血流比值增大而非减小，故该项错误。安静正常值约0.84；比值减小反映功能性动静脉短路，增大反映肺泡无效腔增大，肺尖部比值偏高"},{"q":"心动周期中，占时间最长的是","o":["心房收缩期","等容收缩期","快速射血期","等容舒张期","心室充盈期"],"a":4,"e":"心动周期中心室充盈期历时最长，约0.5秒，保证血液充分回流。等容收缩期与等容舒张期各约0.06～0.08秒，快速射血期约0.1秒，心房收缩期也仅约0.1秒"},{"q":"下列属于条件反射的是","o":["吸吮反射","眨眼反射","屈肌反射","窦弓反射","看到食物引起唾液分泌增加"],"a":4,"e":"看到食物引起唾液分泌是后天建立的条件反射，需大脑皮层参与。吸吮反射、眨眼反射、屈肌反射与窦弓压力感受性反射均为先天遗传的非条件反射"},{"q":"纤溶酶的主要作用是水解","o":["凝血因子Ⅴ","凝血因子Ⅱa","凝血因子Ⅻ","凝血因子Ⅰ、Ⅰa","凝血因子Ⅳ"],"a":3,"e":"纤溶酶主要水解纤维蛋白及纤维蛋白原，即凝血因子Ⅰ和Ⅰa，使血栓溶解。因子Ⅴ、Ⅱa即凝血酶、Ⅻ与Ⅳ即钙离子均非纤溶酶的主要作用底物"},{"q":"下列哪种跨膜物质转运的方式无饱和现象","o":["单纯扩散","载体介导的易化扩散","质子泵","Na+-H+交换","受体介导的入胞"],"a":0,"e":"单纯扩散是脂溶性物质顺浓度差直接跨膜，不需载体或通道，故无饱和现象。载体介导易化扩散、质子泵、Na+-H+交换与受体介导入胞均依赖有限数量的蛋白或受体，具有饱和性"},{"q":"心肌组织中，兴奋传导速度最快的是","o":["浦肯野纤维","结间束","心房肌","心室肌","希氏束"],"a":0,"e":"浦肯野纤维兴奋传导速度最快，约4米每秒，利于兴奋迅速扩布至整个心室。结间束与希氏束次之，心室肌约1米每秒，心房肌约0.4米每秒，均慢于浦肯野纤维"},{"q":"血浆蛋白减少可引起组织水肿，其主要原因是","o":["淋巴液回流减少","毛细血管通透性增加","毛细血管血压升高","血浆胶体渗透压降低","毛细血管血压降低"],"a":3,"e":"血浆蛋白减少使血浆胶体渗透压降低，毛细血管内液体重吸收减少、组织液生成增多，导致水肿。淋巴回流减少、毛细血管通透性增加与血压升高虽可致水肿，但并非血浆蛋白减少的直接机制"},{"q":"切除肾上腺会导致动物死亡，其原因是由于缺乏下列哪种激素","o":["脱氢异雄酮","肾上腺素","雌二醇","糖皮质激素","醛固酮"],"a":3,"e":"切除肾上腺致死的关键是缺乏糖皮质激素，机体失去应激能力与对儿茶酚胺的允许作用，血管扩张、血压骤降。肾上腺素、醛固酮与性激素缺乏不至于迅速致死，可代偿或补充"},{"q":"脊髓腰骶段受到损伤时，排尿反射的障碍主要表现为","o":["少尿","多尿","尿失禁","尿潴留","尿频"],"a":3,"e":"脊髓腰骶段为排尿反射初级中枢，受损后排尿反射弧中断，逼尿肌无力、膀胱充盈而不能排出，表现为尿潴留。少尿多尿属肾功能异常，尿失禁多见于骶髓以上损伤或高位截瘫"},{"q":"下列关于等张收缩的描述错误的是","o":["等张收缩过程发生肌纤维的缩短","消耗能量主要用于肌肉缩短和移动负荷","收缩过程张力始终不变","肌肉开始缩短前，先表现出等张收缩，后表现出等长收缩","肌肉收缩产生的张力大于或等于阻力负荷，肌肉发生等张收缩"],"a":3,"e":"肌肉开始缩短前先表现等长收缩使张力升至负荷，随后才表现等张收缩，故先等张后等长的说法错误。等张收缩中肌纤维缩短、张力保持不变、能量用于缩短与移动负荷均正确"},{"q":"心肌细胞兴奋后，其兴奋性发生周期变化的顺序是","o":["绝对不应期—相对不应期—局部反应期—超常期","绝对不应期—相对不应期—超常期—局部反应期","绝对不应期—超常期—局部反应期—相对不应期","绝对不应期—局部反应期—相对不应期—超常期","绝对不应期—相对不应期—超常期—低常期"],"a":3,"e":"心肌兴奋后兴奋性变化依次为绝对不应期、局部反应期、相对不应期、超常期，之后还可有低常期。把局部反应期置于相对不应期之后，或遗漏局部反应期而直接列超常期的顺序均不正确"},{"q":"关于胃的蠕动，下列哪一项是正确的","o":["空腹时基本不发生","发生频率约为12次/分","一个蠕动彼消失后才产生另一个蠕动","蠕动波向胃底和幽门两个方向传播","起始于胃底部"],"a":0,"e":"胃蠕动在空腹时基本不发生，进食后开始，频率约每分钟3次而非12次。蠕动波可重叠出现，由一个部位向幽门单向传播，起始于胃体中部而非胃底"},{"q":"关于肾小球滤过液中葡萄糖重吸收的描述错误的是","o":["只有近端小管可以重吸收","与Na+重吸收相偶联","正常情况下有部分葡萄糖在近端小管不能被重吸收","是一种主动转运的过程","肾小管重吸收葡萄糖的能力有一定限度"],"a":2,"e":"正常情况下滤过的葡萄糖在近端小管被全部重吸收，尿中不含葡萄糖，故部分不能被重吸收错误。仅近端小管重吸收、与Na+重吸收偶联、属主动转运且受肾糖阈限制均正确"},{"q":"下列哪种激素分泌不足可引起呆小病的发生","o":["生长激素","甲状旁腺激素","维生素D3","肾上腺糖皮质激素","甲状腺激素"],"a":4,"e":"婴幼儿期甲状腺激素分泌不足引起呆小病，表现为智力低下与身材矮小。生长激素缺乏致侏儒症而智力正常；甲状旁腺激素与维生素D3影响钙磷代谢，糖皮质激素缺乏致肾上腺皮质功能不全"},{"q":"肾脏的排泄具有维持机体水平衡的功能，水的重吸收过程取决于小管内外的渗透压和不同管段管壁对水的通透性。维持水平衡重吸收的部位是","o":["近端小管","髓袢降支细段","髓袢升支细段","髓袢升支粗段","远曲小管和集合管"],"a":4,"e":"远曲小管和集合管在抗利尿激素调节下按机体需要重吸收水，是维持水平衡的关键部位。近端小管按固定比例等渗重吸收水，不受ADH调节；髓袢各段主要参与髓质渗透梯度的建立"},{"q":"决定微循环中真毛细血管网开放与否的因素是","o":["动脉血压","静脉血压","脉压","微动脉和后微动脉的舒缩状态","毛细血管前括约肌的舒缩状态"],"a":4,"e":"真毛细血管网是否开放取决于毛细血管前括约肌的舒缩状态，其交替舒缩使真毛细血管轮流开放。微动脉与后微动脉调节进入毛细血管的总血量，动静脉血压与脉压非直接决定因素"},{"q":"正常成人总的呼吸膜面积约有","o":["30m2","70m2","120m2","150m2","300m2"],"a":1,"e":"正常成人呼吸膜总面积约70平方米，利于高效气体交换。30平方米明显偏小，120平方米、150平方米与300平方米则远大于实际数值"},{"q":"去大脑动物仰卧时伸肌紧张性最高，俯卧时则伸肌紧张性最低，这一现象称为","o":["翻正反射","探究反射","颈紧张反射","迷路紧张反射","腱反射"],"a":3,"e":"去大脑动物仰卧时伸肌紧张最高、俯卧时最低，由内耳迷路传入冲动引起，称迷路紧张反射。翻正反射恢复姿势，探究反射为朝向反应，颈紧张反射源于颈部本体感受器，腱反射为牵张反射"},{"q":"巨幼红细胞性贫血是由于缺少","o":["亚铁离子","蛋白质","维生素B12和叶酸","促红细胞生成素","维生素D3"],"a":2,"e":"巨幼红细胞性贫血因缺乏维生素B12和叶酸，DNA合成障碍致红细胞发育受阻、体积增大。缺亚铁离子致缺铁性贫血，促红细胞生成素缺乏致肾性贫血，蛋白质与维生素D3非本病原因"},{"q":"慢性肾衰竭患者常出现的电解质紊乱是","o":["低磷血症","低钙血症","代谢性碱中毒","低钾血症","低镁血症"],"a":1,"e":"慢性肾衰竭时肾脏排磷减少致高磷血症，钙磷乘积升高并伴活性维生素D生成减少，出现低钙血症，还常有代谢性酸中毒与高钾血症。低磷、代谢性碱中毒、低钾与低镁均不符合"},{"q":"下列选项中不是血浆蛋白功能的是","o":["运输物质","参与机体的免疫","缓冲pH值","维持血浆晶体渗透压","参与凝血和抗凝血作用"],"a":3,"e":"维持血浆晶体渗透压主要靠Na+和Cl-等晶体物质，而非血浆蛋白，故该项不属于血浆蛋白功能。运输物质、参与免疫、缓冲pH以及参与凝血与抗凝血均为血浆蛋白的重要功能"},{"q":"不属于含氮激素的是","o":["生长激素","生长抑素","促卵泡激素","肾上腺糖皮质激素","催乳素"],"a":3,"e":"肾上腺糖皮质激素属类固醇激素，不属于含氮激素。生长激素、生长抑素、促卵泡激素与催乳素化学本质均为肽类或蛋白质，属含氮激素"},{"q":"关于糖皮质激素生理作用，下列哪一项是错误的","o":["升高血糖","使肝外全身细胞内蛋白质减少","加强心肌收缩力、维持动脉血压","增加肩背部、腹部脂肪的合成","减少淋巴细胞数量"],"a":2,"e":"加强心肌收缩力主要是儿茶酚胺与甲状腺激素的作用，糖皮质激素仅通过允许作用维持血管对儿茶酚胺的反应性以助维持血压，故该项错误。升高血糖、促蛋白分解、致肩背腹部脂肪增加、减少淋巴细胞均为其真实作用"},{"q":"体内二氧化碳分压最高的是","o":["静脉血液","毛细血管血液","动脉血液","组织液","细胞内液"],"a":4,"e":"细胞内液是体内二氧化碳分压最高处，细胞代谢不断产生CO2，其分压高于组织液，再依次经静脉血、毛细血管血、动脉血递减排出"},{"q":"在甲状腺手术中误伤甲状旁腺时，下列哪项变化会出现","o":["血磷升高","血钙降低","血钙升高","血钙降低、血磷升高","血钙升高、血磷降低"],"a":3,"e":"甲状腺手术误伤甲状旁腺使PTH缺乏，保钙排磷作用减弱，出现血钙降低与血磷升高。只提血磷升高或血钙降低均不全面，血钙升高的方向与甲状旁腺功能减退相反"},{"q":"迷走神经末梢释放乙酰胆碱可引起心率减慢主要是由于","o":["窦房结细胞对K+通透性降低","窦房结细胞对K+通透性增加","窦房结细胞对Ca2+通透性增加","窦房结细胞对Na+通透性增加","窦房结细胞对Cl-通透性增加"],"a":1,"e":"迷走神经末梢释放乙酰胆碱激动窦房结M受体，提高K+通透性，K+外流增多使最大舒张电位更负、自动去极减慢，心率减慢。K+通透性降低及Ca2+、Na+、Cl-通透性增加均不符"},{"q":"刺激的阈强度是指","o":["用最小刺激强度，刚刚引起组织的最短作用时间","保持一定的刺激强不变，能引起组织兴奋的最适作用时间","保持一定的刺激时间不变，引起组织发生兴奋的最小刺激强度","刺激时间不限，能引起组织兴奋的最适刺激强度","刺激时间不限，能引起组织最大兴奋的最小刺激强度"],"a":2,"e":"阈强度指保持刺激时间不变时，引起组织兴奋所需的最小刺激强度。用最小强度与最短时间组合描述的是时值概念，最适强度与最大兴奋的说法均不属阈强度定义"},{"q":"关于月经出血的描述，下列哪一项是错误的","o":["黄体期后期，促卵泡激素和黄体生成素分泌减少","黄体退化，雌激素和孕激素分泌减少","前列腺素F2α释放，子宫内膜血管痉挛","溶酶体释出蛋白水解酶，使组织溶解，内膜剥脱，形成出血","出血期中由于雌激素和孕激素的正反馈，促卵泡激素和黄体生成素又开始加强分泌"],"a":4,"e":"出血期雌、孕激素水平低落，对下丘脑和腺垂体的负反馈减弱，FSH与LH才逐渐恢复分泌，并非正反馈加强，故该项错误。黄体后期FSH与LH减少、黄体退化激素下降、PGF2α致血管痉挛、溶酶体酶致内膜剥脱均正确"},{"q":"当达到K+平衡电位时","o":["膜两侧K+浓度梯度为零","膜外K+浓度大于膜内","膜两侧电位梯度为零","膜内电位较膜外电位相对较正","膜内侧K+的净外流为零"],"a":4,"e":"达K+平衡电位时，浓度差驱动的外流与电场力驱动的内流相等，K+净外流为零。膜两侧K+浓度梯度并不为零，膜内K+仍高于膜外，电位梯度也不为零，膜内电位相对膜外为负"},{"q":"下列关于大肠内消化的叙述，正确的是","o":["大肠液的pH为7","大肠运动强而快","大肠内细菌对糖和脂肪有发酵作用","大肠对刺激反应较敏感","大肠液内不含任何消化酶"],"a":2,"e":"大肠内细菌可对糖类与脂肪进行发酵和腐败作用，故该项正确。大肠液pH约8.2～8.4而非中性，运动慢而弱、对刺激反应迟钝，且大肠液含黏液与碳酸氢盐及少量消化酶"},{"q":"吸收后以淋巴管为主要转运途径的物质是","o":["葡萄糖","氨基酸","乳糜微粒","中链脂肪酸","无机盐"],"a":2,"e":"乳糜微粒由长链脂肪酸与甘油三酯组成，经淋巴管吸收转运后入血。葡萄糖、氨基酸、无机盐及中链脂肪酸则直接吸收入毛细血管，经门静脉转运"},{"q":"IPSP的产生是由于突触后膜提高了下列哪些离子的通透性","o":["Cl-、K+，尤其是Cl-","K+、Na+，尤其是K+","K+、Ca2+，尤其是Ca2+","K+、HCO3-，尤其是HCO3-","Na+、Cl-，尤其是Na+"],"a":0,"e":"抑制性突触后电位因突触后膜对Cl-、K+通透性增高所致，尤以Cl-内流为主，使膜超极化。Na+通透性增高产生兴奋性突触后电位，Ca2+内流与HCO3-通透并非IPSP的主要离子基础"},{"q":"下列哪种疾病会使基础代谢率明显升高","o":["肢端肥大症","甲状腺功能亢进","糖尿病","呆小病","肾上腺皮质功能亢进"],"a":1,"e":"甲状腺功能亢进时甲状腺激素分泌过多，显著提高基础代谢率。肢端肥大症与糖尿病代谢改变不及甲亢显著，肾上腺皮质功能亢进影响较小，呆小病因激素不足而基础代谢率降低"},{"q":"下列关于CO2解离曲线的叙述，正确的是","o":["表示Hb结合CO2的量与PCO2的关系","有饱和点","呈S形","PO2的变化可使之移位","纵坐标可用饱和度表示"],"a":3,"e":"CO2解离曲线受PO2影响，PO2升高使曲线右移，即霍尔登效应。该曲线近似直线且无饱和点，纵坐标为血液CO2含量而非饱和度，也不呈S形"},{"q":"远曲小管和集合管对Na+的重吸收主要受下列哪种激素调节","o":["抗利尿激素","醛固酮","肾上腺素","肾素","缓激肽"],"a":1,"e":"远曲小管和集合管对Na+的重吸收主要受醛固酮调节，促进保Na+排K+。抗利尿激素主要调节水的重吸收，肾上腺素、肾素与缓激肽不直接作为该段Na+重吸收的主要激素"},{"q":"游离神经末梢作为一种痛觉感受器，依其所接受刺激的性质可归属于","o":["温度感受器","机械感受器","触压感受器","牵张感受器","化学感受器"],"a":4,"e":"游离神经末梢作为痛觉感受器属化学感受器，接受组织损伤释放的缓激肽、组胺、H+与K+等致痛物质。温度、机械、触压与牵张感受器各有专门结构和适宜刺激，与痛觉末梢不同"},{"q":"下列物质中，可直接引起冠脉舒张，血流量增加的是","o":["血管紧张素Ⅱ","去甲肾上腺素","甲状腺激素","腺苷","内皮素"],"a":3,"e":"腺苷是冠脉最强的舒血管物质之一，由心肌在代谢增强或缺氧时释放，直接作用于冠脉平滑肌使其舒张、血流量增加。血管紧张素Ⅱ和内皮素均为强烈缩血管物质，使冠脉收缩；去甲肾上腺素经α受体主要起缩血管效应；甲状腺激素通过提高代谢率间接增加冠脉血流，均非直接舒张冠脉"},{"q":"生理条件下，调节冠脉血流量的最重要因素是","o":["心交感神经","心迷走神经","腺苷","血氧水平","血二氧化碳水平"],"a":2,"e":"冠脉血流量主要受心肌局部代谢水平调节，腺苷是最重要的舒血管介质，心肌代谢增强或缺氧时释放增多使冠脉舒张。心交感和心迷走神经对冠脉的直接作用较弱且短暂，不是生理状态下最重要的因素；血氧降低虽可舒冠脉，但仅在明显缺氧时起作用；二氧化碳的舒血管作用也远弱于腺苷，均非主导"},{"q":"安静时，微循环中真毛细血管网的状态是","o":["经常关闭","经常开放","交替开放","受交感神经调节","突然开放或关闭"],"a":2,"e":"安静时真毛细血管由毛细血管前括约肌交替舒缩，造成毛细血管网轮流开放与关闭，同一时间仅部分开放以满足局部代谢需要。经常开放描述的是通血毛细血管；经常关闭会使组织缺氧，不符合实际；其开闭主要受局部代谢产物调节，而非交感神经直接支配，也不是突然的开放或关闭"},{"q":"月经血不会发生凝固是由于以下哪个原因","o":["雌激素阻止血液凝固","孕激素阻止血液凝固","子宫分泌前列腺素阻止血液凝固","子宫内有丰富的纤溶酶原激活物","子宫内有大量肝素"],"a":3,"e":"月经血中含来自子宫内膜的大量纤溶酶原激活物，可将纤溶酶原激活为纤溶酶，溶解已形成的纤维蛋白，使经血保持不凝状态。雌激素与孕激素并不直接抑制凝血；前列腺素主要引起子宫收缩与血管变化，与抗凝无关；子宫内并无大量肝素，肝素丰富并非经血不凝的机制"},{"q":"临床上常可以通过牵涉痛来初步判断内脏疾病部位，如心肌缺血患者，常主诉","o":["右肩、右上臂、心前区疼痛","右肩、右上臂、上腹部疼痛","左肩、左上臂、上腹部疼痛","左肩、左上臂、心前区疼痛","左肩、左上臂、肩胛区疼痛"],"a":3,"e":"心肌缺血的牵涉痛常放射至心前区、左肩及左上臂内侧，因心脏传入神经与这些部位皮肤传入神经在脊髓同一节段会聚，定位常不精确。右肩右上臂疼痛多见于肝胆疾病；上腹部疼痛易与胃十二指肠病混淆；单纯肩胛区疼痛也不典型，辨认放射部位有助于初步判断病变脏器"},{"q":"下列生物活性物质中，哪一种不属于内分泌激素","o":["肾上腺素","胰岛素","甲状腺素","前列腺素","内因子"],"a":4,"e":"内因子是胃壁细胞分泌的糖蛋白，作用为保护维生素B12并促进其在回肠吸收，属消化液成分而非激素。肾上腺素、胰岛素、甲状腺素分别为肾上腺髓质、胰岛β细胞和甲状腺分泌的经典内分泌激素；前列腺素虽为局部性体液因素，仍属激素样生物活性物质，内因子则完全不具信息传递特征"},{"q":"心迷走神经分布数量较少的心肌组织是","o":["窦房结","心室肌","心房肌","房室交界","房室束"],"a":1,"e":"心迷走神经纤维主要分布于窦房结、心房肌和房室交界，对心室肌的支配很少，故心室肌受迷走影响最小，而交感神经对心室肌支配丰富。窦房结与房室交界迷走分布密集，是调节心率和房室传导的部位；心房肌也有较多迷走纤维；房室束迷走分布同样稀少，但主要影响传导，心室肌才是迷走分布最少的收缩组织"},{"q":"心室肌细胞动作电位0期形成的离子流是","o":["K＋外流","K＋内流","Na＋内流","Ca2＋内流","Cl-内流"],"a":2,"e":"心室肌细胞动作电位0期为去极化期，由快钠通道开放、Na＋快速内流形成，属快反应细胞，去极速度快、幅度大。K＋外流主导复极化而非0期；Ca2＋内流主要形成平台期，是慢反应细胞0期的基础，在心室肌不参与0期去极；Cl-内流仅与1期短暂复极有关，K＋内流不符合心肌电生理"},{"q":"血液与组织液之间物质交换的最主要形式是","o":["吞饮","滤过","扩散","滤过和重吸收","重吸收"],"a":2,"e":"血液与组织液之间的物质交换以扩散最主要，脂溶性物质、O2、CO2及葡萄糖等依浓度差通过毛细血管壁，是交换的主要方式。滤过与重吸收靠有效滤过压驱动液体和小分子溶质移动，维持组织液生成与回流，但不是溶质交换的最主要形式；吞饮仅转运大分子、量小，单列滤过或重吸收均不全面"},{"q":"发热开始前，先出现寒战的原因是","o":["身体特别虚弱","体温调节中枢功能障碍","机体过度散热","机体产热量不足","体温调定点上移"],"a":4,"e":"致热原使下丘脑体温调定点上移，实际体温低于新调定点，中枢即发动寒战产热、皮肤血管收缩减少散热，使体温升至新水平，故发热前先寒战。体温调节中枢功能障碍属中枢性发热机制，并非一般发热的寒战原因；过度散热使体温下降；产热量不足不能解释主动寒战；身体虚弱只是诱因"},{"q":"肺泡表面张力来自","o":["肺泡表面活性物质","肺泡上皮","基膜层","肺泡内液-气分子间的吸引力","肺泡表面活性物质与液体分子之间的吸引力"],"a":3,"e":"肺泡表面张力源于肺泡内表面液层与气体界面上水分子间的相互吸引，使肺泡有回缩倾向。肺泡表面活性物质由Ⅱ型上皮分泌，作用是降低而非产生表面张力；肺泡上皮与基膜层为组织结构，不直接产生张力；表面活性物质与液体分子间的吸引也不是表面张力的来源"},{"q":"下列哪项活动属于条件反射","o":["看到酸梅时引起唾液分泌","食物进入口腔引起胃腺分泌","大量饮水后尿量增加","寒冷环境下皮肤血管收缩","炎热环境下出汗"],"a":0,"e":"看到酸梅引起唾液分泌是建立在既往经验基础上的条件反射，酸梅形象作为条件刺激需后天习得才能引起反应。食物进入口腔引起胃腺分泌、大量饮水后尿量增加、寒冷时皮肤血管收缩、炎热时出汗均为生来具有的非条件反射，由刺激直接引起，不需学习，中枢多在皮质下"},{"q":"在刺激作用时间无限长的情况下，引起细胞产生动作电位的最小刺激强度是","o":["阈强度","基强度","时值","阈刺激","阈下刺激"],"a":1,"e":"基强度指在刺激作用时间足够长时引起组织兴奋所需的最小刺激强度，是衡量兴奋性的指标，时间无限长条件下即对应此值。阈强度是在特定作用时间下的最小刺激强度；时值为两倍基强度刺激引起兴奋所需的最短作用时间，不是强度；阈刺激是达到阈强度的刺激，阈下刺激不能引起动作电位"},{"q":"红细胞的主要功能为","o":["吞噬细菌","参与凝集","参与特异性免疫","运输氧气和二氧化碳","缓冲pH值"],"a":3,"e":"红细胞的主要功能是运输O2和CO2，依靠血红蛋白的可逆结合完成，同时参与血液缓冲。吞噬细菌是白细胞的功能；参与特异性免疫主要由淋巴细胞承担；参与凝集是血型不合时红细胞表面抗原的作用，并非其生理功能；缓冲pH虽由血红蛋白参与，但属次要作用，不能替代气体运输"},{"q":"由于突触前膜的活动发生改变而形成突触前抑制，这个活动是","o":["突触前膜释放兴奋性神经递质减少","突触前膜发生超极化","突触前膜释放抑制性神经递质","突触前神经元末梢内流的Ca2+增多","突触前神经元末梢对Na+通透性增大"],"a":0,"e":"突触前抑制由轴突-轴突式突触活动引起，使突触前末梢去极化，动作电位幅度减小，进入末梢的Ca2＋减少，兴奋性递质释放量下降，突触后EPSP减小，但突触后膜兴奋性不变。突触前膜超极化不是其机制；释放抑制性递质属突触后抑制；Ca2＋内流增多会加强释放；Na＋通透性增大也非关键改变"},{"q":"下列哪一项描述符合Wolff-Chaikoff效应","o":["腺垂体分泌促甲状腺激素调节甲状腺激素的分泌","下丘脑对腺垂体促甲状腺激素分泌的调节","甲状腺激素反馈调节促甲状腺激素分泌","自主神经对甲状腺功能的调节","过量碘产生的抗甲状腺聚碘作用"],"a":4,"e":"Wolff-Chaikoff效应指摄入过量碘时，甲状腺内碘浓度升高会暂时抑制碘的有机化和甲状腺激素合成，属自身保护性调节，故对应过量碘的抗甲状腺聚碘作用。腺垂体TSH调节、下丘脑调节、甲状腺激素负反馈及自主神经调节均属甲状腺功能的常规调节机制，与碘的这一特殊效应无关"},{"q":"关于钙的吸收，正确的叙述是","o":["钙吸收的主要部位是回肠","离子状态的钙最易吸收","胃酸抑制钙的吸收","维生素E促进钙的吸收","钙吸收为被动过程"],"a":1,"e":"钙主要以离子状态在小肠被吸收，尤其十二指肠和空肠上段，需活性维生素D促进，属主动转运并受机体需要调节。回肠并非钙吸收主要部位；胃酸可使钙盐溶解、促进吸收而非抑制；促进钙吸收的是维生素D而非维生素E；钙吸收包含主动过程，不是单纯被动扩散"},{"q":"肾小管中H+的分泌主要位于","o":["近端小管","髓袢升支粗段","髓袢降支细段","髓袢升支细段","远曲小管"],"a":0,"e":"肾小管H＋分泌主要在近端小管，通过Na＋-H＋交换大量泌H＋，并与HCO3-重吸收偶联，是排酸保碱的主要部位。髓袢升支粗段主要重吸收NaCl并参与尿液稀释；降支细段对水通透、几乎不泌H＋；升支细段以被动重吸收NaCl为主；远曲小管也能泌H＋但量较少，并非主要部位"},{"q":"下列哪项不是调节甲状旁腺激素的因素","o":["血钙浓度","血糖","血磷浓度","血镁浓度","前列腺素F2"],"a":1,"e":"甲状旁腺激素的分泌主要受血钙浓度负反馈调节，血磷升高、血镁改变及某些前列腺素也可影响其分泌。血糖浓度不是甲状旁腺激素的调节因素，血钙、血磷、血镁均是明确调节因子，前列腺素F2等亦参与调节，故这几项都不能选"},{"q":"控制四肢远端肌肉精细运动的传导通路是","o":["皮质脊髓束","顶盖脊髓束","网状脊髓束","皮质脑干束","前庭脊髓束"],"a":0,"e":"皮质脊髓束尤其皮质脊髓侧束支配四肢远端肌，与精细的随意运动有关，损伤后出现精细动作障碍。顶盖脊髓束与视听觉引起的姿势反射有关；网状脊髓束调节肌张力和姿势；前庭脊髓束维持平衡与伸肌张力；皮质脑干束支配脑神经运动核、管理头面部肌，均不主导四肢远端精细运动"},{"q":"人类新小脑损伤的特有表现有","o":["意向性震颤","静止性震颤","肌张力增强","偏瘫","平衡失调"],"a":4,"e":"官方答案为【平衡失调】，但依据教材，正确答案为【意向性震颤】。新小脑即大脑小脑，主管随意运动的协调，其损伤表现为随意运动的力量、方向、速度与限度紊乱，出现指鼻不准、轮替动作障碍及意向性震颤，肌张力多减低。平衡失调是前庭小脑（绒球小结叶）损伤的特征；静止性震颤与肌张力增强见于锥体外系病变，偏瘫为皮质脊髓束损伤表现，均非新小脑损伤特有"},{"q":"突触传递中，影响突触前神经末梢递质释放量的关键因素是","o":["神经末梢膜Na+通道密度","进入神经末梢的Ca2+量","神经末梢内囊泡数量","囊泡内递质含量","活化区面积大小"],"a":1,"e":"递质释放量取决于突触前末梢动作电位引起的Ca2＋内流，Ca2＋促使囊泡与前膜融合并胞吐，进入量越多释放越多，是关键因素。膜上Na＋通道密度决定动作电位的产生与传导，不直接决定释放量；囊泡数量与递质含量提供物质基础，但不是即时调节的关键；活化区面积影响释放位点，仍需Ca2＋触发"},{"q":"丘脑特异投射系统的结构特点是","o":["主要接受来自脑干网状上行激动系统的传入纤维","起始核团是髓板内核群","所有特定感觉的传入纤维都要到丘脑换元","弥散投射到大脑皮质广泛区域","点对点投射到大脑皮质特定区域"],"a":4,"e":"丘脑特异投射系统接受特定感觉传导通路的投射，在丘脑换元后点对点投射到大脑皮质特定感觉区，具有严格定位关系，引起特定感觉。接受脑干网状上行激动系统纤维、起始于髓板内核群、弥散投射皮质广泛区域均为非特异投射系统的特点；嗅觉传入可绕过丘脑，并非所有感觉都在此换元"},{"q":"可阻断浦肯野纤维细胞0期去极化的药物是","o":["普萘洛尔","河豚毒素","阿托品","维拉帕米","四乙铵"],"a":1,"e":"浦肯野纤维属快反应细胞，0期去极由快钠通道开放、Na＋内流引起，河豚毒素可阻断钠通道而抑制其0期去极。普萘洛尔阻断β受体，主要影响自律性与传导；阿托品阻断M受体，解除迷走抑制；维拉帕米阻断L型钙通道，影响窦房结、房室结等慢反应细胞；四乙铵阻断钾通道，主要影响复极"},{"q":"下列关于小肠上皮细胞吸收糖的叙述，正确的是","o":["吸收速率为葡萄糖>甘露糖>果糖>半乳糖","单糖通过腔面膜属于主动过程，而通过基侧膜属于被动过程","腔面膜上2分子单糖与1个Na+同向转运","戊糖吸收不依赖Na+转运","与氨基酸竞争转运体"],"a":1,"e":"小肠上皮吸收单糖时，腔面膜依靠Na＋-单糖同向转运体继发性主动转运摄入，需消耗钠泵建立的Na＋梯度；基侧膜则通过易化扩散将单糖转出进入血液，属被动过程。葡萄糖与半乳糖吸收最快，果糖次之，甘露糖最慢；腔面膜为1分子单糖配2个Na＋；戊糖吸收也依赖Na＋，且不与氨基酸竞争同一转运体"},{"q":"在心动周期中，心室内压上升速率最快的时期是","o":["心房收缩期","等容收缩期","快速射血期","减慢射血期","快速充盈期"],"a":1,"e":"等容收缩期房室瓣与动脉瓣均关闭，心室成为封闭腔，心肌强烈收缩而容积不变，室内压急剧升高，上升速率达全程最高。快速射血期虽室内压达峰，但已开始射血、容积缩小，压力上升速率反而下降；减慢射血期与充盈期压力变化平缓；心房收缩期主要升高房内压，对室内压影响很小"},{"q":"调节体温的基本中枢位于","o":["下丘脑","脑桥","延髓","脊髓","大脑皮质"],"a":0,"e":"调节体温的基本中枢位于下丘脑，其中视前区-下丘脑前部是体温调节中枢整合的关键部位，含热敏与冷敏神经元，感受温度变化并整合产热散热反应。脑桥、延髓、脊髓仅具初级调节能力，不能独立完成体温恒定；大脑皮质参与行为性调节，属高级中枢而非基本中枢"},{"q":"抗凝血酶Ⅲ的作用机制是","o":["除掉血浆中游离的钙离子","使血浆中的纤维蛋白原降解","抑制凝血因子Ⅻ不被激活","封闭了某些凝血因子的丝氨酸残基","抑制凝血因子Ⅲ激活"],"a":3,"e":"抗凝血酶Ⅲ与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ、Ⅺ、Ⅻ的丝氨酸残基结合，封闭其活性中心使其失活，是体内重要抗凝物质，肝素可增强其作用。除去游离钙离子是草酸盐、枸橼酸钠等体外抗凝剂的机制；降解纤维蛋白原属纤溶系统作用；抑制Ⅻ激活或因子Ⅲ激活均非抗凝血酶Ⅲ的作用方式"},{"q":"根据王田的BMR检测结果(252、5kJ/m2·h)，下列哪项是正确的（正常BMR参考值146、9kJ/m2·h）","o":["甲状腺功能亢进","BMR在正常范围","提示有肾上腺皮质功能低下","提示有垂体性肥胖","甲状腺功能低下"],"a":0,"e":"该受试者基础代谢率为252.5 kJ/(m2·h)，较正常参考值146.9显著升高约70%，超出正常变动范围（±10%～15%），符合甲状腺功能亢进时甲状腺激素促进代谢、产热增加的表现。BMR并未在正常范围；肾上腺皮质功能低下与垂体性肥胖多表现为偏低或正常；甲状腺功能低下时BMR明显降低，与结果相反"},{"q":"如果人为地保持脑脊液pH值不变，用含高浓度CO2的人工脑脊液灌流脑室不再引起通气加强，此情况表明","o":["CO2可直接兴奋呼吸中枢","CO2可直接兴奋中枢化学总受器","CO2通过改变脑脊液H+浓度而兴奋呼吸中枢","CO2通过改变脑脊液H+浓度而兴奋中枢化学感受器","脑脊液中的H+可直接兴奋呼吸中枢"],"a":3,"e":"CO2本身不直接兴奋呼吸中枢，须先进入脑脊液生成H＋，由H＋刺激中枢化学感受器再兴奋呼吸；人为维持脑脊液pH不变时高CO2即失去作用，说明其通过改变H＋浓度发挥效应，且感受器位于中枢。CO2直接兴奋呼吸中枢或中枢化学感受器的说法不成立；外周化学感受器感受动脉血H＋、CO2、O2，与脑脊液灌流无关"},{"q":"关于心动周期的叙述，错误的是","o":["心房开始收缩，作为一个心动周期的开始","通常心动周期是指心室的活动周期","舒张期大于收缩期","心房和心室有共同收缩的时期","心动周期持续的时间与心率有关"],"a":3,"e":"心动周期以心房收缩开始，但心房收缩结束后心室才开始收缩，二者不存在共同收缩的时期，否则房室瓣无法顺序开放充盈。通常所说心动周期指心室活动周期，且舒张期长于收缩期，有利于充盈与冠脉供血；周期长短随心率增减而改变。其余各项均为心动周期的正确描述"},{"q":"下列关于N型受体的叙述，错误的是","o":["属于胆碱能受体","存在于副交感神经节内神经元的突触后膜上","存在于交感神经节内神经元的突触后膜上","能与毒蕈碱发生特异性结合","其阻断剂为筒箭毒"],"a":3,"e":"N型受体为胆碱能受体，能与烟碱特异性结合，其阻断剂为筒箭毒；毒蕈碱是M型受体的激动剂，不与N型受体结合，故该项错误。N型受体分布于交感和副交感神经节突触后膜及神经肌肉接头，兴奋后产生快反应；其余关于其为胆碱能受体、存在于自主神经节及阻断剂为筒箭毒的叙述均正确"},{"q":"影响外周阻力最主要的因素是","o":["血液黏滞性","血管长度","小动脉、微动脉的口径","血流速度","血管弹性"],"a":2,"e":"外周阻力主要来自小动脉和微动脉，其口径是决定阻力的最关键因素，按泊肃叶定律阻力与半径四次方成反比，口径稍变即显著改变阻力。血液黏滞性与血管长度是影响因素但相对恒定；血流速度是阻力的结果而非原因；血管弹性主要影响脉搏压及主动脉的弹性储器作用"},{"q":"下列哪一种因素可抑制胃排空","o":["食物对胃的扩张刺激","肠-胃反射增强","迷走神经兴奋释放乙酰胆碱","迷走-迷走反射增强","G细胞释放促胃液素增多"],"a":1,"e":"食糜进入十二指肠后通过肠-胃反射抑制胃运动和胃排空，使排空速度与小肠消化吸收能力匹配，酸性、高渗及脂肪食糜均可触发。食物对胃的扩张刺激、迷走神经兴奋释放乙酰胆碱及迷走-迷走反射均促进胃运动与排空；G细胞释放促胃液素也增强胃收缩、促进排空，而非抑制"},{"q":"促胃液素由下列哪一种消化道细胞分泌","o":["I细胞","S细胞","G细胞","D细胞","PP细胞"],"a":2,"e":"促胃液素由胃窦和十二指肠的G细胞分泌，主要刺激胃酸分泌并促进胃运动。I细胞分泌缩胆囊素；S细胞分泌促胰液素；D细胞分泌生长抑素，抑制胃酸与胃肠激素释放；PP细胞分泌胰多肽。各细胞分泌产物具有特异性，是胃肠激素来源的常考点"},{"q":"下列哪一项不是调节胃排空速度的因素","o":["胃内容物中碳水化合物","胃黏膜G细胞的分泌物","十二指肠的扩张刺激","十二指肠内容物的渗透压","进入十二指肠的食糜的酸度"],"a":0,"e":"胃排空速度主要受十二指肠内容物的酸度、渗透压、脂肪及扩张刺激通过肠-胃反射和促胰液素、抑胃肽等调节，胃黏膜G细胞分泌的促胃液素也促进排空。胃内容物中碳水化合物本身不是直接的调节因素，其排空快慢仍取决于进入十二指肠后的反馈；其余各项均明确参与排空调节"},{"q":"关于O2在血液中的运输，描述正确的是","o":["物理溶解的O2量占98、5%","化学结合的O2量占1、5%","与红细胞内的Hb结合运输","与血浆蛋白质结合运输","与血浆中的铁结合在一起运输"],"a":2,"e":"血液中O2主要以氧合血红蛋白形式与红细胞内Hb结合运输，约占98.5%；物理溶解仅约1.5%，虽量小却是气体交换与Hb结合的前提。不以血浆蛋白结合运输，也不与血浆中铁结合；选项中把物理溶解与化学结合的比例颠倒，故相关表述错误"},{"q":"促进胰酶分泌作用最强的是","o":["生长抑素","缩胆囊素","胰岛素","促胃液素","促胰液素"],"a":1,"e":"缩胆囊素由十二指肠I细胞在蛋白质分解产物和脂肪酸刺激下释放，主要促进胰腺分泌大量酶，是促胰酶分泌最强的激素，并引起胆囊收缩。促胰液素主要促进胰液中水和HCO3-分泌，对酶作用弱；生长抑素抑制胰液分泌；促胃液素作用较弱；胰岛素不直接调节胰酶分泌"},{"q":"女性的基础体温随月经周期而变动，这可能与下列哪种激素有关","o":["甲状腺激素","肾上腺激素","雌激素","孕激素","促肾上腺皮质激素"],"a":3,"e":"排卵后黄体分泌孕激素增多，作用于下丘脑体温调节中枢使基础体温升高约0.3～0.6℃，月经前随孕激素下降而回落，形成双相体温曲线。雌激素不引起这种明显升温效应；甲状腺激素、肾上腺激素及促肾上腺皮质激素虽可影响代谢产热，但不随月经周期呈现规律性变化"},{"q":"对体温调节起关键作用的中枢部位是","o":["脊髓灰质侧角","脑干网状结构","视前区-下丘脑前部","下丘脑后部","中脑中央灰质"],"a":2,"e":"视前区-下丘脑前部含大量热敏与冷敏神经元，能感受局部脑温变化并整合外周温度信息，是体温调节中枢整合的核心部位，起关键作用。下丘脑后部主要参与产热与寒战反应的传出整合，并非最关键；脊髓灰质侧角、脑干网状结构及中脑中央灰质只具初级或辅助调节作用"},{"q":"下列关于生理性止血描述，错误的是","o":["包括血管收缩、血小板血栓形成和血液凝固三个过程","血小板与止血栓的形成有关","首先表现为受损血管局部和附近的小血管收缩，使局部血流减少","一期止血主要依赖于血管收缩及血小板止血栓的形成","血小板减少时，凝血时间明显延长"],"a":4,"e":"血小板减少主要使出血时间延长、止血栓形成障碍，而凝血时间反映内源性凝血因子功能，一般不受血小板数量影响，故该项表述错误。生理性止血包括血管收缩、血小板血栓形成和血液凝固三个过程，一期止血依赖血管收缩与血小板栓形成；受损局部血管先收缩使血流减少，均为正确描述"},{"q":"生长因子进行信号转导的方式是","o":["酪氨酸激酶受体介导的信号转导通路","酪氨酸激酶结合型受体介导的信号转导通路","鸟苷酸环化酶受体介导的信号转导通路","G蛋白偶联受体介导的信号转导通路","离子通道型受体介导的信号转导通路"],"a":0,"e":"多数生长因子受体本身具酪氨酸激酶活性，配体结合后受体二聚化并自磷酸化，启动下游信号转导，属酪氨酸激酶受体通路。酪氨酸激酶结合型受体无内在酶活性、需结合JAK；鸟苷酸环化酶受体以cGMP为第二信使；G蛋白偶联受体与离子通道型受体分别通过G蛋白和离子通透变化传递信号，均非主要方式"},{"q":"骨骼肌收缩过程中，后负荷改变可以影响肌肉的","o":["兴奋性","初长度","最适初长度","收缩速度","收缩能力"],"a":3,"e":"后负荷是肌肉收缩时遇到的阻力，增大后负荷使收缩速度减慢、缩短程度减小，等长收缩时则表现为张力增大，故主要影响收缩速度与做功。兴奋性取决于刺激与膜状态；初长度由前负荷决定，最适初长度是固定的最佳长度；收缩能力为内在功能，不受后负荷改变"},{"q":"去甲肾上腺素和α受体结合后产生的效应，错误的是","o":["血管收缩","瞳孔扩大","小肠平滑肌收缩","妊娠子宫收缩","竖毛肌收缩"],"a":2,"e":"去甲肾上腺素激动α受体引起血管收缩、瞳孔开大肌收缩扩瞳、妊娠子宫收缩及竖毛肌收缩，而使小肠平滑肌舒张而非收缩，故该项错误。α受体兴奋对胃肠平滑肌一般呈抑制效应，可使胃肠运动减弱；其余各项均为α受体兴奋的典型表现"},{"q":"可引起射血分数增大的因素是","o":["心室舒张末期容积增大","动脉血压升高","心率减慢","心肌收缩能力增强","快速射血期缩短"],"a":3,"e":"射血分数为每搏输出量与心室舒张末期容积之比，心肌收缩能力增强使每搏输出量增多、收缩末期容积减小，射血分数增大。心室舒张末期容积增大虽可增加每搏量，但分母同步增大，射血分数未必升高；动脉血压升高增加后负荷，心率减慢及快速射血期缩短均不利于射血分数增大"},{"q":"在动物实验中，将蛋白质的中间消化产物(如蛋白胨)通过肠瘘直接注入十二指肠中，其引起胰液分泌的主要机制是","o":["交感神经兴奋","食物引起促胰液素和缩胆囊素的分泌","食物引起降钙素基因相关肽的分泌","食物引起生长抑素的分泌","食物引起胰多肽的分泌"],"a":1,"e":"蛋白质中间消化产物进入十二指肠后，刺激小肠黏膜I细胞释放缩胆囊素、S细胞释放促胰液素，二者共同促进胰液分泌，以酶和HCO3-为主，属体液调节机制。交感神经兴奋一般抑制胰液分泌；降钙素基因相关肽、生长抑素、胰多肽并非该过程的主要介质，生长抑素反而抑制分泌"},{"q":"肺的通气/血流比值反映肺部气体交换的气泵与血泵的匹配情况。如果通气/血流比值增大，表明该受试者肺内出现","o":["解剖无效腔增大","肺泡无效腔增大","解剖动-静脉短路","功能性动-静脉短路","气体交换效率提高"],"a":1,"e":"通气/血流比值增大说明肺泡通气相对过多而血流相对不足，部分肺泡气体不能与血液充分交换，相当于肺泡无效腔增大，气体交换效率下降。解剖无效腔指气道本身不参与交换的容积，与比值改变无关；功能性动-静脉短路是比值减小、血流相对过多的结果；比值增大并不意味着交换效率提高"},{"q":"电击头部或脑震荡可能导致","o":["逆行性遗忘症","顺行性遗忘症","近期记忆受损","远期记忆受损","近期和远期记忆障碍"],"a":0,"e":"脑震荡或电击头部常损伤颞叶、海马等与记忆有关的部位，表现为逆行性遗忘，即不能回忆受伤前一段时间的经历，而新信息形成障碍相对较轻。顺行性遗忘为伤后不能形成新记忆；近期与远期记忆受损均不强调损伤前记忆的缺失和时间方向，二者同时障碍也非脑震荡典型特征"},{"q":"腱反射属于","o":["屈肌反射","防御反射","肌牵张反射","条件反射","发汗反射"],"a":2,"e":"腱反射是快速牵拉肌腱时发生的单突触牵张反射，如膝反射、跟腱反射，感受器为肌梭，属于肌牵张反射的一种。屈肌反射与防御反射为多突触反射，由伤害性刺激引起；条件反射需后天建立；发汗反射属自主神经反射，均不属于腱反射的范畴"},{"q":"去甲肾上腺素和β受体结合后产生的效应，错误的是","o":["血管平滑肌舒张","子宫平滑肌舒张","小肠平滑肌舒张","支气管平滑肌舒张","心脏活动减弱"],"a":4,"e":"去甲肾上腺素激动β受体使心率加快、心肌收缩力增强、传导加速，心脏活动增强而非减弱，故该项错误。β2受体兴奋可引起血管平滑肌、子宫平滑肌、小肠平滑肌及支气管平滑肌舒张，其余各项均为β受体兴奋的典型效应；心脏活动减弱是M受体兴奋或β受体阻断的表现"},{"q":"迷走神经对冠状动脉的直接作用表现是","o":["兴奋血管平滑肌α受体","冠脉舒张","冠脉收缩","冠脉循环阻力增加","血流量减少"],"a":1,"e":"迷走神经及其递质乙酰胆碱对冠状动脉有直接舒张作用，可使冠脉血流量增加，但直接作用较弱，且易被心肌代谢活动改变引起的继发性舒血管效应掩盖。兴奋血管平滑肌α受体、冠脉收缩、冠脉循环阻力增加及血流量减少均为交感缩血管纤维或缩血管物质的作用，与迷走神经的直接效应相反"},{"q":"神经细胞在产生动作电位时，去极相的变化方向是朝向下列哪种电位的变化方向","o":["K+的平衡电位","Na+的平衡电位","Ca2+的平衡电位","Cl-的平衡电位","有机负离子的平衡电位"],"a":1,"e":"神经细胞动作电位去极相由Na＋通道开放、Na＋内流引起，膜电位由静息电位向Na＋平衡电位方向移动，故变化方向朝向Na＋平衡电位。K＋平衡电位是复极相趋近的电位；Ca2＋平衡电位与某些慢反应细胞或递质释放有关；Cl-与有机负离子平衡电位接近静息电位，均不主导去极相"},{"q":"使用冰袋给高热患者降温是","o":["增加辐射散热","增加传导散热","增加蒸发散热","增加对流散热","增加环境湿度"],"a":1,"e":"冰袋与皮肤直接接触，通过热传导将机体热量传给低温冰袋，属于增加传导散热。辐射散热靠红外线发散，无需接触；蒸发散热靠汗液汽化，冰袋不增加蒸发；对流散热依靠空气或液体流动，冰袋静置不主要依赖对流；增加环境湿度反而不利于蒸发散热"},{"q":"关于胰高血糖素的生理作用，下列哪一项是正确的","o":["促进糖原分解","抑制糖异生","抑制脂肪分解","促进胆汁和胃液分泌","抑制胰岛素分泌"],"a":0,"e":"胰高血糖素主要作用于肝，促进肝糖原分解和糖异生，抑制糖原合成，使血糖升高，同时促进脂肪分解。抑制糖异生与其升糖作用相反；它不促进胆汁和胃液分泌；可旁分泌促进而非抑制胰岛素分泌，抑制胰岛素分泌并非其主要作用"},{"q":"神经肌肉接头传递中，使乙酰胆碱降解的酶是","o":["磷酸二酯酶","腺苷酸环化酶","胆碱酯酶","ATP酶","胆碱乙酰化酶"],"a":2,"e":"神经肌肉接头处，乙酰胆碱酯酶迅速水解突触间隙中的ACh，终止其发挥作用，保证单次神经冲动引起单次肌肉收缩。磷酸二酯酶降解cAMP等环核苷酸；腺苷酸环化酶催化生成cAMP；ATP酶分解ATP供能；胆碱乙酰化酶合成ACh而非降解"},{"q":"循环系统平均充盈压的高低取决于","o":["动脉血压与外周阻力的关系","心输出量与外周阻力的关系","中心静脉压的高低","心输出量与心脏射血能力之间的关系","循环血量与血管容量之间的关系"],"a":4,"e":"循环系统平均充盈压是心脏停搏、血流停止时循环系统内各处相等的压力，取决于循环血量与血管容量的相对关系：血量增多或血管容量减小则充盈压升高，反之降低。动脉血压与外周阻力、心输出量的关系决定动脉压水平；中心静脉压反映右心前负荷；心输出量与射血能力的关系不决定充盈压"},{"q":"正常成人白细胞总数是","o":["（3、0～5、0）×1012/L","（3、0～8、0）×1011/L","（4、0～10、0）×109∕L","（5、0～10、0）×108/L","（5、0～10、0）×1012∕L"],"a":2,"e":"正常成人白细胞总数为(4.0～10.0)×10^9/L，超过10×10^9/L为增多，低于4×10^9/L为减少。以10^12/L或10^11/L为单位的计数对应红细胞的量级，明显过高；10^8/L又远低于实际，均与白细胞正常值不符，属于单位与数量级的常见设错"},{"q":"平静呼吸过程中，胸膜腔负压最大值(绝对值)出现在","o":["呼气末","呼气中","吸气中","吸气末","吸气初"],"a":3,"e":"平静吸气时胸廓扩大，肺被牵拉扩张，肺回缩力增大，胸膜腔负压随之增大，至吸气末肺扩张程度最大，负压绝对值达最大；呼气时逐渐减小，呼气末最小。吸气中不如吸气末显著；呼气中与呼气初均处于负压减小阶段；吸气初负压刚开始增加"},{"q":"平滑肌细胞中不含以下哪种结构","o":["肌球蛋白","肌动蛋白","原肌球蛋白","致密体","肌钙蛋白"],"a":4,"e":"平滑肌收缩由钙调蛋白介导，不含肌钙蛋白，Ca2＋与钙调蛋白结合后激活肌球蛋白轻链激酶引发收缩。平滑肌含肌球蛋白、肌动蛋白与原肌球蛋白，也具有致密体作为收缩结构的附着点，发挥类似横纹肌Z线的功能，故这些结构均存在，只有肌钙蛋白缺失"},{"q":"给狗制备“食管瘘”进行胃液分泌的研究是","o":["混合实验法","慢性在体实验法","急性在体实验法","急性离体实验法","慢性离体实验法"],"a":1,"e":"给狗制备食管瘘进行假饲研究胃液分泌，动物清醒、完整，可长期重复观察，属慢性在体实验法，能保留神经与体液调节的完整性。急性在体实验为麻醉或急性手术下短时观察；急性或慢性离体实验均将器官取出、脱离整体联系；混合实验法也非该经典模型的归类"},{"q":"有关平静呼吸的叙述，错误的是","o":["吸气时肋间外肌收缩","吸气时膈肌收缩","呼气时肋间内肌收缩","呼气时胸廓自然回位","吸气是主动的过程"],"a":2,"e":"平静呼吸时呼气是被动过程，靠吸气肌舒张、胸廓与肺弹性回位完成，肋间内肌并不收缩；用力呼气时才有肋间内肌和腹肌收缩。平静吸气由肋间外肌和膈肌主动收缩完成，属主动过程，吸气时胸廓扩大；其余各项均为平静呼吸的正确描述"},{"q":"下列哪一种原因导致月经出血的发生","o":["雌激素急剧减少","孕激素急剧减少","雌激素与孕激素都急剧减少","前列腺素F2α减少","缩宫素急剧减少"],"a":2,"e":"月经来潮前黄体退化，雌激素与孕激素水平同时急剧下降，子宫内膜失去激素支持而坏死脱落、出血，形成月经。单独雌激素或孕激素减少均不完整；前列腺素F2α参与子宫收缩与血管痉挛，其减少不会引起出血；缩宫素急剧减少也不是月经发生的机制"},{"q":"下列哪一项因素会影响醛固酮的分泌","o":["血Ca2+浓度降低","血Ca2+浓度升高","血K+浓度升高","血Cl-浓度降低","血Cl-浓度升高"],"a":2,"e":"血K＋浓度升高是刺激醛固酮分泌的重要因素，醛固酮促进远曲小管和集合管保Na＋排K＋，使血钾恢复正常；血管紧张素Ⅱ亦参与调节。血Ca2＋浓度变化主要影响甲状旁腺激素；血Cl-浓度并非醛固酮分泌的直接调节因素，故其余选项不成立"},{"q":"临床上常选择一种能充分反映肺组织的弹性状态和气道通畅程度的通气功能状况的指标是","o":["肺活量","肺总容量","深吸气量","时间肺活量","通气血流比值"],"a":3,"e":"时间肺活量指尽力吸气后尽快呼气，测定一定时间内呼出的气量，以第1秒用力呼气量占用力肺活量的百分比最有意义，既受肺弹性回缩力影响，又受气道阻力制约，能反映肺弹性状态与气道通畅程度。肺活量、肺总容量、深吸气量均为静态容积指标，不能反映气道通畅性；通气血流比值反映换气功能"},{"q":"下列关于近端小管重吸收的叙述正确的是","o":["Cl-为主动重吸收","K+为被动重吸收","Na+为主动或被动重吸收","HCO3-为主动重吸收","水不被重吸收"],"a":2,"e":"近端小管Na＋重吸收以钠泵驱动的主动转运为主，部分可经细胞旁被动重吸收，故Na＋为主动或被动重吸收的表述成立。Cl-以被动重吸收为主；HCO3-主要以CO2形式被动重吸收；K＋多经细胞旁被动重吸收；水随渗透梯度被重吸收，故其余各项的归属均不准确"},{"q":"关于抑制性突触后电位的产生，正确的叙述是","o":["突触前轴突末梢超极化","对Ca2+、K+通透性增大","突触后膜出现超极化","突触后膜去极化","突触后膜出现复极化"],"a":2,"e":"抑制性突触后电位由抑制性递质作用于突触后膜，使Cl-内流或K＋外流增加，突触后膜发生超极化，兴奋性降低。它是突触后膜的电位变化，而非突触前轴突末梢超极化；超极化时膜对Na＋通透性并未增大；去极化是EPSP的表现；复极化是动作电位下降相，均不符合IPSP"},{"q":"巴比妥类催眠药、全身麻醉药乙醚对机体发挥作用的机制，可能是阻断","o":["丘脑特异投射系统","脑干网状结构上行激动系统","边缘系统与大脑皮质之间的联系","脊髓丘脑侧束","脊髓丘脑前束"],"a":1,"e":"巴比妥类催眠药和乙醚全身麻醉药主要通过抑制脑干网状结构上行激动系统，阻断其对大脑皮质的唤醒作用，使皮质兴奋性降低而产生镇静、催眠和麻醉。丘脑特异投射系统传递特定感觉，不是主要靶点；边缘系统、脊髓丘脑侧束与前束分别参与情绪和感觉传导，与催眠麻醉机制无关"},{"q":"肺牵张反射的传入神经是","o":["舌咽神经","迷走神经","舌下神经","交感神经","窦神经"],"a":1,"e":"肺牵张反射的感受器位于气管和支气管平滑肌内，肺扩张时兴奋，冲动沿迷走神经传入延髓，抑制吸气、促使呼气，防止肺过度扩张。舌咽神经与颈动脉窦、主动脉弓压力感受器有关；舌下神经支配舌肌；窦神经传导颈动脉体化学感受信息；交感神经主要调节气道平滑肌，均非该反射传入通路"},{"q":"平均动脉压的粗略计算公式为","o":["收缩压+1/3脉压","收缩压－1/3脉压","舒张压＋2/3脉压","舒张压＋1/3脉压","(收缩压+舒张压）÷2"],"a":3,"e":"平均动脉压约等于舒张压加三分之一脉压，因心动周期中舒张期较长，平均压更接近舒张压。收缩压加1/3脉压高于实际平均压；收缩压减1/3脉压和舒张压加2/3脉压均偏低；收缩压与舒张压的算术平均未考虑舒张期更长，故不准确"},{"q":"血液循环流经肾小球时，血浆中的水分和小分子溶质可经滤过膜进入肾小囊，但滤液中几乎没有蛋白质。其原因是","o":["血浆蛋白分子较大，不能通过滤过膜上的孔","滤过膜上有带负电荷的成分，可以排斥血浆蛋白","滤过膜上孔的大小和带负电荷的蛋白两个因素共同作用","肾小球滤过的蛋白质可在肾小管主动重吸收","滤过膜中的内皮细胞层和基膜层有相同大小的网孔"],"a":2,"e":"肾小球滤过膜对蛋白质有机械屏障与电荷屏障双重作用：孔径限制大分子通过，膜上带负电荷的糖蛋白排斥同样带负电的血浆蛋白，二者共同使滤液中几乎无蛋白。单强调分子大小或单强调负电荷均不全面；蛋白质在肾小管被重吸收并非滤液中无蛋白的原因；内皮细胞层与基膜层孔径并不相同"},{"q":"阻力血管主要是指","o":["大动脉","小动脉和微动脉","大静脉","小动脉","毛细血管"],"a":1,"e":"小动脉和微动脉管径小、管壁平滑肌丰富，是形成外周阻力的主要部位，称阻力血管，其口径变化显著影响血压与器官血流分配。大动脉主要起弹性储器作用；大静脉为容量血管、储存血液；毛细血管主要进行物质交换；单列小动脉不如小动脉和微动脉完整"},{"q":"当下丘脑温度升高时，热敏神经元放电频率的变化是","o":["减少","不变","增加","先增加后减少","先减少后增加"],"a":2,"e":"下丘脑视前区的热敏神经元对局部温度升高敏感，温度升高时放电频率增加，促进散热反应并抑制产热，是体温调节中枢的核心机制。放电减少是冷敏神经元在升温时的反应；放电不变不符合其温度敏感性；先增加后减少或先减少后增加均非热敏神经元对温度升高的典型反应规律"},{"q":"临床上，胆道瘘管长期引流及胆汁缺乏的患者应用胆酸钠（利胆剂）治疗的主要机制是","o":["促进促胃液素的分泌","促进促胰液素的分泌","兴奋迷走神经","促进胆盐的肠肝循环","兴奋交感神经"],"a":3,"e":"胆道瘘管长期引流使胆盐大量丢失、胆汁酸池缩小，补充胆酸钠可经肠道吸收、随门静脉回肝再分泌入胆汁，即促进胆盐的肠肝循环，维持胆汁酸池并改善消化。该药不直接促进促胃液素或促胰液素分泌，对迷走神经与交感神经也无直接兴奋作用"},{"q":"下列哪一个激素不属于胃肠激素","o":["促胃液素","促胰液素","肾上腺素","缩胆囊素","生长抑素"],"a":2,"e":"肾上腺素由肾上腺髓质分泌，属儿茶酚胺类激素，不是胃肠激素。促胃液素、促胰液素、缩胆囊素分别由胃窦G细胞、十二指肠S细胞和I细胞分泌，生长抑素由胃肠D细胞分泌，均为典型的胃肠激素，调节消化液分泌与胃肠运动"},{"q":"贫血和CO中毒时，可携带O2的Hb减少，但并不引起呼吸加强，这是因为","o":["颈动脉体血流量代偿性增加","动脉血Hb氧饱和度正常","颈动脉体化学感受器发生适应","动脉血PO2正常","动脉血氧含量正常"],"a":3,"e":"外周化学感受器主要感受动脉血PO2降低，贫血和CO中毒时虽Hb携氧减少、血氧含量下降，但动脉血PO2正常，故不引起反射性呼吸加强。颈动脉体血流量代偿增加不是主要原因；CO中毒时Hb氧饱和度降低但关键在PO2正常；动脉血氧含量正常不符合贫血与CO中毒；化学感受器适应也不成立"},{"q":"机体的内环境通常是指","o":["体腔内空间","组织间隙","细胞外液","细胞内液","血液"],"a":2,"e":"内环境指细胞直接生活的液体环境，即细胞外液，包括血浆、组织液和淋巴液，是细胞与外界进行物质交换的媒介。体腔内空间不属于内环境；组织间隙中的组织液只是细胞外液的一部分；细胞内液不属内环境；血液含血细胞，也不等同于内环境"},{"q":"调节红细胞生成的最重要的体液因素是","o":["雄激素","雌激素","甲状腺激素","促红细胞生成素","生长激素"],"a":3,"e":"促红细胞生成素主要由肾产生，是调节红细胞生成最重要的体液因素，缺氧时分泌增加，促进骨髓红系增殖分化。雄激素也可刺激红细胞生成但作用次要；雌激素反而抑制；甲状腺激素与生长激素通过影响代谢间接作用，均不如EPO直接和重要"},{"q":"血型抗体主要是","o":["IgG与IgA","IgG与IgD","IgG与IgM","IgD与IgM","IgG与IgE"],"a":2,"e":"血型抗体以IgM和IgG为主，天然抗体多为IgM，不能通过胎盘；免疫性抗体多为IgG，可通过胎盘引起新生儿溶血。IgA主要存在于黏膜分泌液；IgD含量极低，多为B细胞表面受体；IgE与过敏及寄生虫免疫有关，均不是血型抗体的主要类别"},{"q":"醛固酮分泌减少可导致","o":["低血钾","高血钾","细胞外液量增多","血压升高","高血钠"],"a":1,"e":"醛固酮促进远曲小管和集合管保Na＋排K＋，分泌减少时K＋排出减少、血钾升高，同时Na＋重吸收减少，可致细胞外液量减少、血压下降。低血钾是醛固酮增多时的表现；细胞外液量增多、血压升高及高血钠均与醛固酮减少的效应相反"},{"q":"老年人大动脉硬化时，动脉血压的变化主要是","o":["收缩压降低","舒张压升高","收缩压升高，舒张压降低","收缩压降低，舒张压升高","收缩压和舒张压均升高，且升高幅度相同"],"a":2,"e":"大动脉硬化使血管弹性储器作用减弱，收缩期不能有效缓冲压力，收缩压升高；舒张期弹性回缩力减弱，舒张压降低，脉压增大。收缩压降低与单纯舒张压升高不符合硬化特点；收缩压降低伴舒张压升高无机制依据；二者同等幅度升高也不符合老年人单纯收缩期高血压的特征"},{"q":"心室肌细胞膜反应曲线反映的是","o":["静息电位和不应期的关系","动作电位和不应期的关系","静息电位和心肌兴奋性的关系","动作电位和心肌传导性的关系","静息电位和动作电位最大去极化速率的关系"],"a":4,"e":"心室肌细胞膜反应曲线描述静息电位水平与动作电位0期最大去极化速率的关系：静息电位负值增大则快钠通道备用增多、去极化速率加快，反之减慢，反映兴奋性随膜电位变化。它不反映静息电位与不应期、传导性或动作电位与不应期的关系，也非静息电位与心肌兴奋性的直接对应"},{"q":"一次进食后的食物残渣全部从大肠排出约需","o":["6～8h","8～12h","12～18h","18～24h","24h以上"],"a":4,"e":"一次进食后，食物残渣完成胃排空、小肠消化吸收及结肠推进排出体外，全程约需24小时以上，常达1～2天，受食物成分与个体胃肠动力影响。6～8h与8～12h仅相当于胃排空或小肠通过时间；12～18h、18～24h仍短于完整消化道通过所需时间，不足以使残渣全部排出"},{"q":"当肾动脉血压在一定范围内波动时，肾血流量相对稳定的调节方式属于","o":["免疫调节","体液调节","神经调节","神经-内分泌调节","自身调节"],"a":4,"e":"肾动脉血压在一定范围内波动时，肾血流量通过入球小动脉的自身调节保持相对稳定，不依赖神经或体液因素，主要与血管平滑肌的肌源性反应和管球反馈有关。免疫调节不参与；体液调节与神经调节虽可影响肾血流，但不是这种血压波动下短时稳定的主要方式；神经-内分泌调节也不符合"},{"q":"新生儿溶血性贫血可能发生在","o":["Rh阳性母亲所生Rh阳性婴儿","Rh阳性母亲所生Rh阴性婴儿","Rh阴性母亲所生Rh阳性婴儿","Rh阴性母亲所生Rh阴性婴儿","B或C均可发生"],"a":2,"e":"Rh阴性母亲首次妊娠Rh阳性胎儿时致敏产生抗Rh抗体，再次妊娠Rh阳性胎儿时，IgG抗体通过胎盘破坏胎儿红细胞，引起新生儿溶血。Rh阳性母亲所生婴儿均不会发生抗Rh免疫；Rh阴性母亲所生Rh阴性婴儿因缺乏Rh抗原也不发病；B或C均可发生扩大了范围"},{"q":"维持胸内负压的必要条件是","o":["呼吸道存在一定阻力","胸膜腔密闭","呼气肌收缩","吸气肌收缩","肺内压低于大气压"],"a":1,"e":"胸膜腔必须保持密闭，脏层与壁层胸膜间形成潜在负压腔，肺的回缩力才能作用于胸腔并维持负压；若胸膜腔与外界相通形成气胸，负压立即消失、肺萎陷。呼吸道阻力影响通气但不决定胸内负压是否存在；呼气肌、吸气肌收缩改变胸腔容积；肺内压低于大气压是吸气时表现，并非必要条件"},{"q":"交感神经活动增强时，下列哪项不会出现","o":["肠蠕动抑制","肾素分泌","胰岛素分泌","瞳孔开大肌收缩","支气管平滑肌舒张"],"a":2,"e":"交感神经兴奋通过α2受体抑制胰岛素分泌，同时促进胰高血糖素分泌，以保证应急状态下血糖供应，故胰岛素分泌不会出现增加。交感兴奋还抑制肠蠕动、经β1受体促进肾素分泌、兴奋瞳孔开大肌使瞳孔扩大、激动β2受体使支气管平滑肌舒张，其余各项均为交感兴奋的表现"},{"q":"阈电位是指","o":["造成膜对K+通透性突然增大的临界膜电位","造成膜对K+通透性突然减小的临界膜电位","超极化到刚能引起动作电位时的膜电位","造成膜对Na+通透性突然增大的临界膜电位","造成膜对Na+通透性突然减小的临界膜电位"],"a":3,"e":"阈电位是使膜对Na＋通透性突然增大、爆发动作电位的临界膜电位，达到此值时快钠通道大量开放、Na＋再生性内流。它不是K＋通透性突然增大或减小的临界电位；超极化到刚能引起动作电位的说法方向错误，阈电位通常在静息电位之上；Na＋通透性减小更与去极相机制相反"},{"q":"下列哪些临床表现不会见于甲状腺功能亢进病人","o":["病人体重明显减轻","喜热畏寒","突眼","甲状腺功能检查游离T3、T4升高","双侧甲状腺Ⅰ度大"],"a":1,"e":"甲亢时甲状腺激素增多，产热增加、怕热多汗，不会出现喜热畏寒，后者见于甲状腺功能减退。体重明显减轻因代谢亢进；突眼为Graves病特征；游离T3、T4升高符合甲亢实验室改变；双侧甲状腺Ⅰ度增大也常见，均可见于甲亢病人"},{"q":"下列关于甲状腺激素的作用机制的描述，哪一项是正确的","o":["与核受体结合刺激mRNA生成","与核受体结合促进Ca2+释放","与核受体结合抑制Ca2+释放","与核受体结合促进cAMP生成","与膜受体结合抑制cAMP生成"],"a":0,"e":"甲状腺激素为脂溶性，进入细胞后与核内甲状腺激素受体结合，调控靶基因转录，促进mRNA生成和蛋白质合成，发挥缓慢而持久的代谢调节作用。它不通过核受体直接促进或抑制Ca2＋释放；cAMP是含氮激素的第二信使，甲状腺激素不主要经此途径；与膜受体结合抑制cAMP也不符合其经典机制"},{"q":"可以较迅速地反映内环境变化状况的体液是","o":["脑脊液","血液","尿液","细胞内液","淋巴液"],"a":1,"e":"血液在循环系统中快速流动，与全身组织进行物质交换，其理化性质如pH、渗透压、气体、代谢物可较迅速反映内环境变化，故临床常检测血液。脑脊液更新慢、局限于中枢；尿液反映排泄与代谢终产物，变化滞后；细胞内液不属内环境；淋巴液回流缓慢，均不如血液迅速"},{"q":"关于头期胃液分泌的叙述，下列哪一项是正确的","o":["只有食物直接刺激口腔才能引起","只有神经调节","不包括条件反射","传出神经是迷走神经","酸度高、消化力弱"],"a":3,"e":"头期胃液分泌由看到、闻到、咀嚼及吞咽食物引起，包括条件反射与非条件反射，传出神经均为迷走神经，故迷走神经是其共同通路。并非只有食物直接刺激口腔才能引起；分泌受神经和体液共同调节；包括条件反射；头期胃液酸度高、消化力强，而非消化力弱"},{"q":"节后纤维兴奋可导致自律细胞动作电位4期内向电流If增强的是","o":["心交感神经","心迷走神经","交感缩血管神经","A和C都符合","A、B、C都符合"],"a":0,"e":"心交感神经节后纤维释放去甲肾上腺素，激动窦房结β1受体，通过cAMP-PKA途径增强4期内向电流If，使舒张期去极化加快、心率增加。心迷走神经释放ACh，抑制If、减慢心率；交感缩血管神经主要作用于血管平滑肌、不支配心肌自律细胞，故A和C、A/B/C均不正确"},{"q":"血浆中某物质能被肾小球滤过，同时肾小管对其有吸收作用，该物质的血浆清除率和菊粉的血浆清除率相比较正确的说法是","o":["一定相等","不能肯定，应当考虑肾小管该物质的分泌情况","一定少于菊粉的血浆清除率","一定大于菊粉的血浆清除率","不能肯定，应当考虑集合管该物质的分泌情况"],"a":1,"e":"菊粉只滤过而不重吸收也不分泌，其清除率等于GFR。某物质能滤过且被肾小管重吸收时，若仅重吸收则清除率小于菊粉；但同时可能存在分泌，分泌会抵消重吸收的影响，故不能简单断定大小，必须考虑该物质的肾小管分泌情况。集合管分泌并非主要判断点；一定相等或一定少于、大于均过于绝对"},{"q":"射血分数是指","o":["每搏输出量/心室舒张末期容积","心输出量/体表面积","心室收缩末期容积/心室舒张末期容积","心输出量/心室舒张末期容积","心室舒张末期容积/体表面积"],"a":0,"e":"射血分数指每搏输出量占心室舒张末期容积的百分比，正常约55%～65%，是评价心室泵血效率的指标。心输出量/体表面积是心指数的定义；收缩末期容积/舒张末期容积为剩余分数，与射血分数互补；心输出量/舒张末期容积及舒张末期容积/体表面积均非射血分数的定义"},{"q":"EPSP发生时，突触后膜电位的状态是","o":["超射","超极化","反极化","复极化","去极化"],"a":4,"e":"兴奋性突触后电位由兴奋性递质作用于突触后膜，使Na＋内流增加，突触后膜发生去极化，膜电位向阈电位靠近，兴奋性升高。超极化是IPSP的表现；反极化指膜电位超过0 mV、极性倒转，为动作电位上升相后段；复极化是去极化后回到静息电位的过程，均不是EPSP的电位状态"}];
